    /// <summary>
    /// Holds everything a <see cref="SparklineCellPanel"/> needs: the numeric series, the full
    /// <see cref="SparklineModel"/> (colors, markers, axis flags, line weight), and the axis-bound
    /// overrides pre-computed from group/custom scaling so construction is O(1) per cell.
    /// </summary>
    private sealed record SparklineCellEntry(
        IReadOnlyList<double> Values,
        SparklineModel Sparkline,
        double? OverrideMin,
        double? OverrideMax,
        double? OverrideMaxAbs);

    // StartIndex/EndIndex span the whole resize target: just Index..Index for a lone header, or
    // the full band of a pre-existing multi-column/row selection that Index falls inside
    // (GridResizePreviewPlanner.GetSelectedColumnResizeRange/GetSelectedRowResizeRange -- matching
    // the WPF host, R84-app-mouse-selection-5-2). Snapshot captures every original size/hidden-flag
    // across that whole band so the drag can preview/restore it in one shot via
    // GridResizePreviewPlanner.
    private sealed record HeaderResizeDrag(
        HeaderResizeKind Kind,
        uint Index,
        uint StartIndex,
        uint EndIndex,
        Control Capture,
        IPointer Pointer,
        double StartPointer,
        double StartSize,
        GridResizePreviewSnapshot Snapshot);

    private enum HeaderResizeKind
    {
        Column,
        Row
    }

    public MainWindow(IReadOnlyList<string> startupArguments)
        : this(
            startupArguments,
            WorkbookShareSheetServiceFactory.Create(WorkbookShareSheetLabel),
            WorkbookFileAccessServiceFactory.Create(App.Diagnostics),
            CreatePlatformPrintService())
    {
    }

    internal MainWindow(IReadOnlyList<string> startupArguments, bool deferStartupFileOpen)
        : this(
            startupArguments,
            WorkbookShareSheetServiceFactory.Create(WorkbookShareSheetLabel),
            WorkbookFileAccessServiceFactory.Create(App.Diagnostics),
            CreatePlatformPrintService(),
            sharedSession: null,
            platformClipboard: null,
            deferStartupFileOpen: deferStartupFileOpen)
