    /// <summary>
    /// Reads every sparkline on <paramref name="sheet"/> into a per-cell lookup keyed by its anchor
    /// <see cref="SparklineModel.Location"/>, using the same numeric series read as the Windows host
    /// (<see cref="SparklineRenderPlanner.BuildValues"/>). <paramref name="workbook"/> must own
    /// <paramref name="sheet"/> -- it resolves each sparkline's data range to its own source sheet
    /// when that differs from the host sheet (Excel's cross-sheet sparkline data range). Empty
    /// series are dropped so cells without drawable data don't get an empty panel. Group scaling
    /// (min/max/maxAbs) is pre-computed here so each <see cref="SparklineCellPanel"/> receives the
    /// correct axis overrides at construction.
    /// </summary>
    private static IReadOnlyDictionary<(uint Row, uint Col), SparklineCellEntry> BuildSparklineCellLookup(Workbook workbook, Sheet sheet)
    {
        var lookup = new Dictionary<(uint Row, uint Col), SparklineCellEntry>();
        if (sheet.Sparklines.Count == 0)
            return lookup;

        var values = SparklineRenderPlanner.BuildValues(workbook, sheet);

        // ── Pre-compute group scaling bounds ──────────────────────────────────
        // When MinAxisType or MaxAxisType == Group, find the shared min/max across all
        // sparklines that share the same GroupId, mirroring the WPF RenderSparklines logic.
        var axisScalePlan = SparklineAxisScalePlanner.Build(sheet.Sparklines, values);

        // ── Build per-cell entries with resolved axis overrides ───────────────
        foreach (var sparkline in sheet.Sparklines)
        {
            if (!values.TryGetValue(sparkline.Id, out var series) || series.Count == 0)
                continue;

            var axisScale = axisScalePlan.Resolve(sparkline);

            lookup[(sparkline.Location.Row, sparkline.Location.Col)] =
                new SparklineCellEntry(
                    series,
                    sparkline,
                    axisScale.Minimum,
                    axisScale.Maximum,
                    axisScale.MaximumAbsolute);
        }

        return lookup;
    }

    private Border CreateCell(DisplayCell cell, uint row, uint col, double zoomFactor, double cellWidth, double cellHeight, GridRange? mergeRegion = null)
    {
        var hasCell = cell.Row != 0 && cell.Col != 0;
        var address = new CellAddress(_session.ActiveSheet.Id, row, col);
        var selected = IsSelectedCell(address, mergeRegion);

        // Resolve the sparkline layer early: sparkline cells are typically empty (no cell value),
        // so the lookup must happen before the hasCell early-return guard below.
        var sparklineLayer = _sparklinesByCell.TryGetValue((row, col), out var sparklineEntry)
            ? new SparklineCellPanel(
                sparklineEntry.Values,
                sparklineEntry.Sparkline,
                sparklineEntry.OverrideMin,
                sparklineEntry.OverrideMax,
                sparklineEntry.OverrideMaxAbs)
            : null;

        if (!hasCell)
        {
            // Empty cell: still resolve the sheet's own reading order (no per-cell style exists yet)
            // so a blank cell in a right-to-left sheet gets the same mirrored FlowDirection/alignment
            // an Excel user would see the instant they start typing into it.
            var emptyCellIsRtl = CellTextOrientationLayoutPlanner.ResolveIsEffectivelyRightToLeft(
                CellReadingOrder.Context, _session.ActiveSheet.IsRightToLeft);
            return CreateInteractiveCellBorder(
                "",
                Brushes.White,
                Brushes.Black,
                MapCellTextAlignment(CellHAlign.General, isNumericOrDate: false, emptyCellIsRtl),
                AvaloniaVerticalAlignment.Center,
                TextWrapping.NoWrap,
                FontWeight.Normal,
                FontStyle.Normal,
                fontSize: 12,
                textDecorations: null,
                selected,
                address,
                zoomFactor: zoomFactor,
                cellWidth: cellWidth,
                cellHeight: cellHeight,
                sparklineLayer: sparklineLayer,
                mergeRegion: mergeRegion,
                flowDirection: MapCellFlowDirection(emptyCellIsRtl));
        }

        var style = cell.Style;
        var fillPlan = CellFillMaterializationPlanner.Plan(
            style,
            _session.Workbook.Theme,
            CellFillMaterializationProfile.Avalonia,
            _activeSheetHasBackgroundImage ? CellFillFallbackKind.Transparent : CellFillFallbackKind.White);
        IBrush? background = fillPlan.BackgroundKind switch
        {
            CellFillBackgroundKind.WhiteFallback => Brushes.White,
            CellFillBackgroundKind.Solid when fillPlan.SolidColor is { } fillColor => Brush(fillColor),
            CellFillBackgroundKind.LinearGradient or CellFillBackgroundKind.RadialGradient
                when fillPlan.Gradient is { } gradient => CellGradientBrush.Build(gradient),
            _ => null,
        };
        // Pattern fills (Gray0625…DarkTrellis) layer on top of the solid/gradient background.
        var patternBrush = CellPatternFill.Build(fillPlan);

        var foreground = style is null
            ? Brushes.Black
            : Brush(style.ResolveFontColor(_session.Workbook.Theme));
        var horizontalAlignment = style?.HorizontalAlignment ?? CellHAlign.General;
        var verticalAlignmentModel = style?.VerticalAlignment ?? CellVAlign.Bottom;
        var isNumeric = cell.RawValue is NumberValue or DateTimeValue;
        var isEffectivelyRightToLeft = CellTextOrientationLayoutPlanner.ResolveIsEffectivelyRightToLeft(
            style?.ReadingOrder ?? CellReadingOrder.Context, _session.ActiveSheet.IsRightToLeft);
        var alignment = MapCellTextAlignment(horizontalAlignment, isNumeric, isEffectivelyRightToLeft);
        var flowDirection = MapCellFlowDirection(isEffectivelyRightToLeft);
        var verticalAlignment = MapCellVerticalAlignment(verticalAlignmentModel);
        var textWrapping = style?.WrapText == true ? TextWrapping.Wrap : TextWrapping.NoWrap;
        var weight = style?.Bold == true ? FontWeight.Bold : FontWeight.Normal;
        var fontStyle = style?.Italic == true ? FontStyle.Italic : FontStyle.Normal;
        var fontSize = (style?.FontSize ?? CellStyle.Default.FontSize) + WorksheetFontSizeDisplayOffset;
        var fontFamily = ResolveAvaloniaCellFontFamily(style, _session.Workbook.Theme);
        var textDecorations = BuildTextDecorations(style);
        var indentPadding = GetCellIndentPadding(style) + GetPivotRowLabelTextPadding(address.Row, address.Col);
        var textRotation = style?.TextRotation ?? CellStyle.Default.TextRotation;

        // Highlight and color-scale rules are already baked into cell.Style (fill/font) by the
        // engine, so they ride along with the background/foreground above. Data bars and icon sets
        // arrive as separate engine results on the DisplayCell; the portable planner turns each into
        // a framework-neutral render instruction that the cell content layer draws.
        var dataBar = ConditionalFormatCellRenderPlanner.PlanDataBar(cell.ConditionalDataBar);
        var icon = ConditionalFormatCellRenderPlanner.PlanIcon(cell.ConditionalIcon);

        // Per-run rich text: resolve raw runs (null props → cell style) via the shared planner.
        // Only text cells with multiple character-level format variations carry entries here.
        // Use CellStyle.Default when style is null so run props inherit sensible defaults.
        IReadOnlyList<ResolvedCellTextRun>? richRuns = null;
        if (_session.ActiveSheet.RichTextRuns.TryGetValue(address, out var rawRuns))
        {
            richRuns = CellRichRunLayoutPlanner.Resolve(rawRuns, style ?? CellStyle.Default);
        }

        return CreateInteractiveCellBorder(
            cell.DisplayText,
            background,
            foreground,
            alignment,
            verticalAlignment,
            textWrapping,
            weight,
            fontStyle,
            fontSize,
            textDecorations,
            selected,
            address,
            indentPadding,
            textRotation,
            style,
            zoomFactor,
            cellWidth,
            cellHeight,
            horizontalAlignment,
            verticalAlignmentModel,
            isNumeric,
            dataBar,
            icon,
            sparklineLayer,
            patternBrush: patternBrush,
            richRuns: richRuns,
            mergeRegion: mergeRegion,
            flowDirection: flowDirection,
            commentDisplay: cell.CommentDisplay,
            fontFamily: fontFamily,
            isFormula: !string.IsNullOrEmpty(cell.Formula));
    }

    private static FontFamily ResolveAvaloniaCellFontFamily(CellStyle? style, WorkbookTheme theme)
    {
        var fontName = (style ?? CellStyle.Default).ResolveEffectiveFontName(theme);
        var fallback = fontName.Trim().ToUpperInvariant() switch
        {
            "CALIBRI" => "Carlito, Liberation Sans",
            "APTOS" => "Carlito, Liberation Sans",
            "APTOS NARROW" => "Arial Narrow, Liberation Sans Narrow, Nimbus Sans Narrow, Liberation Sans",
            "ARIAL" => "Liberation Sans",
            "SEGOE UI" => "Liberation Sans",
            "VERDANA" => "DejaVu Sans, Liberation Sans",
            "TIMES NEW ROMAN" => "Liberation Serif",
            _ => "Liberation Sans, sans-serif",
        };
        return new FontFamily($"{fontName}, {fallback}");
    }

    /// <summary>
    /// Looks up the four neighboring cells' touching border edges (above's bottom, below's top,
    /// left's right, right's left) from the active sheet's raw (unmerged/un-CF'd) styles, so
    /// <see cref="CellBorderPanel"/> can resolve adjacent-edge conflicts via
    /// <see cref="CellBorderVisualPlanner.ResolveEdgeWinner"/> instead of always drawing its own
    /// cell's edge unconditionally. Border styles are not affected by conditional formatting (only
    /// fill/font are), so the raw <see cref="Cell.StyleId"/> lookup mirrors what the neighbor's own
    /// <see cref="CellBorderPanel"/> would draw for that shared edge. A missing neighbor cell (no
    /// authored cell at that address, or off the top/left edge of the sheet) yields a default
    /// (<see cref="BorderStyle.None"/>) edge, which never overrides this cell's own style.
    /// </summary>
    private CellBorderNeighborEdges ResolveCellBorderNeighborEdges(CellAddress address)
    {
        var sheet = _session.ActiveSheet;
        var workbook = _session.Workbook;

        CellBorder above = default, below = default, left = default, right = default;
        if (address.Row > 1 && sheet.GetCell(address.Row - 1, address.Col) is { } aboveCell)
            above = workbook.GetStyle(aboveCell.StyleId).BorderBottom;
        if (sheet.GetCell(address.Row + 1, address.Col) is { } belowCell)
            below = workbook.GetStyle(belowCell.StyleId).BorderTop;
        if (address.Col > 1 && sheet.GetCell(address.Row, address.Col - 1) is { } leftCell)
            left = workbook.GetStyle(leftCell.StyleId).BorderRight;
        if (sheet.GetCell(address.Row, address.Col + 1) is { } rightCell)
            right = workbook.GetStyle(rightCell.StyleId).BorderLeft;

        return new CellBorderNeighborEdges(above, below, left, right);
    }

    /// <summary>
    /// A merged cell collapses to a single rendered <see cref="Border"/> spanning the whole region
    /// (<c>CreateCell</c> only ever renders the true/substitute anchor's own Border — every other
    /// member cell hits the "non-anchor member" <c>continue</c> a few lines up), so the anchor's own
    /// <see cref="CellStyle"/> would otherwise be the only style ever consulted for that Border's
    /// four edges. But <c>BorderShortcutService</c>'s per-cell diff (Ribbon Home ▸ Borders ▸ Outline)
    /// stores the BOTTOM and RIGHT outline edges on the OTHER constituent cells of the merge (the
    /// bottom-row and right-column members), never on the anchor — so those edges must be pulled
    /// from the actual owning member cell instead of silently dropping out. Top/left always come
    /// from the anchor itself, which sits at the merge's own top-left corner. Mirrors WPF's
    /// GridView.Rendering.cs per-constituent-cell border resolution for merges.
    /// </summary>
    private CellStyle? ResolveMergedOuterBorderStyle(CellStyle? anchorStyle, GridRange? mergeRegion)
    {
        if (mergeRegion is not { } region || region.Start == region.End)
            return anchorStyle;

        var sheet = _session.ActiveSheet;
        var workbook = _session.Workbook;
        var anchorEdges = ViewportGeometryPlanner.GetCellEdgeVisibility(
            region,
            region.Start.Row,
            region.Start.Col);

        var bottomBorder = anchorEdges.Bottom
            ? anchorStyle?.BorderBottom ?? default
            : sheet.GetCell(region.End.Row, region.Start.Col) is { } bottomCell
            ? workbook.GetStyle(bottomCell.StyleId).BorderBottom
            : default;
        var rightBorder = anchorEdges.Right
            ? anchorStyle?.BorderRight ?? default
            : sheet.GetCell(region.Start.Row, region.End.Col) is { } rightCell
            ? workbook.GetStyle(rightCell.StyleId).BorderRight
            : default;

        if (bottomBorder == (anchorStyle?.BorderBottom ?? default) &&
            rightBorder == (anchorStyle?.BorderRight ?? default))
        {
            return anchorStyle;
        }

        var merged = (anchorStyle ?? CellStyle.Default).Clone();
        merged.BorderBottom = bottomBorder;
        merged.BorderRight = rightBorder;
        return merged;
    }

    private Border CreateInteractiveCellBorder(
        string text,
        IBrush? background,
        IBrush foreground,
        TextAlignment textAlignment,
        AvaloniaVerticalAlignment verticalAlignment,
        TextWrapping textWrapping,
        FontWeight fontWeight,
        FontStyle fontStyle,
        double fontSize,
        TextDecorationCollection? textDecorations,
        bool selected,
        CellAddress address,
        double indentPadding = 0,
        int textRotation = 0,
        CellStyle? style = null,
        double zoomFactor = 1,
        double cellWidth = 80,
        double cellHeight = 20,
        CellHAlign horizontalAlignment = CellHAlign.General,
        CellVAlign? verticalAlignmentModel = null,
        bool isNumeric = false,
        CfDataBarRenderInstruction? conditionalDataBar = null,
        CfIconRenderInstruction? conditionalIcon = null,
        Control? sparklineLayer = null,
        IBrush? patternBrush = null,
        IReadOnlyList<ResolvedCellTextRun>? richRuns = null,
        GridRange? mergeRegion = null,
        FlowDirection flowDirection = FlowDirection.LeftToRight,
        CellCommentDisplay? commentDisplay = null,
        FontFamily? fontFamily = null,
        bool isFormula = false)
    {
        var applySelectionFill = selected &&
            address != _session.ActiveCell &&
            mergeRegion?.Contains(_session.ActiveCell) != true;
        var borderNeighbors = ResolveCellBorderNeighborEdges(address);
        var borderStyle = ResolveMergedOuterBorderStyle(style, mergeRegion);
        var border = CreateCellBorder(
            text,
            background,
            foreground,
            textAlignment,
            verticalAlignment,
            textWrapping,
            fontWeight,
            fontStyle,
            fontSize,
            textDecorations,
            applySelectionFill,
            indentPadding,
            textRotation,
            borderStyle,
            _session.IsShowingGridlines,
            zoomFactor,
            cellWidth,
            cellHeight,
            horizontalAlignment,
            verticalAlignmentModel,
            isNumeric,
            conditionalDataBar,
            conditionalIcon,
            sparklineLayer,
            patternBrush: patternBrush,
            richRuns: richRuns,
            flowDirection: flowDirection,
            commentDisplay: commentDisplay,
            fontFamily: fontFamily,
            suppressDefaultGridlines: CellSurfaceGridlinePlanner.HasVisibleFill(
                style,
                _session.Workbook.Theme),
            borderNeighbors: borderNeighbors);

        // Grid tracks define worksheet ownership. Give the interactive border the exact slot size
        // (cellWidth/cellHeight already include merged spans) so Linux font measurement cannot let
        // a long source cell's visual and pointer bounds extend into an adjacent empty cell.
        border.Width = cellWidth;
        border.Height = cellHeight;

        // The outer cell border is the worksheet hit target.  Keep rendered content out of the
        // hit-test tree so an overflowing TextBlock cannot capture a pointer over the adjacent
        // cell; WPF paints cell text directly into its DrawingContext and has no equivalent child
        // visual.  Inline editing replaces this child with a live TextBox below, so edit gestures
        // remain interactive.
        if (border.Child is { } cellContent)
            cellContent.IsHitTestVisible = false;

        // Comment/note corner indicator + hover card: mirrors WPF's GridView.Rendering.cs
        // DrawCommentIndicator (small top-right triangle, red for a legacy note, purple for a
        // threaded comment or a cell that mixes both) and GridView.CommentPreview.cs (hover shows
        // the thread's title/body). Without this a Linux/macOS reviewer has no way to tell which
        // cells carry comments except by navigating Review ▸ Next/Previous Comment.
        if (commentDisplay is { } comment)
        {
            ToolTip.SetTip(border, FormatCommentTooltip(comment));
        }
        else if (FormatHyperlinkTooltip(_session.Workbook.GetSheet(address.Sheet), address) is { } hyperlinkTooltip)
        {
            // R88-app-hyperlink-navigation-5-4: a hyperlink's ScreenTip (or, absent one, its target
            // URL) is captured and persisted but was never surfaced anywhere in the grid -- real
            // Excel shows it as a hover tooltip over the linked cell. Skipped when the cell also
            // carries a comment (handled above); Excel itself prioritizes the comment popup there.
            ToolTip.SetTip(border, hyperlinkTooltip);
        }

        // Per-cell accessible name/id so a screen reader (Orca/AT-SPI on Linux, VoiceOver on macOS)
        // can announce which cell has focus, its address, its value, and (R114 parity fix for
        // finding "Avalonia grid's screen-reader cell name silently drops comment/formula/merge/
        // hyperlink cues that WPF announces") the same "has <note>", "is a formula", "is merged",
        // and "has a hyperlink" cues WPF's GridViewCellAutomationPeer.GetNameCore/
        // GridView.BuildCellAnnouncementName append (GridView.cs:688-708) -- previously this shell
        // only ever emitted the bare "<address>" or "<address>: <value>", silently omitting every
        // cue a sighted user gets for free from the comment corner-triangle, the formula-bar "="
        // prefix, the merged span, and the hand cursor. HasDataValidation/IsLocked cues are
        // intentionally left out here too, mirroring WPF: CellAnnouncementMetadata's own doc
        // comment (GridView.cs) explains neither is wired to a live signal on that shell either.
        // Cells are plain Borders rebuilt on every selection change/RefreshShell (no persisted control
        // to "update" in place), so setting these at construction time keeps them live automatically.
        var columnName = CellAddress.NumberToColumnName(address.Col);
        AutomationProperties.SetAutomationId(border, $"Cell_{columnName}{address.Row}");
        var hasHyperlink = _session.Workbook.GetSheet(address.Sheet)?.Hyperlinks.ContainsKey(address) == true;
        AutomationProperties.SetName(
            border,
            CellAnnouncementPlanner.BuildName(
                $"{columnName}{address.Row}",
                text,
                new CellAnnouncementMetadata(
                    HasComment: commentDisplay is not null,
                    CommentTitle: commentDisplay?.Title,
                    IsFormula: isFormula,
                    IsMerged: mergeRegion is not null,
                    HasHyperlink: hasHyperlink)));

        // The active cell (not just any selected cell) is made a REAL focusable/focus-tracked
        // element so keyboard focus actually moves as the user arrows around the grid, matching
        // WPF's GridViewAutomationPeer.NotifySelectionChanged (GridView.cs), which raises
        // AutomationFocusChanged/SelectionItemPatternOnElementSelected on every active-cell move.
        // Avalonia has no direct equivalent of RaiseAutomationEvent for arbitrary UIA/AT-SPI
        // events; instead its automation bridges observe real FocusManager focus changes, so
        // moving actual keyboard focus here (see MoveFocusToActiveCellBorder, called after each
        // BuildSheetGrid/RefreshShell pass) is what makes a screen reader announce the new
        // cell's name/address on every navigation instead of staying silent on _sheetGridHost.
        if (address == _session.ActiveCell)
        {
            border.Focusable = true;
            _activeCellBorder = border;
        }

        if (IsBorderDrawModeActive)
            border.Cursor = new Cursor(StandardCursorType.Cross);
        border.PointerPressed += (_, args) =>
        {
            var point = args.GetCurrentPoint(border);
            if (point.Properties.IsLeftButtonPressed &&
                _formulaRangeEditingSession.ShouldAppendDisjointReference(
                    FormulaBarAvaloniaInputAdapter.ToFormulaEditorModifiers(args.KeyModifiers)) &&
                TryAppendDisjointFormulaPointReference(address))
            {
                var referenceStart = _formulaRangeEditingSession.ReferenceSpan?.Start;
                var referenceLength = _formulaRangeEditingSession.ReferenceSpan?.Length;
                BeginCellSelectionDrag(args, border, address);
                TrackFormulaPointDragAnchor(address, referenceStart, referenceLength);
                args.Handled = true;
                return;
            }

            if (point.Properties.IsLeftButtonPressed &&
                !args.KeyModifiers.HasFlag(KeyModifiers.Shift) &&
                HasHyperlinkActivationModifier(args.KeyModifiers) &&
                _session.TryGetHyperlinkPlan(address, out var _))
            {
                args.Handled = true;
                RunGuarded(() => OpenHyperlinkAsync(address));
                return;
            }

            if (IsContextClick(point, args))
            {
                // Right-click selects the clicked cell (so the menu commands target it) and then
                // opens the worksheet cell context menu, built from the shared neutral plan.
                if (!IsSelectedCell(address))
                    SelectCell(address);
                OpenWorksheetCellContextMenu((Control?)_activeCellBorder ?? _sheetGridHost);
                args.Handled = true;
                return;
            }

            if (point.Properties.IsLeftButtonPressed &&
                TryInsertFormulaPointReference(address))
            {
                var referenceStart = _formulaRangeEditingSession.ReferenceSpan?.Start;
                var referenceLength = _formulaRangeEditingSession.ReferenceSpan?.Length;
                BeginCellSelectionDrag(args, border, address);
                TrackFormulaPointDragAnchor(address, referenceStart, referenceLength);
                args.Handled = true;
                return;
            }

            // In Draw Border mode skip autofill / move-drag detection and go straight to
            // selection-drag so the drag extent becomes the range that gets bordered.
            if (!IsBorderDrawModeActive &&
                (TryBeginAutofillDrag(args, border, address) ||
                 TryBeginSelectionMoveDrag(args, border, address)))
            {
                args.Handled = true;
                return;
            }

            if (point.Properties.IsLeftButtonPressed && IsCellDoubleClick(address, args.ClickCount))
            {
                if (ConsumePivotDetailsDoubleClickSuppression(address))
                {
                    args.Handled = true;
                    return;
                }

                var editText = FormatEditText(_session.ActiveSheet.GetCell(address), address);
                var caretIndex = CalculateInlineCellCaretIndex(
                    editText,
                    point.Position.X,
                    cellWidth,
                    fontSize * zoomFactor,
                    fontWeight,
                    fontStyle,
                    fontFamily ?? FontFamily.Default,
                    (8 + indentPadding) * zoomFactor,
                    textAlignment);
                if (!TryShowPivotTableDetailsFromDoubleClick(address))
                    BeginInlineCellEdit(address, editText, caretIndex);
                args.Handled = true;
                return;
            }

            SelectClickedCell(address, args.KeyModifiers);
            BeginCellSelectionDrag(args, border, address);
            args.Handled = true;
        };
        // PointerMoved and PointerReleased for cell-selection drag are now subscribed on _sheetGridHost
        // (the survivor that is NOT rebuilt by RefreshShell) inside BeginCellSelectionDrag, not here on
        // the per-cell Border which gets destroyed the moment SelectRangeFromAnchor triggers RefreshShell.
        border.DoubleTapped += (_, args) =>
        {
            if (ConsumePivotDetailsDoubleClickSuppression(address))
            {
                args.Handled = true;
                return;
            }

            var editText = FormatEditText(_session.ActiveSheet.GetCell(address), address);
            var caretIndex = CalculateInlineCellCaretIndex(
                editText,
                args.GetPosition(border).X,
                cellWidth,
                fontSize * zoomFactor,
                fontWeight,
                fontStyle,
                fontFamily ?? FontFamily.Default,
                (8 + indentPadding) * zoomFactor,
                textAlignment);
            if (!TryShowPivotTableDetailsFromDoubleClick(address))
                BeginInlineCellEdit(address, editText, caretIndex);
            args.Handled = true;
        };
        if (Equals(_inlineCellEditAddress, address))
        {
            border.Cursor = new Cursor(StandardCursorType.Ibeam);
            border.Child = CreateInlineCellEditor(
                address,
                background ?? Brushes.White,
                foreground,
                textAlignment,
                fontWeight,
                fontStyle,
                fontSize,
                fontFamily ?? FontFamily.Default,
                indentPadding,
                zoomFactor,
                cellHeight);
        }
        return DecoratePivotHeaderCell(DecorateAutoFilterHeaderCell(border, address), address);
    }

    private bool IsCellDoubleClick(CellAddress address, int frameworkClickCount)
    {
        var now = Stopwatch.GetTimestamp();
        var elapsed = _lastCellPointerPressTimestamp == 0
            ? double.PositiveInfinity
            : Stopwatch.GetElapsedTime(_lastCellPointerPressTimestamp, now).TotalMilliseconds;
        var isDoubleClick = frameworkClickCount >= 2 ||
            (_lastCellPointerPressAddress == address && elapsed <= 500);

        _lastCellPointerPressAddress = isDoubleClick ? null : address;
        _lastCellPointerPressTimestamp = isDoubleClick ? 0 : now;
        return isDoubleClick;
    }

    private Control CreateInlineCellEditor(
        CellAddress address,
        IBrush background,
        IBrush foreground,
        TextAlignment textAlignment,
        FontWeight fontWeight,
        FontStyle fontStyle,
        double fontSize,
        FontFamily fontFamily,
        double indentPadding,
        double zoomFactor,
        double cellHeight)
    {
        var editor = new TextBox
        {
            Text = _inlineCellEditText ?? "",
            Background = background,
            Foreground = foreground,
            BorderBrush = Brushes.Transparent,
            BorderThickness = new Thickness(0),
            Padding = new Thickness((8 + indentPadding) * zoomFactor, 0, 8 * zoomFactor, 0),
            FontSize = Math.Max(1, fontSize * zoomFactor),
            FontFamily = fontFamily,
            FontWeight = fontWeight,
            FontStyle = fontStyle,
            TextAlignment = textAlignment,
            AcceptsReturn = false,
            TextWrapping = TextWrapping.NoWrap,
            MinHeight = 0,
            Height = cellHeight,
            VerticalContentAlignment = AvaloniaVerticalAlignment.Center,
        };
        AutomationProperties.SetAutomationId(editor, "WorksheetInlineCellEditor");
        editor.TextInput += (_, args) => InlineCellEditor_TextInput(address, editor, args);
        editor.PropertyChanged += (_, args) =>
        {
            if (!Equals(_inlineCellEditAddress, address) || !ReferenceEquals(_inlineCellEditor, editor) ||
                (args.Property != TextBox.SelectionStartProperty && args.Property != TextBox.SelectionEndProperty))
            {
                return;
            }

            _inlineCellEditSelectionStart = editor.SelectionStart;
            _inlineCellEditSelectionEnd = editor.SelectionEnd;
            if (!_isApplyingFormulaBoxText)
                ClearFormulaReferenceEntrySpanIfCaretLeftReference(editor);
        };
        editor.TextChanged += (_, _) =>
        {
            if (!Equals(_inlineCellEditAddress, address) || !ReferenceEquals(_inlineCellEditor, editor))
                return;

            _inlineCellEditText = editor.Text ?? "";
            if (_isApplyingFormulaBoxText)
            {
                return;
            }

            _isApplyingFormulaBoxText = true;
            try
            {
                _formulaBox.Text = _inlineCellEditText;
            }
            finally
            {
                _isApplyingFormulaBoxText = false;
            }

            ClearFormulaReferenceEntrySpan();
            UpdateFormulaRangeEntryStateAfterTextChanged(_inlineCellEditText);
            RefreshFormulaReferenceHighlights();
            RefreshFormulaReferenceGridHighlights();
            RefreshFormulaFunctionAutocomplete(editor);
            RefreshFormulaSignatureHelp(editor);

            if (!_formulaRangeEditingSession.ConsumeCellValueAutocompleteSuppression())
                ApplyInlineCellValueAutoCompleteSuggestion(address, editor);
        };
        editor.KeyDown += (_, args) => InlineCellEditor_KeyDown(address, editor, args);

        // R78-render-inplace-editor-5-2: mirrors the WPF host's second inline overlay
        // (_inlineFormulaReferenceOverlay in MainWindow.Editing.cs), stacked on top of the editor
        // itself in a Grid so the colored reference text renders at the cell the user is actually
        // typing into, not only in the (possibly scrolled-out-of-view) formula bar above.
        var referenceOverlay = new TextBlock
        {
            Foreground = foreground,
            Padding = new Thickness((8 + indentPadding) * zoomFactor, 0, 8 * zoomFactor, 0),
            FontSize = Math.Max(1, fontSize * zoomFactor),
            FontFamily = fontFamily,
            FontWeight = fontWeight,
            FontStyle = fontStyle,
            TextAlignment = textAlignment,
            TextWrapping = TextWrapping.NoWrap,
            Height = cellHeight,
            VerticalAlignment = AvaloniaVerticalAlignment.Center,
            IsHitTestVisible = false,
            IsVisible = false,
            ClipToBounds = true,
        };
        AutomationProperties.SetAutomationId(referenceOverlay, "WorksheetInlineCellReferenceOverlay");

        var container = new AvaloniaGrid();
        container.Children.Add(editor);
        container.Children.Add(referenceOverlay);

        _inlineCellEditor = editor;
        _inlineCellReferenceTextOverlay = referenceOverlay;
        _inlineCellEditorForeground = foreground;
        Dispatcher.UIThread.Post(
            () => FocusInlineCellEditor(address, editor),
            DispatcherPriority.Input);

        return container;
    }

    private void FocusInlineCellEditor(CellAddress address, TextBox editor)
    {
        if (!Equals(_inlineCellEditAddress, address) || !ReferenceEquals(_inlineCellEditor, editor))
            return;

        // A queued focus handoff must never reset a caret that has already received input. This
        // occurs on X11 when the first TextInput reaches the attached TextBox before the queued
        // input-priority focus callback is dispatched.
        if (editor.IsFocused && _pendingInlineCellCaretIndex is null)
            return;

        var textLength = editor.Text?.Length ?? 0;
        var selectionStart = Math.Clamp(
            _pendingInlineCellCaretIndex ?? _inlineCellEditSelectionStart ?? textLength,
            0,
            textLength);
        var selectionEnd = Math.Clamp(
            _pendingInlineCellCaretIndex ?? _inlineCellEditSelectionEnd ?? selectionStart,
            0,
            textLength);
        editor.Focus();
        editor.CaretIndex = selectionEnd;
        editor.SelectionStart = selectionStart;
        editor.SelectionEnd = selectionEnd;
        _inlineCellEditSelectionStart = selectionStart;
        _inlineCellEditSelectionEnd = selectionEnd;
        _pendingInlineCellCaretIndex = null;
    }

    private void InlineCellEditor_TextInput(
        CellAddress address,
        TextBox editor,
        TextInputEventArgs args)
    {
        if (!Equals(_inlineCellEditAddress, address) || !ReferenceEquals(_inlineCellEditor, editor))
            return;

        if (TryApplyInlineCellTextInput(editor, args.Text))
            args.Handled = true;
    }

    private bool TryApplyInlineCellTextInput(TextBox inlineEditor, string? input)
    {
        if (string.IsNullOrEmpty(input))
            return false;

        foreach (var character in input)
        {
            if (char.IsControl(character))
                return false;
        }

        var text = inlineEditor.Text ?? "";
        // TextInput packets can arrive back-to-back on X11 before Avalonia publishes the newly
        // assigned SelectionStart/CaretIndex values. The inline-edit session owns its most recent
        // selection so that consecutive packets preserve their arrival order; normal pointer and
        // keyboard selection changes keep that state synchronized through PropertyChanged above.
        var rawSelectionStart = _pendingInlineCellCaretIndex ?? _inlineCellEditSelectionStart ?? Math.Min(
            inlineEditor.SelectionStart,
            inlineEditor.SelectionEnd);
        var rawSelectionEnd = _pendingInlineCellCaretIndex ?? _inlineCellEditSelectionEnd ?? Math.Max(
            inlineEditor.SelectionStart,
            inlineEditor.SelectionEnd);
        var selectionStart = Math.Clamp(
            rawSelectionStart,
            0,
            text.Length);
        var selectionLength = Math.Clamp(
            rawSelectionEnd - rawSelectionStart,
            0,
            text.Length - selectionStart);
        var nextCaretIndex = selectionStart + input.Length;
        ApplyTextBoxEdit(
            inlineEditor,
            new ExcelTextEdit(
                text.Remove(selectionStart, selectionLength).Insert(selectionStart, input),
                nextCaretIndex,
                0));
        _inlineCellEditSelectionStart = nextCaretIndex;
        _inlineCellEditSelectionEnd = nextCaretIndex;
        _pendingInlineCellCaretIndex = null;

        // R92-meta-2: ApplyTextBoxEdit sets Text before CaretIndex, so the editor.TextChanged pass
        // it triggers (which drives RefreshFormulaFunctionAutocomplete) sees the *previous* caret
        // position, not the one this keystroke just produced -- e.g. typing the "P" of "=XNP" would
        // still evaluate the popup against the stale "=XN" caret. Re-run it now that both Text and
        // CaretIndex reflect this keystroke, so the AutoComplete popup always matches what was
        // actually just typed (mirrors the WPF host, whose native TextBox typing keeps caret and
        // text in sync before TextChanged fires, so it never needed this second pass).
        RefreshFormulaFunctionAutocomplete(inlineEditor);
        RefreshFormulaSignatureHelp(inlineEditor);
        return true;
    }

    private void InlineCellEditor_KeyDown(CellAddress address, TextBox editor, KeyEventArgs args)
    {
        // R92-meta-2: while the function-name AutoComplete popup is open, Up/Down/Tab/Enter/Escape
        // drive the popup instead of their normal formula-editing meaning, exactly as Excel's own
        // popup takes priority over those keys. Checked first, before any other key handling below.
        if (HandleFunctionAutocompleteKeyDown(editor, args.Key))
        {
            args.Handled = true;
            return;
        }

        // R88-app-autocomplete-picklist-5-2: Backspace/Delete reject a live AutoComplete suggestion
        // (Excel behavior) rather than instantly re-offering the same completion the deletion just
        // removed. The key itself is left unhandled so it still performs its normal TextBox deletion.
        if (args.Key is Key.Back or Key.Delete)
            _formulaRangeEditingSession.SuppressNextCellValueAutocomplete();

        if (TryToggleFormulaRangeEntrySelectionMode(args.Key, args.KeyModifiers))
        {
            args.Handled = true;
            return;
        }

        if (TryHandleFormulaEditorModeOrReferenceCycle(editor, args))
            return;

        if (TryHandleFormulaRangeEntryNavigation(editor, address, args))
            return;

        var formulaRangeEntryActive = IsFormulaRangeEntryActive(editor.Text);
        // Avalonia's in-cell overlay is entered by F2/double-click, so it is always Excel's Edit mode.
        var intent = _formulaRangeEditingSession.PlanEditKey(
            FormulaBarAvaloniaInputAdapter.ToFormulaEditorKey(args.Key),
            FormulaEditorKey.None,
            FormulaBarAvaloniaInputAdapter.ToFormulaEditorModifiers(args.KeyModifiers),
            address,
            Math.Max(1, WorkbookViewportScrollPlanner.CountVisibleScrollableRows(
                _session.Viewport, _session.Workbook.GetSheet(address.Sheet)) - 1),
            editor.Text,
            _session.FormulaEditAddress is not null,
            FormulaEditorSurfaceKind.Inline,
            true,
            MoveSelectionAfterEnter,
            AfterEnterDirection);

        if (intent.Action == ExcelEditKeyAction.InsertLineBreak)
        {
            ApplyTextBoxEdit(
                editor,
                ExcelTextEditorPlanner.InsertLineBreak(
                    editor.Text ?? "",
                    Math.Min(editor.SelectionStart, editor.SelectionEnd),
                    Math.Abs(editor.SelectionEnd - editor.SelectionStart),
                    Environment.NewLine));
            SynchronizeFormulaEditors(editor);
            args.Handled = true;
        }
        else if (intent.Action == ExcelEditKeyAction.CommitAndMove && intent.Target is { } target)
        {
            var adjustedTarget = ExcelWorksheetNavigationPlanner.AdjustTargetPastMerge(
                _session.Workbook.GetSheet(address.Sheet),
                address,
                target);
            CommitInlineCellEdit(address, adjustedTarget, args.Key, args.KeyModifiers.HasFlag(KeyModifiers.Shift));
            args.Handled = true;
        }
        else if (intent.Action == ExcelEditKeyAction.CommitSelection)
        {
            var text = editor.Text ?? _inlineCellEditText ?? "";
            _formulaBox.Text = text;
            ClearInlineCellEditorState();
            if (CommitEditAcrossSelection(text))
            {
                ClearFormulaRangeEntryState();
                RefreshShell(UiText.Get("MainLoc_Ready"));
                FocusShellRegion(ShellFocusTarget.Worksheet);
            }
            args.Handled = true;
        }
        else if (args.Key == Key.Escape)
        {
            CancelCellEditAndRestoreCommittedText();
            args.Handled = true;
        }
    }

    /// <summary>
    /// R88-app-autocomplete-picklist-5-2: Excel's "AutoComplete for cell values", ported to the
    /// in-cell inline editor from the WPF host's ApplyCellValueAutoCompleteSuggestion
    /// (MainWindow.Editing.cs). Runs on every inline-editor keystroke; only actually offers a
    /// completion when all of these hold, so it never fires while the user is mid-formula,
    /// mid-navigation, or already accepted/rejected a suggestion:
    /// <list type="bullet">
    /// <item>the option is enabled (<see cref="EnableAutoCompleteForCellValues"/>);</item>
    /// <item>the cell is a plain text entry -- not a formula (leading '=') and not mid formula
    /// range-reference entry;</item>
    /// <item>the caret sits at the very end of the text with nothing selected -- i.e. the user is
    /// typing forward, not editing mid-string or already sitting on a live suggestion.</item>
    /// </list>
    /// On a match it appends the remainder of the matched column entry and selects it: Tab/Enter
    /// commits the completed text, continuing to type overwrites the selected remainder with the new
    /// keystroke (which re-runs this same check for the new prefix), and Backspace/Delete rejects it
    /// via the session's one-shot suppression state.
    /// </summary>
    private void ApplyInlineCellValueAutoCompleteSuggestion(CellAddress address, TextBox editor)
    {
        if (_applyingInlineCellValueAutoCompleteSuggestion ||
            !Equals(_inlineCellEditAddress, address) ||
            !ReferenceEquals(_inlineCellEditor, editor))
        {
            return;
        }

        var text = editor.Text ?? "";
        var sheet = _session.Workbook.GetSheet(address.Sheet);
        var plan = _formulaRangeEditingSession.PlanCellValueAutocomplete(
            EnableAutoCompleteForCellValues,
            text,
            editor.CaretIndex,
            Math.Abs(editor.SelectionEnd - editor.SelectionStart),
            sheet,
            address);
        if (plan is null)
            return;

        _applyingInlineCellValueAutoCompleteSuggestion = true;
        try
        {
            editor.Text = plan.Value.Text;
            editor.CaretIndex = plan.Value.Text.Length;
            editor.SelectionStart = plan.Value.SelectionStart;
            editor.SelectionEnd = plan.Value.SelectionStart + plan.Value.SelectionLength;
            _inlineCellEditSelectionStart = plan.Value.SelectionStart;
            _inlineCellEditSelectionEnd = plan.Value.SelectionStart + plan.Value.SelectionLength;
        }
        finally
        {
            _applyingInlineCellValueAutoCompleteSuggestion = false;
        }
    }

    private void BeginInlineCellEdit(CellAddress address, string editText, int caretIndex)
    {
        ClearSelectedDrawingObject();
        _inlineCellEditAddress = address;
        _inlineCellEditText = editText;
        var safeCaretIndex = Math.Clamp(caretIndex, 0, editText.Length);
        _inlineCellEditSelectionStart = safeCaretIndex;
        _inlineCellEditSelectionEnd = safeCaretIndex;
        _pendingInlineCellCaretIndex = safeCaretIndex;
        _formulaBox.Text = editText;
        _formulaBoxEditOriginalText = editText;
        ClearFormulaRangeEntryState();
        _formulaRangeEditingSession.ApplyTypedEntry(editText);
        _session.BeginFormulaEdit(address);
        RefreshShell(UiText.Get("MainLoc_Ready"));
        if (_inlineCellEditor is { } editor)
            FocusInlineCellEditor(address, editor);
    }

    private void CommitInlineCellEdit(CellAddress current, CellAddress adjustedTarget, Key key, bool shiftHeld)
    {
        _formulaBox.Text = _inlineCellEditor?.Text ?? _inlineCellEditText ?? "";
        ClearInlineCellEditorState();
        if (CommitFormulaBox())
        {
            MoveActiveCellAfterEditCommit(current, adjustedTarget, key, shiftHeld);

            RefreshShell(UiText.Get("MainLoc_Ready"));
            // The inline editor is detached by CommitFormulaBox before the next-cell refresh.
            // Restore focus to the newly active cell itself, matching WPF's worksheet focus handoff
            // and keeping the next physical F2/text packet on the worksheet rather than the shell
            // host after an Enter/Tab edit continuation.
            MoveFocusToActiveCellBorder();
        }
    }

    /// <summary>
    /// R139-freex-cell-editing-edit-commit-collapses-range-selection: Enter/Tab (and their Shift
    /// variants) that commit an in-cell/formula-bar edit must CYCLE the active cell within a
    /// pre-existing multi-cell selection -- wrapping at the far end back to the start -- exactly
    /// like Excel and like the ready-mode Enter/Tab handler in NavigateActiveCell (which routes
    /// through the same <see cref="GridSelectionNavigationPlanner.PlanCycle"/> +
    /// <see cref="WorkbookSession.MoveActiveCellWithinSelection"/> pair). It must NOT collapse
    /// the selection via the plain delta-based <see cref="WorkbookSession.MoveActiveCell"/>,
    /// which is what happened before this fix. Arrow-key commits (the inline editor's
    /// inlineEditorCommitsOnArrow path, and the formula bar's Up/Down/PageUp/PageDown fallback)
    /// are ordinary navigation, not range-cycling, so this only engages when the physical key
    /// that triggered the commit was actually Enter or Tab; every other key -- and any Enter/Tab
    /// where there is no eligible multi-cell selection to cycle within (a single selected cell,
    /// or a single selected merged region) -- falls back unchanged to the pre-existing
    /// delta-based MoveActiveCell behavior.
    /// </summary>
    private void MoveActiveCellAfterEditCommit(CellAddress current, CellAddress adjustedTarget, Key key, bool shiftHeld)
    {
        var cycleKey = key switch
        {
            Key.Enter => GridSelectionCycleKey.Enter,
            Key.Tab => GridSelectionCycleKey.Tab,
            _ => (GridSelectionCycleKey?)null
        };

        var cyclePlan = cycleKey is { } resolvedKey
            ? GridSelectionNavigationPlanner.PlanCycle(
                _session.Workbook.GetSheet(current.Sheet),
                _session.SelectedRange,
                _session.SelectedRanges,
                current,
                resolvedKey,
                forward: !shiftHeld)
            : null;

        if (cyclePlan is { } cycle)
        {
            _session.MoveActiveCellWithinSelection(cycle.Target);
            return;
        }

        var rowDelta = GetCellIndexDelta(current.Row, adjustedTarget.Row);
        var colDelta = GetCellIndexDelta(current.Col, adjustedTarget.Col);
        if (rowDelta != 0 || colDelta != 0)
            _session.MoveActiveCell(rowDelta, colDelta);
    }

    private void CancelCellEditAndRestoreCommittedText()
    {
        var formulaEditAddress = _session.FormulaEditAddress;
        _session.CancelFormulaEdit();
        if (formulaEditAddress is { } address)
            _session.SelectCell(address);
        _formulaBoxEditOriginalText = null;
        ClearFormulaRangeEntryState();
        ClearInlineCellEditorState();
        RefreshShell(UiText.Get("MainLoc_Ready"));
        FocusShellRegion(ShellFocusTarget.Worksheet);
    }

    private void ClearInlineCellEditorState()
    {
        HideFormulaFunctionAutocomplete();
        HideFormulaSignatureHelp();
        _inlineCellEditor = null;
        _inlineCellReferenceTextOverlay = null;
        _inlineCellEditorForeground = null;
        _inlineCellEditAddress = null;
        _inlineCellEditText = null;
        _inlineCellEditSelectionStart = null;
        _inlineCellEditSelectionEnd = null;
        _pendingInlineCellCaretIndex = null;
    }

    private void ClearFormulaReferenceEntrySpan() =>
        _formulaRangeEditingSession.ClearReferenceSpan();

    private void ClearFormulaReferenceEntrySpanIfCaretLeftReference(TextBox editor)
    {
        var textLength = editor.Text?.Length ?? 0;
        var selectionStart = Math.Clamp(Math.Min(editor.SelectionStart, editor.SelectionEnd), 0, textLength);
        var selectionLength = Math.Abs(editor.SelectionEnd - editor.SelectionStart);
        _formulaRangeEditingSession.ClearReferenceSpanIfCaretLeft(
            textLength,
            selectionStart,
            selectionLength,
            editor.CaretIndex,
            preserveWhileSelectionActive: true);
    }

    private void ClearFormulaRangeEntryState()
    {
        FormulaReferenceEditingController.Reset(
            _formulaRangeEditingSession,
            HideFormulaFunctionAutocomplete,
            () =>
            {
                ClearFormulaReferenceTextOverlay();
                ClearFormulaReferenceGridHighlights();
            });
    }

    private void UpdateFormulaRangeEntryStateAfterTextChanged(string? text)
    {
        var plan = _formulaRangeEditingSession.ApplyTextChanged(text);
        if (!plan.StartsPointMode)
            return;

        ApplyFormulaEditStatusBarPlan(plan.StatusBarPlan);
    }

    private void ApplyFormulaEditStatusBarPlan(FormulaEditStatusBarPlan? plan)
    {
        if (plan is not { } statusBarPlan)
            return;

        var status = UiText.Get(statusBarPlan.ResourceKey);
        _statusText.Text = status;
        ApplyStatusBarModel(status);
    }

    private bool TryHandleFormulaEditorModeOrReferenceCycle(TextBox editor, KeyEventArgs args)
    {
        var key = FormulaBarAvaloniaInputAdapter.ToFormulaEditorKey(args.Key);
        var modifiers = FormulaBarAvaloniaInputAdapter.ToFormulaEditorModifiers(args.KeyModifiers);

        if (args.Key == Key.F2 && args.KeyModifiers == KeyModifiers.None)
        {
            var togglePlan = _formulaRangeEditingSession.TogglePointMode(editor.Text);
            if (togglePlan.ClearReferenceSpan)
                _formulaRangeEditingSession.ClearSelection();

            ApplyFormulaEditStatusBarPlan(togglePlan.StatusBarPlan);
            args.Handled = togglePlan.Handled;
            return args.Handled;
        }

        if (!_formulaRangeEditingSession.ShouldCycleReference(key, modifiers))
            return false;

        if (!TryCycleFormulaReference(editor))
            return false;

        args.Handled = true;
        return true;
    }

    private bool TryCycleFormulaReference(TextBox editor)
    {
        var caretIndex = editor.SelectionStart != editor.SelectionEnd
            ? Math.Min(editor.SelectionStart, editor.SelectionEnd)
            : editor.CaretIndex;
        var anchor = _session.FormulaEditAddress ?? _session.ActiveCell;
        if (!_formulaRangeEditingSession.TryPlanReferenceCycle(
                editor.Text ?? "",
                caretIndex,
                anchor,
                UseR1C1ReferenceStyle,
                out var edit))
        {
            return false;
        }

        _isApplyingFormulaBoxText = true;
        try
        {
            ApplyTextBoxEdit(editor, edit);
            SynchronizeFormulaEditors(editor);
        }
        finally
        {
            _isApplyingFormulaBoxText = false;
        }

        _formulaRangeEditingSession.TrackReferenceSpan(edit.SelectionStart, edit.SelectionLength);
        return true;
    }

    private bool TryHandleFormulaRangeEntryNavigation(TextBox editor, CellAddress fallbackCurrent, KeyEventArgs args)
    {
        if (!IsFormulaRangeEntryActive(editor.Text))
            return false;

        var current = _formulaRangeEditingSession.ResolveKeyboardCursor(
            _session.SelectedRange,
            fallbackCurrent);
        var navigation = _formulaRangeEditingSession.PlanKeyboardNavigation(
            _session.SelectedRange,
            fallbackCurrent,
            FormulaBarAvaloniaInputAdapter.ToFormulaEditorKey(args.Key),
            FormulaEditorKey.None,
            FormulaBarAvaloniaInputAdapter.ToFormulaEditorModifiers(args.KeyModifiers),
            _session.Workbook.GetSheet(current.Sheet),
            Math.Max(1, WorkbookViewportScrollPlanner.CountVisibleScrollableRows(
                _session.Viewport, _session.Workbook.GetSheet(current.Sheet)) - 1),
            Math.Max(1, WorkbookViewportScrollPlanner.CountVisibleScrollableColumns(
                _session.Viewport, _session.Workbook.GetSheet(current.Sheet)) - 1));
        if (navigation is null)
            return false;

        if (!TryApplyFormulaRangeEntryKeyboardSelection(
                navigation.Value.Current,
                navigation.Value.Target,
                navigation.Value.ExtendSelection))
        {
            return false;
        }

        args.Handled = true;
        return true;
    }

    private bool TryToggleFormulaRangeEntrySelectionMode(Key key, KeyModifiers modifiers)
    {
        var editor = GetFormulaRangeEntryEditor();
        if (editor is null || !IsFormulaRangeEntryActive(editor.Text) ||
            !_formulaRangeEditingSession.TryToggleSelectionMode(
                FormulaBarAvaloniaInputAdapter.ToFormulaEditorKey(key),
                FormulaBarAvaloniaInputAdapter.ToFormulaEditorModifiers(modifiers),
                out var plan))
        {
            return false;
        }

        if (plan.EditStatusBarPlan is { } statusBarPlan)
            ApplyFormulaEditStatusBarPlan(statusBarPlan);
        else if (plan.StatusBarModeResourceKey is { } resourceKey)
            RefreshShell(UiText.Get(resourceKey));
        return true;
    }

    private bool TryApplyFormulaRangeEntryKeyboardSelection(
        CellAddress current,
        CellAddress target,
        bool extendSelection)
    {
        var editor = GetFormulaRangeEntryEditor();
        var formulaCell = _session.FormulaEditAddress;
        FormulaRangeEditorSnapshot? snapshot = null;
        if (editor is not null && formulaCell is { } editCell)
        {
            var text = editor.Text ?? "";
            var (selectionStart, selectionLength) = GetFormulaEditorSelection(editor, text.Length);
            snapshot = FormulaRangeEditorSnapshot.Capture(
                text,
                selectionStart,
                selectionLength,
                editCell,
                UseR1C1ReferenceStyle,
                _session.Workbook,
                _formulaRangeEditingSession.PlanKeyboardSelectionRange(current, target, extendSelection));
        }

        if (!FormulaReferenceEditingController.TryApplyKeyboardSelection(
                _formulaRangeEditingSession,
                current,
                target,
                extendSelection,
                snapshot,
                TryApplyFormulaRangeSelection,
                edit => ApplyFormulaRangeEditorEdit(editor!, edit),
                editPlan => _session.SelectRangeForFormulaEdit(
                    editPlan.Range,
                    formulaCell!.Value,
                    editPlan.Anchor),
                (range, anchor, cursor) => TryApplyFormulaRangeSelection(range, anchor, cursor),
                out var result))
        {
            return false;
        }

        if (result.Route != FormulaKeyboardSelectionRoute.DisjointReference)
            return true;

        var range = result.Range;
        _cellAddressText.Text = FormatRangeReference(range);
        RefreshFormulaReferenceHighlights();
        RefreshFormulaReferenceGridHighlights();
        ApplyFormulaEditStatusBarPlan(_formulaRangeEditingSession.BuildEditStatusBarPlan(pointMode: true));
        editor!.Focus();
        return true;
    }

    private bool IsFormulaRangeEntryActive(string? text) =>
        _session.FormulaEditAddress is not null &&
        _formulaRangeEditingSession.IsRangeEntryActive(text);

    private TextBox? GetFormulaRangeEntryEditor()
    {
        if (_formulaBox.IsFocused && IsFormulaRangeEntryActive(_formulaBox.Text))
            return _formulaBox;

        if (_inlineCellEditor is { } inlineEditor &&
            _inlineCellEditAddress is not null &&
            IsFormulaRangeEntryActive(inlineEditor.Text))
        {
            return inlineEditor;
        }

        return IsFormulaRangeEntryActive(_formulaBox.Text) ? _formulaBox : null;
    }

    private TextBox? GetFormulaReferenceHighlightEditor()
    {
        if (_session.FormulaEditAddress is null)
            return null;

        if (_inlineCellEditor is { } inlineEditor &&
            _inlineCellEditAddress is not null &&
            _formulaRangeEditingSession.IsFormulaText(inlineEditor.Text))
        {
            return inlineEditor;
        }

        return _formulaRangeEditingSession.IsFormulaText(_formulaBox.Text) ? _formulaBox : null;
    }

    private bool TryApplyFormulaRangeSelection(CellAddress target, bool extendSelection)
    {
        var selection = _formulaRangeEditingSession.PlanSelection(target, extendSelection);
        return TryApplyFormulaRangeSelection(
            selection.Range,
            selection.Anchor,
            selection.Cursor);
    }

    private bool TryApplyFormulaRangeSelection(
        GridRange range,
        CellAddress selectionAnchor,
        CellAddress selectionCursor,
        string? selectedSheetNameOverride = null,
        string? selectedWorkbookName = null)
    {
        var editor = GetFormulaRangeEntryEditor();
        var formulaCell = _session.FormulaEditAddress;
        if (editor is null || formulaCell is null)
            return false;

        var text = editor.Text ?? "";
        var (selectionStart, selectionLength) = GetFormulaEditorSelection(editor, text.Length);
        var snapshot = FormulaRangeEditorSnapshot.Capture(
            text,
            selectionStart,
            selectionLength,
            formulaCell.Value,
            UseR1C1ReferenceStyle,
            _session.Workbook,
            range,
            selectedSheetNameOverride,
            selectedWorkbookName);
        if (!_formulaRangeEditingSession.TryApplyPointRangeSelectionEdit(
                snapshot,
                _session.Workbook,
                _session.ActiveSheet.Id,
                range,
                selectionAnchor,
                selectionCursor,
                GenerateGetPivotData,
                beforeEditorEdit: null,
                applyEditorEdit: edit => ApplyFormulaRangeEditorEdit(editor, edit),
                afterEditorEdit: editPlan =>
                {
                    if (editPlan.UpdateLocalSelection)
                        _session.SelectRangeForFormulaEdit(range, formulaCell.Value, selectionAnchor);
                },
                out var plan))
        {
            return false;
        }

        if (plan.UpdateLocalSelection)
        {
            _cellAddressText.Text = FormatRangeReference(range);
        }
        RefreshFormulaReferenceHighlights();
        RefreshFormulaReferenceGridHighlights();
        ApplyFormulaEditStatusBarPlan(_formulaRangeEditingSession.BuildEditStatusBarPlan(pointMode: true));
        if (ReferenceEquals(editor, _formulaBox))
            _formulaBox.Focus();
        else
            editor.Focus();

        return true;
    }

    private void SynchronizeFormulaEditors(TextBox source)
    {
        var text = source.Text ?? "";
        if (!ReferenceEquals(source, _formulaBox))
        {
            _inlineCellEditText = text;
            _formulaBox.Text = text;
            _formulaBox.CaretIndex = source.CaretIndex;
            _formulaBox.SelectionStart = source.SelectionStart;
            _formulaBox.SelectionEnd = source.SelectionEnd;
        }
        else if (_inlineCellEditor is { } inlineEditor && _inlineCellEditAddress is not null)
        {
            _inlineCellEditText = text;
            inlineEditor.Text = text;
            inlineEditor.CaretIndex = source.CaretIndex;
            inlineEditor.SelectionStart = source.SelectionStart;
            inlineEditor.SelectionEnd = source.SelectionEnd;
        }
    }

    private void ApplyFormulaRangeEditorEdit(TextBox editor, ExcelTextEdit edit)
    {
        _isApplyingFormulaBoxText = true;
        try
        {
            ApplyTextBoxEdit(editor, edit);
            SetInlineCellEditorSelection(editor, edit);
            SynchronizeFormulaEditors(editor);
        }
        finally
        {
            _isApplyingFormulaBoxText = false;
        }
    }

    private (int Start, int Length) GetFormulaEditorSelection(TextBox editor, int textLength)
    {
        var usesInlineSessionSelection = ReferenceEquals(editor, _inlineCellEditor) &&
            _inlineCellEditAddress is not null;
        var rawStart = usesInlineSessionSelection
            ? _pendingInlineCellCaretIndex ?? _inlineCellEditSelectionStart ?? editor.SelectionStart
            : editor.SelectionStart;
        var rawEnd = usesInlineSessionSelection
            ? _pendingInlineCellCaretIndex ?? _inlineCellEditSelectionEnd ?? editor.SelectionEnd
            : editor.SelectionEnd;
        var start = Math.Clamp(Math.Min(rawStart, rawEnd), 0, textLength);
        var end = Math.Clamp(Math.Max(rawStart, rawEnd), start, textLength);
        return (start, end - start);
    }

    private void SetInlineCellEditorSelection(TextBox editor, ExcelTextEdit edit)
    {
        if (!ReferenceEquals(editor, _inlineCellEditor) || _inlineCellEditAddress is null)
            return;

        var start = Math.Clamp(edit.SelectionStart, 0, edit.Text.Length);
        _inlineCellEditSelectionStart = start;
        _inlineCellEditSelectionEnd = Math.Clamp(
            start + Math.Max(0, edit.SelectionLength),
            start,
            edit.Text.Length);
        _pendingInlineCellCaretIndex = null;
    }

    private static int CalculateInlineCellCaretIndex(
        string text,
        double pointerX,
        double cellWidth,
        double fontSize,
        FontWeight fontWeight,
        FontStyle fontStyle,
        FontFamily fontFamily,
        double leftPadding,
        TextAlignment textAlignment)
    {
        if (string.IsNullOrEmpty(text))
            return 0;

        var textWidth = MeasureInlineCellTextWidth(text, fontSize, fontWeight, fontStyle, fontFamily);
        var textLeft = textAlignment switch
        {
            TextAlignment.Center => Math.Max(leftPadding, (cellWidth - textWidth) / 2),
            TextAlignment.Right => Math.Max(leftPadding, cellWidth - leftPadding - textWidth),
            _ => leftPadding
        };
        var relativeX = Math.Clamp(pointerX - textLeft, 0, textWidth);
        var closestIndex = 0;
        var closestDistance = double.MaxValue;
        for (var i = 0; i <= text.Length; i++)
        {
            var prefixWidth = i == 0
                ? 0
                : MeasureInlineCellTextWidth(text[..i], fontSize, fontWeight, fontStyle, fontFamily);
            var distance = Math.Abs(prefixWidth - relativeX);
            if (distance < closestDistance)
            {
                closestDistance = distance;
                closestIndex = i;
            }
        }

        return closestIndex;
    }

    // Caches for inline text-width measurement and Shrink-to-fit font resolution — mirrors WPF's
    // GridView.TextLayoutCache.cs (_textWidthLayoutCache / _shrinkTextLayoutCache): both are hot
    // paths invoked per visible cell on every BuildSheetGrid rebuild (scroll/zoom/edit refresh), and
    // an uncached ResolveShrinkToFitFontSize can construct hundreds of fresh FormattedText objects
    // for a single large-font Shrink-to-fit cell (Excel allows fonts up to 409pt, and the loop steps
    // down in whole-DIP increments). Capped + clear-on-overflow like the WPF caches, since these are
    // static/UI-thread-only exactly like their WPF counterparts.
    private const int TextWidthMeasurementCacheLimit = 32768;
    private const int ShrinkToFitFontSizeCacheLimit = 32768;
    // Per THREAD, not per process: the "UI-thread-only" assumption above holds for the shipping app,
    // which has one UI thread, but not for a process running several (the headless test sessions).
    // A plain Dictionary written from two threads can corrupt its buckets, and these are written on
    // every grid rebuild. Thread-static keeps the cache hit rate and makes that impossible.
    [ThreadStatic] private static Dictionary<TextWidthMeasurementKey, double>? _textWidthMeasurementCache;
    [ThreadStatic] private static Dictionary<ShrinkToFitFontSizeKey, double>? _shrinkToFitFontSizeCache;

    private static Dictionary<TextWidthMeasurementKey, double> TextWidthMeasurementCache =>
        _textWidthMeasurementCache ??= [];

    private static Dictionary<ShrinkToFitFontSizeKey, double> ShrinkToFitFontSizeCache =>
        _shrinkToFitFontSizeCache ??= [];

    private readonly record struct TextWidthMeasurementKey(
        string Text,
        double FontSize,
        FontWeight FontWeight,
        FontStyle FontStyle,
        string FontFamilyName);

    private readonly record struct ShrinkToFitFontSizeKey(
        string Text,
        FontWeight FontWeight,
        FontStyle FontStyle,
        double RequestedFontSize,
        double AvailableWidth);

    private static double MeasureInlineCellTextWidth(
        string text,
        double fontSize,
        FontWeight fontWeight,
        FontStyle fontStyle,
        FontFamily? fontFamily = null)
    {
        fontFamily ??= FontFamily.Default;
        var key = new TextWidthMeasurementKey(text, fontSize, fontWeight, fontStyle, fontFamily.ToString());
        if (TextWidthMeasurementCache.TryGetValue(key, out var cachedWidth))
            return cachedWidth;

        if (TextWidthMeasurementCache.Count >= TextWidthMeasurementCacheLimit)
            TextWidthMeasurementCache.Clear();

        var formatted = new FormattedText(
            text,
            CultureInfo.InvariantCulture,
            FlowDirection.LeftToRight,
            new Typeface(fontFamily, fontStyle, fontWeight),
            Math.Max(1, fontSize),
            Brushes.Black);
        TextWidthMeasurementCache.Add(key, formatted.Width);
        return formatted.Width;
    }

    // Minimum font size (in DIPs) Shrink to fit will reduce to, mirroring WPF's
    // GridView.Rendering.cs floor of ToDisplayFontSize(6) — 6pt converted to DIPs.
    private const double ShrinkToFitMinimumFontSize = 6.0 * (96.0 / 72.0);

    /// <summary>
    /// Shrinks <paramref name="requestedFontSize"/> in whole-DIP steps until <paramref name="text"/>
    /// fits within <paramref name="availableWidth"/>, floored at <see cref="ShrinkToFitMinimumFontSize"/>.
    /// Mirrors WPF's GridView.cs ResolveShrinkFontSize so Shrink to fit behaves the same on both hosts.
    /// The resolved size is memoized per (text, font, requested size, available width) — see
    /// <see cref="ShrinkToFitFontSizeCache"/> — so repeated BuildSheetGrid rebuilds (scroll/zoom/edit)
    /// don't re-run the whole-DIP search loop from scratch for every visible Shrink-to-fit cell.
    /// </summary>
    private static double ResolveShrinkToFitFontSize(
        string text,
        FontWeight fontWeight,
        FontStyle fontStyle,
        double requestedFontSize,
        double availableWidth)
    {
        if (string.IsNullOrEmpty(text) || requestedFontSize <= ShrinkToFitMinimumFontSize || availableWidth <= 0)
            return Math.Min(requestedFontSize, ShrinkToFitMinimumFontSize);

        var key = new ShrinkToFitFontSizeKey(text, fontWeight, fontStyle, requestedFontSize, availableWidth);
        if (ShrinkToFitFontSizeCache.TryGetValue(key, out var cachedFontSize))
            return cachedFontSize;

        if (ShrinkToFitFontSizeCache.Count >= ShrinkToFitFontSizeCacheLimit)
            ShrinkToFitFontSizeCache.Clear();

        var fontSize = CellTextShrinkPlanner.ResolveFontSize(
            requestedFontSize,
            availableWidth,
            size => MeasureInlineCellTextWidth(text, size, fontWeight, fontStyle),
            ShrinkToFitMinimumFontSize);

        ShrinkToFitFontSizeCache.Add(key, fontSize);
        return fontSize;
    }

    private void AddSelectionOverlayToGrid(
        AvaloniaGrid grid,
        IReadOnlyList<RowMetric> rowMetrics,
        IReadOnlyList<ColMetric> colMetrics,
        int headerOffset,
        double zoomFactor)
    {
        var thickness = Math.Max(SelectionOutlineThickness, SelectionOutlineThickness * zoomFactor);
        var halfThickness = thickness / 2;

        foreach (var range in _session.SelectedRanges)
        {
            // A lone selected cell that is itself part of a merged region (e.g. clicking once on a
            // merged B2:D2 title cell) arrives here as an anchor-only 1x1 range -- selection never
            // merge-expands it (see WorkbookSession.SetSingleSelectedRange). Excel's selection outline
            // and fill handle always wrap the WHOLE merge, matching AddActiveCellBoxOverlayToGrid's own
            // GetMergeRegion expansion above, so route a merged single cell through the multi-cell
            // layout path using its full merge footprint instead of sizing the rect from its own 1x1
            // metrics (mirroring the WPF host's CalculateSelectionRangeLayout). The equality check below
            // against _session.SelectedRange intentionally still compares the ORIGINAL anchor-only
            // range, since that is what SelectedRange itself holds.
            var layoutRange = IsSingleCellRange(range) && _session.ActiveSheet.GetMergeRegion(range.Start) is { } merge
                ? merge
                : range;

            if (range.Start.Sheet != _session.ActiveSheet.Id ||
                !TryResolveVisibleSelectionGridSpan(
                    layoutRange,
                    rowMetrics,
                    colMetrics,
                    out var rowIndex,
                    out var rowSpan,
                    out var colIndex,
                    out var colSpan,
                    out var hasTopEdge,
                    out var hasLeftEdge,
                    out var hasBottomEdge,
                    out var hasRightEdge))
            {
                continue;
            }

            var outline = new Border
            {
                BorderBrush = SelectionBorder,
                BorderThickness = new Thickness(
                    hasLeftEdge ? thickness : 0,
                    hasTopEdge ? thickness : 0,
                    hasRightEdge ? thickness : 0,
                    hasBottomEdge ? thickness : 0),
                Margin = new Thickness(
                    hasLeftEdge ? -halfThickness : 0,
                    hasTopEdge ? -halfThickness : 0,
                    hasRightEdge ? -halfThickness : 0,
                    hasBottomEdge ? -halfThickness : 0),
                IsHitTestVisible = false,
                ClipToBounds = false,
                ZIndex = 100,
            };
            AutomationProperties.SetAutomationId(outline, "WorksheetSelectionOutline");
            AvaloniaGrid.SetRow(outline, rowIndex + headerOffset);
            AvaloniaGrid.SetRowSpan(outline, rowSpan);
            AvaloniaGrid.SetColumn(outline, colIndex + headerOffset);
            AvaloniaGrid.SetColumnSpan(outline, colSpan);
            grid.Children.Add(outline);

            if (!range.Equals(_session.SelectedRange))
                continue;

            _activeSelectionOutlineVisual = outline;
            _activeSelectionHasTopEdge = hasTopEdge;
            _activeSelectionHasLeftEdge = hasLeftEdge;
            _activeSelectionHasBottomEdge = hasBottomEdge;
            _activeSelectionHasRightEdge = hasRightEdge;

            if (!EnableFillHandleAndCellDragAndDrop || !hasRightEdge || !hasBottomEdge)
                continue;

            var handleSize = Math.Max(AutofillHandleSize, AutofillHandleSize * zoomFactor);
            var handle = new Border
            {
                Width = handleSize,
                Height = handleSize,
                Background = Brushes.White,
                BorderBrush = SelectionBorder,
                BorderThickness = new Thickness(Math.Max(1, zoomFactor)),
                HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
                VerticalAlignment = AvaloniaVerticalAlignment.Bottom,
                Margin = new Thickness(0, 0, -(handleSize / 2), -(handleSize / 2)),
                IsHitTestVisible = false,
                ClipToBounds = false,
                ZIndex = 101,
                Child = new Border
                {
                    Background = SelectionBorder,
                    Margin = new Thickness(Math.Max(1, zoomFactor)),
                },
            };
            AutomationProperties.SetAutomationId(handle, "WorksheetAutofillHandle");
            AvaloniaGrid.SetRow(handle, rowIndex + rowSpan - 1 + headerOffset);
            AvaloniaGrid.SetColumn(handle, colIndex + colSpan - 1 + headerOffset);
            grid.Children.Add(handle);
            _autofillHandleVisual = handle;
        }
    }

    // Excel always draws a dedicated, crisp box tightly around the active cell, independent of
    // the selection outline drawn above: AddSelectionOverlayToGrid only turns on a perimeter edge
    // (BorderThickness side) where the *whole selected range's* Start/End row or column happens to
    // be visible, so once the range's own perimeter is off-screen (e.g. after Select All, scrolled
    // away from A1/the last cell) or the active cell sits at an interior position of the selected
    // range, no border was drawn around it at all. Draw the active cell's own box independently,
    // on top of the selection fill/outline, whenever the active cell resolves to a visible span.
    private void AddActiveCellBoxOverlayToGrid(
        AvaloniaGrid grid,
        IReadOnlyList<RowMetric> rowMetrics,
        IReadOnlyList<ColMetric> colMetrics,
        int headerOffset,
        double zoomFactor)
    {
        if (_session.ActiveCell.Sheet != _session.ActiveSheet.Id)
            return;

        var activeCellRange = _session.ActiveSheet.GetMergeRegion(_session.ActiveCell)
            ?? new GridRange(_session.ActiveCell, _session.ActiveCell);

        if (!TryResolveVisibleSelectionGridSpan(
                activeCellRange,
                rowMetrics,
                colMetrics,
                out var rowIndex,
                out var rowSpan,
                out var colIndex,
                out var colSpan,
                out _,
                out _,
                out _,
                out _))
        {
            return;
        }

        var thickness = Math.Max(SelectionOutlineThickness, SelectionOutlineThickness * zoomFactor);
        var halfThickness = thickness / 2;
        var activeCellBox = new Border
        {
            BorderBrush = SelectionBorder,
            BorderThickness = new Thickness(thickness),
            Margin = new Thickness(-halfThickness),
            IsHitTestVisible = false,
            ClipToBounds = false,
            ZIndex = 100,
        };
        AutomationProperties.SetAutomationId(activeCellBox, "WorksheetActiveCellBox");
        AvaloniaGrid.SetRow(activeCellBox, rowIndex + headerOffset);
        AvaloniaGrid.SetRowSpan(activeCellBox, rowSpan);
        AvaloniaGrid.SetColumn(activeCellBox, colIndex + headerOffset);
        AvaloniaGrid.SetColumnSpan(activeCellBox, colSpan);
        grid.Children.Add(activeCellBox);
    }

    /// <summary>
    /// R75-render-selection-marquee-4-2: minimal port of the WPF host's GridView.Overlays.cs
    /// RenderMarchingAnts -- this Avalonia shell drew NO Copy/Cut marquee at all around
    /// <see cref="_clipboardMarqueeRange"/>, so a Paste happening well after a Copy/Cut gave the
    /// user no visual reminder of which range was actually being pasted. This draws a static
    /// (non-animated) black dashed rectangle around the source range instead of the WPF host's
    /// animated black/white "marching ants" (a DispatcherTimer-driven dash-offset repaint over a
    /// dedicated overlay layer) -- that animation infrastructure is out of scope for this minimal
    /// port; a static dashed outline is still a large improvement over nothing.
    /// </summary>
    private void AddClipboardMarqueeOverlayToGrid(
        AvaloniaGrid grid,
        IReadOnlyList<RowMetric> rowMetrics,
        IReadOnlyList<ColMetric> colMetrics,
        int headerOffset,
        double zoomFactor)
    {
        if (_clipboardMarqueeRange is not { } range)
            return;

        // The marquee only belongs on the sheet the range was copied/cut from -- Excel hides the
        // marching ants while any other sheet is active. _clipboardMarqueeRange is not cleared on
        // a sheet switch, so without this check a same-numbered range (e.g. A1:B2) on an unrelated
        // sheet would draw a marquee for cells that were never copied there (matching the WPF
        // host's identical ActiveSheetId guard in RenderMarchingAnts).
        if (range.Start.Sheet != _session.ActiveSheet.Id || range.End.Sheet != _session.ActiveSheet.Id)
            return;

        if (!TryResolveVisibleSelectionGridSpan(
                range,
                rowMetrics,
                colMetrics,
                out var rowIndex,
                out var rowSpan,
                out var colIndex,
                out var colSpan,
                out _,
                out _,
                out _,
                out _))
        {
            return;
        }

        var thickness = Math.Max(1.5, 1.5 * zoomFactor);
        var marquee = new AvaloniaRectangle
        {
            Stroke = ClipboardMarqueeBrush,
            StrokeThickness = thickness,
            StrokeDashArray = new AvaloniaList<double>([4, 3]),
            IsHitTestVisible = false,
            ClipToBounds = false,
            ZIndex = 90,
        };
        AutomationProperties.SetAutomationId(marquee,
            _clipboardMarqueeIsCut ? "WorksheetClipboardCutMarquee" : "WorksheetClipboardCopyMarquee");
        AvaloniaGrid.SetRow(marquee, rowIndex + headerOffset);
        AvaloniaGrid.SetRowSpan(marquee, rowSpan);
        AvaloniaGrid.SetColumn(marquee, colIndex + headerOffset);
        AvaloniaGrid.SetColumnSpan(marquee, colSpan);
        grid.Children.Add(marquee);
    }

    /// <summary>
    /// R119-avalonia-drag-preview: while a fill-handle drag is in progress, draws a dashed
    /// rectangle around the union of the source range and the live drag target -- mirrors the
    /// WPF host's RenderAutofillPreview/AutofillPreviewPen (GridView.Overlays.cs), which repaints
    /// this on every pointer move via InvalidateVisual. Avalonia has no DrawingContext repaint for
    /// the sheet grid (it is a rebuilt Border-tree), so this overlay is only ever visible when the
    /// caller (ContinueAutofillDrag) triggers a grid rebuild after updating <see cref="_autofillTarget"/>;
    /// without that rebuild call this method is dead code, just like the WPF pen would be dead
    /// paint logic without its own InvalidateVisual call.
    /// </summary>
    private void AddAutofillPreviewOverlayToGrid(
        AvaloniaGrid grid,
        IReadOnlyList<RowMetric> rowMetrics,
        IReadOnlyList<ColMetric> colMetrics,
        int headerOffset,
        double zoomFactor)
    {
        if (!_autofillDragging ||
            _autofillSourceRange is not { } source ||
            _autofillTarget is not { } target ||
            source.Start.Sheet != _session.ActiveSheet.Id)
        {
            return;
        }

        var previewStart = new CellAddress(
            source.Start.Sheet,
            Math.Min(source.Start.Row, target.Row),
            Math.Min(source.Start.Col, target.Col));
        var previewEnd = new CellAddress(
            source.Start.Sheet,
            Math.Max(source.End.Row, target.Row),
            Math.Max(source.End.Col, target.Col));

        if (!TryResolveVisibleSelectionGridSpan(
                new GridRange(previewStart, previewEnd),
                rowMetrics,
                colMetrics,
                out var rowIndex,
                out var rowSpan,
                out var colIndex,
                out var colSpan,
                out _,
                out _,
                out _,
                out _))
        {
            return;
        }

        var thickness = Math.Max(2.0, 2.0 * zoomFactor);
        var preview = new AvaloniaRectangle
        {
            Stroke = Brushes.Black,
            StrokeThickness = thickness,
            StrokeDashArray = new AvaloniaList<double>([4, 4]),
            IsHitTestVisible = false,
            ClipToBounds = false,
            ZIndex = 95,
        };
        AutomationProperties.SetAutomationId(preview, "WorksheetAutofillPreview");
        AvaloniaGrid.SetRow(preview, rowIndex + headerOffset);
        AvaloniaGrid.SetRowSpan(preview, rowSpan);
        AvaloniaGrid.SetColumn(preview, colIndex + headerOffset);
        AvaloniaGrid.SetColumnSpan(preview, colSpan);
        grid.Children.Add(preview);
    }

    /// <summary>
    /// R119-avalonia-drag-preview: while a selection-border-move drag is in progress, draws the
    /// selection-colored outline at the live drag destination -- mirrors the WPF host's
    /// RenderSelectionMovePreview (GridView.Rendering.Selection.cs), which reuses the plain
    /// selection-range outline (no fill handle) and repaints it on every pointer move. See the
    /// doc comment on <see cref="AddAutofillPreviewOverlayToGrid"/> for why this is only ever
    /// visible once ContinueSelectionMoveDrag triggers a grid rebuild.
    /// </summary>
    private void AddSelectionMovePreviewOverlayToGrid(
        AvaloniaGrid grid,
        IReadOnlyList<RowMetric> rowMetrics,
        IReadOnlyList<ColMetric> colMetrics,
        int headerOffset,
        double zoomFactor)
    {
        if (!_selectionMoveDragging ||
            _selectionMovePreviewRange is not { } previewRange ||
            previewRange.Equals(_session.SelectedRange) ||
            previewRange.Start.Sheet != _session.ActiveSheet.Id)
        {
            return;
        }

        if (!TryResolveVisibleSelectionGridSpan(
                previewRange,
                rowMetrics,
                colMetrics,
                out var rowIndex,
                out var rowSpan,
                out var colIndex,
                out var colSpan,
                out var hasTopEdge,
                out var hasLeftEdge,
                out var hasBottomEdge,
                out var hasRightEdge))
        {
            return;
        }

        var thickness = Math.Max(SelectionOutlineThickness, SelectionOutlineThickness * zoomFactor);
        var halfThickness = thickness / 2;
        var preview = new Border
        {
            BorderBrush = SelectionBorder,
            BorderThickness = new Thickness(
                hasLeftEdge ? thickness : 0,
                hasTopEdge ? thickness : 0,
                hasRightEdge ? thickness : 0,
                hasBottomEdge ? thickness : 0),
            Margin = new Thickness(
                hasLeftEdge ? -halfThickness : 0,
                hasTopEdge ? -halfThickness : 0,
                hasRightEdge ? -halfThickness : 0,
                hasBottomEdge ? -halfThickness : 0),
            IsHitTestVisible = false,
            ClipToBounds = false,
            ZIndex = 96,
        };
        AutomationProperties.SetAutomationId(preview, "WorksheetSelectionMovePreview");
        AvaloniaGrid.SetRow(preview, rowIndex + headerOffset);
        AvaloniaGrid.SetRowSpan(preview, rowSpan);
        AvaloniaGrid.SetColumn(preview, colIndex + headerOffset);
        AvaloniaGrid.SetColumnSpan(preview, colSpan);
        grid.Children.Add(preview);
    }

    private static bool TryResolveVisibleSelectionGridSpan(
        GridRange range,
        IReadOnlyList<RowMetric> rowMetrics,
        IReadOnlyList<ColMetric> colMetrics,
        out int rowIndex,
        out int rowSpan,
        out int colIndex,
        out int colSpan,
        out bool hasTopEdge,
        out bool hasLeftEdge,
        out bool hasBottomEdge,
        out bool hasRightEdge)
    {
        rowIndex = -1;
        rowSpan = 0;
        colIndex = -1;
        colSpan = 0;
        hasTopEdge = false;
        hasLeftEdge = false;
        hasBottomEdge = false;
        hasRightEdge = false;

        for (var i = 0; i < rowMetrics.Count; i++)
        {
            var row = rowMetrics[i].Row;
            if (row < range.Start.Row || row > range.End.Row)
                continue;

            if (rowIndex < 0)
                rowIndex = i;
            rowSpan = i - rowIndex + 1;
            hasTopEdge |= row == range.Start.Row;
            hasBottomEdge |= row == range.End.Row;
        }

        for (var i = 0; i < colMetrics.Count; i++)
        {
            var col = colMetrics[i].Col;
            if (col < range.Start.Col || col > range.End.Col)
                continue;

            if (colIndex < 0)
                colIndex = i;
            colSpan = i - colIndex + 1;
            hasLeftEdge |= col == range.Start.Col;
            hasRightEdge |= col == range.End.Col;
        }

        return rowIndex >= 0 && rowSpan > 0 && colIndex >= 0 && colSpan > 0;
    }

    private static bool IsSingleCellRange(GridRange range) =>
        range.Start.Row == range.End.Row && range.Start.Col == range.End.Col;

    private void SheetGridHost_PointerMoved(object? sender, PointerEventArgs args)
    {
        if (IsBorderDrawModeActive)
        {
            _sheetGridHost.Cursor = new Cursor(StandardCursorType.Cross);
            return;
        }

        if (TryGetSplitPanePointerLayout(out var splitLayout))
        {
            var splitPosition = args.GetPosition(_sheetGridHost);
            var splitPointer = new GridPoint(splitPosition.X, splitPosition.Y);
            if (SplitPanePointerPlanner.HitTestScrollbar(
                    splitLayout.Chrome,
                    splitPointer) is { } scrollbarHit)
            {
                _sheetGridHost.Cursor = scrollbarHit.Orientation == SplitPanePointerScrollbarOrientation.Horizontal
                    ? new Cursor(StandardCursorType.SizeWestEast)
                    : new Cursor(StandardCursorType.SizeNorthSouth);
                return;
            }

            var splitHandle = SplitPanePointerPlanner.HitTestDivider(
                splitLayout.Viewport,
                splitPointer,
                splitLayout.Width,
                splitLayout.Height,
                splitLayout.RowHeaderWidth,
                splitLayout.ColumnHeaderHeight,
                splitLayout.MetricScale);
            if (splitHandle != SplitPanePointerHandle.None)
            {
                _sheetGridHost.Cursor = splitHandle == SplitPanePointerHandle.Intersection
                    ? new Cursor(StandardCursorType.SizeAll)
                    : splitHandle == SplitPanePointerHandle.Vertical
                        ? new Cursor(StandardCursorType.SizeWestEast)
                        : new Cursor(StandardCursorType.SizeNorthSouth);
                return;
            }
        }

        if (IsPointerOnAutofillHandle(args))
        {
            _sheetGridHost.Cursor = new Cursor(StandardCursorType.Cross);
            return;
        }

        if (IsPointerOnSelectionMoveBorder(args))
        {
            _sheetGridHost.Cursor = new Cursor(StandardCursorType.SizeAll);
            return;
        }

        _sheetGridHost.Cursor = HasHyperlinkActivationModifier(args.KeyModifiers) &&
            TryResolveCellPointerAddress(args, out var address) &&
            _session.TryGetHyperlinkPlan(address, out _)
                ? new Cursor(StandardCursorType.Hand)
                : Cursor.Default;
    }

    private bool TryInsertFormulaPointReference(CellAddress address)
    {
        var editor = GetFormulaRangeEntryEditor();
        if (editor is null)
            return TryRouteFormulaPointModeSelection(new GridRange(address, address));

        if (!_formulaRangeEditingSession.IsPointModeActive(
                hasRangeEditor: true,
                hasFormulaEditCell: _session.FormulaEditAddress is not null))
        {
            return false;
        }

        return TryApplyFormulaRangeSelection(
            new GridRange(address, address),
            address,
            address);
    }

    private bool IsFormulaRangeEntryActiveForPointMode() =>
        _formulaRangeEditingSession.IsPointModeActive(
            GetFormulaRangeEntryEditor() is not null,
            _session.FormulaEditAddress is not null);

    // WPF/Excel append a comma-separated area when the command modifier is held during formula
    // point mode. Keep the existing reference span intact and track the newly appended span so a
    // subsequent drag replaces only that area, including when the pointed cell is on another tab.
    private bool TryAppendDisjointFormulaPointReference(CellAddress address)
        => TryAppendDisjointFormulaPointRange(new GridRange(address, address));

    private bool TryAppendDisjointFormulaPointRange(GridRange range)
        => TryAppendDisjointFormulaPointRange(range, null, null);

    private bool TryAppendDisjointFormulaPointRange(
        GridRange range,
        string? selectedSheetNameOverride,
        string? selectedWorkbookName)
    {
        var editor = GetFormulaRangeEntryEditor();
        var formulaCell = _session.FormulaEditAddress;
        if (editor is null || formulaCell is null)
            return TryRouteFormulaPointModeSelection(range, append: true);

        var editorText = editor.Text ?? "";
        var (selectionStart, selectionLength) = GetFormulaEditorSelection(editor, editorText.Length);
        var snapshot = FormulaRangeEditorSnapshot.Capture(
            editorText,
            selectionStart,
            selectionLength,
            formulaCell.Value,
            UseR1C1ReferenceStyle,
            _session.Workbook,
            range,
            selectedSheetNameOverride,
            selectedWorkbookName);
        if (!_formulaRangeEditingSession.TryApplyDisjointRangeSelectionEdit(
                snapshot,
                range,
                range.Start,
                range.End,
                includeSheetSpan: false,
                applyEditorEdit: edit => ApplyFormulaRangeEditorEdit(editor, edit),
                afterEditorEdit: editPlan =>
                {
                    if (editPlan.UpdateLocalSelection)
                        _session.SelectRangeForFormulaEdit(range, formulaCell.Value, range.Start);
                },
                out var plan))
        {
            return false;
        }

        if (plan.UpdateLocalSelection)
        {
            _cellAddressText.Text = FormatRangeReference(range);
        }
        RefreshFormulaReferenceHighlights();
        RefreshFormulaReferenceGridHighlights();
        ApplyFormulaEditStatusBarPlan(_formulaRangeEditingSession.BuildEditStatusBarPlan(pointMode: true));
        editor.Focus();
        return true;
    }

    private bool TryContinueFormulaRangeSelectionDrag(CellAddress address)
    {
        if (GetFormulaRangeEntryEditor() is null)
        {
            if (_cellDragSelectionAnchor is not { } sourceAnchor)
                return false;

            var range = _formulaRangeEditingSession.PlanRange(sourceAnchor, address);
            return TryRouteFormulaPointModeSelection(range, extendSelection: true);
        }

        if (_cellDragFormulaPointCursor == address)
            return true;

        _formulaRangeEditingSession.TrackReferenceSpan(
            _cellDragFormulaReferenceStart,
            _cellDragFormulaReferenceLength);
        var applied = TryApplyFormulaRangeSelection(address, extendSelection: true);
        if (applied)
        {
            _cellDragFormulaPointCursor = address;
            _cellDragFormulaReferenceStart = _formulaRangeEditingSession.ReferenceSpan?.Start;
            _cellDragFormulaReferenceLength = _formulaRangeEditingSession.ReferenceSpan?.Length;
        }
        return applied;
    }

    private void TrackFormulaPointDragAnchor(
        CellAddress address,
        int? referenceStart,
        int? referenceLength)
    {
        _cellDragFormulaPointCursor = address;
        _cellDragFormulaReferenceStart = referenceStart;
        _cellDragFormulaReferenceLength = referenceLength;
    }

    private static void RestoreFormulaRangeEditorFocusAfterDrag(TextBox? editor) =>
        editor?.Focus();

    private void FormulaBox_TextChanged(object? sender, TextChangedEventArgs e)
    {
        if (_isApplyingFormulaBoxText)
        {
            return;
        }

        UpdateFormulaRangeEntryStateAfterTextChanged(_formulaBox.Text);
        if (_session.FormulaEditAddress is null)
        {
            ClearFormulaReferenceTextOverlay();
            ClearFormulaReferenceGridHighlights();
            RefreshFormulaReferenceGrips();
            HideFormulaFunctionAutocomplete();
            HideFormulaSignatureHelp();
            return;
        }

        RefreshFormulaReferenceHighlights();
        RefreshFormulaReferenceGridHighlights();
        RefreshFormulaFunctionAutocomplete(_formulaBox);
        RefreshFormulaSignatureHelp(_formulaBox);
    }

    private IReadOnlyList<FormulaReferenceHighlight> GetFormulaReferenceHighlights(string text) =>
        FormulaReferenceEditingController.BuildHighlights(
            text,
            _session.Workbook,
            _session.ActiveSheet.Id,
            _session.FormulaEditAddress ?? _session.ActiveCell);

    private bool IsFormulaReferenceHighlightActive() =>
        _session.FormulaEditAddress is not null &&
        _formulaRangeEditingSession.IsFormulaText(_formulaBox.Text);

    private void RefreshFormulaReferenceHighlights()
    {
        if (!IsFormulaReferenceHighlightActive())
        {
            ClearFormulaReferenceTextOverlay();
            ClearFormulaReferenceGridHighlights();
            return;
        }

        var text = _formulaBox.Text ?? "";
        var highlights = GetFormulaReferenceHighlights(text);
        ApplyFormulaReferenceTextOverlay(_formulaBox, _formulaReferenceTextOverlay, PrimaryInk, text, highlights);

        // R78-render-inplace-editor-5-2: keep the in-cell editor's own overlay in sync too, so the
        // colored reference text renders at the cell being edited in place, not only in the formula
        // bar above (matches the WPF host's dual inline/formula-bar overlay update).
        if (_inlineCellEditor is { } inlineEditor && _inlineCellReferenceTextOverlay is { } inlineOverlay)
        {
            ApplyFormulaReferenceTextOverlay(
                inlineEditor,
                inlineOverlay,
                _inlineCellEditorForeground ?? PrimaryInk,
                text,
                highlights);
        }
    }

    private void AddFormulaReferenceHighlightOverlay(
        Canvas overlay,
        ViewportModel viewport,
        bool showHeadings,
        double zoomFactor)
    {
        if (!IsFormulaReferenceHighlightActive())
            return;

        foreach (var highlight in GetFormulaReferenceHighlights(_formulaBox.Text ?? ""))
        {
            if (highlight.Range is not { } range || range.Start.Sheet != _session.ActiveSheet.Id)
                continue;

            if (!TryGetDisplayedRangeBounds(viewport, range, showHeadings, zoomFactor, out var left, out var top, out var width, out var height))
                continue;

            var brush = FormulaReferenceBrushes[highlight.PaletteIndex % FormulaReferenceBrushes.Count];
            var border = new Border
            {
                Width = width,
                Height = height,
                BorderBrush = brush,
                BorderThickness = new Thickness(2),
                Background = CreateFormulaReferenceFill(brush),
                IsHitTestVisible = false,
            };
            AutomationProperties.SetAutomationId(border, "WorksheetFormulaReferenceHighlight");
            Canvas.SetLeft(border, left);
            Canvas.SetTop(border, top);
            overlay.Children.Add(border);
            _formulaReferenceGridHighlightVisuals.Add(border);
        }
    }

    private void AddFormulaReferenceGripOverlay(
        Canvas overlay,
        ViewportModel viewport,
        bool showHeadings,
        double zoomFactor)
    {
        foreach (var preview in _formulaReferenceGripPreviewVisuals)
            overlay.Children.Remove(preview);
        foreach (var grip in _formulaReferenceGripVisuals)
            overlay.Children.Remove(grip);

        _formulaReferenceGripVisuals.Clear();
        _formulaReferenceGripPreviewVisuals.Clear();
        if (!IsFormulaReferenceHighlightActive())
            return;

        foreach (var highlight in GetFormulaReferenceHighlights(_formulaBox.Text ?? ""))
        {
            if (highlight.Range is not { } range || range.Start.Sheet != _session.ActiveSheet.Id ||
                !TryGetDisplayedRangeBounds(
                    viewport,
                    range,
                    showHeadings,
                    zoomFactor,
                    out var left,
                    out var top,
                    out var width,
                    out var height))
            {
                continue;
            }

            var brush = FormulaReferenceBrushes[highlight.PaletteIndex % FormulaReferenceBrushes.Count];
            var preview = new Border
            {
                Width = width,
                Height = height,
                BorderBrush = brush,
                BorderThickness = new Thickness(2),
                Background = CreateFormulaReferenceFill(brush),
                IsHitTestVisible = false,
                IsVisible = false,
            };
            Canvas.SetLeft(preview, left);
            Canvas.SetTop(preview, top);
            overlay.Children.Add(preview);
            _formulaReferenceGripPreviewVisuals.Add(preview);

            // Keep the visible square small like WPF, but give the pointer a forgiving hit area.
            // The transparent outer border is the actual input target; its child is decorative.
            var grip = new Border
            {
                Width = FormulaReferenceGripHitSize,
                Height = FormulaReferenceGripHitSize,
                Background = Brushes.Transparent,
                Child = new Border
                {
                    Width = FormulaReferenceGripSize,
                    Height = FormulaReferenceGripSize,
                    Background = brush,
                    IsHitTestVisible = false,
                    HorizontalAlignment = AvaloniaHorizontalAlignment.Center,
                    VerticalAlignment = AvaloniaVerticalAlignment.Center,
                },
                Cursor = new Cursor(StandardCursorType.SizeAll),
            };
            AutomationProperties.SetAutomationId(grip, "WorksheetFormulaReferenceGrip");
            AutomationProperties.SetName(
                grip,
                UiText.Format("FormulaPointMode_ResizeGripAutomationNameFormat", highlight.Text));
            Canvas.SetLeft(grip, left + width - FormulaReferenceGripHitSize / 2);
            Canvas.SetTop(grip, top + height - FormulaReferenceGripHitSize / 2);
            grip.PointerPressed += (_, args) =>
                BeginFormulaReferenceDrag(args, grip, preview, highlight);
            overlay.Children.Add(grip);
            _formulaReferenceGripVisuals.Add(grip);
        }
    }

    private void BeginFormulaReferenceDrag(
        PointerPressedEventArgs args,
        Border grip,
        Border preview,
        FormulaReferenceHighlight highlight)
    {
        if (!args.GetCurrentPoint(grip).Properties.IsLeftButtonPressed ||
            highlight.Range is not { } range ||
            GetFormulaReferenceHighlightEditor() is not { } editor)
        {
            return;
        }

        DetachFormulaReferenceDragHandlers();
        if (!_formulaRangeEditingSession.TryBeginReferenceDrag(highlight))
            return;

        _formulaReferenceDragPointer = args.Pointer;
        _formulaReferenceDragGrip = grip;
        _formulaReferenceDragPreviewVisual = preview;
        _formulaReferenceDragEditor = editor;
        UpdateFormulaReferenceDragPreview(range);

        _sheetGridHost.PointerMoved += FormulaReferenceDragPointerMoved;
        _sheetGridHost.PointerReleased += FormulaReferenceDragPointerReleased;
        _sheetGridHost.PointerCaptureLost += FormulaReferenceDragPointerCaptureLost;
        args.Pointer.Capture(_sheetGridHost);
        args.Handled = true;
    }

    private void FormulaReferenceDragPointerMoved(object? sender, PointerEventArgs args)
    {
        if (!_formulaRangeEditingSession.IsReferenceDragActive)
            return;

        if (TryResolveCellPointerAddress(args, out var targetCell) &&
            _formulaRangeEditingSession.PlanActiveReferenceDrag(targetCell) is { } previewRange)
        {
            UpdateFormulaReferenceDragPreview(previewRange);
        }

        args.Handled = true;
    }

    private void FormulaReferenceDragPointerReleased(object? sender, PointerReleasedEventArgs args)
    {
        if (!_formulaRangeEditingSession.IsReferenceDragActive)
            return;

        var highlight = _formulaRangeEditingSession.EndReferenceDrag();
        var editor = _formulaReferenceDragEditor;
        var pointer = _formulaReferenceDragPointer;
        var targetResolved = TryResolveCellPointerAddress(args, out var targetCell);

        DetachFormulaReferenceDragHandlers();
        pointer?.Capture(null);
        ClearFormulaReferenceDragState();

        if (editor is not null && highlight is not null && targetResolved &&
            _formulaRangeEditingSession.PlanReferenceDrag(highlight, targetCell) is { } newRange)
        {
            TryApplyFormulaReferenceResize(editor, highlight, newRange);
        }

        args.Handled = true;
    }

    private void FormulaReferenceDragPointerCaptureLost(object? sender, PointerCaptureLostEventArgs args)
    {
        if (!_formulaRangeEditingSession.IsReferenceDragActive)
            return;

        DetachFormulaReferenceDragHandlers();
        _formulaReferenceDragPointer?.Capture(null);
        ClearFormulaReferenceDragState();
    }

    private void DetachFormulaReferenceDragHandlers()
    {
        _sheetGridHost.PointerMoved -= FormulaReferenceDragPointerMoved;
        _sheetGridHost.PointerReleased -= FormulaReferenceDragPointerReleased;
        _sheetGridHost.PointerCaptureLost -= FormulaReferenceDragPointerCaptureLost;
    }

    private void ClearFormulaReferenceDragState()
    {
        if (_formulaReferenceDragPreviewVisual is { } preview)
            preview.IsVisible = false;

        _formulaReferenceDragPointer = null;
        _formulaReferenceDragGrip = null;
        _formulaReferenceDragPreviewVisual = null;
        _formulaReferenceDragEditor = null;
        _formulaRangeEditingSession.CancelReferenceDrag();
    }

    private void UpdateFormulaReferenceDragPreview(GridRange range)
    {
        if (_formulaReferenceDragGrip is not { } grip ||
            _formulaReferenceDragPreviewVisual is not { } preview ||
            !TryGetDisplayedRangeBounds(
                _session.Viewport,
                range,
                _session.IsShowingHeadings,
                GetActiveZoomFactor(),
                out var left,
                out var top,
                out var width,
                out var height))
        {
            return;
        }

        preview.Width = width;
        preview.Height = height;
        Canvas.SetLeft(preview, left);
        Canvas.SetTop(preview, top);
        preview.IsVisible = true;
        Canvas.SetLeft(grip, left + width - FormulaReferenceGripHitSize / 2);
        Canvas.SetTop(grip, top + height - FormulaReferenceGripHitSize / 2);
    }

    private bool TryApplyFormulaReferenceResize(
        TextBox editor,
        FormulaReferenceHighlight highlight,
        GridRange newRange)
    {
        var text = editor.Text ?? "";
        var edit = _formulaRangeEditingSession.PlanReferenceResizeEdit(
            text,
            highlight,
            newRange,
            UseR1C1ReferenceStyle);

        _isApplyingFormulaBoxText = true;
        try
        {
            ApplyTextBoxEdit(editor, edit);
            SetInlineCellEditorSelection(editor, edit);
            SynchronizeFormulaEditors(editor);
        }
        finally
        {
            _isApplyingFormulaBoxText = false;
        }

        _formulaRangeEditingSession.ApplyReferenceResizeEdit(highlight, edit);
        RefreshFormulaReferenceHighlights();
        RefreshFormulaReferenceGridHighlights();
        editor.Focus();
        return true;
    }

    private void RefreshFormulaReferenceGridHighlights()
    {
        if (_formulaReferenceGridOverlay is not { } overlay)
            return;

        ClearFormulaReferenceGridHighlights();
        AddFormulaReferenceHighlightOverlay(
            overlay,
            _session.Viewport,
            _session.IsShowingHeadings,
            GetActiveZoomFactor());
        RefreshFormulaReferenceGrips();
    }

    private void RefreshFormulaReferenceGrips()
    {
        if (_cellAffordanceOverlay is not { } overlay)
            return;

        AddFormulaReferenceGripOverlay(
            overlay,
            _session.Viewport,
            _session.IsShowingHeadings,
            GetActiveZoomFactor());
    }

    private void ClearFormulaReferenceGridHighlights()
    {
        if (_formulaReferenceGridOverlay is not { } overlay)
        {
            _formulaReferenceGridHighlightVisuals.Clear();
            return;
        }

        foreach (var visual in _formulaReferenceGridHighlightVisuals)
            overlay.Children.Remove(visual);

        _formulaReferenceGridHighlightVisuals.Clear();
    }

    // ── R92-meta-2: function-name AutoComplete popup ────────────────────────────────────────────
    // Ported from the WPF host's RefreshFormulaFunctionAutocomplete/HandleFunctionAutocompleteKeyDown
    // (MainWindow.Editing.cs) onto FormulaFunctionAutocompletePlanner, the same portable planner the
    // host already uses -- so this shell's formula editors (the Formula Bar and the in-cell inline
    // editor) get the same "=SU" -> SUM/SUMIF/... dropdown Windows users already see.

    /// <summary>
    /// Recomputes and shows/hides the function-name AutoComplete popup for the given formula editor
    /// (the in-cell inline editor or the Formula Bar). Called on every formula-editor TextChanged
    /// pass alongside the existing reference-highlight refresh.
    /// </summary>
    private void RefreshFormulaFunctionAutocomplete(TextBox editor)
    {
        var candidates = _formulaRangeEditingSession.RefreshFunctionAutocomplete(
            editor.Text,
            editor.CaretIndex,
            BuiltInFunctions.Names,
            _session.Workbook.NamedRanges.Keys,
            _session.Workbook.Sheets.SelectMany(s => s.StructuredTables).Select(t => t.Name));

        if (candidates.Count == 0)
        {
            HideFormulaFunctionAutocomplete();
            return;
        }

        ShowFormulaFunctionAutocomplete(editor, candidates);
    }

    private void ShowFormulaFunctionAutocomplete(TextBox editor, IReadOnlyList<string> candidates)
    {
        EnsureFunctionAutocompletePopup();
        _functionAutocompleteListBox!.ItemsSource = candidates;
        _functionAutocompleteListBox.SelectedIndex = 0;

        _functionAutocompletePopup!.PlacementTarget = editor;
        _functionAutocompletePopup.Placement = PlacementMode.BottomEdgeAlignedLeft;
        _functionAutocompletePopup.IsOpen = true;
    }

    private void HideFormulaFunctionAutocomplete()
    {
        if (_functionAutocompletePopup is not null)
            _functionAutocompletePopup.IsOpen = false;
        _formulaRangeEditingSession.ClearFunctionAutocomplete();
    }

    private void EnsureFunctionAutocompletePopup()
    {
        if (_functionAutocompletePopup is not null)
            return;

        _functionAutocompleteListBox = new ListBox
        {
            MaxHeight = 220,
            Focusable = false,
        };
        AutomationProperties.SetAutomationId(_functionAutocompleteListBox, "FormulaFunctionAutocompleteList");
        _functionAutocompletePopup = new Popup
        {
            Child = new Border
            {
                Background = Brushes.White,
                BorderBrush = Brushes.Gray,
                BorderThickness = new Thickness(1),
                Child = _functionAutocompleteListBox,
            },
            IsLightDismissEnabled = false,
        };
    }

    /// <summary>
    /// Handles Up/Down/Tab/Enter/Escape while the function AutoComplete popup is open. Returns true
    /// when the key was consumed by the popup, so the caller skips its normal formula-editing
    /// handling for that key (mirrors the WPF host's HandleFunctionAutocompleteKeyDown).
    /// </summary>
    private bool HandleFunctionAutocompleteKeyDown(TextBox editor, Key key)
    {
        if (!FunctionAutocompleteIsOpen)
            return false;

        return _formulaRangeEditingSession.ExecuteFunctionAutocompleteKey(
            FormulaBarAvaloniaInputAdapter.ToFormulaEditorKey(key),
            _functionAutocompleteListBox!.SelectedIndex,
            index => _functionAutocompleteListBox.SelectedIndex = index,
            _ =>
            {
                if (_functionAutocompleteListBox.SelectedItem is string chosen)
                    CommitFunctionAutocomplete(editor, chosen);
            },
            HideFormulaFunctionAutocomplete);
    }

    private void CommitFunctionAutocomplete(TextBox editor, string chosenName)
    {
        var edit = _formulaRangeEditingSession.CommitFunctionAutocomplete(
            editor.Text ?? "",
            chosenName,
            BuiltInFunctions.Names);
        HideFormulaFunctionAutocomplete();
        ApplyTextBoxEdit(editor, edit);
        SynchronizeFormulaEditors(editor);
    }

    // ── R93-formula-editing-assist: live argument-signature tooltip ─────────────────────────────
    // Ported from the WPF host's RefreshFormulaSignatureHelp/EnsureSignatureHelpPopup
    // (MainWindow.Editing.cs) onto FormulaSignatureHelpPlanner, the same portable planner the host
    // already uses -- so this shell's formula editors (the Formula Bar and the in-cell inline
    // editor) show the same "VLOOKUP(lookup_value, table_array, **col_index_num**, ...)" live
    // argument tooltip Windows users already see once the caret sits inside an open function call.

    /// <summary>
    /// Recomputes and shows/hides the live argument-signature tooltip for the given formula editor.
    /// Called alongside <see cref="RefreshFormulaFunctionAutocomplete"/> on every formula-editor
    /// TextChanged pass (the in-cell inline editor and the Formula Bar).
    /// </summary>
    private void RefreshFormulaSignatureHelp(TextBox editor)
    {
        var info = FormulaSignatureHelpPlanner.Resolve(editor.Text, editor.CaretIndex);
        if (info is null)
        {
            HideFormulaSignatureHelp();
            return;
        }

        EnsureSignatureHelpPopup();
        _signatureHelpTextBlock!.Inlines?.Clear();
        _signatureHelpTextBlock.Inlines?.Add(new Run(info.FunctionName + "("));
        for (var i = 0; i < info.Arguments.Count; i++)
        {
            if (i > 0)
                _signatureHelpTextBlock.Inlines?.Add(new Run(", "));

            var argument = info.Arguments[i];
            var displayName = argument.Optional ? $"[{argument.Name}]" : argument.Name;
            _signatureHelpTextBlock.Inlines?.Add(new Run(displayName)
            {
                FontWeight = argument.IsCurrent ? FontWeight.Bold : FontWeight.Normal
            });
        }
        _signatureHelpTextBlock.Inlines?.Add(new Run(")"));

        _signatureHelpPopup!.PlacementTarget = editor;
        _signatureHelpPopup.Placement = PlacementMode.Top;
        _signatureHelpPopup.IsOpen = true;
    }

    private void HideFormulaSignatureHelp()
    {
        if (_signatureHelpPopup is not null)
            _signatureHelpPopup.IsOpen = false;
    }

    private void EnsureSignatureHelpPopup()
    {
        if (_signatureHelpPopup is not null)
            return;

        _signatureHelpTextBlock = new TextBlock
        {
            Padding = new Thickness(4, 2, 4, 2),
        };
        _signatureHelpPopup = new Popup
        {
            Child = new Border
            {
                Background = Brushes.LightYellow,
                BorderBrush = Brushes.Gray,
                BorderThickness = new Thickness(1),
                Child = _signatureHelpTextBlock,
            },
            IsLightDismissEnabled = false,
        };
    }

    private static void ApplyFormulaReferenceTextOverlay(
        TextBox editor,
        TextBlock overlay,
        IBrush plainBrush,
        string text,
        IReadOnlyList<FormulaReferenceHighlight> highlights)
    {
        overlay.Inlines?.Clear();
        var segments = FormulaReferenceTextSegmentPlanner.CreateSegments(text, highlights);
        if (segments.Count == 0)
        {
            ClearFormulaReferenceTextOverlay(editor, overlay, plainBrush);
            return;
        }

        foreach (var segment in segments)
        {
            AddFormulaReferenceRun(
                overlay,
                segment.Text,
                segment.PaletteIndex is { } paletteIndex
                    ? FormulaReferenceBrushes[paletteIndex % FormulaReferenceBrushes.Count]
                    : plainBrush);
        }

        overlay.IsVisible = true;
        editor.Foreground = Brushes.Transparent;
    }

    private static void AddFormulaReferenceRun(TextBlock overlay, string text, IBrush brush) =>
        overlay.Inlines?.Add(new Run(text) { Foreground = brush });

    private void ClearFormulaReferenceTextOverlay()
    {
        ClearFormulaReferenceTextOverlay(_formulaBox, _formulaReferenceTextOverlay, PrimaryInk);

        if (_inlineCellEditor is { } inlineEditor && _inlineCellReferenceTextOverlay is { } inlineOverlay)
            ClearFormulaReferenceTextOverlay(inlineEditor, inlineOverlay, _inlineCellEditorForeground ?? PrimaryInk);
    }

    private static void ClearFormulaReferenceTextOverlay(TextBox editor, TextBlock overlay, IBrush plainBrush)
    {
        overlay.Inlines?.Clear();
        overlay.IsVisible = false;
        editor.Foreground = plainBrush;
    }

    private static IBrush CreateFormulaReferenceFill(IBrush brush)
    {
        if (brush is ISolidColorBrush solid)
            return new SolidColorBrush(Color.FromArgb(24, solid.Color.R, solid.Color.G, solid.Color.B));

        return Brushes.Transparent;
    }

    /// <summary>
    /// Builds and opens the worksheet cell context menu for <paramref name="anchor"/>. The menu is
    /// produced from the platform-neutral <see cref="WorksheetContextMenuPlanner"/> (same plan WPF
    /// uses), bridged to the shared <see cref="RibbonMenu"/> model, then rendered into an Avalonia
    /// <see cref="ContextMenu"/> by <see cref="AvaloniaContextMenuRenderer"/>.
    /// </summary>
    private void OpenWorksheetCellContextMenu(Control anchor)
    {
        var menu = BuildWorksheetCellContextMenu();
        menu.Open(anchor);
    }

    /// <summary>
    /// Creates the worksheet cell <see cref="ContextMenu"/> from the shared neutral plan. The
    /// dropdown-target flag is computed from the active cell so "Pick From Drop-down List" is enabled
    /// exactly when the cell carries an in-cell list validation or is an AutoFilter header. The other
    /// state flags mirror the WPF host's worksheet context state so comments, notes, filters, pivots,
    /// and hyperlinks expose the same enabled commands on both shells.
    /// </summary>
    private ContextMenu BuildWorksheetCellContextMenu()
    {
        var sheet = _session.ActiveSheet;
        var address = _session.ActiveCell;
        var state = WorksheetContextMenuPlanner.ResolveWorksheetState(sheet, address);
        var commands = WorksheetContextMenuPlanner.BuildCommands(
            WorksheetContextMenuTargetKind.Worksheet,
            state);
        var ribbonMenu = WorksheetContextMenuRibbonAdapter.ToRibbonMenu(commands);
        return AvaloniaContextMenuRenderer.BuildContextMenu(ribbonMenu, DispatchWorksheetContextMenuCommand);
    }

    /// <summary>
    /// Routes a worksheet context-menu command id back to the matching Avalonia document command.
    /// Every action that has a working shell handler (clipboard, clear, insert/delete, sort/filter,
    /// clear filter, data tools, outline grouping, comments/notes, hyperlinks, format cells, pivot
    /// options, pick-from-drop-down) is wired to the same handler the ribbon uses. The drawing/chart/
    /// picture per-target variants (Format Picture/Chart Area, Bring Forward, Selection Pane, etc.) are
    /// raised instead from the Picture/Shape/TextBox/Chart object menus (right-clicking a selected
    /// drawing object) via <see cref="DispatchDrawingObjectContextMenuCommand"/>, so they do not appear
    /// in this worksheet cell menu.
    /// </summary>
    private async void DispatchWorksheetContextMenuCommand(RibbonCommandId commandId)
    {
        if (!Enum.TryParse<WorksheetContextMenuAction>(commandId.Value, out var action))
            return;

        if (!WorkbookApplicationCommandRouter.TryRouteWorksheetContextMenu(action.ToString(), out var route))
            return;

        await WorkbookApplicationCommands.TryExecuteAsync(
            route,
            targetAddress: _session.ActiveCell);
    }

    private static Border CreateCellBorder(
        string text,
        IBrush? background,
        IBrush foreground,
        TextAlignment textAlignment,
        AvaloniaVerticalAlignment verticalAlignment,
        TextWrapping textWrapping,
        FontWeight fontWeight,
        FontStyle fontStyle,
        double fontSize,
        TextDecorationCollection? textDecorations,
        bool selected,
        double indentPadding = 0,
        int textRotation = 0,
        CellStyle? style = null,
        bool showGridlines = true,
        double zoomFactor = 1,
        double cellWidth = 80,
        double cellHeight = 20,
        CellHAlign horizontalAlignment = CellHAlign.General,
        CellVAlign? verticalAlignmentModel = null,
        bool isNumeric = false,
        CfDataBarRenderInstruction? conditionalDataBar = null,
        CfIconRenderInstruction? conditionalIcon = null,
        Control? sparklineLayer = null,
        double horizontalPadding = 8,
        IBrush? patternBrush = null,
        IReadOnlyList<ResolvedCellTextRun>? richRuns = null,
        FlowDirection flowDirection = FlowDirection.LeftToRight,
        CellCommentDisplay? commentDisplay = null,
        FontFamily? fontFamily = null,
        bool suppressDefaultGridlines = false,
        CellBorderNeighborEdges borderNeighbors = default)
    {
        var effectiveText = FormatTextForRotation(text, textRotation);
        var effectiveTextWrapping = textRotation == 255 ? TextWrapping.NoWrap : textWrapping;
        var scaledFontSize = Math.Max(1, fontSize * zoomFactor);
        var scaledHorizontalPadding = horizontalPadding * zoomFactor;
        var scaledIndentPadding = indentPadding * zoomFactor;

        // Rich text runs override cell-level super/subscript — each run carries its own VertAlign
        // and RenderedFontSize from the planner.  When runs are present the TextBlock uses Inlines
        // rather than a single Text string, so cell-level super/sub adjustment is skipped.
        var textMaterialization = CellTextMaterializationPlanner.Plan(
            effectiveText,
            isNumeric,
            style,
            scaledFontSize,
            richRuns,
            CellTextMaterializationProfile.Avalonia);
        var adjustedFontSize = textMaterialization.RenderedFontSize;
        var superSubOffsetDip = textMaterialization.BaselineOffset;

        // HAlign=Fill: repeat the display text to overflow the cell width then rely on ClipToBounds.
        // Approximate char width as 0.6× font size to determine repetition count; always over-allocate
        // so the text reaches the cell edge regardless of proportional font widths.
        var isFillAlign = horizontalAlignment == CellHAlign.Fill;

        // Format Cells > Alignment > Shrink to fit: reduce the font size until the text fits the
        // cell's available width, matching Excel/WPF's GridView.Rendering.cs ResolveCachedShrinkFontSize.
        // Only applies when WrapText is off (Excel disables Shrink to fit whenever Wrap text is on)
        // and is skipped for Fill alignment / rich runs, which resolve sizing independently.
        if (style?.ShrinkToFit == true && textWrapping != TextWrapping.Wrap && !isFillAlign && !textMaterialization.HasRichText)
        {
            var availableWidth = Math.Max(1, cellWidth - (scaledHorizontalPadding * 2) - scaledIndentPadding);
            adjustedFontSize = ResolveShrinkToFitFontSize(effectiveText, fontWeight, fontStyle, adjustedFontSize, availableWidth);
        }

        if (isFillAlign && effectiveText.Length > 0 && cellWidth > 0)
        {
            var approxCharWidth = adjustedFontSize * 0.6 * zoomFactor;
            var approxTextWidth = effectiveText.Length * approxCharWidth;
            if (approxTextWidth < cellWidth)
            {
                var repeatCount = (int)Math.Ceiling(cellWidth / approxTextWidth) + 1;
                effectiveText = string.Concat(Enumerable.Repeat(effectiveText, repeatCount));
            }
        }

        var textMarginTop = superSubOffsetDip;  // negative = up (superscript), positive = down (subscript)
        // Fill alignment and vertical (rotation 255) text always render left-anchored regardless of
        // the cell's configured alignment (see the TextAlignment assignment just below).
        var effectiveTextAlignment = (isFillAlign || textRotation == 255) ? TextAlignment.Left : textAlignment;
        // Format Cells > Alignment > Indent insets from the side the text is anchored to, not always
        // the physical left: a right-aligned cell (explicit Right, or General text-content mirrored
        // into TextAlignment.Right by a right-to-left sheet — see MapCellTextAlignment) anchors its
        // text to the right edge, so the indent must inset from the right margin instead. Left/Center
        // anchored cells (including General content mirrored to Left in an RTL sheet) keep the
        // original left-inset behavior.
        var isRightAnchored = effectiveTextAlignment == TextAlignment.Right;
        var textBlock = new TextBlock
        {
            FontSize = adjustedFontSize,
            FontFamily = fontFamily ?? FontFamily.Default,
            FontWeight = fontWeight,
            FontStyle = fontStyle,
            Foreground = foreground,
            TextAlignment = effectiveTextAlignment,
            TextWrapping = isFillAlign ? TextWrapping.NoWrap : effectiveTextWrapping,
            TextTrimming = TextTrimming.None,
            VerticalAlignment = verticalAlignment,
            Margin = new Thickness(
                scaledHorizontalPadding + (isRightAnchored ? 0 : scaledIndentPadding),
                textMarginTop,
                scaledHorizontalPadding + (isRightAnchored ? scaledIndentPadding : 0),
                0),
            // Base bidi (UAX #9) direction for shaping/reordering mixed-direction runs (e.g. Arabic
            // text with embedded Latin words/digits) — resolved per-cell from the sheet's Right-to-left
            // view flag and the cell's own Format Cells ▸ Alignment ▸ Text direction override. Was
            // previously always the FlowDirection default (LeftToRight); see MapCellFlowDirection.
            FlowDirection = flowDirection,
        };

        // Per-run rich text: populate Inlines (one Run per resolved run) when present.
        // Each Run carries its own font size, weight, style, color, decorations, and baseline
        // alignment — the planner has already coalesced null props against the cell style.
        // Otherwise fall back to a single plain-text string (existing path).
        if (textMaterialization.HasRichText)
        {
            CellRichTextInlinesBuilder.Build(
                textMaterialization.RunSegments,
                textBlock.Inlines!,
                color => Brush(color));
        }
        else
        {
            textBlock.Text = effectiveText;
            textBlock.TextDecorations = textDecorations;
        }

        var content = CellTextOrientationLayoutPlanner.HasTextOrientation(textRotation)
            ? CreateOrientedCellContent(
                textBlock,
                cellWidth,
                cellHeight,
                horizontalAlignment,
                verticalAlignmentModel,
                textMaterialization.Formatting.IsNumericOrDate,
                scaledIndentPadding,
                textRotation,
                effectiveTextWrapping,
                style,
                borderNeighbors,
                isEffectivelyRightToLeft: flowDirection == FlowDirection.RightToLeft,
                zoomFactor: zoomFactor)
            : CreateDefaultCellContent(
                textBlock,
                style,
                conditionalDataBar,
                conditionalIcon,
                zoomFactor,
                scaledIndentPadding,
                sparklineLayer,
                patternBrush,
                borderNeighbors,
                isRightToLeft: flowDirection == FlowDirection.RightToLeft);

        // Selected cells get a faint translucent-green wash over their content (matching the WPF grid's
        // SelectionBrush), so a multi-cell selection reads as a light highlight rather than bare green
        // gridlines — the wash is drawn ON TOP of any cell fill so styled fills still show through.
        Control cellContent = content;
        if (selected)
        {
            var overlayHost = new AvaloniaGrid { ClipToBounds = true };
            overlayHost.Children.Add(content);
            overlayHost.Children.Add(new AvaloniaRectangle
            {
                Fill = SelectionFill,
                IsHitTestVisible = false,
            });
            cellContent = overlayHost;
        }

        // Comment/note corner indicator: small top-right triangle, drawn above selection wash so it
        // stays visible on a selected cell too. Color mirrors WPF's CommentIndicatorBrush — red for a
        // legacy note, purple (#7C379E) for a threaded comment or a cell that mixes both kinds.
        if (commentDisplay is { } indicatorComment)
        {
            var indicatorHost = new AvaloniaGrid { ClipToBounds = true };
            indicatorHost.Children.Add(cellContent);
            indicatorHost.Children.Add(CreateCommentIndicatorLayer(indicatorComment.Kind, zoomFactor));
            cellContent = indicatorHost;
        }

        // Gridline/selection border thickness scales with zoom so it grows together with cell
        // content/text — matching Excel/WPF where the whole grid (gridlines included) is scaled by a
        // single RenderTransform (see MainWindow.ViewCommands.cs), instead of staying a razor-thin
        // fixed 1 DIP line at high zoom while everything else quadruples in size.
        var scaledBorderThickness = Math.Max(1, zoomFactor);
        var defaultBorderBrush = suppressDefaultGridlines
            ? background ?? patternBrush ?? Brushes.Transparent
            : GridLine;
        return new Border
        {
            Background = background,
            BorderBrush = showGridlines ? defaultBorderBrush : Brushes.Transparent,
            BorderThickness = showGridlines
                ? new Thickness(scaledBorderThickness)
                : new Thickness(0),
            ClipToBounds = true,
            Child = cellContent,
        };
    }

    private static AvaloniaGrid CreateDefaultCellContent(
        TextBlock textBlock,
        CellStyle? style,
        CfDataBarRenderInstruction? conditionalDataBar = null,
        CfIconRenderInstruction? conditionalIcon = null,
        double zoomFactor = 1,
        double scaledIndentPadding = 0,
        Control? sparklineLayer = null,
        IBrush? patternBrush = null,
        CellBorderNeighborEdges borderNeighbors = default,
        bool isRightToLeft = false)
    {
        var content = new AvaloniaGrid { ClipToBounds = true };

        // Sparklines and data bars render behind the text; add them first so they sit at the bottom
        // of the z-order.
        if (sparklineLayer is not null)
            content.Children.Add(sparklineLayer);

        // Data bars render behind the text; add them first so they sit at the bottom of the z-order.
        if (conditionalDataBar is { } bar)
            content.Children.Add(CreateConditionalDataBarLayer(bar, zoomFactor));

        // Pattern fill overlay: rendered on top of the Border background (solid/gradient) but below
        // the cell text.  A full-cell Rectangle with a DrawingBrush or semi-transparent SolidBrush
        // produces the hatch/dot pattern.  Mirrors WPF DrawFillPattern compositing order.
        if (patternBrush is not null)
            content.Children.Add(new AvaloniaRectangle { Fill = patternBrush });

        // Icon-set glyphs occupy a gutter next to the icon and push the cell text away from it —
        // on the cell's left edge for LTR (icon pinned left), or on the RIGHT edge for an RTL sheet
        // (icon pinned right, mirroring Excel/WPF's ConditionalIconCellLayoutPlanner isRightToLeft
        // branch and how data bars/row headers/alignment already mirror there) (R68-render-
        // conditional-format-icon-6-3).
        if (conditionalIcon is { } icon)
        {
            var gutter = icon.TextGutter * zoomFactor;
            if (gutter > 0)
            {
                var existing = textBlock.Margin;
                textBlock.Margin = isRightToLeft
                    ? new Thickness(
                        existing.Left,
                        existing.Top,
                        Math.Max(existing.Right, gutter + scaledIndentPadding),
                        existing.Bottom)
                    : new Thickness(
                        Math.Max(existing.Left, gutter + scaledIndentPadding),
                        existing.Top,
                        existing.Right,
                        existing.Bottom);
            }
        }

        // "Show Icon Only" (ShowValue=false) hides the cell text entirely so just the icon glyph
        // renders — mirroring WPF's GridView.ConditionalIcons.cs ShouldDrawText=false /
        // GridView.Rendering.cs skip-draw-text behavior (R79-render-cf-icon-showonly-5-2). Without
        // this, the text still rendered on top of the icon gutter area since only the gutter
        // spacing (not the text itself) was conditioned on ShowValue.
        if (conditionalIcon is not { ShowValue: false })
            content.Children.Add(textBlock);

        if (conditionalIcon is { } iconGlyph)
            content.Children.Add(CreateConditionalIconLayer(iconGlyph, zoomFactor, isRightToLeft));

        AddStyledCellBorderOverlay(content, style, borderNeighbors, zoomFactor);
        return content;
    }

    private static Control CreateConditionalDataBarLayer(CfDataBarRenderInstruction bar, double zoomFactor)
    {
        var horizontalInset = bar.HorizontalInset * zoomFactor;
        var verticalInset = bar.VerticalInset * zoomFactor;
        var color = Color.FromRgb(bar.FillColor.R, bar.FillColor.G, bar.FillColor.B);

        // P53: mirror WPF's gradient direction (GridView.ConditionalDataBars.cs) — a negative bar's
        // gradient flows from solid (away from the axis) to faded (toward the axis), i.e. the
        // reverse of a positive bar's light-to-solid left-to-right ramp.
        IBrush fill;
        if (bar.Gradient)
        {
            var gradientBrush = new LinearGradientBrush
            {
                StartPoint = new RelativePoint(0, 0, RelativeUnit.Relative),
                EndPoint = new RelativePoint(1, 0, RelativeUnit.Relative),
            };
            if (bar.IsNegative)
            {
                gradientBrush.GradientStops.Add(new GradientStop(color, 0));
                gradientBrush.GradientStops.Add(new GradientStop(Color.FromArgb(90, color.R, color.G, color.B), 1));
            }
            else
            {
                gradientBrush.GradientStops.Add(new GradientStop(Color.FromArgb(90, color.R, color.G, color.B), 0));
                gradientBrush.GradientStops.Add(new GradientStop(color, 1));
            }
            fill = gradientBrush;
        }
        else
        {
            fill = new SolidColorBrush(color);
        }

        var rectangle = new AvaloniaRectangle
        {
            Fill = fill,
            // Horizontal extent is set by the hosting panel at arrange time; the rectangle only
            // applies the vertical inset so the bar is shorter than the cell.
            Margin = new Thickness(0, verticalInset, 0, verticalInset),
            IsHitTestVisible = false,
        };
        if (bar.Border)
        {
            // P53: use the authored border color when supplied, matching WPF, instead of always
            // stroking with the bar's own fill color.
            var borderColor = bar.BorderColor is { } bc
                ? Color.FromRgb(bc.R, bc.G, bc.B)
                : color;
            rectangle.Stroke = new SolidColorBrush(borderColor);
            rectangle.StrokeThickness = 0.75 * zoomFactor;
        }

        // P53: zero-crossing axis line for a negative-axis data bar, mirroring WPF's
        // GridView.ConditionalDataBars.cs (drawn only when the axis sits strictly inside the cell).
        Control? axisLine = null;
        if (bar.AxisFraction > 0d && bar.AxisFraction < 1d)
        {
            var axisColor = bar.AxisColor is { } ac
                ? Color.FromRgb(ac.R, ac.G, ac.B)
                : Colors.Black;
            axisLine = new AvaloniaRectangle
            {
                Fill = new SolidColorBrush(axisColor),
                Width = Math.Max(1d, 1d * zoomFactor),
                Margin = new Thickness(0, verticalInset, 0, verticalInset),
                IsHitTestVisible = false,
            };
        }

        // Width is resolved relative to the cell's drawable content area via a binding-free
        // panel that places the fraction-sized rectangle at arrange time.
        return new ConditionalDataBarPanel(
            rectangle, bar.StartFraction, bar.FractionWidth, horizontalInset, axisLine, bar.AxisFraction);
    }

    private static Control CreateConditionalIconLayer(CfIconRenderInstruction icon, double zoomFactor, bool isRightToLeft = false)
    {
        const double iconSize = ConditionalIconCellLayoutPlanner.IconSize;
        const double iconLeftInset = ConditionalIconCellLayoutPlanner.IconLeftInset;
        var size = iconSize * zoomFactor;
        var glyph = ConditionalFormatIconGlyphFactory.Create(icon, size);
        // R68-render-conditional-format-icon-6-3: Excel/WPF pin the icon-set glyph to the sheet's
        // LEADING edge, which is the RIGHT edge on a right-to-left sheet (mirroring
        // ConditionalIconCellLayoutPlanner's isRightToLeft branch and how data bars/row headers/cell
        // alignment already mirror there), instead of always the physical left edge.
        var pinnedAlignment = isRightToLeft ? AvaloniaHorizontalAlignment.Right : AvaloniaHorizontalAlignment.Left;
        var insetPadding = isRightToLeft
            ? new Thickness(0, 0, iconLeftInset * zoomFactor, 0)
            : new Thickness(iconLeftInset * zoomFactor, 0, 0, 0);
        return new Border
        {
            Width = (iconLeftInset + iconSize) * zoomFactor,
            HorizontalAlignment = pinnedAlignment,
            VerticalAlignment = AvaloniaVerticalAlignment.Stretch,
            Padding = insetPadding,
            IsHitTestVisible = false,
            Child = new Border
            {
                Width = size,
                Height = size,
                HorizontalAlignment = pinnedAlignment,
                VerticalAlignment = AvaloniaVerticalAlignment.Center,
                Child = glyph,
            },
        };
    }

    /// <summary>
    /// Small filled top-right corner triangle marking a cell that carries a legacy note and/or a
    /// threaded comment — the Avalonia counterpart of WPF's DrawCommentIndicator
    /// (GridView.Rendering.cs). Colors match CommentIndicatorBrush exactly: red for a Note-only
    /// cell, purple #7C379E for ThreadedComment or Mixed (Excel suppresses the note color once a
    /// thread coexists on the same cell).
    /// </summary>
    private static Control CreateCommentIndicatorLayer(CellCommentDisplayKind kind, double zoomFactor)
    {
        const double size = 7;
        var scaledSize = size * zoomFactor;
        var brush = kind == CellCommentDisplayKind.Note
            ? Brushes.Red
            : Brush(0x7C, 0x37, 0x9E);

        var geometry = new StreamGeometry();
        using (var context = geometry.Open())
        {
            context.BeginFigure(new Point(scaledSize, 0), isFilled: true);
            context.LineTo(new Point(scaledSize, scaledSize));
            context.LineTo(new Point(0, 0));
            context.EndFigure(isClosed: true);
        }

        return new global::Avalonia.Controls.Shapes.Path
        {
            Data = geometry,
            Fill = brush,
            Stretch = Stretch.None,
            Width = scaledSize,
            Height = scaledSize,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            VerticalAlignment = AvaloniaVerticalAlignment.Top,
            IsHitTestVisible = false,
        };
    }

    /// <summary>
    /// Hover-card text for a cell's comment/note, mirroring WPF's GridView.CommentPreview.cs
    /// (title on the first line, body below).
    /// </summary>
    private static string FormatCommentTooltip(CellCommentDisplay comment)
    {
        var title = comment.Title;
        var body = comment.Body;
        return string.IsNullOrEmpty(title) ? body : $"{title}{Environment.NewLine}{body}";
    }

    /// <summary>
    /// R88-app-hyperlink-navigation-5-4: the hover tooltip for a hyperlinked cell -- the custom
    /// ScreenTip set via the Insert Hyperlink dialog's ScreenTip... button, falling back to the raw
    /// link target when no custom ScreenTip was set. Returns null when the cell carries no
    /// hyperlink, matching Excel's own behavior of showing nothing for a plain cell.
    /// </summary>
    private static string? FormatHyperlinkTooltip(Sheet? sheet, CellAddress address)
    {
        if (sheet is null || !sheet.Hyperlinks.TryGetValue(address, out var target) || string.IsNullOrWhiteSpace(target))
            return null;

        sheet.HyperlinkMetadata.TryGetValue(address, out var metadata);
        var screenTip = metadata?.ScreenTip;
        return string.IsNullOrWhiteSpace(screenTip) ? target.Trim() : screenTip.Trim();
    }

    /// <summary>
    /// Wrap-width available to a rotated cell's TextBlock before it is measured, matching WPF's
    /// unconditional-of-rotation <c>rect.Width - 4 - indentPx</c> (GridView.Rendering.cs
    /// wrapMaxTextWidth): the indent must be subtracted here too, or a rotated+wrapped+indented cell
    /// measures its wrapped lines wider than the space actually left once CalculateLayout's boundsX
    /// applies the same indent as an offset.
    /// </summary>
    private static double ResolveOrientedWrapMeasureWidth(double cellWidth, double indentPixels, TextWrapping textWrapping) =>
        textWrapping == TextWrapping.Wrap
            ? Math.Max(1, cellWidth - 4 - indentPixels)
            : double.PositiveInfinity;

    private static AvaloniaGrid CreateOrientedCellContent(
        TextBlock textBlock,
        double cellWidth,
        double cellHeight,
        CellHAlign horizontalAlignment,
        CellVAlign? verticalAlignment,
        bool isNumeric,
        double indentPixels,
        int textRotation,
        TextWrapping textWrapping,
        CellStyle? style,
        CellBorderNeighborEdges borderNeighbors = default,
        bool isEffectivelyRightToLeft = false,
        double zoomFactor = 1)
    {
        var content = new AvaloniaGrid { ClipToBounds = true };
        var canvas = new Canvas { ClipToBounds = true };
        var measureWidth = ResolveOrientedWrapMeasureWidth(cellWidth, indentPixels, textWrapping);

        textBlock.Margin = default;
        textBlock.HorizontalAlignment = AvaloniaHorizontalAlignment.Left;
        textBlock.VerticalAlignment = AvaloniaVerticalAlignment.Top;
        textBlock.Measure(new Size(measureWidth, double.PositiveInfinity));
        var desired = textBlock.DesiredSize;
        textBlock.Width = Math.Max(0, desired.Width);
        textBlock.Height = Math.Max(0, desired.Height);

        var layout = CellTextOrientationLayoutPlanner.CalculateLayout(
            new CellTextLayoutRect(0, 0, cellWidth, cellHeight),
            desired.Width,
            desired.Height,
            horizontalAlignment,
            verticalAlignment,
            isNumeric,
            indentPixels,
            textRotation,
            isEffectivelyRightToLeft);
        if (CreateTextRotationTransform(layout.TransformAngle) is { } transform)
        {
            textBlock.RenderTransformOrigin = new RelativePoint(0, 0, RelativeUnit.Relative);
            textBlock.RenderTransform = transform;
        }

        Canvas.SetLeft(textBlock, layout.TextPoint.X);
        Canvas.SetTop(textBlock, layout.TextPoint.Y);
        canvas.Children.Add(textBlock);
        content.Children.Add(canvas);
        AddStyledCellBorderOverlay(content, style, borderNeighbors, zoomFactor);
        return content;
    }

    private static void AddStyledCellBorderOverlay(
        AvaloniaGrid content,
        CellStyle? style,
        CellBorderNeighborEdges borderNeighbors = default,
        double zoomFactor = 1)
    {
        if (style is not { } visibleStyle || !HasVisibleCellBorder(visibleStyle))
            return;

        // CellBorderPanel draws all four edges plus optional diagonals as stroked Lines,
        // supporting dash patterns and correct per-style thicknesses (replaces the old solid
        // Border-strip approach that could not dash and had incorrect Hair/SlantDashDot thickness).
        // borderNeighbors carries the touching neighbor cells' opposing edge styles so a shared
        // grid edge resolves to the heavier/more-prominent style through CellBorderVisualPlanner
        // instead of this cell always winning by paint order.
        content.Children.Add(new CellBorderPanel(visibleStyle, borderNeighbors, zoomFactor));
    }

    private static bool HasVisibleCellBorder(CellStyle? style) =>
        style is not null &&
        (style.BorderTop.Style != BorderStyle.None ||
         style.BorderRight.Style != BorderStyle.None ||
         style.BorderBottom.Style != BorderStyle.None ||
         style.BorderLeft.Style != BorderStyle.None ||
         style.BorderDiagonalDown.Style != BorderStyle.None ||
         style.BorderDiagonalUp.Style != BorderStyle.None);

    private static string FormatTextForRotation(string text, int textRotation) =>
        CellTextOrientationLayoutPlanner.PrepareDisplayText(text, textRotation);

    private static int NormalizeTextRotationForDisplay(int textRotation) =>
        CellTextOrientationLayoutPlanner.NormalizeRotationForDisplay(textRotation);

    private static RotateTransform? CreateTextRotationTransform(double transformAngle) =>
        Math.Abs(transformAngle) <= 0.001 ? null : new RotateTransform(transformAngle);

