            ShowInTaskbar = false,
        };

        var sheetBox = new ListBox
        {
            ItemsSource = hiddenSheets,
            MinWidth = 280,
            MinHeight = 64,
            SelectionMode = SelectionMode.Single,
            SelectedIndex = hiddenSheets.Count > 0 ? 0 : -1,
            Background = Brushes.White,
        };
        AutomationProperties.SetName(sheetBox, UiText.Get("UnhideSheet_UnhideSheet"));
        AutomationProperties.SetAutomationId(sheetBox, "UnhideSheetList");
        AutomationProperties.SetHelpText(sheetBox, UiText.Get("UnhideSheet_SelectTheHiddenWorksheetToMakeVisible"));
        sheetBox.DoubleTapped += (_, _) => Accept();

        var okButton = new Button { Content = UiText.CreateAutomationName(UiText.Get("Common_Ok")) };
        var cancelButton = new Button { Content = UiText.CreateAutomationName(UiText.Get("Common_Cancel")) };
        ApplyDialogButtonChrome(okButton, width: 72, isDefault: true);
        ApplyDialogButtonChrome(cancelButton, width: 72);
        AutomationProperties.SetAutomationId(okButton, "UnhideSheetOkButton");
        AutomationProperties.SetAutomationId(cancelButton, "UnhideSheetCancelButton");

        void Accept()
        {
            if (sheetBox.SelectedItem is not WorkbookHiddenSheet selected)
                return;

            result = selected;
            dialog.Close();
        }

        okButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => dialog.Close();
        sheetBox.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                Accept();
                e.Handled = true;
            }
            else if (e.Key == Key.Escape)
            {
                dialog.Close();
                e.Handled = true;
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Children =
            {
                okButton,
                cancelButton,
            },
        };

        dialog.Content = new StackPanel
        {
            Margin = new Thickness(16),
            Spacing = 8,
            Children =
            {
                new TextBlock { Text = StripDisplayMnemonic(UiText.Get("UnhideSheet_UnhideSheet2")).Replace("_", string.Empty) },
                sheetBox,
                buttonRow,
            },
        };
        dialog.Opened += (_, _) => sheetBox.Focus();

        await dialog.ShowDialog(this);
        return result;
    }

