    private async Task ShowFindDialogAsync()
    {
        if (!TryCommitPendingFormulaEdit())
            return;

        await ShowFindReplaceTabbedDialogAsync(replaceMode: false);
    }

    /// <summary>
    /// The tabbed Find &amp; Replace dialog used by the Find command (Ctrl/Cmd+F) — the Avalonia equivalent of the
    /// WPF <c>FindReplaceDialog</c>. A <see cref="TabControl"/> exposes a "Find" tab and a "Replace" tab that share
    /// the Options area (Within / Search / Look in / Match case / Match entire cell contents) and a results list.
    /// The Replace tab adds a "Replace with:" box; the Replace and Replace All buttons are only visible on that tab.
    /// The dialog stays open so multiple Find Next / Replace operations can run, matching Excel. Find actions route
    /// through <see cref="WorkbookSession.FindNext"/>/<c>FindAll</c>; replace actions through
    /// <see cref="WorkbookSession.ReplaceNextValue"/>/<c>ReplaceAllValues</c>.
    /// </summary>
    private Task ShowFindReplaceTabbedDialogAsync(bool replaceMode = false)
    {
        if (_findReplaceDialog is { IsVisible: true } existing)
        {
            _switchFindReplaceMode?.Invoke(replaceMode);
            if (existing.WindowState == WindowState.Minimized)
                existing.WindowState = WindowState.Normal;
            existing.Activate();
            return Task.CompletedTask;
        }

        var dialog = new Window
        {
            Title = FindReplaceText(FindReplaceDialogText.Title),
            Width = FindReplaceDialogPlanner.Width,
            Height = FindReplaceDialogPlanner.Height,
            MinWidth = FindReplaceDialogPlanner.MinWidth,
            MinHeight = FindReplaceDialogPlanner.MinHeight,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };
        AvaloniaCompactDialogChrome.ApplyWindow(dialog);
        AutomationProperties.SetAutomationId(dialog, "FindReplaceDialog");

        var selectionScopeAtOpen = CaptureFindReplaceSelectionScopeAtOpen();

        string Fr(FindReplaceDialogText text, params object?[] arguments) =>
            FindReplaceText(text, arguments);

        // ── Find tab: "Find what" box ───────────────────────────────────────────
        var findBox = new TextBox { Text = _session.LastFindText, MinWidth = FindReplaceDialogPlanner.FieldMinWidth };
        AutomationProperties.SetName(findBox, Fr(FindReplaceDialogText.FindWhat));
        AutomationProperties.SetAutomationId(findBox, "FindReplaceFindBox");
        ApplyDialogTextBoxChrome(findBox);

        // ── Replace tab: "Find what" + "Replace with" boxes ─────────────────────
        var replaceFindBox = new TextBox { Text = _session.LastFindText, MinWidth = FindReplaceDialogPlanner.FieldMinWidth };
        AutomationProperties.SetName(replaceFindBox, Fr(FindReplaceDialogText.FindWhat));
        AutomationProperties.SetAutomationId(replaceFindBox, "FindReplaceReplaceFindBox");
        ApplyDialogTextBoxChrome(replaceFindBox);

        var replaceWithBox = new TextBox { Text = "", MinWidth = FindReplaceDialogPlanner.FieldMinWidth };
        AutomationProperties.SetName(replaceWithBox, Fr(FindReplaceDialogText.ReplaceWith));
        AutomationProperties.SetAutomationId(replaceWithBox, "FindReplaceReplaceWithBox");
        ApplyDialogTextBoxChrome(replaceWithBox);

        // Keep the two "Find what" boxes in sync so switching tabs preserves the term.
        var syncing = false;
        findBox.TextChanged += (_, _) =>
        {
            if (syncing) return;
            syncing = true;
            replaceFindBox.Text = findBox.Text;
            syncing = false;
        };
        replaceFindBox.TextChanged += (_, _) =>
        {
            if (syncing) return;
            syncing = true;
            findBox.Text = replaceFindBox.Text;
            syncing = false;
        };

        var findFormatButton = CreateFindReplaceFormatButton("FindReplaceFindFormatButton", FindReplaceDialogText.Format);
        var findFormatClearButton = CreateFindReplaceFormatButton("FindReplaceFindClearFormatButton", FindReplaceDialogText.Clear);
        var findChooseFormatButton = CreateFindReplaceFormatButton("FindReplaceFindChooseFormatFromCellButton", FindReplaceDialogText.ChooseFromCell);
        findFormatButton.Margin = new Thickness(FindReplaceDialogPlanner.FormatButtonMargin, 0, 0, 0);
        findFormatClearButton.Margin = new Thickness(FindReplaceDialogPlanner.AdjacentFormatButtonMargin, 0, 0, 0);
        findChooseFormatButton.Margin = new Thickness(FindReplaceDialogPlanner.AdjacentFormatButtonMargin, 0, 0, 0);

        var findTabGrid = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions($"{FindReplaceDialogPlanner.FieldLabelColumnWidth},*,Auto,Auto,Auto"),
            Margin = new Thickness(FindReplaceDialogPlanner.TabContentMargin),
        };
        var findLabel = new TextBlock { Text = Fr(FindReplaceDialogText.FindWhat), VerticalAlignment = AvaloniaVerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
        Grid.SetColumn(findLabel, 0);
        Grid.SetColumn(findBox, 1);
        Grid.SetColumn(findFormatButton, 2);
        Grid.SetColumn(findFormatClearButton, 3);
        Grid.SetColumn(findChooseFormatButton, 4);
        findTabGrid.Children.Add(findLabel);
        findTabGrid.Children.Add(findBox);
        findTabGrid.Children.Add(findFormatButton);
        findTabGrid.Children.Add(findFormatClearButton);
        findTabGrid.Children.Add(findChooseFormatButton);

        var replaceFindFormatButton = CreateFindReplaceFormatButton("FindReplaceReplaceFindFormatButton", FindReplaceDialogText.Format);
        var replaceFindFormatClearButton = CreateFindReplaceFormatButton("FindReplaceReplaceFindClearFormatButton", FindReplaceDialogText.Clear);
        var replaceFindChooseFormatButton = CreateFindReplaceFormatButton("FindReplaceReplaceFindChooseFormatFromCellButton", FindReplaceDialogText.ChooseFromCell);
        var replaceWithFormatButton = CreateFindReplaceFormatButton("FindReplaceReplaceWithFormatButton", FindReplaceDialogText.Format);
        var replaceWithFormatClearButton = CreateFindReplaceFormatButton("FindReplaceReplaceWithClearFormatButton", FindReplaceDialogText.Clear);
        var replaceWithChooseFormatButton = CreateFindReplaceFormatButton("FindReplaceReplaceWithChooseFormatFromCellButton", FindReplaceDialogText.ChooseFromCell);
        replaceFindFormatButton.Margin = new Thickness(FindReplaceDialogPlanner.FormatButtonMargin, 0, 0, 0);
        replaceFindFormatClearButton.Margin = new Thickness(FindReplaceDialogPlanner.AdjacentFormatButtonMargin, 0, 0, 0);
        replaceFindChooseFormatButton.Margin = new Thickness(FindReplaceDialogPlanner.AdjacentFormatButtonMargin, 0, 0, 0);
        replaceWithFormatButton.Margin = new Thickness(FindReplaceDialogPlanner.FormatButtonMargin, 0, 0, 0);
        replaceWithFormatClearButton.Margin = new Thickness(FindReplaceDialogPlanner.AdjacentFormatButtonMargin, 0, 0, 0);
        replaceWithChooseFormatButton.Margin = new Thickness(FindReplaceDialogPlanner.AdjacentFormatButtonMargin, 0, 0, 0);

        var replaceTabPanel = new Grid
        {
            RowDefinitions = new RowDefinitions("Auto,Auto"),
            Margin = new Thickness(FindReplaceDialogPlanner.TabContentMargin),
        };
        var replaceFindRow = new Grid { ColumnDefinitions = new ColumnDefinitions($"{FindReplaceDialogPlanner.FieldLabelColumnWidth},*,Auto,Auto,Auto") };
        var replaceFindLabel = new TextBlock { Text = Fr(FindReplaceDialogText.FindWhat), VerticalAlignment = AvaloniaVerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
        Grid.SetColumn(replaceFindLabel, 0);
        Grid.SetColumn(replaceFindBox, 1);
        Grid.SetColumn(replaceFindFormatButton, 2);
        Grid.SetColumn(replaceFindFormatClearButton, 3);
        Grid.SetColumn(replaceFindChooseFormatButton, 4);
        replaceFindRow.Children.Add(replaceFindLabel);
        replaceFindRow.Children.Add(replaceFindBox);
        replaceFindRow.Children.Add(replaceFindFormatButton);
        replaceFindRow.Children.Add(replaceFindFormatClearButton);
        replaceFindRow.Children.Add(replaceFindChooseFormatButton);
        var replaceWithRow = new Grid { ColumnDefinitions = new ColumnDefinitions($"{FindReplaceDialogPlanner.FieldLabelColumnWidth},*,Auto,Auto,Auto") };
        var replaceWithLabel = new TextBlock { Text = Fr(FindReplaceDialogText.ReplaceWith), VerticalAlignment = AvaloniaVerticalAlignment.Center, Margin = new Thickness(0, 0, 8, 0) };
        Grid.SetColumn(replaceWithLabel, 0);
        Grid.SetColumn(replaceWithBox, 1);
        Grid.SetColumn(replaceWithFormatButton, 2);
        Grid.SetColumn(replaceWithFormatClearButton, 3);
        Grid.SetColumn(replaceWithChooseFormatButton, 4);
        replaceWithRow.Children.Add(replaceWithLabel);
        replaceWithRow.Children.Add(replaceWithBox);
        replaceWithRow.Children.Add(replaceWithFormatButton);
        replaceWithRow.Children.Add(replaceWithFormatClearButton);
        replaceWithRow.Children.Add(replaceWithChooseFormatButton);
        Grid.SetRow(replaceFindRow, 0);
        Grid.SetRow(replaceWithRow, 1);
        replaceTabPanel.Children.Add(replaceFindRow);
        replaceTabPanel.Children.Add(replaceWithRow);

        var findTabItem = new TabItem { Header = Fr(FindReplaceDialogText.Find), Content = findTabGrid };
        AutomationProperties.SetAutomationId(findTabItem, "FindReplaceFindTab");
        var replaceTabItem = new TabItem { Header = Fr(FindReplaceDialogText.Replace), Content = replaceTabPanel };
        AutomationProperties.SetAutomationId(replaceTabItem, "FindReplaceReplaceTab");

        var openTabHeight = FindReplaceDialogPlanner.ShowsReplaceCommands(replaceMode)
            ? FindReplaceDialogPlanner.ReplaceTabHeight
            : FindReplaceDialogPlanner.FindTabHeight;
        var tabs = new TabControl
        {
            Items = { findTabItem, replaceTabItem },
            SelectedIndex = FindReplaceDialogPlanner.ShowsReplaceCommands(replaceMode) ? 1 : 0,
            Height = openTabHeight,
            MinHeight = openTabHeight,
            MaxHeight = openTabHeight,
        };
        AutomationProperties.SetAutomationId(tabs, "FindReplaceTabs");
        AvaloniaCompactDialogChrome.ApplyClassicTabChrome(tabs);
        var findReplaceTabStyle = new Style(selector => selector.OfType<TabItem>());
        findReplaceTabStyle.Setters.Add(new Setter(Layoutable.HeightProperty, 22d));
        findReplaceTabStyle.Setters.Add(new Setter(Layoutable.MinHeightProperty, 22d));
        findReplaceTabStyle.Setters.Add(new Setter(Layoutable.MaxHeightProperty, 22d));
        findReplaceTabStyle.Setters.Add(new Setter(TabItem.PaddingProperty, new Thickness(6, 1)));
        tabs.Styles.Add(findReplaceTabStyle);

        // ── Shared options ──────────────────────────────────────────────────────
        StyleDiff? findFormat = null;
        StyleDiff? replacementFormat = null;
        var optionsControls = CreateFindOptionsControls("FindReplace", defaultLookInIndex: 0);
        var statusLabel = new TextBlock { Foreground = Brush(85, 85, 85), FontSize = 11, MinHeight = 18 };
        AutomationProperties.SetAutomationId(statusLabel, "FindReplaceStatusLabel");
        void UpdateFormatButtons(
            StyleDiff? format,
            Button formatButton,
            Button clearButton)
        {
            UpdateFindReplaceFormatButtonState(
                format,
                formatButton,
                clearButton,
                Fr(FindReplaceDialogText.Format),
                Fr(FindReplaceDialogText.FormatSetButton));
        }

        UpdateFormatButtons(findFormat, findFormatButton, findFormatClearButton);
        UpdateFormatButtons(findFormat, replaceFindFormatButton, replaceFindFormatClearButton);
        UpdateFormatButtons(replacementFormat, replaceWithFormatButton, replaceWithFormatClearButton);
        findFormatButton.Click += async (_, _) =>
        {
            var selectedFormat = await PickFindReplaceFormatAsync(findFormat);
            if (selectedFormat is not null)
            {
                findFormat = selectedFormat;
                UpdateFormatButtons(findFormat, findFormatButton, findFormatClearButton);
            }
        };
        findFormatClearButton.Click += (_, _) =>
        {
            findFormat = null;
            UpdateFormatButtons(findFormat, findFormatButton, findFormatClearButton);
        };
        findChooseFormatButton.Click += (_, _) =>
        {
            findFormat = _session.CreateFormatDiffFromActiveCell();
            UpdateFormatButtons(findFormat, findFormatButton, findFormatClearButton);
        };
        replaceFindFormatButton.Click += async (_, _) =>
        {
            var selectedFormat = await PickFindReplaceFormatAsync(findFormat);
            if (selectedFormat is not null)
            {
                findFormat = selectedFormat;
                UpdateFormatButtons(findFormat, replaceFindFormatButton, replaceFindFormatClearButton);
            }
        };
        replaceFindFormatClearButton.Click += (_, _) =>
        {
            findFormat = null;
            UpdateFormatButtons(findFormat, replaceFindFormatButton, replaceFindFormatClearButton);
        };
        replaceFindChooseFormatButton.Click += (_, _) =>
        {
            findFormat = _session.CreateFormatDiffFromActiveCell();
            UpdateFormatButtons(findFormat, replaceFindFormatButton, replaceFindFormatClearButton);
        };
        replaceWithFormatButton.Click += async (_, _) =>
        {
            var selectedFormat = await PickFindReplaceFormatAsync(replacementFormat);
            if (selectedFormat is not null)
            {
                replacementFormat = selectedFormat;
                UpdateFormatButtons(replacementFormat, replaceWithFormatButton, replaceWithFormatClearButton);
            }
        };
        replaceWithFormatClearButton.Click += (_, _) =>
        {
            replacementFormat = null;
            UpdateFormatButtons(replacementFormat, replaceWithFormatButton, replaceWithFormatClearButton);
        };
        replaceWithChooseFormatButton.Click += (_, _) =>
        {
            replacementFormat = _session.CreateFormatDiffFromActiveCell();
            UpdateFormatButtons(replacementFormat, replaceWithFormatButton, replaceWithFormatClearButton);
        };

        async Task<StyleDiff?> PickFindReplaceFormatAsync(StyleDiff? existingFormat)
        {
            var selection = await ShowFormatCellsInputDialogAsync(initialTabIndex: 2);
            if (selection is null)
                return existingFormat;

            if (!FormatCellsCompactPlanner.TryPlan(selection.Request, out var diff, out var errorMessage))
            {
                statusLabel.Text = errorMessage ?? Fr(FindReplaceDialogText.FormatCellsFailed);
                return existingFormat;
            }

            return diff;
        }

        // ── Results list ────────────────────────────────────────────────────────
        var resultsList = new ListBox { MinHeight = FindReplaceDialogPlanner.ResultsMinimumHeight };
        AutomationProperties.SetName(resultsList, Fr(FindReplaceDialogText.ResultsAutomationName));
        AutomationProperties.SetAutomationId(resultsList, "FindReplaceResultsList");
        resultsList.SelectionChanged += (_, _) =>
        {
            if (resultsList.SelectedItem is WorkbookFindAllMatch match)
                NavigateToFindAllMatch(match);
        };
        resultsList.ItemTemplate = new FuncDataTemplate<WorkbookFindAllMatch>(
            (match, _) =>
            {
                var row = new Grid { ColumnDefinitions = FindReplaceResultColumns() };
                AddFindReplaceResultCell(row, match.Book, 0);
                AddFindReplaceResultCell(row, match.Sheet, 1);
                AddFindReplaceResultCell(row, match.Name, 2);
                AddFindReplaceResultCell(row, match.Cell, 3);
                AddFindReplaceResultCell(row, match.Value, 4);
                AddFindReplaceResultCell(row, match.Formula, 5);
                return row;
            },
            supportsRecycling: true);
        var resultsHeader = new Grid
        {
            ColumnDefinitions = FindReplaceResultColumns(),
            Background = Brush(245, 245, 245),
        };
        AddFindReplaceResultCell(resultsHeader, Fr(FindReplaceDialogText.Book), 0);
        AddFindReplaceResultCell(resultsHeader, Fr(FindReplaceDialogText.Sheet), 1);
        AddFindReplaceResultCell(resultsHeader, Fr(FindReplaceDialogText.Name), 2);
        AddFindReplaceResultCell(resultsHeader, Fr(FindReplaceDialogText.Cell), 3);
        AddFindReplaceResultCell(resultsHeader, Fr(FindReplaceDialogText.Value), 4);
        AddFindReplaceResultCell(resultsHeader, Fr(FindReplaceDialogText.Formula), 5);
        var resultsPanel = new Grid { RowDefinitions = new RowDefinitions("Auto,*") };
        Grid.SetRow(resultsHeader, 0);
        Grid.SetRow(resultsList, 1);
        resultsPanel.Children.Add(resultsHeader);
        resultsPanel.Children.Add(resultsList);
        var resultsBorder = new Border
        {
            BorderBrush = Brush(68, 114, 196),
            BorderThickness = new Thickness(1),
            Background = Brush(242, 242, 242),
            Child = resultsPanel,
        };

        // ── Buttons ─────────────────────────────────────────────────────────────
        var findAllButton = new Button { Content = Fr(FindReplaceDialogText.FindAll), Width = FindReplaceDialogPlanner.FindAllButtonWidth, MinWidth = FindReplaceDialogPlanner.FindAllButtonWidth, Padding = new Thickness(4, 1) };
        AutomationProperties.SetAutomationId(findAllButton, "FindReplaceFindAllButton");
        ApplyDialogButtonChrome(findAllButton);

        var findNextButton = new Button { Content = Fr(FindReplaceDialogText.FindNext), Width = FindReplaceDialogPlanner.FindNextButtonWidth, MinWidth = FindReplaceDialogPlanner.FindNextButtonWidth, Padding = new Thickness(4, 1) };
        AutomationProperties.SetAutomationId(findNextButton, "FindReplaceFindNextButton");
        ApplyDialogButtonChrome(findNextButton, isDefault: true);

        var replaceButton = new Button { Content = Fr(FindReplaceDialogText.Replace), Width = FindReplaceDialogPlanner.ReplaceButtonWidth, MinWidth = FindReplaceDialogPlanner.ReplaceButtonWidth, Padding = new Thickness(4, 1), IsVisible = false };
        AutomationProperties.SetAutomationId(replaceButton, "FindReplaceReplaceButton");
        ApplyDialogButtonChrome(replaceButton);

        var replaceAllButton = new Button { Content = Fr(FindReplaceDialogText.ReplaceAll), Width = FindReplaceDialogPlanner.ReplaceAllButtonWidth, MinWidth = FindReplaceDialogPlanner.ReplaceAllButtonWidth, Padding = new Thickness(4, 1), IsVisible = false };
        AutomationProperties.SetAutomationId(replaceAllButton, "FindReplaceReplaceAllButton");
        ApplyDialogButtonChrome(replaceAllButton);

        var closeButton = new Button { Content = Fr(FindReplaceDialogText.Close), Width = FindReplaceDialogPlanner.CloseButtonWidth, MinWidth = FindReplaceDialogPlanner.CloseButtonWidth, Padding = new Thickness(4, 1), IsCancel = true };
        AutomationProperties.SetAutomationId(closeButton, "FindReplaceCloseButton");
        ApplyDialogButtonChrome(closeButton);

        foreach (var button in new[] { findAllButton, findNextButton, replaceButton, replaceAllButton, closeButton,
                                       findFormatButton, findFormatClearButton, findChooseFormatButton,
                                       replaceFindFormatButton, replaceFindFormatClearButton, replaceFindChooseFormatButton,
                                       replaceWithFormatButton, replaceWithFormatClearButton, replaceWithChooseFormatButton })
        {
            button.Height = FindReplaceDialogPlanner.ActionButtonHeight;
            button.MinHeight = FindReplaceDialogPlanner.ActionButtonHeight;
            button.MaxHeight = FindReplaceDialogPlanner.ActionButtonHeight;
            button.Padding = new Thickness(4, 0);
            button.CornerRadius = new CornerRadius(0);
            button.Background = Brush(221, 221, 221);
            button.BorderBrush = button.IsDefault ? Brush(0, 120, 215) : Brush(112, 112, 112);
        }
        foreach (var textBox in new[] { findBox, replaceFindBox, replaceWithBox })
            textBox.CornerRadius = new CornerRadius(0);

        // The selected TabItem is this renderer's rendering of the cross-app FindReplaceOpenMode;
        // every mode-dependent decision below is resolved through the shared planner projection.
        FindReplaceOpenMode CurrentOpenMode() =>
            FindReplaceDialogPlanner.OpenModeFor(tabs.SelectedItem == replaceTabItem);
        bool OnReplaceTab() => FindReplaceDialogPlanner.ShowsReplaceCommands(CurrentOpenMode());
        string CurrentFindText() => (OnReplaceTab() ? replaceFindBox.Text : findBox.Text) ?? "";

        void FocusSearchBox()
        {
            var target = OnReplaceTab() ? replaceFindBox : findBox;
            FocusDialogControl(target);
            target.SelectAll();
        }

        void UpdateButtonVisibility()
        {
            var isReplaceMode = OnReplaceTab();
            replaceButton.IsVisible = isReplaceMode;
            replaceAllButton.IsVisible = isReplaceMode;
            replaceWithRow.IsVisible = isReplaceMode;
        }
        tabs.SelectionChanged += (_, _) =>
        {
            var tabHeight = OnReplaceTab()
                ? FindReplaceDialogPlanner.ReplaceTabHeight
                : FindReplaceDialogPlanner.FindTabHeight;
            tabs.Height = tabHeight;
            tabs.MinHeight = tabHeight;
            tabs.MaxHeight = tabHeight;
            UpdateButtonVisibility();
            if (dialog.IsVisible)
                Dispatcher.UIThread.Post(FocusSearchBox, DispatcherPriority.Input);
        };
        UpdateButtonVisibility();

        var options = optionsControls;

        FindOptions BuildOptions() => CreateFindOptions(options, findFormat, selectionScopeAtOpen);
        bool MatchCase() => options.MatchCaseBox.IsChecked == true;
        bool MatchEntire() => options.MatchEntireCellBox.IsChecked == true;

        void DoFindNext()
        {
            if (!TryCommitPendingFormulaEdit()) return;
            var r = _session.FindNext(CurrentFindText(), BuildOptions(), MatchCase(), MatchEntire());
            if (!r.Success)
            {
                statusLabel.Text = r.ErrorMessage ?? Fr(FindReplaceDialogText.FindFailed);
                return;
            }
            statusLabel.Text = Fr(
                FindReplaceDialogText.FoundRangeStatus,
                FormatRangeReference(r.SelectedRange!.Value),
                r.MatchIndex,
                r.MatchCount);
            RefreshShell(statusLabel.Text);
        }

        void DoFindAll()
        {
            if (!TryCommitPendingFormulaEdit()) return;
            var search = new FindDialogResult(CurrentFindText(), FindDialogAction.FindAll, BuildOptions(), MatchCase(), MatchEntire());
            var result = _session.FindAll(search.FindText, search.Options, search.MatchCase, search.MatchEntireCell);
            if (!result.Success)
            {
                statusLabel.Text = result.ErrorMessage ?? Fr(FindReplaceDialogText.FindAllFailed);
                return;
            }
            resultsList.ItemsSource = result.Matches;
            statusLabel.Text = result.MatchCount == 0
                ? Fr(FindReplaceDialogText.NoMatchesFound)
                : Fr(FindReplaceDialogText.CellsFoundStatus, result.MatchCount);
            RefreshShell(statusLabel.Text);
        }

        void DoReplace()
        {
            if (!TryCommitPendingFormulaEdit()) return;
            var r = _session.ReplaceNextValue(CurrentFindText(), replaceWithBox.Text ?? "", BuildOptions(), MatchCase(), MatchEntire(), replacementFormat);
            if (!r.Success)
            {
                statusLabel.Text = r.ErrorMessage ?? Fr(FindReplaceDialogText.ReplaceFailed);
                return;
            }
            statusLabel.Text = r.ReplacedCount == 0
                ? (r.MatchCount == 0
                    ? Fr(FindReplaceDialogText.NoMatchesFound)
                    : Fr(FindReplaceDialogText.NoReplaceableMatchFound))
                : Fr(
                    FindReplaceDialogText.ReplacedRangeStatus,
                    FormatRangeReference(r.ReplacedRange!.Value),
                    r.MatchIndex,
                    r.MatchCount);
            RefreshShell(statusLabel.Text);
        }

        void DoReplaceAll()
        {
            if (!TryCommitPendingFormulaEdit()) return;
            var r = _session.ReplaceAllValues(CurrentFindText(), replaceWithBox.Text ?? "", BuildOptions(), MatchCase(), MatchEntire(), replacementFormat);
            if (!r.Success)
            {
                statusLabel.Text = r.ErrorMessage ?? Fr(FindReplaceDialogText.ReplaceFailed);
                return;
            }
            statusLabel.Text = r.ReplacedCount == 0
                ? (r.MatchCount == 0
                    ? Fr(FindReplaceDialogText.NoMatchesFound)
                    : Fr(FindReplaceDialogText.NoReplaceableMatchFound))
                : Fr(FindReplaceDialogText.ReplacedCellsStatus, r.ReplacedCount);
            RefreshShell(statusLabel.Text);
        }

        findNextButton.Click += (_, _) => DoFindNext();
        findAllButton.Click += (_, _) => DoFindAll();
        replaceButton.Click += (_, _) => DoReplace();
        replaceAllButton.Click += (_, _) => DoReplaceAll();
        closeButton.Click += (_, _) => dialog.Close();

        void HandleEnter(KeyEventArgs e)
        {
            if (e.Key == Key.Enter)
            {
                e.Handled = true;
                if (OnReplaceTab()) DoReplace(); else DoFindNext();
            }
            else if (e.Key == Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        }
        findBox.KeyDown += (_, e) => HandleEnter(e);
        replaceFindBox.KeyDown += (_, e) => HandleEnter(e);
        replaceWithBox.KeyDown += (_, e) => HandleEnter(e);

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = FindReplaceDialogPlanner.ActionButtonSpacing,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Children = { findAllButton, findNextButton, replaceButton, replaceAllButton, closeButton },
        };

        var optionsGlyph = new Border
        {
            Width = 18,
            Height = 18,
            CornerRadius = new CornerRadius(9),
            BorderBrush = Brush(64, 64, 64),
            BorderThickness = new Thickness(1),
            Child = new TextBlock
            {
                Text = "⌄",
                FontSize = 12,
                Foreground = Brushes.Black,
                HorizontalAlignment = AvaloniaHorizontalAlignment.Center,
                VerticalAlignment = AvaloniaVerticalAlignment.Center,
                Margin = new Thickness(0, -2, 0, 0),
            },
        };
        var optionsHeaderText = new TextBlock
        {
            Text = Fr(FindReplaceDialogText.Options),
            FontSize = 12,
            Foreground = Brushes.Black,
            VerticalAlignment = AvaloniaVerticalAlignment.Center,
        };
        var optionsHeader = new Button
        {
            Content = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 4,
                Children =
                {
                    optionsGlyph,
                    optionsHeaderText,
                },
            },
            Width = FindReplaceDialogPlanner.OptionsHeaderMinimumWidth,
            MinWidth = FindReplaceDialogPlanner.OptionsHeaderMinimumWidth,
            MaxWidth = FindReplaceDialogPlanner.OptionsHeaderMinimumWidth,
            Height = FindReplaceDialogPlanner.ActionButtonHeight,
            MinHeight = FindReplaceDialogPlanner.ActionButtonHeight,
            MaxHeight = FindReplaceDialogPlanner.ActionButtonHeight,
            Padding = new Thickness(1, 0),
            Background = Brushes.Transparent,
            BorderThickness = new Thickness(0),
            HorizontalContentAlignment = AvaloniaHorizontalAlignment.Left,
            VerticalContentAlignment = AvaloniaVerticalAlignment.Center,
        };
        AutomationProperties.SetName(optionsHeader, Fr(FindReplaceDialogText.Options));
        AutomationProperties.SetAutomationId(optionsHeader, "FindReplaceOptionsExpander");
        ApplyDialogButtonChrome(optionsHeader);
        optionsHeader.Height = FindReplaceDialogPlanner.ActionButtonHeight;
        optionsHeader.MinHeight = FindReplaceDialogPlanner.ActionButtonHeight;
        optionsHeader.MaxHeight = FindReplaceDialogPlanner.ActionButtonHeight;
        optionsHeader.Padding = new Thickness(1, 0);
        optionsHeader.Width = FindReplaceDialogPlanner.OptionsHeaderMinimumWidth;
        optionsHeader.MinWidth = FindReplaceDialogPlanner.OptionsHeaderMinimumWidth;
        optionsHeader.MaxWidth = FindReplaceDialogPlanner.OptionsHeaderMinimumWidth;
        optionsHeader.HorizontalContentAlignment = AvaloniaHorizontalAlignment.Left;
        optionsHeader.Background = Brushes.White;
        optionsHeader.BorderBrush = Brushes.White;
        optionsHeader.BorderThickness = new Thickness(0);
        optionsHeader.CornerRadius = new CornerRadius(0);

        var optionsContent = new Border
        {
            Child = optionsControls.Panel,
            IsVisible = false,
            Margin = new Thickness(0, 8, 0, 0),
        };
        var optionsExpander = new Grid { RowDefinitions = new RowDefinitions("20,Auto") };
        Grid.SetRow(optionsHeader, 0);
        Grid.SetRow(optionsContent, 1);
        optionsExpander.Children.Add(optionsHeader);
        optionsExpander.Children.Add(optionsContent);
        optionsHeader.Click += (_, _) =>
        {
            optionsContent.IsVisible = !optionsContent.IsVisible;
            optionsHeaderText.Text = optionsContent.IsVisible
                ? Fr(FindReplaceDialogText.OptionsExpanded)
                : Fr(FindReplaceDialogText.Options);
            AutomationProperties.SetName(optionsHeader, optionsHeaderText.Text);
            optionsGlyph.Child = new TextBlock
            {
                Text = optionsContent.IsVisible ? "⌃" : "⌄",
                FontSize = 12,
                Foreground = Brushes.Black,
                HorizontalAlignment = AvaloniaHorizontalAlignment.Center,
                VerticalAlignment = AvaloniaVerticalAlignment.Center,
                Margin = new Thickness(0, optionsContent.IsVisible ? 2 : -2, 0, 0),
            };
        };

        var root = new Grid
        {
            Margin = new Thickness(
                FindReplaceDialogPlanner.RootMargin,
                FindReplaceDialogPlanner.RootMargin,
                FindReplaceDialogPlanner.AvaloniaRootRightMargin,
                FindReplaceDialogPlanner.AvaloniaRootBottomMargin),
            RowDefinitions = new RowDefinitions("Auto,Auto,*,Auto,Auto"),
        };
        ConfigureDialogTabCycle(dialog, root);

        tabs.Margin = new Thickness(0, 0, 0, FindReplaceDialogPlanner.TabContentMargin);
        optionsExpander.Margin = new Thickness(0, 0, 0, FindReplaceDialogPlanner.AvaloniaOptionsBottomMargin);
        resultsBorder.MinHeight = FindReplaceDialogPlanner.ResultsMinimumHeight;
        resultsBorder.Margin = new Thickness(0, 0, 0, FindReplaceDialogPlanner.ResultsBottomMargin);
        resultsHeader.Height = FindReplaceDialogPlanner.ResultsHeaderHeight;
        resultsHeader.MinHeight = FindReplaceDialogPlanner.ResultsHeaderHeight;
        resultsHeader.MaxHeight = FindReplaceDialogPlanner.ResultsHeaderHeight;
        resultsPanel.Background = Brush(242, 242, 242);
        statusLabel.MinHeight = FindReplaceDialogPlanner.StatusMinimumHeight;
        statusLabel.Margin = new Thickness(0, 0, 0, FindReplaceDialogPlanner.StatusBottomMargin);
        buttonRow.Margin = new Thickness(0);

        Grid.SetRow(tabs, 0);
        Grid.SetRow(optionsExpander, 1);
        Grid.SetRow(resultsBorder, 2);
        Grid.SetRow(statusLabel, 3);
        Grid.SetRow(buttonRow, 4);
        root.Children.Add(tabs);
        root.Children.Add(optionsExpander);
        root.Children.Add(resultsBorder);
        root.Children.Add(statusLabel);
        root.Children.Add(buttonRow);

        dialog.Content = root;
        dialog.Opened += (_, _) => resultsList.Background = Brush(242, 242, 242);
        _findReplaceDialog = dialog;
        _switchFindReplaceMode = requestedReplaceMode =>
        {
            tabs.SelectedIndex = requestedReplaceMode ? 1 : 0;
            Dispatcher.UIThread.Post(FocusSearchBox, DispatcherPriority.Input);
        };
        ShowOwnedModelessWindow(
            dialog,
            FocusSearchBox,
            () =>
            {
                if (!ReferenceEquals(_findReplaceDialog, dialog))
                    return;

                _findReplaceDialog = null;
                _switchFindReplaceMode = null;
            });
        return Task.CompletedTask;
    }

    private async Task<FindDialogResult?> ShowFindInputDialogAsync()
    {
        FindDialogResult? result = null;
        var selectionScopeAtOpen = CaptureFindReplaceSelectionScopeAtOpen();
        var dialog = new Window
        {
            Title = FindReplaceText(FindReplaceDialogText.Find),
            Width = 420,
            Height = 430,
            MinWidth = 360,
            MinHeight = 390,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };

        var findBox = new TextBox
        {
            Text = _session.LastFindText,
            MinWidth = 300,
        };
        AutomationProperties.SetName(findBox, FindReplaceText(FindReplaceDialogText.FindWhat));
        AutomationProperties.SetAutomationId(findBox, "FindTextBox");
        ApplyDialogTextBoxChrome(findBox);

        var findNextButton = new Button
        {
            Content = FindReplaceText(FindReplaceDialogText.FindNext),
            MinWidth = 84,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(findNextButton, "FindNextButton");
        ApplyDialogButtonChrome(findNextButton, isDefault: true);

        var findAllButton = new Button
        {
            Content = FindReplaceText(FindReplaceDialogText.FindAll),
            MinWidth = 84,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(findAllButton, "FindAllButton");
        ApplyDialogButtonChrome(findAllButton);

        var cancelButton = new Button
        {
            Content = UiText.CreateAutomationName(UiText.Get("Common_Cancel")),
            MinWidth = 84,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(cancelButton, "FindCancelButton");
        ApplyDialogButtonChrome(cancelButton);

        var optionsControls = CreateFindOptionsControls("Find", defaultLookInIndex: 0);
        StyleDiff? findFormat = null;
        var chooseFormatButton = CreateFindReplaceFormatButton(
            "FindChooseFormatFromCellButton",
            FindReplaceText(FindReplaceDialogText.ChooseFromCell));
        var clearFormatButton = CreateFindReplaceFormatButton(
            "FindClearFormatButton",
            UiText.Get("FindReplace_ClearFormat"));
        UpdateFindReplaceFormatState(findFormat, chooseFormatButton, clearFormatButton);
        chooseFormatButton.Click += (_, _) =>
        {
            findFormat = _session.CreateFormatDiffFromActiveCell();
            UpdateFindReplaceFormatState(findFormat, chooseFormatButton, clearFormatButton);
        };
        clearFormatButton.Click += (_, _) =>
        {
            findFormat = null;
            UpdateFindReplaceFormatState(findFormat, chooseFormatButton, clearFormatButton);
        };
        var findFormatRow = CreateFindReplaceFormatRow(
            UiText.Get("FindReplace_FindFormat"),
            chooseFormatButton,
            clearFormatButton);

        void Accept(FindDialogAction action)
        {
            result = new FindDialogResult(
                findBox.Text ?? "",
                action,
                CreateFindOptions(optionsControls, findFormat, selectionScopeAtOpen),
                optionsControls.MatchCaseBox.IsChecked == true,
                optionsControls.MatchEntireCellBox.IsChecked == true);
            dialog.Close();
        }

        findNextButton.Click += (_, _) => Accept(FindDialogAction.FindNext);
        findAllButton.Click += (_, _) => Accept(FindDialogAction.FindAll);
        cancelButton.Click += (_, _) => dialog.Close();
        findBox.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                e.Handled = true;
                Accept(FindDialogAction.FindNext);
            }
            else if (e.Key == Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = FindReplaceDialogPlanner.ActionButtonSpacing,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Children =
            {
                findAllButton,
                findNextButton,
                cancelButton,
            },
        };

        dialog.Content = new StackPanel
        {
            Margin = new Thickness(16),
            Spacing = 8,
            Children =
            {
                new TextBlock { Text = FindReplaceText(FindReplaceDialogText.FindWhat) },
                findBox,
                findFormatRow,
                optionsControls.Panel,
                buttonRow,
            },
        };
        dialog.Opened += (_, _) =>
        {
            findBox.Focus();
            findBox.SelectAll();
        };
        AttachOptionalFindDialogObservation(
            dialog,
            findBox,
            findNextButton,
            findAllButton,
            cancelButton,
            optionsControls,
            chooseFormatButton,
            clearFormatButton);

        await dialog.ShowDialog(this);
        return result;
    }

    private void FindNext(
        string? searchText = null,
        FindOptions? options = null,
        bool matchCase = false,
        bool matchEntireCell = false)
    {
        if (!TryCommitPendingFormulaEdit())
            return;

        var result = _session.FindNext(searchText, options, matchCase, matchEntireCell);
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? FindReplaceText(FindReplaceDialogText.FindFailed));
            return;
        }

        RefreshShell(FindReplaceText(
            FindReplaceDialogText.FoundRangeStatus,
            FormatRangeReference(result.SelectedRange!.Value),
            result.MatchIndex,
            result.MatchCount));
    }

    private void NavigateToFindAllMatch(WorkbookFindAllMatch match)
    {
        var result = _session.GoToCell(match.Address);
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? FindReplaceText(FindReplaceDialogText.FindResultNotSelected));
            return;
        }

        RefreshShell(FindReplaceText(FindReplaceDialogText.FoundSheetCellStatus, match.Sheet, match.Cell));
    }

