            "GoToSpecialTextBox");
        var logicalsBox = CreateGoToSpecialValueTypeBox(
            StripDisplayMnemonic(UiText.Get("GoToSpecial_Logicals")),
            "GoToSpecialLogicalsBox");
        var errorsBox = CreateGoToSpecialValueTypeBox(
            StripDisplayMnemonic(UiText.Get("GoToSpecial_Errors")),
            "GoToSpecialErrorsBox");
        AvaloniaCompactDialogChrome.ApplyCompactCheckBox(numbersBox, AvaloniaCompactDialogChrome.WindowsStyle);
        AvaloniaCompactDialogChrome.ApplyCompactCheckBox(textBox, AvaloniaCompactDialogChrome.WindowsStyle);
        AvaloniaCompactDialogChrome.ApplyCompactCheckBox(logicalsBox, AvaloniaCompactDialogChrome.WindowsStyle);
        AvaloniaCompactDialogChrome.ApplyCompactCheckBox(errorsBox, AvaloniaCompactDialogChrome.WindowsStyle);

        var okButton = new Button
        {
            Content = UiText.CreateAutomationName(UiText.Get("Common_Ok")),
            Width = 72,
            MinWidth = 72,
            IsDefault = true,
        };
        AutomationProperties.SetAutomationId(okButton, "GoToSpecialOkButton");
        ApplyDialogButtonChrome(okButton, width: 72, isDefault: true);

        var cancelButton = new Button
        {
            Content = UiText.CreateAutomationName(UiText.Get("Common_Cancel")),
            Width = 72,
            MinWidth = 72,
            IsCancel = true,
        };
        AutomationProperties.SetAutomationId(cancelButton, "GoToSpecialCancelButton");
        ApplyDialogButtonChrome(cancelButton, width: 72);

        void RefreshValueTypeState()
        {
            var enabled = SelectedGoToSpecialChoice(kindButtons) is { } choice &&
                GoToSpecialDialogPlanner.UsesValueTypeOptions(choice.Kind);
            numbersBox.IsEnabled = enabled;
            textBox.IsEnabled = enabled;
            logicalsBox.IsEnabled = enabled;
            errorsBox.IsEnabled = enabled;
            numbersBox.Opacity = enabled ? 1 : 0.7;
            textBox.Opacity = enabled ? 1 : 0.7;
            logicalsBox.Opacity = enabled ? 1 : 0.7;
            errorsBox.Opacity = enabled ? 1 : 0.7;
        }

        GoToSpecialValueTypes GetValueTypes()
        {
            var valueTypes = GoToSpecialValueTypes.None;
            if (numbersBox.IsChecked == true)
                valueTypes |= GoToSpecialValueTypes.Numbers;
            if (textBox.IsChecked == true)
                valueTypes |= GoToSpecialValueTypes.Text;
            if (logicalsBox.IsChecked == true)
                valueTypes |= GoToSpecialValueTypes.Logicals;
            if (errorsBox.IsChecked == true)
                valueTypes |= GoToSpecialValueTypes.Errors;
            return valueTypes;
        }

        void Accept()
        {
            var choice = SelectedGoToSpecialChoice(kindButtons) ?? choices[0];
            var options = GoToSpecialDialogPlanner.BuildOptions(choice.Kind, GetValueTypes());
            result = new GoToSpecialDialogResult(choice.Kind, options);
            dialog.Close();
        }

        okButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => dialog.Close();
        foreach (var button in kindButtons)
        {
            button.PropertyChanged += (_, e) =>
            {
                if (e.Property == ToggleButton.IsCheckedProperty)
                    RefreshValueTypeState();
            };
        }
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                e.Handled = true;
                Accept();
            }
            else if (e.Key == Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        var valueTypeRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = GoToSpecialDialogPlanner.AvaloniaValueTypeSpacing,
            Margin = new Thickness(8, 6, 8, 1),
            Children =
            {
                numbersBox,
                textBox,
                logicalsBox,
                errorsBox,
            },
        };

        var buttonRow = AvaloniaCompactDialogChrome.CreateActionRow(
            [okButton, cancelButton],
            new Thickness(
                0,
                GoToSpecialDialogPlanner.ActionRowTopMargin,
                GoToSpecialDialogPlanner.ActionRowRightMargin,
                GoToSpecialDialogPlanner.ActionRowBottomMargin));

        var availableGroup = new GroupBox
        {
            Header = UiText.Get("GoToSpecial_GoToSpecial"),
            Margin = new Thickness(
                0,
                GoToSpecialDialogPlanner.AvaloniaChoiceGroupTopMargin,
                0,
                GoToSpecialDialogPlanner.AvaloniaChoiceGroupBottomMargin),
            Padding = new Thickness(
                GoToSpecialDialogPlanner.AvaloniaChoiceGroupHorizontalPadding,
                1,
                GoToSpecialDialogPlanner.AvaloniaChoiceGroupHorizontalPadding,
                GoToSpecialDialogPlanner.AvaloniaChoiceGroupBottomPadding),
            Content = choiceGrid,
        };
        AvaloniaCompactDialogChrome.ApplyGroupBox(availableGroup, borderBrush: Brush(213, 223, 229));

        var valueTypeGroup = new GroupBox
        {
            Header = UiText.Get("GoToSpecial_ValuesForConstantsAndFormulas"),
            Margin = new Thickness(0),
            Padding = new Thickness(0, 0, 0, GoToSpecialDialogPlanner.AvaloniaValueTypeGroupBottomPadding),
            Content = valueTypeRow,
        };
        AvaloniaCompactDialogChrome.ApplyGroupBox(valueTypeGroup, borderBrush: Brush(213, 223, 229));

        var content = new StackPanel
        {
            Margin = new Thickness(
                GoToSpecialDialogPlanner.AvaloniaContentLeftMargin,
                GoToSpecialDialogPlanner.AvaloniaContentTopMargin,
                GoToSpecialDialogPlanner.AvaloniaContentRightMargin,
                0),
            Children =
            {
                new TextBlock
                {
                    Text = UiText.Get("MainWindow_Content_Select"),
                    FontWeight = FontWeight.SemiBold,
                    Margin = new Thickness(0, 0, 0, 7),
                },
                availableGroup,
                valueTypeGroup,
            },
        };
        var root = new DockPanel { Margin = new Thickness(0) };
        DockPanel.SetDock(buttonRow, Dock.Bottom);
        root.Children.Add(buttonRow);
        root.Children.Add(content);
        dialog.Content = root;
        dialog.Opened += (_, _) =>
        {
            RefreshValueTypeState();
            ApplyGoToSpecialButtonSize(okButton);
            ApplyGoToSpecialButtonSize(cancelButton);
            kindButtons.FirstOrDefault()?.Focus();
        };
        AttachOptionalGoToSpecialDialogObservation(
            dialog,
            choiceGrid,
            numbersBox,
            textBox,
            logicalsBox,
            errorsBox,
            okButton,
            cancelButton);

        await dialog.ShowDialog(this);
        return result;
    }

    private static AvaloniaGrid CreateGoToSpecialChoiceGrid(
        IReadOnlyList<GoToSpecialChoice> choices,
        ICollection<RadioButton> buttons)
    {
        var grid = new AvaloniaGrid();
        grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

        for (var index = 0; index < choices.Count; index++)
        {
            var row = index / 2;
            while (grid.RowDefinitions.Count <= row)
                grid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var choice = choices[index];
            var button = new RadioButton
            {
                Content = choice.Label,
                Tag = choice,
                GroupName = "GoToSpecialKind",
                Margin = new Thickness(
                    0,
                    0,
                    GoToSpecialDialogPlanner.AvaloniaChoiceButtonRightMargin,
                    GoToSpecialDialogPlanner.AvaloniaChoiceButtonBottomMargin),
                IsChecked = index == 0,
            };
            buttons.Add(button);
            Grid.SetRow(button, row);
            Grid.SetColumn(button, index % 2);
            grid.Children.Add(button);
        }

        return grid;
    }

    private static GoToSpecialChoice? SelectedGoToSpecialChoice(IEnumerable<RadioButton> buttons)
    {
        foreach (var button in buttons)
        {
            if (button.IsChecked == true && button.Tag is GoToSpecialChoice choice)
                return choice;
        }

        return null;
    }

    private static CheckBox CreateGoToSpecialValueTypeBox(string label, string automationId)
    {
        var checkBox = new CheckBox
        {
            Content = label,
            IsChecked = true,
            Margin = new Thickness(0, 0, 4, 0),
        };
        AutomationProperties.SetAutomationId(checkBox, automationId);
        return checkBox;
    }

    private static void ApplyGoToSpecialButtonSize(Button button)
    {
        button.Height = GoToSpecialDialogPlanner.ActionButtonHeight;
        button.MinHeight = GoToSpecialDialogPlanner.ActionButtonHeight;
        button.MaxHeight = GoToSpecialDialogPlanner.ActionButtonHeight;
        button.VerticalContentAlignment = AvaloniaVerticalAlignment.Center;
    }

    private static GoToSpecialChoice[] CreateGoToSpecialChoices() =>
        GoToSpecialDialogPlanner.BuildChoices().ToArray();

    private bool SelectGoToSpecial(GoToSpecialKind kind, GoToSpecialOptions? options = null)
    {
        if (!TryCommitPendingFormulaEdit())
            return false;

        ClearSelectedDrawingObject();
        var result = _session.GoToSpecial(kind, options);
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_GoToSpecialFailed"));
            return false;
        }

        // R92-render-localization-chrome-5-4: the multi-range branch previously spliced a raw
        // English "cells" noun into this otherwise-localized status; route it through the shared
        // catalog (MainLoc_CellsCount) like the single-range branch's own FormatRangeReference,
        // which is already culture-neutral.
        var selectedText = result.SelectedRanges.Count == 1
            ? FormatRangeReference(result.SelectedRange!.Value)
            : UiText.Format("MainLoc_CellsCount", result.MatchCount);
        RefreshShell(UiText.Format("MainLoc_SelectedX", selectedText));
        return true;
    }

    private async Task ShowInsertHyperlinkDialogAsync()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var plan = await ShowInsertHyperlinkInputDialogAsync();
        if (plan is null)
            return;

        var rangeReference = FormatRangeReference(_session.SelectedRange);
        var result = _session.SetSelectedRangeHyperlink(plan);
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_InsertHyperlinkFailed"));
            return;
        }

        RefreshShell(UiText.Format("MainLoc_InsertedHyperlinkFor", rangeReference));
    }

    private async Task<HyperlinkDialogPlan?> ShowInsertHyperlinkInputDialogAsync()
    {
        HyperlinkDialogPlan? result = null;
        var prefill = _session.GetSelectedRangeHyperlinkDialogPrefill();
        var linkTypeChoices = CreateHyperlinkTypeChoices();
        var selectedLinkType = linkTypeChoices[0];
        foreach (var choice in linkTypeChoices)
        {
            if (choice.Value != prefill.LinkType)
                continue;

            selectedLinkType = choice;
            break;
        }

        var dialog = new Window
        {
            Title = UiText.Get("Hyperlink_InsertHyperlink"),
            Width = HyperlinkDialogPlanner.Width,
            Height = HyperlinkDialogPlanner.Height,
            MinWidth = HyperlinkDialogPlanner.MinWidth,
            MinHeight = HyperlinkDialogPlanner.MinHeight,
            CanResize = false,
            Background = Brushes.White,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
            FontFamily = FormulaBarFontFamily,
            FontSize = 12,
        };
        AutomationProperties.SetAutomationId(dialog, "HyperlinkCompactDialog");

        var linkTypeBox = new ListBox
        {
            ItemsSource = linkTypeChoices,
            SelectedItem = selectedLinkType,
            MinWidth = HyperlinkDialogPlanner.LinkTypeColumnWidth,
            Width = HyperlinkDialogPlanner.LinkTypeColumnWidth,
            Height = HyperlinkDialogPlanner.LinkTypeListHeight,
        };
        AvaloniaCompactDialogChrome.ApplyListBox(
            linkTypeBox,
            AvaloniaCompactDialogChrome.WindowsStyle with
            {
                ListBoxItemPadding = new Thickness(4, 0),
            });
        // WPF keeps the selected link type in its inactive selection state because the
        // address editor receives initial focus.  Keep this correction local to the
        // hyperlink dialog while covering the template's focused and hover states.
        var inactiveLinkTypeSelection = Brush(246, 246, 246);
        void AddInactiveLinkTypeSelectionStyle(Func<Selector, Selector> select)
        {
            linkTypeBox.Styles.Add(new Style(x => select(x.OfType<ListBoxItem>()))
            {
                Setters =
                {
                    new Setter(TemplatedControl.BackgroundProperty, inactiveLinkTypeSelection),
                    new Setter(TemplatedControl.ForegroundProperty, HeaderForeground),
                    new Setter(TemplatedControl.BorderBrushProperty, Brushes.Transparent),
                    new Setter(TemplatedControl.BorderThicknessProperty, new Thickness(0)),
                },
            });
        }
        AddInactiveLinkTypeSelectionStyle(selector => selector.Class(":selected"));
        AddInactiveLinkTypeSelectionStyle(selector => selector.Class(":selected").Class(":focus"));
        AddInactiveLinkTypeSelectionStyle(selector => selector.Class(":selected").Class(":pointerover"));
        AddInactiveLinkTypeSelectionStyle(selector => selector.Class(":selected").Class(":focus").Class(":pointerover"));
        AutomationProperties.SetName(linkTypeBox, UiText.Get("Hyperlink_LinkTo2"));
        AutomationProperties.SetAutomationId(linkTypeBox, "HyperlinkLinkTypeBox");

        var displayBox = new TextBox
        {
            Text = prefill.DisplayText,
        };
        AutomationProperties.SetName(displayBox, UiText.Get("Hyperlink_TextToDisplay"));
        AutomationProperties.SetAutomationId(displayBox, "HyperlinkDisplayTextBox");
        ApplyDialogTextBoxChrome(displayBox);

        var targetLabel = new TextBlock();
        var targetBox = new TextBox
        {
            Text = prefill.Target,
        };
        AutomationProperties.SetAutomationId(targetBox, "HyperlinkTargetTextBox");
        ApplyDialogTextBoxChrome(targetBox);

        // ScreenTip / Bookmark are surfaced as buttons on Windows (not inline fields).
        // These backing text boxes hold the current values but are not added to the
        // visible tree; the buttons below edit them via small popup prompts.
        var screenTipBox = new TextBox
        {
            Text = prefill.ScreenTip,
        };
        AutomationProperties.SetName(screenTipBox, UiText.Get("Hyperlink_ScreenTipTextLabel"));
        AutomationProperties.SetAutomationId(screenTipBox, "HyperlinkScreenTipTextBox");
        ApplyDialogTextBoxChrome(screenTipBox);

        var bookmarkBox = new TextBox
        {
            Text = prefill.Bookmark,
        };
        AutomationProperties.SetName(bookmarkBox, UiText.Get("Hyperlink_BookmarkOrCellReferenceLabel"));
        AutomationProperties.SetAutomationId(bookmarkBox, "HyperlinkBookmarkTextBox");
        ApplyDialogTextBoxChrome(bookmarkBox);

        var screenTipButton = new Button { Content = StripDisplayMnemonic(UiText.Get("Hyperlink_ScreenTip")) };
        ApplyDialogButtonChrome(screenTipButton, width: HyperlinkDialogPlanner.SecondaryButtonWidth);
        AutomationProperties.SetName(screenTipButton, UiText.CreateAutomationName(UiText.Get("Hyperlink_ScreenTip")));
        AutomationProperties.SetAutomationId(screenTipButton, "HyperlinkScreenTipButton");
        AutomationProperties.SetHelpText(screenTipButton, UiText.Get("Hyperlink_ScreenTipButtonHelpText"));

        var bookmarkButton = new Button { Content = StripDisplayMnemonic(UiText.Get("Hyperlink_Bookmark")) };
        ApplyDialogButtonChrome(bookmarkButton, width: HyperlinkDialogPlanner.SecondaryButtonWidth);
        AutomationProperties.SetName(bookmarkButton, UiText.CreateAutomationName(UiText.Get("Hyperlink_Bookmark")));
        AutomationProperties.SetAutomationId(bookmarkButton, "HyperlinkBookmarkButton");
        AutomationProperties.SetHelpText(bookmarkButton, UiText.Get("Hyperlink_BookmarkButtonHelpText"));

        var validationText = new TextBlock
        {
            MinHeight = 20,
            Foreground = Brush(143, 74, 18),
            IsVisible = false,
        };
        AutomationProperties.SetAutomationId(validationText, "HyperlinkValidationText");

        var okButton = new Button
        {
            Content = UiText.Get("Common_Ok"),
            MinWidth = HyperlinkDialogPlanner.ActionButtonWidth,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(okButton, "HyperlinkOkButton");
        ApplyDialogButtonChrome(okButton, isDefault: true);

        var cancelButton = new Button
        {
            Content = UiText.Get("Common_Cancel"),
            MinWidth = HyperlinkDialogPlanner.ActionButtonWidth,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(cancelButton, "HyperlinkCancelButton");
        ApplyDialogButtonChrome(cancelButton);

        HyperlinkTargetKind CurrentLinkType() =>
            linkTypeBox.SelectedItem is SortDialogComboItem<HyperlinkTargetKind> choice
                ? choice.Value
                : HyperlinkTargetKind.ExistingFileOrWebPage;

        void RefreshTargetField()
        {
            var linkType = CurrentLinkType();
            targetLabel.Text = GetHyperlinkTargetLabel(linkType);
            AutomationProperties.SetName(targetBox, targetLabel.Text);
            AutomationProperties.SetHelpText(targetBox, GetHyperlinkTargetHelpText(linkType));
        }

        void Accept()
        {
            if (!HyperlinkDialogPlanner.TryPlan(
                    targetBox.Text,
                    displayBox.Text,
                    CurrentLinkType(),
                    screenTipBox.Text,
                    bookmarkBox.Text,
                    out var plan,
                    out var validationError))
            {
                validationText.Text = GetHyperlinkValidationErrorText(validationError);
                validationText.IsVisible = true;
                targetBox.Focus();
                targetBox.SelectAll();
                return;
            }

            result = plan;
            dialog.Close();
        }

        linkTypeBox.SelectionChanged += (_, _) => RefreshTargetField();
        okButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => dialog.Close();
        screenTipButton.Click += async (_, _) =>
        {
            var value = await ShowHyperlinkSubPromptAsync(
                dialog,
                UiText.Get("Hyperlink_SetHyperlinkScreenTipTitle"),
                StripDisplayMnemonic(UiText.Get("Hyperlink_ScreenTipTextLabel")),
                screenTipBox.Text);
            if (value is not null)
                screenTipBox.Text = value;
        };
        bookmarkButton.Click += async (_, _) =>
        {
            var value = await ShowHyperlinkSubPromptAsync(
                dialog,
                StripDisplayMnemonic(UiText.Get("Hyperlink_Bookmark")).Replace(".", string.Empty).Trim(),
                StripDisplayMnemonic(UiText.Get("Hyperlink_BookmarkOrCellReferenceLabel")),
                bookmarkBox.Text);
            if (value is not null)
                bookmarkBox.Text = value;
        };
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                e.Handled = true;
                Accept();
            }
            else if (e.Key == Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = HyperlinkDialogPlanner.ButtonGap,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Children =
            {
                okButton,
                cancelButton,
            },
        };

        // Keep the category column and detail grid aligned with the WPF dialog:
        // labels share a fixed column with their editors instead of stacking above them.
        var linkToLabel = new TextBlock
        {
            Text = UiText.Get("Hyperlink_LinkTo2") + ":",
            Margin = new Thickness(0, 0, 0, HyperlinkDialogPlanner.FieldBottomMargin),
        };
        var linkToColumn = new StackPanel
        {
            VerticalAlignment = AvaloniaVerticalAlignment.Top,
            Children =
            {
                linkToLabel,
                linkTypeBox,
            },
        };

        // Right detail area: "Text to display" + "Address" + screen-tip/bookmark fields,
        // arranged as the WPF label/editor rows.
        targetBox.HorizontalAlignment = AvaloniaHorizontalAlignment.Stretch;
        displayBox.HorizontalAlignment = AvaloniaHorizontalAlignment.Stretch;
        targetBox.Height = HyperlinkDialogPlanner.FieldHeight;
        displayBox.Height = HyperlinkDialogPlanner.FieldHeight;

        // ScreenTip... + Bookmark... sit on one right-aligned row beneath the Address
        // field (as buttons, not inline fields), matching the Windows dialog.
        var hyperlinkButtonsRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = HyperlinkDialogPlanner.ButtonGap,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Left,
            Margin = new Thickness(0, 0, 0, 12),
            Children = { screenTipButton, bookmarkButton },
        };

        var detailArea = new AvaloniaGrid
        {
            RowDefinitions = new RowDefinitions("Auto,Auto,Auto,Auto"),
            ColumnDefinitions = new ColumnDefinitions
            {
                new ColumnDefinition { Width = new GridLength(HyperlinkDialogPlanner.LabelColumnWidth) },
                new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) },
            },
        };
        AddHyperlinkFieldRow(detailArea, 0, UiText.Get("Hyperlink_TextToDisplay"), displayBox);
        AddHyperlinkFieldRow(detailArea, 1, targetLabel, targetBox);
        detailArea.Children.Add(hyperlinkButtonsRow);
        AvaloniaGrid.SetRow(hyperlinkButtonsRow, 2);
        AvaloniaGrid.SetColumn(hyperlinkButtonsRow, 1);
        detailArea.Children.Add(buttonRow);
        AvaloniaGrid.SetRow(buttonRow, 3);
        AvaloniaGrid.SetColumn(buttonRow, 1);

        var bodyGrid = new AvaloniaGrid
        {
            ColumnDefinitions = new ColumnDefinitions
            {
                new ColumnDefinition { Width = new GridLength(HyperlinkDialogPlanner.LinkTypeColumnWidth) },
                new ColumnDefinition { Width = new GridLength(HyperlinkDialogPlanner.LinkTypeColumnGap) },
                new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) },
            },
        };
        bodyGrid.Children.Add(linkToColumn);
        AvaloniaGrid.SetColumn(linkToColumn, 0);
        detailArea.Margin = new Thickness(
            HyperlinkDialogPlanner.DialogMargin,
            HyperlinkDialogPlanner.DialogMargin,
            HyperlinkDialogPlanner.DialogMargin,
            0);
        bodyGrid.Children.Add(detailArea);
        AvaloniaGrid.SetColumn(detailArea, 2);

        dialog.Content = new StackPanel
        {
            Margin = new Thickness(HyperlinkDialogPlanner.DialogMargin),
            Children =
            {
                bodyGrid,
                validationText,
            },
        };
        dialog.Opened += (_, _) =>
        {
            RefreshTargetField();
            targetBox.Focus();
            targetBox.SelectAll();
        };

        await dialog.ShowDialog(this);
        return result;
    }

    // Small modal prompt used by the Insert Hyperlink "ScreenTip..." / "Bookmark..."
    // buttons to edit their value, mirroring the Windows secondary dialogs.
    private static async Task<string?> ShowHyperlinkSubPromptAsync(
        Window owner,
        string title,
        string label,
        string? initialValue)
    {
        string? result = null;
        var prompt = new Window
        {
            Title = title,
            Width = 380,
            Height = 160,
            MinWidth = 340,
            MinHeight = 150,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
            FontFamily = FormulaBarFontFamily,
            FontSize = 12,
        };

        var inputBox = new TextBox { Text = initialValue ?? string.Empty, MinWidth = 300 };
        ApplyDialogTextBoxChrome(inputBox);
        AutomationProperties.SetName(inputBox, label);

        var okButton = new Button { Content = UiText.Get("Common_Ok") };
        ApplyDialogButtonChrome(okButton, width: 84, isDefault: true);
        var cancelButton = new Button { Content = UiText.Get("Common_Cancel") };
        ApplyDialogButtonChrome(cancelButton, width: 84);

        void Accept()
        {
            result = inputBox.Text ?? string.Empty;
            prompt.Close();
        }

        okButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => prompt.Close();
        prompt.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter) { e.Handled = true; Accept(); }
            else if (e.Key == Key.Escape) { e.Handled = true; prompt.Close(); }
        };

        prompt.Content = new StackPanel
        {
            Margin = new Thickness(16),
            Spacing = 8,
            Children =
            {
                new TextBlock { Text = label },
                inputBox,
                new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Spacing = 8,
                    HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
                    Margin = new Thickness(0, 8, 0, 0),
                    Children = { okButton, cancelButton },
                },
            },
        };
        prompt.Opened += (_, _) => { inputBox.Focus(); inputBox.SelectAll(); };

        await prompt.ShowDialog(owner);
        return result;
    }

    private static SortDialogComboItem<HyperlinkTargetKind>[] CreateHyperlinkTypeChoices() =>
    [
        new(UiText.Get("Hyperlink_LinkTypeExistingFileOrWebPage"), HyperlinkTargetKind.ExistingFileOrWebPage),
        new(UiText.Get("Hyperlink_LinkTypeCreateNewDocument"), HyperlinkTargetKind.CreateNewDocument),
        new(UiText.Get("Hyperlink_LinkTypePlaceInThisDocument"), HyperlinkTargetKind.PlaceInThisDocument),
        new(UiText.Get("Hyperlink_LinkTypeEmailAddress"), HyperlinkTargetKind.EmailAddress),
    ];

    private static void AddHyperlinkFieldRow(AvaloniaGrid grid, int row, string label, Control control) =>
        AddHyperlinkFieldRow(grid, row, new TextBlock { Text = StripDisplayMnemonic(label) }, control);

    private static void AddHyperlinkFieldRow(AvaloniaGrid grid, int row, Control label, Control control)
    {
        label.VerticalAlignment = AvaloniaVerticalAlignment.Center;
        label.Margin = new Thickness(0, 0, HyperlinkDialogPlanner.ButtonGap, HyperlinkDialogPlanner.FieldBottomMargin);
        grid.Children.Add(label);
        AvaloniaGrid.SetRow(label, row);
        AvaloniaGrid.SetColumn(label, 0);

        control.Margin = new Thickness(0, 0, 0, HyperlinkDialogPlanner.FieldBottomMargin);
        grid.Children.Add(control);
        AvaloniaGrid.SetRow(control, row);
        AvaloniaGrid.SetColumn(control, 1);
    }

    private static string StripDisplayMnemonic(string text) =>
        (text ?? string.Empty).Replace("_", string.Empty, StringComparison.Ordinal);

    // CheckBox/RadioButton in this Avalonia shell render their string Content literally
    // (no AccessText, see MainWindow.ParityCapture access-key note), so WPF mnemonic
    // markers ("_Show legend") would show the underscore. Strip it for string content;
    // leave non-string content (panels, etc.) untouched. Safe no-op without underscores.
    private static void StripContentMnemonic(ContentControl control)
    {
        if (control.Content is string text)
            control.Content = StripDisplayMnemonic(text);
    }

    private static string GetHyperlinkTargetLabel(HyperlinkTargetKind linkType) =>
        StripDisplayMnemonic(linkType switch
        {
            HyperlinkTargetKind.PlaceInThisDocument => UiText.Get("Hyperlink_CellReferenceLabel"),
            HyperlinkTargetKind.CreateNewDocument => UiText.Get("Hyperlink_NewDocumentLabel"),
            HyperlinkTargetKind.EmailAddress => UiText.Get("Hyperlink_EmailAddressLabel"),
            _ => UiText.Get("Hyperlink_Address"),
        });

    private static string GetHyperlinkTargetHelpText(HyperlinkTargetKind linkType) =>
        linkType switch
        {
            HyperlinkTargetKind.PlaceInThisDocument => "Enter a workbook location such as Sheet1!A1.",
            HyperlinkTargetKind.CreateNewDocument => "Enter the document name to store with this hyperlink.",
            HyperlinkTargetKind.EmailAddress => "Enter an email address or mailto link.",
            _ => "Enter a web page or file address."
        };

    private static string GetHyperlinkValidationErrorText(HyperlinkDialogValidationError error) =>
        HyperlinkDialogPlanner
            .DescribeValidationError(error)
            .Message.Resolve(UiText.Get, UiText.Format);

    private async Task ShowWorkbookStatisticsDialogAsync()
    {
        if (!TryCommitPendingFormulaEdit())
            return;

        var statistics = WorkbookStatisticsService.GetStatistics(_session.Workbook);
        var dialog = new Window
        {
            Title = UiText.Get("MainWindow_Content_WorkbookStatistics"),
            Width = WorkbookStatisticsDialogPlanner.Width,
            Height = WorkbookStatisticsDialogPlanner.Height,
            MinWidth = WorkbookStatisticsDialogPlanner.MinWidth,
            MinHeight = WorkbookStatisticsDialogPlanner.MinHeight,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };
        AutomationProperties.SetAutomationId(dialog, "WorkbookStatisticsDialog");

        var okButton = new Button
        {
            Content = UiText.CreateAutomationName(UiText.Get("Common_Ok")),
            MinWidth = 84,
            Padding = new Thickness(10, 4),
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
        };
        AutomationProperties.SetName(okButton, UiText.CreateAutomationName(UiText.Get("Common_Ok")));
        AutomationProperties.SetAutomationId(okButton, "WorkbookStatisticsOkButton");
        AutomationProperties.SetHelpText(okButton, UiText.Get("WorkbookStatistics_CloseHelpText"));

        var copyToClipboardButton = new Button
        {
            Content = UiText.Get("WorkbookStatistics_CopyToClipboard"),
            MinWidth = 120,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetName(copyToClipboardButton, UiText.Get("WorkbookStatistics_CopyToClipboard"));
        AutomationProperties.SetAutomationId(
            copyToClipboardButton,
            FreeXAutomationIdCatalog.WorkbookStatisticsCopyButton);
        AutomationProperties.SetHelpText(copyToClipboardButton, UiText.Get("WorkbookStatistics_CopyToClipboardHelpText"));
        ApplyDialogButtonChrome(copyToClipboardButton);

        var statsText = FormatWorkbookStatistics(statistics);
        copyToClipboardButton.Click += async (_, _) =>
        {
            _ = await _platformClipboard.WriteAsync(
                new PlatformClipboardContent(Text: statsText));
        };

        okButton.Click += (_, _) => dialog.Close();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key is Key.Enter or Key.Escape)
            {
                dialog.Close();
                e.Handled = true;
            }
        };

        dialog.Content = CreateWorkbookStatisticsDialogContent(statistics, okButton, copyToClipboardButton);
        dialog.Opened += (_, _) => okButton.Focus();
        await dialog.ShowDialog(this);
    }

    private static Control CreateWorkbookStatisticsDialogContent(WorkbookStatistics statistics, Button okButton, Button? copyToClipboardButton = null)
    {
        var statisticsBlock = new TextBox
        {
            Text = FormatWorkbookStatistics(statistics),
            IsReadOnly = true,
            AcceptsReturn = true,
            TextWrapping = TextWrapping.Wrap,
            Background = Brushes.White,
            BorderBrush = Brush(171, 171, 171),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(6, 4),
            VerticalContentAlignment = AvaloniaVerticalAlignment.Top,
        };
        AutomationProperties.SetName(statisticsBlock, UiText.Get("WorkbookStatistics_WorkbookStatistics"));
        AutomationProperties.SetAutomationId(
            statisticsBlock,
            FreeXAutomationIdCatalog.WorkbookStatisticsSummary);
        AutomationProperties.SetHelpText(
            statisticsBlock,
            UiText.Get("WorkbookStatistics_SummarizesSheetCellFormulaCommentAndObjectCountsForTheWorkbook"));

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Margin = new Thickness(0, 12, 0, 0),
        };
        if (copyToClipboardButton is not null)
            buttonRow.Children.Add(copyToClipboardButton);
        buttonRow.Children.Add(okButton);

        var root = new DockPanel
        {
            Margin = new Thickness(16),
        };
        DockPanel.SetDock(buttonRow, Dock.Bottom);
        root.Children.Add(buttonRow);
        root.Children.Add(statisticsBlock);

        return root;
    }

    private static string FormatWorkbookStatistics(WorkbookStatistics statistics) =>
        WorkbookStatisticsFormatter.Format(statistics);

    private async Task ShowReviewSummaryDialogAsync(bool focusAccessibility = false)
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var plan = _session.GetReviewWorkflowPlan();
        var display = ReviewWorkflowPlanner.CreateDisplayModel(plan);
        var dialog = new Window
        {
            Title = focusAccessibility ? "Accessibility Check" : "Review Summary",
            Width = 640,
            Height = 520,
            MinWidth = 520,
            MinHeight = 420,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };
        AutomationProperties.SetAutomationId(dialog, "ReviewSummaryDialog");

        var summaryBlock = new TextBlock
        {
            Text = display.Summary,
            TextWrapping = TextWrapping.Wrap,
            LineHeight = 21,
        };
        AutomationProperties.SetName(summaryBlock, UiText.Get("ReviewSummary_AutomationName"));
        AutomationProperties.SetAutomationId(summaryBlock, "ReviewSummaryText");
        AutomationProperties.SetHelpText(summaryBlock, UiText.Get("ReviewSummary_HelpText"));

        var spellingList = CreateReviewPreviewList(
            UiText.Get("ReviewSummary_SpellingIssues"),
            "ReviewSpellingIssuesList",
            display.SpellingIssues);
        var accessibilityList = CreateReviewPreviewList(
            UiText.Get("AccessibilityChecker_IssueListAutomationName"),
            "ReviewAccessibilityIssuesList",
            display.AccessibilityIssues);
        var notesList = CreateReviewPreviewList(
            UiText.Get("ShellLoc_NotesTitle"),
            "ReviewNotesList",
            display.Notes);
        var commentsList = CreateReviewPreviewList(
            UiText.Get("ReviewSummary_ThreadedComments"),
            "ReviewCommentsList",
            display.ThreadedComments);

        var closeButton = new Button
        {
            Content = UiText.CreateAutomationName(UiText.Get("Common_Close")),
            MinWidth = 84,
            Padding = new Thickness(10, 4),
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
        };
        AutomationProperties.SetName(closeButton, UiText.CreateAutomationName(UiText.Get("Common_Close")));
        AutomationProperties.SetAutomationId(closeButton, "ReviewCloseButton");
        AutomationProperties.SetHelpText(closeButton, UiText.Get("ReviewSummary_CloseHelpText"));
        closeButton.Click += (_, _) => dialog.Close();

        dialog.KeyDown += (_, e) =>
        {
            if (e.Key is Key.Enter or Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Margin = new Thickness(0, 12, 0, 0),
            Children =
            {
                closeButton,
            },
        };
        DockPanel.SetDock(buttonRow, Dock.Bottom);

        dialog.Content = new DockPanel
        {
            Margin = new Thickness(16),
            Children =
            {
                buttonRow,
                new ScrollViewer
                {
                    HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
                    VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                    Content = new StackPanel
                    {
                        Spacing = 10,
                        Children =
                        {
                            summaryBlock,
                            CreateReviewPreviewSection("Spelling", spellingList),
                            CreateReviewPreviewSection("Accessibility", accessibilityList),
                            CreateReviewPreviewSection("Notes", notesList),
                            CreateReviewPreviewSection("Comments", commentsList),
                        },
                    },
                },
            },
        };
        dialog.Opened += (_, _) =>
        {
            if (focusAccessibility)
                accessibilityList.Focus();
            else
                closeButton.Focus();
        };

        await dialog.ShowDialog(this);
    }

    private void NavigateReviewNote(bool previous) =>
        NavigateReviewTarget(
            () => ReviewSessionController.NavigateNote(previous),
            previous ? "previous note" : "next note",
            previous ? "Previous note was not found." : "Next note was not found.");

    private void NavigateReviewThreadedComment(bool previous) =>
        NavigateReviewTarget(
            () => ReviewSessionController.NavigateThreadedComment(previous),
            previous ? "previous comment" : "next comment",
            previous ? "Previous threaded comment was not found." : "Next threaded comment was not found.");

    private void NavigateReviewTarget(
        Func<PresentationReviewNavigationResult> navigate,
        string statusLabel,
        string fallbackMessage)
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        ClearSelectedDrawingObject();
        var result = navigate();
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? fallbackMessage);
            return;
        }

        if (result.Target is null)
        {
            ShowEditIssue(UiText.Get("MainLoc_ReviewTargetNotSelected"));
            return;
        }

        ApplyReviewRefreshPlan(
            result.RefreshPlan,
            $"Selected {FormatRangeReference(_session.SelectedRange)} ({statusLabel})");
    }

    private static StackPanel CreateReviewPreviewSection(string header, ListBox list) =>
        new()
        {
            Spacing = 4,
            Children =
            {
                new TextBlock
                {
                    Text = StripDisplayMnemonic(header),
                    FontWeight = FontWeight.SemiBold,
                },
                list,
            },
        };

    private static ListBox CreateReviewPreviewList(
        string name,
        string automationId,
        IReadOnlyList<string> items)
    {
