    private static IReadOnlyList<FormatCellsNullableChoice<CellBorderPreset>> CreateFormatCellsBorderPresetChoices() =>
    [
        new("No border change", null),
        .. FormatCellsCompactPlanner.GetBorderPresetMetadata()
            .Select(metadata => new FormatCellsNullableChoice<CellBorderPreset>(metadata.DisplayName, metadata.Preset)),
    ];

    // The native controls retain their nullable wrapper, but their order, labels, and typed values
    // project exclusively from the portable catalog shared with WPF.
    internal static IReadOnlyList<FormatCellsNullableChoice<BorderStyle>> CreateFormatCellsBorderStyleListChoices() =>
        FormatCellsBorderPalettePlanner.StyleChoices
            .Select(choice => new FormatCellsNullableChoice<BorderStyle>(
                choice.DisplayName,
                choice.Style == BorderStyle.None ? null : choice.Style))
            .ToArray();

    private static ListBox CreateFormatCellsBorderStyleListBox(string automationId, BorderStyle currentValue)
    {
        var choices = CreateFormatCellsBorderStyleListChoices();
        FormatCellsNullableChoice<BorderStyle>? selected = null;
        foreach (var choice in choices)
        {
            if (choice.Value == currentValue)
            {
                selected = choice;
                break;
            }
        }

        var listBox = new ListBox
        {
            ItemsSource = choices,
            SelectedItem = selected ?? choices[1],
            Width = 178,
            Height = 124,
            FontSize = 12,
            FontFamily = FormulaBarFontFamily,
        };
        listBox.ItemTemplate = new FuncDataTemplate<FormatCellsNullableChoice<BorderStyle>>((choice, _) =>
            new TextBlock
            {
                Text = choice.Label,
                VerticalAlignment = AvaloniaVerticalAlignment.Center,
            }, supportsRecycling: true);
        AvaloniaCompactDialogChrome.ApplyListBox(
            listBox,
            AvaloniaCompactDialogChrome.WindowsStyle with
            {
                ListBoxItemPadding = new Thickness(4, 0),
                ListBoxItemMinHeight = 20,
            });
        var selectedItemBackground = Brush(246, 246, 246);
        foreach (var selector in new[] { ":selected", ":selected:focus" })
        {
            listBox.Styles.Add(new Style(x => x.OfType<ListBoxItem>().Class(selector))
            {
                Setters =
                {
                    new Setter(TemplatedControl.BackgroundProperty, selectedItemBackground),
                    new Setter(TemplatedControl.ForegroundProperty, Brushes.Black),
                    new Setter(TemplatedControl.BorderBrushProperty, Brushes.Transparent),
                    new Setter(TemplatedControl.BorderThicknessProperty, new Thickness(0)),
                },
            });
        }
        AutomationProperties.SetName(listBox, UiText.Get("FormatCells_BorderLineStyleAutomationName"));
        AutomationProperties.SetAutomationId(listBox, automationId);
        return listBox;
    }

