    private async Task<string?> ShowSingleInputDialogAsync(
        string title,
        string label,
        string initialText,
        string acceptText,
        string automationId)
    {
        string? result = null;
        var dialog = new Window
        {
            Title = title,
            Width = 380,
            Height = 165,
            MinWidth = 340,
            MinHeight = 155,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };

        var inputBox = new TextBox
        {
            Text = initialText,
            MinWidth = 280,
        };
        AutomationProperties.SetName(inputBox, label);
        AutomationProperties.SetAutomationId(inputBox, automationId);

        var acceptButton = new Button { Content = acceptText };
        ApplyDialogButtonChrome(acceptButton, width: 84, isDefault: true);
        AutomationProperties.SetAutomationId(acceptButton, $"{automationId}AcceptButton");

        var cancelButton = new Button { Content = UiText.CreateAutomationName(UiText.Get("Common_Cancel")) };
        ApplyDialogButtonChrome(cancelButton, width: 84);
        AutomationProperties.SetAutomationId(cancelButton, $"{automationId}CancelButton");

        void Accept()
        {
            result = inputBox.Text ?? "";
            dialog.Close();
        }

        acceptButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => dialog.Close();
        inputBox.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                Accept();
                e.Handled = true;
            }
            else if (e.Key == Key.Escape)
            {
                dialog.Close();
                e.Handled = true;
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Children =
            {
                acceptButton,
                cancelButton,
            },
        };

        dialog.Content = new StackPanel
        {
            Margin = new Thickness(16),
            Spacing = 8,
            Children =
            {
                new TextBlock { Text = label },
                inputBox,
                buttonRow,
            },
        };
        dialog.Opened += (_, _) =>
        {
            inputBox.Focus();
            inputBox.SelectAll();
        };

        await dialog.ShowDialog(this);
        return result;
    }

