    private void BeginFormulaEdit(CellAddress address, string? initialText = null)
    {
        ClearSelectedDrawingObject();
        ClearFormulaRangeEntryState();
        _session.BeginFormulaEdit(address);
        RefreshShell(UiText.Get("MainLoc_Ready"));
        var originalText = _formulaBox.Text ?? "";
        _formulaBox.Focus();
        if (initialText is not null)
        {
            _formulaBox.Text = initialText;
            _formulaRangeEditingSession.ApplyTypedEntry(initialText);
            // Existing formulas are populated after the shell refresh above. Rebuild the live
            // reference visuals now so Edit-mode highlights and resize grips are available on the
            // same first frame as WPF's formula editor.
            RefreshFormulaReferenceHighlights();
            RefreshFormulaReferenceGridHighlights();
        }

        _formulaBoxEditOriginalText = originalText;
        MoveFormulaBoxCaretToEnd();
    }

    private void FormulaBox_GotFocus(object? sender, FocusChangedEventArgs e)
    {
        if (_session.FormulaEditAddress is not null)
            return;

        ClearFormulaRangeEntryState();
        _session.BeginFormulaEdit(_session.ActiveCell);
        _formulaBoxEditOriginalText = _formulaBox.Text ?? "";
    }

    private void FormulaBox_KeyDown(object? sender, KeyEventArgs e)
    {
        // R154-M3-formula-box-escape-local-first: mirrors the window-level guard added for the
        // same defect (ShouldHandleEscapeLocallyBeforeFormulaPointMode, applied to
        // MainWindow_KeyDownAsync above) -- Escape must be offered to THIS window's own local UI
        // state (F8 sticky-selection mode, ribbon key-tip dismissal, Start-screen/backstage
        // dismissal) before TryRouteFormulaPointModeKey is allowed to route it to some OTHER open
        // workbook window's in-progress formula point-mode edit and silently cancel it. This
        // window's formula box can be the live focus target (TryHandleFocusedEditorShortcut calls
        // straight into this handler), so it needs the identical guard, not just the window-level
        // fallback.
        if (e.KeyModifiers == KeyModifiers.None &&
            (e.Key == Key.Enter || e.Key == Key.Escape || e.Key == Key.F4) &&
            !ShouldHandleEscapeLocallyBeforeFormulaPointMode(e.Key) &&
            TryRouteFormulaPointModeKey(e.Key))
        {
            e.Handled = true;
            return;
        }

        // R92-meta-2: see the matching check in InlineCellEditor_KeyDown -- the popup must claim
        // these keys before any of the Formula Bar's own navigation/commit handling below.
        if (HandleFunctionAutocompleteKeyDown(_formulaBox, e.Key))
        {
            e.Handled = true;
            return;
        }

        if (TryToggleFormulaRangeEntrySelectionMode(e.Key, e.KeyModifiers))
        {
            e.Handled = true;
            return;
        }

        if (TryHandleFormulaEditorModeOrReferenceCycle(_formulaBox, e))
            return;

        if (e.Key == Key.Escape)
        {
            CancelCellEditAndRestoreCommittedText();
            e.Handled = true;
            return;
        }

        var current = _session.FormulaEditAddress ?? _session.ActiveCell;
        if (TryHandleFormulaRangeEntryNavigation(_formulaBox, current, e))
            return;

        var formulaRangeEntryActive = IsFormulaRangeEntryActive(_formulaBox.Text);
        var intent = _formulaRangeEditingSession.PlanEditKey(
            FormulaBarAvaloniaInputAdapter.ToFormulaEditorKey(e.Key),
            FormulaEditorKey.None,
            FormulaBarAvaloniaInputAdapter.ToFormulaEditorModifiers(e.KeyModifiers),
            current,
            Math.Max(1, WorkbookViewportScrollPlanner.CountVisibleScrollableRows(
                _session.Viewport, _session.Workbook.GetSheet(current.Sheet)) - 1),
            _formulaBox.Text,
            _session.FormulaEditAddress is not null,
            FormulaEditorSurfaceKind.FormulaBar,
            false,
            MoveSelectionAfterEnter,
            AfterEnterDirection);

        if (intent.Action == ExcelEditKeyAction.InsertLineBreak)
        {
            var text = _formulaBox.Text ?? "";
            ApplyFormulaBoxTextEdit(
                ExcelTextEditorPlanner.InsertLineBreak(
                    text,
                    Math.Min(_formulaBox.SelectionStart, _formulaBox.SelectionEnd),
                    Math.Abs(_formulaBox.SelectionEnd - _formulaBox.SelectionStart),
                    Environment.NewLine));
            e.Handled = true;
        }
        else if (intent.Action == ExcelEditKeyAction.CommitAndMove && intent.Target is { } target)
        {
            if (_isOpening || _isSaving)
            {
                ShowSaveIssue(UiText.Get("File_FinishSavingBeforeEditing"));
            }
            else if (CommitFormulaBox())
            {
                ClearFormulaRangeEntryState();
                var adjustedTarget = ExcelWorksheetNavigationPlanner.AdjustTargetPastMerge(
                    _session.Workbook.GetSheet(current.Sheet),
                    current,
                    target);
                MoveActiveCellAfterEditCommit(current, adjustedTarget, e.Key, e.KeyModifiers.HasFlag(KeyModifiers.Shift));
                RefreshShell(UiText.Get("MainLoc_Ready"));
                FocusShellRegion(ShellFocusTarget.Worksheet);
            }
            else
            {
                _formulaBox.Focus();
            }

            e.Handled = true;
        }
        else if (intent.Action == ExcelEditKeyAction.CommitSelection)
        {
            if (_isOpening || _isSaving)
            {
                ShowSaveIssue(UiText.Get("File_FinishSavingBeforeEditing"));
            }
            else if (CommitEditAcrossSelection(_formulaBox.Text ?? ""))
            {
                ClearFormulaRangeEntryState();
                RefreshShell(UiText.Get("MainLoc_Ready"));
                FocusShellRegion(ShellFocusTarget.Worksheet);
            }
            else
            {
                _formulaBox.Focus();
            }

            e.Handled = true;
        }
    }

    // ── Name Box (cell-address box): click-to-edit, type a name/ref/cell + Enter to navigate, ──
    // ── define-name-by-typing, and a basic autocomplete list of defined names. Mirrors the WPF ──
    // ── host's editable CellAddressBox (MainWindow.Editing.cs). ──────────────────────────────────

    private void CellAddressBox_GotFocus(object? sender, FocusChangedEventArgs e) =>
        _cellAddressText.SelectAll();

    private void CellAddressBox_LostFocus(object? sender, RoutedEventArgs e)
    {
        if (_cellAddressBoxHasPendingEdit)
            return;

        RestoreCellAddressBoxText();
    }

    private void CellAddressBox_KeyDown(object? sender, KeyEventArgs e)
    {
        // WPF's editable ComboBox opens its popup from the standard dropdown gestures before
        // applying text-entry semantics. Keep the Name Box on that route so the window-level
        // Alt+Down command does not fall through to the worksheet's data-validation dropdowns.
        if ((e.Key == Key.Down && e.KeyModifiers == KeyModifiers.Alt) ||
            (e.Key == Key.F4 && e.KeyModifiers == KeyModifiers.None))
        {
            ShowCellAddressAutocompletePopup();
            e.Handled = true;
            return;
        }

        if (e.Key == Key.Escape)
        {
            RestoreCellAddressBoxText();
            FocusShellRegion(ShellFocusTarget.Worksheet);
            e.Handled = true;
            return;
        }

        if (e.Key != Key.Enter)
        {
            _cellAddressBoxHasPendingEdit = true;
            return;
        }

        _cellAddressBoxHasPendingEdit = false;
        var text = _cellAddressText.Text ?? "";
        if (TryParseCellAddressBoxReferenceRange(text, out var selectedRange))
        {
            NavigateCellAddressBoxTo(selectedRange);
            FocusShellRegion(ShellFocusTarget.Worksheet);
            e.Handled = true;
            return;
        }

        if (TryDefineNameFromCellAddressBox(text))
        {
            FocusShellRegion(ShellFocusTarget.Worksheet);
            e.Handled = true;
            return;
        }

        ShowEditIssue(UiText.Get("MainLoc_GoToFailed"));
        _cellAddressBoxHasPendingEdit = true;
        _cellAddressText.Focus();
        _cellAddressText.SelectAll();
        e.Handled = true;
    }

    // Sheet-scope-aware Name Box reference resolution, matching formula evaluation's precedence
    // (Workbook.TryGetNamedRange(name, contextSheetId, ...): sheet-scoped names on the active sheet
    // take precedence over a same-named workbook-global name).
    private bool TryParseCellAddressBoxReferenceRange(string text, out GridRange range)
    {
        if (WorkbookReferenceNavigator.TryParseReferenceRange(
                text,
                _session.ActiveSheet.Id,
                name => _session.Workbook.Sheets.FirstOrDefault(sheet =>
                    string.Equals(sheet.Name, name, StringComparison.OrdinalIgnoreCase))?.Id,
                _session.Workbook.NamedRanges,
                (name, sheetId) => _session.Workbook.TryGetNamedRange(name, sheetId, out var scoped) ? scoped : null,
                out range))
        {
            return true;
        }

        // Excel also lets the Name Box resolve a structured table's name, selecting the table's
        // data-body range (the same rows a structured reference like Table1[#Data] would select),
        // rather than only cell/named-range references. Without this, an existing table's name
        // falls through to TryDefineNameFromCellAddressBox and silently creates a colliding
        // defined name through the same shared policy used by the WPF host.
        return StructuredTableSelectionPlanner.TryResolveDataBodyRange(
            _session.Workbook,
            text,
            out range);
    }

    private void NavigateCellAddressBoxTo(GridRange selectedRange)
    {
        var result = _session.GoToRange(selectedRange);
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_GoToFailed"));
            return;
        }

        RefreshShell(UiText.Format("MainLoc_SelectedX", FormatRangeReference(result.SelectedRange!.Value)));
    }

    private bool TryDefineNameFromCellAddressBox(string text)
    {
        var plan = DefinedNameUiPolicy.PlanNameBoxDefinition(
            _session.Workbook,
            _session.ActiveSheet.Id,
            _session.SelectedRange,
            text,
            DefinedNameUiProfile.Avalonia);
        if (!plan.CanDefine)
            return false;

        var result = _session.ExecuteReviewCommand(plan.Command!);
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? UiText.Format("InsertLoc_CouldNotDefineName", plan.Name));
            return false;
        }

        RefreshShell(UiText.Format("InsertLoc_DefinedName", plan.Name));
        _cellAddressText.Text = plan.Name;
        _cellAddressText.SelectAll();
        return true;
    }

    private void RestoreCellAddressBoxText()
    {
        _cellAddressBoxHasPendingEdit = false;
        _cellAddressText.Text = FormatCellReference(_session.ActiveCell);
    }

    // Basic Name Box autocomplete: the workbook's defined names, merged with names scoped to the
    // active sheet, deduplicated and alphabetized — mirrors the WPF host's
    // CellAddressBox_DropDownOpened (MainWindow.Editing.cs).
    private IReadOnlyList<NameBoxNavigationItem> BuildCellAddressAutocompleteItems() =>
        NameBoxDropdownPlanner.Build(_session.Workbook, _session.ActiveSheet.Id);

    private IReadOnlyList<string> BuildCellAddressAutocompleteNames() =>
        BuildCellAddressAutocompleteItems().Select(item => item.Name).ToArray();

    private void CreateCellAddressAutocompletePopup()
    {
        _cellAddressAutocompleteListBox = new ListBox
        {
            MaxHeight = 220,
            MinWidth = 180,
            Focusable = true,
        };
        AutomationProperties.SetAutomationId(_cellAddressAutocompleteListBox, "CellAddressAutocompleteList");
        _cellAddressAutocompleteListBox.AddHandler(
            InputElement.KeyDownEvent,
            (_, args) =>
            {
                if (args.Key is Key.Home or Key.End or Key.Up or Key.Down)
                {
                    MoveCellAddressAutocompleteSelection(args.Key);
                    args.Handled = true;
                }
                else if (args.Key == Key.Enter)
                {
                    CommitCellAddressAutocompleteSelection();
                    args.Handled = true;
                }
                else if (args.Key == Key.Escape)
                {
                    _cellAddressAutocompletePopup!.IsOpen = false;
                    FocusShellRegion(ShellFocusTarget.Worksheet);
                    args.Handled = true;
                }
            },
            RoutingStrategies.Tunnel,
            handledEventsToo: true);
        _cellAddressAutocompleteListBox.PointerReleased += (_, args) =>
        {
            if (args.GetCurrentPoint(_cellAddressAutocompleteListBox).Properties.PointerUpdateKind == PointerUpdateKind.LeftButtonReleased)
                CommitCellAddressAutocompleteSelection();
        };
        _cellAddressAutocompletePopup = new Popup
        {
            Child = new Border
            {
                Width = NameBoxDropdownWidth,
                Height = NameBoxDropdownHeight,
                Background = Brushes.White,
                BorderBrush = FormulaBarControlBorder,
                BorderThickness = new Thickness(1),
                Child = _cellAddressAutocompleteListBox,
            },
            IsLightDismissEnabled = true,
        };
    }

    private static ListBoxItem BuildCellAddressAutocompleteRow(NameBoxNavigationItem item)
    {
        var row = new ListBoxItem
        {
            Height = 26.8,
            Padding = new Thickness(0),
            Tag = item,
            Content = new TextBlock
            {
                Text = item.Name,
                FontFamily = new FontFamily("Consolas, DejaVu Sans Mono, Liberation Mono, monospace"),
                FontSize = 15,
                Foreground = Brush(28, 38, 48),
                Padding = new Thickness(8, 3),
                TextWrapping = TextWrapping.NoWrap,
            },
        };
        AutomationProperties.SetName(row, item.AccessibleDescription);
        return row;
    }

    private NameBoxNavigationItem? GetSelectedCellAddressAutocompleteItem() =>
        _cellAddressAutocompleteListBox?.SelectedItem switch
        {
            NameBoxNavigationItem item => item,
            ListBoxItem { Tag: NameBoxNavigationItem item } => item,
            _ => null,
        };

    private void CommitCellAddressAutocompleteSelection()
    {
        if (GetSelectedCellAddressAutocompleteItem() is not { } item ||
            item.Name.StartsWith("(No ", StringComparison.Ordinal))
        {
            return;
        }

        _cellAddressAutocompletePopup!.IsOpen = false;
        SelectCellAddressBoxItem(item);
        FocusShellRegion(ShellFocusTarget.Worksheet);
    }

    private void MoveCellAddressAutocompleteSelection(Key key)
    {
        if (_cellAddressAutocompleteListBox is not { IsEnabled: true } list || list.ItemCount == 0)
            return;

        list.SelectedIndex = key switch
        {
            Key.Home => 0,
            Key.End => list.ItemCount - 1,
            Key.Down => Math.Min(list.ItemCount - 1, Math.Max(0, list.SelectedIndex + 1)),
            Key.Up => Math.Max(0, list.SelectedIndex - 1),
            _ => list.SelectedIndex,
        };
    }

    private void ShowCellAddressAutocompletePopup()
    {
        var items = BuildCellAddressAutocompleteItems();
        _cellAddressAutocompleteListBox!.IsEnabled = items.Count > 0;
        _cellAddressAutocompleteListBox.ItemsSource = items
            .Select(BuildCellAddressAutocompleteRow)
            .ToArray();
        _cellAddressAutocompleteListBox.SelectedIndex = -1;
        _cellAddressAutocompletePopup!.PlacementTarget = _cellAddressDropDownButton;
        _cellAddressAutocompletePopup.Placement = PlacementMode.BottomEdgeAlignedLeft;
        _cellAddressAutocompletePopup.IsOpen = true;
        _cellAddressAutocompleteListBox.Focus();
    }

    private bool SelectCellAddressBoxItem(NameBoxNavigationItem item)
    {
        _cellAddressBoxHasPendingEdit = false;
        _cellAddressText.Text = item.Name;
        if (item.Range is { } selectedRange)
        {
            NavigateCellAddressBoxTo(selectedRange);
            return true;
        }

        return TrySelectCellAddressBoxObject(item);
    }

    private bool TrySelectCellAddressBoxObject(NameBoxNavigationItem item)
    {
        if (item.Kind != NameBoxNavigationItemKind.Object ||
            item.ObjectKind is not { } objectKind ||
            item.ObjectId is not { } objectId ||
            item.Anchor is not { } anchor)
        {
            return false;
        }

        if (!TryCommitPendingFormulaEdit())
            return false;

        if (!_session.ActiveSheet.Id.Equals(item.SheetId))
            _session.SelectSheet(item.SheetId);

        _session.SelectCell(anchor);
        _selectedDrawingObjectKind = objectKind;
        _selectedDrawingObjectId = objectId;
        _ribbonContextSource.OnDrawingObjectSelected(objectKind);
        RefreshTableContextualTab();
        RefreshPivotContextualTab();
        RefreshShell(UiText.Format(
            "MainLoc_SelectedX",
            UiText.Format(
                "RecentFile_AutomationNameFormat",
                FormatDrawingObjectKind(objectKind),
                item.Name)));
        RecordOptionalNameBoxSelection(item);
        return true;
    }

    private void ApplyFormulaBoxTextEdit(ExcelTextEdit edit)
    {
        _isApplyingFormulaBoxText = true;
        try
        {
            ApplyTextBoxEdit(_formulaBox, edit);
        }
        finally
        {
            _isApplyingFormulaBoxText = false;
        }
    }

    private static void ApplyTextBoxEdit(TextBox editor, ExcelTextEdit edit)
    {
        editor.Text = edit.Text;
        editor.CaretIndex = Math.Clamp(edit.SelectionStart, 0, edit.Text.Length);
        editor.SelectionStart = editor.CaretIndex;
        editor.SelectionEnd = Math.Clamp(
            editor.CaretIndex + Math.Max(0, edit.SelectionLength),
            editor.CaretIndex,
            edit.Text.Length);
    }

    private static int GetCellIndexDelta(uint current, uint target)
    {
        var delta = (long)target - current;
        return delta >= 0
            ? (int)Math.Min(int.MaxValue, delta)
            : -(int)Math.Min(int.MaxValue, -delta);
    }

    private bool CommitFormulaBox()
    {
        if (_isOpening || _isSaving)
        {
            ShowSaveIssue(UiText.Get("File_FinishSavingBeforeEditing"));
            return false;
        }

        var address = _session.FormulaEditAddress ?? _session.ActiveCell;
        var result = _session.CommitCellText(_formulaBox.Text ?? "", UseR1C1ReferenceStyle);

        if (!result.Success)
        {
            // R161-freex-data-validation-ui-F2: a Warning/Information ("AskToContinue") alert's
            // Cancel answer must discard the invalid entry and revert the formula bar to the
            // cell's committed value -- exactly like Escape -- while its No answer instead leaves
            // the invalid text in place so the user can keep fixing it (Excel's AskToContinue
            // semantics; mirrors WPF's ShouldRestoreOnCancel in MainWindow.Editing.cs). Without
            // this, both answers left the formula edit session dangling: FormulaEditAddress stayed
            // set and the formula bar kept showing the rejected text even though the in-cell editor
            // overlay was already torn down by the caller.
            if (result.Failure is
                {
                    Kind: WorkbookCellEditFailureKind.DataValidationDeclined,
                    AlertStyle: { } declinedAlertStyle,
                    PromptDecision: { } decision
                } &&
                ShouldDiscardFormulaEditOnDecline(declinedAlertStyle, decision))
            {
                _session.CancelFormulaEdit();
                _formulaBoxEditOriginalText = null;
                ClearFormulaRangeEntryState();
                RefreshShell(UiText.Get("MainLoc_Ready"));
            }

            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_EditFailed"));
            return false;
        }

        // Formula Bar commits can be initiated after a cross-sheet grip drag left the in-cell
        // editor focused. Clear that editor after the model commit succeeds; otherwise its stale
        // overlay remains visible and subsequent physical readback can observe the pre-commit
        // edit surface instead of the committed cell value.
        ClearInlineCellEditorState();
        _formulaBoxEditOriginalText = null;
        ClearFormulaRangeEntryState();
        HideFormulaFunctionAutocomplete();
        HideFormulaSignatureHelp();
        // R75-render-selection-marquee-4-2: mirrors the WPF host's TryExecuteEditCells, which
        // cancels an active Copy/Cut marching-ants marquee as soon as an ordinary cell edit is
        // committed -- a subsequent Paste must not silently move/copy a source range the user has
        // since overwritten.
        SetClipboardMarquee(null, isCut: false);
        RefreshShell(UiText.Format("MainLoc_EditedCellStatusFormat", FormatCellReference(address)));
        return true;
    }

    /// <summary>
    /// Mirrors the WPF host's <c>ShouldRestoreOnCancel</c> (MainWindow.Editing.cs): decides whether
    /// a declined AskToContinue data-validation alert should discard the invalid entry. Excel's
    /// Information style offers only OK/Cancel (Cancel discards), and its Warning style offers
    /// Yes/No/Cancel (Cancel also discards, while No instead leaves the invalid entry for the user
    /// to fix). Stop style never reaches AskToContinue (it's always Block), so it never discards
    /// here.
    /// </summary>
    private static bool ShouldDiscardFormulaEditOnDecline(DvAlertStyle alertStyle, UserMessageResult decision) =>
        decision == UserMessageResult.Cancel && alertStyle != DvAlertStyle.Stop;

    // Ctrl+Enter ("fill selection with same value"): commits the same entered text into every
    // cell of the current selection as a single undoable command, mirroring the WPF host's
    // CommitEditAcrossSelection (MainWindow.Editing.cs). Unlike CommitAndMove, the selection is
    // not collapsed to one cell -- Excel keeps the whole range selected after a Ctrl+Enter fill.
    private bool CommitEditAcrossSelection(string text)
    {
        if (_isOpening || _isSaving)
        {
            ShowSaveIssue(UiText.Get("File_FinishSavingBeforeEditing"));
            return false;
        }

        var result = _session.CommitCellTextAcrossSelection(text, UseR1C1ReferenceStyle);

        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_EditFailed"));
            return false;
        }

        _formulaBoxEditOriginalText = null;
        ClearFormulaRangeEntryState();
        // R75-render-selection-marquee-4-2: same edit-commit marquee cancellation as CommitFormulaBox.
        SetClipboardMarquee(null, isCut: false);
        return true;
    }

    private bool TryCommitPendingFormulaEdit()
    {
        if (_session.FormulaEditAddress is null)
            return true;

        if (!HasPendingFormulaEditText())
        {
            _session.CancelFormulaEdit();
            _formulaBoxEditOriginalText = null;
            ClearFormulaRangeEntryState();
            return true;
        }

        return CommitFormulaBox();
    }

    private bool HasPendingFormulaEditText() =>
        !string.Equals(
            _formulaBox.Text ?? "",
            _formulaBoxEditOriginalText ?? "",
            StringComparison.Ordinal);

    private void MoveFormulaBoxCaretToEnd()
    {
        _formulaBox.CaretIndex = _formulaBox.Text?.Length ?? 0;
        _formulaBox.SelectionStart = _formulaBox.CaretIndex;
        _formulaBox.SelectionEnd = _formulaBox.CaretIndex;
    }

    // Routed through RunGuarded: the disk write inside SaveWorkbookToTargetAsync is already
    // try/catch'd, but the Save-As stages ahead of it are not — the storage-provider save picker,
    // the normalized-overwrite confirm, and identity creation. Save reaches those same stages
    // whenever there is no existing target (the first save of a new workbook), so both handlers need
    // the guard; without it a picker failure escaped this `async void` and killed the app.
    private void SaveButton_Click(object? sender, RoutedEventArgs e) =>
        RunGuarded(SaveCurrentWorkbookAsync);

    private void SaveAsButton_Click(object? sender, RoutedEventArgs e) =>
        RunGuarded(SaveWorkbookAsAsync);

    // Routed through RunGuarded: the workbook LOAD inside OpenWorkbookAsync is already try/catch'd,
    // but the stages before it are not — the dirty-workbook confirm, the storage-provider file
    // picker, and target resolution. A picker failure (sandbox/permission issues on Linux/macOS)
    // therefore escaped this `async void` handler and killed the app on Open.
    private void OpenButton_Click(object? sender, RoutedEventArgs e) =>
        RunGuarded(OpenWorkbookAsync);

    private void UndoButton_Click(object? sender, RoutedEventArgs e)
    {
        UndoLastEdit();
    }

    private void RedoButton_Click(object? sender, RoutedEventArgs e)
    {
        RedoLastEdit();
    }

    // Routed through RunGuarded: Cut awaits clipboard.SetTextAsync directly, with none of the
    // protection its Copy sibling has — Copy deliberately wraps its own clipboard write because a
    // backend may reject the payload. The OS clipboard is shared, so a rejected or contended write
    // is an ordinary runtime failure, and here it escaped this `async void` and killed the app.
    private void CutButton_Click(object? sender, RoutedEventArgs e) =>
        RunGuarded(CutSelectedRangeToClipboardAsync);

    private async void CopyButton_Click(object? sender, RoutedEventArgs e)
    {
        await CopySelectedRangeToClipboardAsync();
    }

    private async void PasteButton_Click(object? sender, RoutedEventArgs e)
    {
        await PasteClipboardTextAsync();
    }

    private void FormatPainterButton_Click(object? sender, RoutedEventArgs e)
    {
        // Matches Excel/WPF's FormatPainterBtn_Click: clicking the already-armed Format Painter
        // button (single-shot or double-clicked/locked) CANCELS it instead of re-capturing a new
        // source from the current selection (R68-commands-format-painter-6-2).
        if (_session.IsFormatPainterActive)
        {
            CancelFormatPainter();
            return;
