    private async Task<SortDialogOptions?> ShowSortOptionsDialogAsync(SortDialogOptions current)
    {
        SortDialogOptions? result = null;
        var presentation = SortOptionsDialogCatalog.Create(UiText.Get);
        var dialog = new Window
        {
            Title = presentation.Title,
            Width = 330,
            Height = 260,
            MinWidth = 330,
            MinHeight = 260,
            MaxWidth = 330,
            MaxHeight = 260,
            CanResize = false,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
            FontSize = 12,
        };
        AutomationProperties.SetAutomationId(dialog, "SortOptionsDialog");
        AvaloniaCompactDialogChrome.ApplyWindow(dialog);

        var caseSensitiveBox = new CheckBox
        {
            Content = presentation.CaseSensitive,
            IsChecked = current.CaseSensitive,
            Margin = new Thickness(0, 0, 0, 10),
        };
        StripContentMnemonic(caseSensitiveBox);
        AvaloniaCompactDialogChrome.ApplyCompactCheckBox(caseSensitiveBox, AvaloniaCompactDialogChrome.WindowsStyle);
        AutomationProperties.SetAutomationId(caseSensitiveBox, "SortOptionsCaseSensitiveCheckBox");

        var firstKeySelection = SortOptionsPolicy.ResolveFirstKeyOrderSelection(
            current.FirstKeySortOrder,
            presentation.FirstKeySortOrders,
            preserveUnlistedEditorText: false);
        var firstKeyBox = new ComboBox
        {
            ItemsSource = presentation.FirstKeySortOrders,
            SelectedItem = firstKeySelection.SelectedChoice,
            Margin = new Thickness(0, 0, 0, 10),
            HorizontalAlignment = AvaloniaHorizontalAlignment.Stretch,
        };
        AvaloniaCompactDialogChrome.ApplyComboBox(firstKeyBox, AvaloniaCompactDialogChrome.WindowsStyle);
        AutomationProperties.SetAutomationId(firstKeyBox, "SortOptionsFirstKeySortOrderBox");

        var topToBottomButton = new RadioButton
        {
            Content = presentation.SortTopToBottom,
            IsChecked = !current.LeftToRight,
            GroupName = "SortOptionsOrientation",
            Margin = new Thickness(0, 0, 0, 1),
        };
        var leftToRightButton = new RadioButton
        {
            Content = presentation.SortLeftToRight,
            IsChecked = current.LeftToRight,
            GroupName = "SortOptionsOrientation",
        };
        StripContentMnemonic(topToBottomButton);
        StripContentMnemonic(leftToRightButton);
        AvaloniaCompactDialogChrome.ApplyCompactRadioButton(topToBottomButton, AvaloniaCompactDialogChrome.WindowsStyle);
        AvaloniaCompactDialogChrome.ApplyCompactRadioButton(leftToRightButton, AvaloniaCompactDialogChrome.WindowsStyle);
        AutomationProperties.SetAutomationId(topToBottomButton, "SortOptionsTopToBottomRadio");
        AutomationProperties.SetAutomationId(leftToRightButton, "SortOptionsLeftToRightRadio");

        var okButton = new Button { Content = UiText.Ok, IsDefault = true };
        var cancelButton = new Button { Content = UiText.Cancel, IsCancel = true };
        AvaloniaCompactDialogChrome.ApplyButton(okButton, AvaloniaCompactDialogChrome.WindowsStyle, 75, isDefault: true);
        AvaloniaCompactDialogChrome.ApplyButton(cancelButton, AvaloniaCompactDialogChrome.WindowsStyle, 75);
        AutomationProperties.SetAutomationId(okButton, "SortOptionsOkButton");
        AutomationProperties.SetAutomationId(cancelButton, "SortOptionsCancelButton");

        okButton.Click += (_, _) =>
        {
            result = SortOptionsPolicy.CreateResult(
                caseSensitiveBox.IsChecked == true,
                leftToRightButton.IsChecked == true,
                firstKeyBox.SelectedItem as SortOptionsFirstKeyOrderChoice,
                editorText: null);
            dialog.Close();
        };
        cancelButton.Click += (_, _) => dialog.Close();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                okButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
                e.Handled = true;
            }
            else if (e.Key == Key.Escape)
            {
                dialog.Close();
                e.Handled = true;
            }
        };

        var body = new StackPanel
        {
            Margin = new Thickness(0),
            Children =
            {
                caseSensitiveBox,
                new TextBlock { Text = StripDisplayMnemonic(presentation.FirstKeySortOrderLabel), FontSize = 12, Margin = new Thickness(0, 0, 0, 3) },
                firstKeyBox,
                new GroupBox
                {
                    Header = StripDisplayMnemonic(presentation.Orientation),
                    Padding = new Thickness(8),
                    Margin = new Thickness(0, 0, 0, 10),
                    Content = new StackPanel
                    {
                        Children =
                        {
                            topToBottomButton,
                            leftToRightButton,
                        },
                    },
                },
            },
        };
        var orientation = (GroupBox)body.Children[3];
        AvaloniaCompactDialogChrome.ApplyGroupBox(
            orientation,
            AvaloniaCompactDialogChrome.WindowsStyle,
            borderBrush: Brush(209, 218, 224));

        var buttons = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Children =
            {
                okButton,
                cancelButton,
            },
        };
        DockPanel.SetDock(body, Dock.Top);
        DockPanel.SetDock(buttons, Dock.Bottom);
        var root = new DockPanel { Margin = new Thickness(12), LastChildFill = false };
        root.Children.Add(body);
        root.Children.Add(buttons);
        dialog.Content = root;
        dialog.Opened += (_, _) =>
        {
            // The shared chrome supplies the Windows control language; these measured footer dimensions
            // preserve the authoritative WPF Sort Options capture inside the fixed 330x260 frame.
            AvaloniaCompactDialogChrome.ApplyButton(okButton, AvaloniaCompactDialogChrome.WindowsStyle, 75, isDefault: true);
            AvaloniaCompactDialogChrome.ApplyButton(cancelButton, AvaloniaCompactDialogChrome.WindowsStyle, 75);
            okButton.Height = okButton.MinHeight = okButton.MaxHeight = 52;
            cancelButton.Height = cancelButton.MinHeight = cancelButton.MaxHeight = 52;
        };
        await dialog.ShowDialog(this);
        return result;
    }

    private async Task ShowGoalSeekDialogAsync()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var request = await ShowGoalSeekInputDialogAsync();
        if (request is null)
            return;

        var proposal = _session.FindGoalSeekProposal(request);
        if (!proposal.Success)
        {
            ShowEditIssue(proposal.ErrorMessage ?? UiText.Get("MainWindowMessage_CommandCouldNotBeCompleted"));
            return;
        }

        var choice = await ShowGoalSeekStatusDialogAsync(proposal);
        if (choice != GoalSeekStatusDialogChoice.KeepResult)
            return;

        var result = _session.ApplyGoalSeekProposal(proposal);
        if (!result.Success)
        {
            ShowEditIssue(FormatGoalSeekStatus(result));
            return;
        }

        RefreshShell(FormatGoalSeekStatus(result));
    }

    private async Task<GoalSeekRequest?> ShowGoalSeekInputDialogAsync(
        string? initialSetCellText = null,
        string? initialTargetValueText = null,
        string? initialChangingCellText = null)
    {
        GoalSeekRequest? result = null;
        var dialog = new Window
        {
            Title = UiText.Get("GoalSeek_GoalSeek"),
            Width = 380,
            Height = 210,
            MinWidth = 380,
            MinHeight = 210,
            MaxWidth = 380,
            MaxHeight = 210,
            CanResize = false,
            FontFamily = FormulaBarFontFamily,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };
        AutomationProperties.SetAutomationId(dialog, "GoalSeekCompactDialog");

        var setCellBox = new TextBox
        {
            Text = initialSetCellText ?? FormatCellReference(_session.ActiveCell),
            MinWidth = 0,
            Margin = new Thickness(0, 4),
        };
        ApplyDataToolsTextBoxChrome(setCellBox);
        AutomationProperties.SetName(setCellBox, UiText.CreateAutomationName(UiText.Get("GoalSeek_SetCellAutomationName")));
        AutomationProperties.SetAutomationId(setCellBox, "GoalSeekSetCellBox");
        AutomationProperties.SetHelpText(setCellBox, UiText.Get("GoalSeek_SetCellHelpText"));

        var targetValueBox = new TextBox
        {
            Text = initialTargetValueText ?? "",
            MinWidth = 0,
            Margin = new Thickness(0, 4),
        };
        ApplyDataToolsTextBoxChrome(targetValueBox);
        AutomationProperties.SetName(targetValueBox, UiText.CreateAutomationName(UiText.Get("GoalSeek_ToValueAutomationName")));
        AutomationProperties.SetAutomationId(targetValueBox, "GoalSeekTargetValueBox");
        AutomationProperties.SetHelpText(targetValueBox, UiText.Get("GoalSeek_ToValueHelpText"));

        var changingCellBox = new TextBox
        {
            Text = initialChangingCellText ?? "",
            MinWidth = 0,
            Margin = new Thickness(0, 4),
        };
        ApplyDataToolsTextBoxChrome(changingCellBox);
        AutomationProperties.SetName(changingCellBox, UiText.CreateAutomationName(UiText.Get("GoalSeek_ByChangingCellAutomationName")));
        AutomationProperties.SetAutomationId(changingCellBox, "GoalSeekChangingCellBox");
        AutomationProperties.SetHelpText(changingCellBox, UiText.Get("GoalSeek_ByChangingCellHelpText"));

        var errorText = new TextBlock
        {
            Foreground = Brush(143, 74, 18),
            TextWrapping = TextWrapping.Wrap,
            IsVisible = false,
        };
        AutomationProperties.SetName(errorText, UiText.Get("GoalSeek_ValidationAutomationName"));
        AutomationProperties.SetAutomationId(errorText, "GoalSeekErrorText");
        AutomationProperties.SetHelpText(errorText, UiText.Get("GoalSeek_ValidationHelpText"));

        var okButton = new Button
        {
            Content = UiText.CreateAutomationName(UiText.Get("Common_Ok")),
            Width = 75,
            MinWidth = 75,
            IsDefault = true,
            Margin = new Thickness(0, 0, 6, 0),
        };
        ApplyDataToolsButtonChrome(okButton, 75, isDefault: true);
        AutomationProperties.SetName(okButton, UiText.CreateAutomationName(UiText.Get("Common_Ok")));
        AutomationProperties.SetAutomationId(okButton, "GoalSeekOkButton");
        AutomationProperties.SetHelpText(okButton, UiText.Get("GoalSeek_RunHelpText"));

        var cancelButton = new Button
        {
            Content = UiText.CreateAutomationName(UiText.Get("Common_Cancel")),
            Width = 75,
            MinWidth = 75,
            IsCancel = true,
        };
        ApplyDataToolsButtonChrome(cancelButton, 75);
        AutomationProperties.SetName(cancelButton, UiText.CreateAutomationName(UiText.Get("Common_Cancel")));
        AutomationProperties.SetAutomationId(cancelButton, "GoalSeekCancelButton");
        AutomationProperties.SetHelpText(cancelButton, UiText.Get("GoalSeek_CancelHelpText"));

        void Accept()
        {
            var parseResult = GoalSeekRequestParser.Parse(
                _session.ActiveSheet.Id,
                setCellBox.Text,
                targetValueBox.Text,
                changingCellBox.Text);
            if (!parseResult.Success)
            {
                var validation = GoalSeekStatusDialogPlanner.DescribeValidationError(parseResult);
                errorText.Text = validation.Message.Resolve(UiText.Get, UiText.Format);
                errorText.IsVisible = true;
                FocusGoalSeekErrorField(validation.FocusTarget, setCellBox, targetValueBox, changingCellBox);
                return;
            }

            result = parseResult.Request;
            dialog.Close();
        }

        okButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => dialog.Close();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                e.Handled = true;
                Accept();
            }
            else if (e.Key == Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Margin = new Thickness(0, 8, 0, 0),
            Children =
            {
                okButton,
                cancelButton,
            },
        };

        var body = new AvaloniaGrid
        {
            Margin = new Thickness(16),
            RowDefinitions =
            {
                new RowDefinition { Height = GridLength.Auto },
                new RowDefinition { Height = GridLength.Auto },
                new RowDefinition { Height = GridLength.Auto },
                new RowDefinition { Height = new GridLength(1, GridUnitType.Star) },
                new RowDefinition { Height = GridLength.Auto },
            },
        };
        body.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(140) });
        body.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        body.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(34) });
        AddGoalSeekField(body, row: 0, "Set cell:", setCellBox, CreateGoalSeekPickerButton(setCellBox, "GoalSeekSetCellPickerButton"));
        AddGoalSeekField(body, row: 1, "To value:", targetValueBox, pickerButton: null);
        AddGoalSeekField(body, row: 2, "By changing cell:", changingCellBox, CreateGoalSeekPickerButton(changingCellBox, "GoalSeekChangingCellPickerButton"));
        AddGridChild(body, errorText, 3, 0);
        AvaloniaGrid.SetColumnSpan(errorText, 3);
        AddGridChild(body, buttonRow, 4, 0);
        AvaloniaGrid.SetColumnSpan(buttonRow, 3);
        dialog.Content = body;
        dialog.Opened += (_, _) =>
        {
            setCellBox.Focus();
            setCellBox.SelectAll();
        };

        await dialog.ShowDialog(this);
        return result;
    }

    private async Task<GoalSeekStatusDialogChoice> ShowGoalSeekStatusDialogAsync(WorkbookGoalSeekProposal proposal)
    {
        var result = proposal.SeekResult ?? throw new ArgumentException("A valid Goal Seek proposal is required.", nameof(proposal));
        var choice = GoalSeekStatusDialogChoice.RestoreOriginalValues;
        var dialog = new Window
        {
            Title = UiText.Get("GoalSeekStatus_GoalSeekStatus"),
            Width = GoalSeekStatusDialogPlanner.WindowWidth,
            Height = GoalSeekStatusDialogPlanner.WindowHeight(result.Converged),
            MinWidth = GoalSeekStatusDialogPlanner.WindowWidth,
            MinHeight = GoalSeekStatusDialogPlanner.WindowHeight(result.Converged),
            MaxWidth = GoalSeekStatusDialogPlanner.WindowWidth,
            MaxHeight = GoalSeekStatusDialogPlanner.WindowHeight(result.Converged),
            CanResize = false,
            FontFamily = FormulaBarFontFamily,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };
        AutomationProperties.SetAutomationId(dialog, "GoalSeekStatusDialog");

        var summaryBlock = new TextBlock
        {
            Text = NormalizeAvaloniaMultilineText(FormatGoalSeekStatus(proposal)),
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(
                0,
                GoalSeekStatusDialogPlanner.SummaryTopCompensation,
                0,
                GoalSeekStatusDialogPlanner.SummaryBottomMargin),
            FontSize = 12,
            FontFamily = FormulaBarFontFamily,
            // Space the status lines out vertically to match the Windows dialog,
            // which renders each line with a blank-line gap between them.
            LineHeight = GoalSeekStatusDialogPlanner.SummaryLineHeight,
        };
        AutomationProperties.SetName(summaryBlock, UiText.CreateAutomationName(UiText.Get("GoalSeekStatus_GoalSeekStatus")));
        AutomationProperties.SetAutomationId(summaryBlock, "GoalSeekStatusText");
        AutomationProperties.SetHelpText(
            summaryBlock,
            UiText.Get("GoalSeekStatus_ReportsWhetherGoalSeekReachedTheTargetValue"));

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
        };
        DockPanel.SetDock(buttonRow, Dock.Bottom);

        Button defaultButton;
        if (result.Converged)
        {
            var restoreButton = new Button
            {
                Content = UiText.Get("GoalSeekStatus_RestoreOriginalValues2"),
                Width = GoalSeekStatusDialogPlanner.RestoreOriginalValuesButtonWidth,
                MinWidth = GoalSeekStatusDialogPlanner.RestoreOriginalValuesButtonWidth,
                IsCancel = true,
            };
            ApplyGoalSeekStatusButtonChrome(restoreButton, GoalSeekStatusDialogPlanner.RestoreOriginalValuesButtonWidth);
            AutomationProperties.SetName(restoreButton, UiText.CreateAutomationName(UiText.Get("GoalSeekStatus_RestoreOriginalValues2")));
            AutomationProperties.SetAutomationId(restoreButton, "GoalSeekRestoreOriginalValuesButton");
        AutomationProperties.SetHelpText(
            restoreButton,
            UiText.Get("GoalSeekStatus_RestoreTheOriginalWorkbookValuesBeforeGoalSeekRan"));

            var keepButton = new Button
            {
                Content = UiText.Get("GoalSeekStatus_KeepResult2"),
                Width = GoalSeekStatusDialogPlanner.KeepResultButtonWidth,
                MinWidth = GoalSeekStatusDialogPlanner.KeepResultButtonWidth,
                Margin = new Thickness(0, 0, GoalSeekStatusDialogPlanner.ButtonGap, 0),
                IsDefault = true,
            };
            ApplyGoalSeekStatusButtonChrome(keepButton, GoalSeekStatusDialogPlanner.KeepResultButtonWidth, isDefault: true);
            AutomationProperties.SetName(keepButton, UiText.CreateAutomationName(UiText.Get("GoalSeekStatus_KeepResult2")));
            AutomationProperties.SetAutomationId(keepButton, "GoalSeekKeepResultButton");
        AutomationProperties.SetHelpText(
            keepButton,
            UiText.Get("GoalSeekStatus_KeepTheGoalSeekResultInTheChangingCell"));

            restoreButton.Click += (_, _) =>
            {
                choice = GoalSeekStatusDialogChoice.RestoreOriginalValues;
                dialog.Close();
            };
            keepButton.Click += (_, _) =>
            {
                choice = GoalSeekStatusDialogChoice.KeepResult;
                dialog.Close();
            };
            buttonRow.Children.Add(keepButton);
            buttonRow.Children.Add(restoreButton);
            defaultButton = keepButton;
        }
        else
        {
            var okButton = new Button
            {
                Content = UiText.CreateAutomationName(UiText.Get("Common_Ok")),
                Width = GoalSeekStatusDialogPlanner.OkButtonWidth,
                MinWidth = GoalSeekStatusDialogPlanner.OkButtonWidth,
                IsDefault = true,
            };
            ApplyGoalSeekStatusButtonChrome(okButton, GoalSeekStatusDialogPlanner.OkButtonWidth, isDefault: true);
            AutomationProperties.SetName(okButton, UiText.CreateAutomationName(UiText.Get("Common_Ok")));
            AutomationProperties.SetAutomationId(okButton, "GoalSeekStatusOkButton");
            AutomationProperties.SetHelpText(okButton, UiText.Get("GoalSeekStatus_KeepTheGoalSeekResultInTheChangingCell"));
            okButton.Click += (_, _) =>
            {
                choice = GoalSeekStatusDialogChoice.KeepResult;
                dialog.Close();
            };

            var cancelButton = new Button
            {
                Content = UiText.Get("Common_Cancel"),
                Width = GoalSeekStatusDialogPlanner.OkButtonWidth,
                MinWidth = GoalSeekStatusDialogPlanner.OkButtonWidth,
                IsCancel = true,
            };
            ApplyGoalSeekStatusButtonChrome(cancelButton, GoalSeekStatusDialogPlanner.OkButtonWidth);
            AutomationProperties.SetName(cancelButton, UiText.CreateAutomationName(UiText.Get("Common_Cancel")));
            AutomationProperties.SetAutomationId(cancelButton, "GoalSeekStatusCancelButton");
            AutomationProperties.SetHelpText(cancelButton, UiText.Get("GoalSeekStatus_RestoreTheOriginalWorkbookValuesBeforeGoalSeekRan"));
            cancelButton.Click += (_, _) =>
            {
                choice = GoalSeekStatusDialogChoice.RestoreOriginalValues;
                dialog.Close();
            };
            buttonRow.Children.Add(okButton);
            buttonRow.Children.Add(cancelButton);
            defaultButton = okButton;
        }

        dialog.KeyDown += (_, e) =>
        {
            if (e.Key is Key.Enter or Key.Escape)
            {
                e.Handled = true;
                choice = e.Key == Key.Enter
                    ? GoalSeekStatusDialogChoice.KeepResult
                    : GoalSeekStatusDialogChoice.RestoreOriginalValues;
                dialog.Close();
            }
        };
        dialog.Content = new StackPanel
        {
            Margin = new Thickness(GoalSeekStatusDialogPlanner.ContentMargin),
            Children =
            {
                summaryBlock,
                new Border
                {
                    Child = buttonRow,
                    Margin = new Thickness(0, 0, GoalSeekStatusDialogPlanner.ContentMargin, 0),
                },
            },
        };
        dialog.Opened += (_, _) => defaultButton.Focus();

        await dialog.ShowDialog(this);
        return choice;
    }

    private static string NormalizeAvaloniaMultilineText(string text) =>
        text.Replace("\r\r\n", "\r\n", StringComparison.Ordinal)
            .ReplaceLineEndings("\n");

    private static string FormatGoalSeekStatus(WorkbookGoalSeekResult result)
    {
        var setCell = FormatCellReference(result.Request.SetCell);
        var changingCell = FormatCellReference(result.Request.ChangingCell);
        return result.Status switch
        {
            WorkbookGoalSeekStatus.Applied when result.SeekResult is { } seekResult =>
                GoalSeekStatusDialogPlanner.DescribeStatus(
                    seekResult.Converged,
                    result.Request.TargetValue,
                    seekResult.ActualResult,
                    seekResult.FoundValue,
                    seekResult.ActualResultError).Resolve(UiText.Get, UiText.Format),
            WorkbookGoalSeekStatus.NotConverged when result.SeekResult is { } seekResult =>
                GoalSeekStatusDialogPlanner.DescribeStatus(
                    false,
                    result.Request.TargetValue,
                    seekResult.ActualResult,
                    seekResult.FoundValue,
                    seekResult.ActualResultError).Resolve(UiText.Get, UiText.Format),
            _ => GoalSeekStatusDialogPlanner.DescribeExecutionFailure(
                result.Status,
                result.ErrorMessage,
                setCell,
                changingCell).Resolve(UiText.Get, UiText.Format)
        };
    }

    private static string FormatGoalSeekStatus(WorkbookGoalSeekProposal proposal)
    {
        var seekResult = proposal.SeekResult ?? throw new ArgumentException("A valid Goal Seek proposal is required.", nameof(proposal));
        return GoalSeekStatusDialogPlanner.DescribeStatus(
            seekResult.Converged,
            proposal.Request.TargetValue,
            seekResult.ActualResult,
            seekResult.FoundValue,
            seekResult.ActualResultError).Resolve(UiText.Get, UiText.Format);
    }

    private static void FocusGoalSeekErrorField(
        GoalSeekValidationFocusTarget focusTarget,
        TextBox setCellBox,
        TextBox targetValueBox,
        TextBox changingCellBox)
    {
        var target = focusTarget switch
        {
            GoalSeekValidationFocusTarget.TargetValue => targetValueBox,
            GoalSeekValidationFocusTarget.ChangingCell => changingCellBox,
            _ => setCellBox
        };
        target.Focus();
        target.SelectAll();
    }

    private static Button CreateGoalSeekPickerButton(TextBox target, string automationId)
    {
        var button = new Button
        {
            Content = "...",
            MinWidth = 26,
            Padding = new Thickness(0),
            Margin = new Thickness(6, 4, 0, 4),
        };
        AutomationProperties.SetAutomationId(button, automationId);
        button.Click += (_, _) =>
        {
            target.Focus();
            target.SelectAll();
        };

        return button;
    }

    private static void AddGoalSeekField(
        AvaloniaGrid grid,
        int row,
        string label,
        TextBox input,
        Button? pickerButton)
    {
        var labelBlock = new TextBlock
        {
            Text = StripDisplayMnemonic(label),
            VerticalAlignment = AvaloniaVerticalAlignment.Center,
            Margin = new Thickness(0, 4),
            FontSize = 12,
        };
        AddGridChild(grid, labelBlock, row, 0);
        AddGridChild(grid, input, row, 1);
        if (pickerButton is not null)
            AddGridChild(grid, pickerButton, row, 2);
    }

    private async Task ShowAdvancedFilterDialogAsync()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var plan = await ShowAdvancedFilterInputDialogAsync();
        if (plan is null)
            return;

        var result = _session.ExecuteAdvancedFilterPlan(plan);
        if (!result.Success)
        {
            RefreshShell(_statusText.Text ?? UiText.Get("MainLoc_Ready"));
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_AdvancedFilterFailed"));
            return;
        }

        _filterWorkflowSession.RememberAdvancedFilter(
            plan.ListRange,
            plan.CriteriaRange,
            plan.OutputMode == AdvancedFilterOutputMode.FilterInPlace,
            plan.UniqueRecordsOnly);

        RefreshShell(FormatAdvancedFilterStatus(plan));
    }

