        (AvaloniaGrid Row, Button PickerButton, TextBlock Label) CreateReferenceRow(
            string label,
            TextBox textBox,
            string pickerAutomationId,
            bool isFirstRow = false)
        {
            var labelBlock = new TextBlock
            {
                Text = StripDisplayMnemonic(label),
                VerticalAlignment = AvaloniaVerticalAlignment.Center,
                Margin = new Thickness(0, 0, 8, 0),
                FontSize = 12,
                FontFamily = FormulaBarFontFamily,
            };
            var pickerButton = new Button
            {
                Content = "...",
            };
            ApplyAdvancedFilterPickerButtonChrome(pickerButton);
            AutomationProperties.SetAutomationId(pickerButton, pickerAutomationId);
            pickerButton.Click += (_, _) =>
            {
                textBox.Focus();
                textBox.SelectAll();
            };

            var row = new AvaloniaGrid { Margin = new Thickness(0, isFirstRow ? 0 : 8, 0, 0) };
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            Grid.SetColumn(labelBlock, 0);
            Grid.SetColumn(pickerButton, 1);
            Grid.SetColumn(textBox, 2);
            row.Children.Add(labelBlock);
            row.Children.Add(pickerButton);
            row.Children.Add(textBox);
            return (row, pickerButton, labelBlock);
        }

        var listRangeRow = CreateReferenceRow(
            StripDisplayMnemonic(UiText.Get("AdvancedFilter_ListRange")) + ":",
            listRangeBox,
            FreeXAutomationIdCatalog.AdvancedFilter.SelectListRangeButton,
            isFirstRow: true);
        var criteriaRangeRow = CreateReferenceRow(
            StripDisplayMnemonic(UiText.Get("AdvancedFilter_CriteriaRange")) + ":",
            criteriaRangeBox,
            FreeXAutomationIdCatalog.AdvancedFilter.SelectCriteriaRangeButton);
        var copyToRow = CreateReferenceRow(
            StripDisplayMnemonic(UiText.Get("AdvancedFilter_CopyTo")) + ":",
            copyToBox,
            FreeXAutomationIdCatalog.AdvancedFilter.SelectCopyToButton);
        var copyToHint = new TextBlock
        {
            Text = UiText.Get("AdvancedFilter_CopyToIsAvailableWhenCopyToAnotherLocationIsSelected"),
            Foreground = SecondaryInk,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 2, 0, 0),
            FontSize = 12,
            FontFamily = FormulaBarFontFamily,
        };
        var criteriaHint = new TextBlock
        {
            Text = UiText.Get("AdvancedFilter_CriteriaShouldIncludeColumnLabelsInTheFirstRowMatchingExcelAdvancedFilte"),
            Foreground = SecondaryInk,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 8, 0, 0),
            FontSize = 12,
            FontFamily = FormulaBarFontFamily,
        };

        var showInteractiveValidation = false;

        void RefreshPlanStatus(bool showInvalid = false)
        {
            var planResult = CreatePlan();
            errorText.Text = AdvancedFilterPlanner
                .DescribeError(planResult, AdvancedFilterErrorPresentationKind.InlineValidation)
                .Message
                .Resolve(UiText.Get, UiText.Format);
            errorText.IsVisible = showInvalid && !planResult.Success;
        }

        void RefreshCopyToState(bool showInvalid = false)
        {
            var isCopyToEnabled = copyToAnotherLocationButton.IsChecked == true;
            copyToRow.Row.IsEnabled = isCopyToEnabled;
            copyToBox.IsEnabled = isCopyToEnabled;
            copyToHint.IsVisible = !isCopyToEnabled;
            RefreshPlanStatus(showInvalid);
        }

        void Accept()
        {
            var planResult = CreatePlan();
            if (!planResult.Success || planResult.Plan is null)
            {
                var error = AdvancedFilterPlanner.DescribeError(
                    planResult,
                    AdvancedFilterErrorPresentationKind.InlineValidation);
                errorText.Text = error.Message.Resolve(UiText.Get, UiText.Format);
                errorText.IsVisible = true;
                FocusAdvancedFilterErrorField(error.FocusTarget, listRangeBox, criteriaRangeBox, copyToBox);
                return;
            }

            result = planResult.Plan;
            dialog.Close();
        }

        void RefreshPlanStatusAfterInput() =>
            RefreshPlanStatus(showInvalid: showInteractiveValidation);

        okButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => dialog.Close();
        listRangeBox.TextChanged += (_, _) => RefreshPlanStatusAfterInput();
        criteriaRangeBox.TextChanged += (_, _) => RefreshPlanStatusAfterInput();
        copyToBox.TextChanged += (_, _) => RefreshPlanStatusAfterInput();
        uniqueBox.PropertyChanged += (_, e) =>
        {
            if (e.Property == ToggleButton.IsCheckedProperty)
                RefreshPlanStatusAfterInput();
        };
        inPlaceButton.PropertyChanged += (_, e) =>
        {
            if (e.Property == ToggleButton.IsCheckedProperty)
                RefreshCopyToState(showInvalid: showInteractiveValidation);
        };
        copyToAnotherLocationButton.PropertyChanged += (_, e) =>
        {
            if (e.Property == ToggleButton.IsCheckedProperty)
                RefreshCopyToState(showInvalid: showInteractiveValidation);
        };
        ConfigureAdvancedFilterDialogEscape(dialog, cancelButton);
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                e.Handled = true;
                Accept();
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Margin = new Thickness(0, 8, 0, 0),
            Children =
            {
                okButton,
                cancelButton,
            },
        };
        DockPanel.SetDock(buttonRow, Dock.Bottom);

        RefreshCopyToState();
        var actionPanel = new StackPanel
        {
            Margin = new Thickness(14, 17, 8, 0),
            Children =
            {
                inPlaceButton,
                copyToAnotherLocationButton,
            },
        };
        inPlaceButton.Margin = new Thickness(0, 0, 0, 4);
        var actionGroup = new AvaloniaGrid
        {
            Height = 60,
            Margin = new Thickness(0, 0, 0, 10),
            Children =
            {
                new Border
                {
                    BorderBrush = Brush(209, 218, 224),
                    BorderThickness = new Thickness(1),
                    Margin = new Thickness(0, 7, 0, 0),
                },
                new TextBlock
                {
                    Text = UiText.Get("AdvancedFilter_Action"),
                    FontSize = 12,
                    FontFamily = FormulaBarFontFamily,
                    Background = Brushes.White,
                    Padding = new Thickness(3, 0),
                    Margin = new Thickness(8, 0, 0, 0),
                    HorizontalAlignment = AvaloniaHorizontalAlignment.Left,
                    VerticalAlignment = AvaloniaVerticalAlignment.Top,
                },
                actionPanel,
            },
        };

        dialog.Content = new StackPanel
        {
            Margin = new Thickness(12),
            Children =
            {
                actionGroup,
                listRangeRow.Row,
                criteriaRangeRow.Row,
                copyToRow.Row,
                copyToHint,
                uniqueBox,
                criteriaHint,
                errorText,
                buttonRow,
            },
        };
        dialog.Opened += (_, _) =>
        {
            inPlaceButton.Focus();
            errorText.IsVisible = false;
            Dispatcher.UIThread.Post(() => showInteractiveValidation = true);
        };

        await dialog.ShowDialog(this);
        return result;
    }

    private static string FormatAdvancedFilterStatus(AdvancedFilterPlan plan)
    {
        var listRange = FormatRangeReference(plan.ListRange);
        return plan is
        {
            OutputMode: AdvancedFilterOutputMode.CopyToAnotherLocation,
            CopyToRange: { } copyToRange
        }
            ? $"Advanced Filter copied {listRange} to {FormatRangeReference(copyToRange)}"
            : $"Advanced Filter applied to {listRange}";
    }

    private static void FocusAdvancedFilterErrorField(
        AdvancedFilterErrorFocusTarget focusTarget,
        TextBox listRangeBox,
        TextBox criteriaRangeBox,
        TextBox copyToBox)
    {
        var target = focusTarget switch
        {
            AdvancedFilterErrorFocusTarget.CriteriaRange => criteriaRangeBox,
            AdvancedFilterErrorFocusTarget.CopyTo => copyToBox,
            _ => listRangeBox
        };
        target.Focus();
        target.SelectAll();
    }

    private async Task ShowSubtotalDialogAsync()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var selection = await ShowSubtotalInputDialogAsync();
        if (selection is null)
            return;

        var rangeReference = FormatRangeReference(_session.SelectedRange);
        var result = selection.Action == SubtotalDialogPlanAction.RemoveAll
            ? _session.RemoveSelectedRangeSubtotals()
            : _session.ExecuteSubtotalOptions(selection.ToInputOptions());
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_SubtotalFailed"));
            return;
        }

        RefreshShell(selection.Action == SubtotalDialogPlanAction.RemoveAll
            ? UiText.Format("MainLoc_RemovedSubtotalsFrom", rangeReference)
            : UiText.Format("MainLoc_AddedSubtotalsTo", rangeReference));
    }

    private async Task<SubtotalDialogPlanResult?> ShowSubtotalInputDialogAsync(
        GridRange? initialRange = null,
        IReadOnlyList<SubtotalDialogColumnChoice>? initialColumns = null,
        SubtotalDialogPlanResult? initialPlan = null)
    {
        SubtotalDialogPlanResult? result = null;
        var range = initialRange ?? _session.SelectedRange;
        var columns = initialColumns ?? SubtotalDialogPlanner.BuildColumnChoices(
            range,
            absoluteColumn => SpreadsheetDisplayFormatter.FormatScalarValue(
                _session.ActiveSheet.GetValue(range.Start.Row, absoluteColumn),
                SpreadsheetScalarFormatProfile.InvariantScalar));
        var plannerText = SubtotalDialogPlannerText.From(UiText.Get);
        var functions = SubtotalDialogPlanner.CreateFunctionChoices(plannerText);
        var initialGroupColumnOffset = initialPlan?.GroupColumnOffset ?? 0;
        var initialSubtotalColumnOffsets = initialPlan?.SubtotalColumnOffsets
            ?? columns.Where(static column => column.IsSelected).Select(static column => column.Offset).ToArray();
        var summaryBelowData = initialPlan?.SummaryBelowData ?? _session.ActiveSheet.OutlineSummaryBelow ?? true;

        var dialog = new Window
        {
            Title = UiText.Get("Subtotal_Subtotal"),
            Width = SubtotalDialogWidth,
            Height = SubtotalDialogHeight,
            MinWidth = SubtotalDialogWidth,
            MinHeight = SubtotalDialogHeight,
            MaxWidth = SubtotalDialogWidth,
            MaxHeight = SubtotalDialogHeight,
            CanResize = false,
            FontFamily = FormulaBarFontFamily,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };
        AvaloniaCompactDialogChrome.ApplyWindow(dialog, SubtotalDialogChromeStyle);
        AutomationProperties.SetAutomationId(dialog, "SubtotalCompactDialog");

        var groupColumnBox = new ComboBox
        {
            ItemsSource = columns,
            SelectedItem = columns.FirstOrDefault(column => column.Offset == initialGroupColumnOffset) ?? columns[0],
            HorizontalAlignment = AvaloniaHorizontalAlignment.Stretch,
        };
        ApplySubtotalComboBoxChrome(groupColumnBox);
        AutomationProperties.SetName(groupColumnBox, StripDisplayMnemonic(UiText.Get("Subtotal_AtEachChangeInAutomationName")));
        AutomationProperties.SetAutomationId(groupColumnBox, "SubtotalGroupColumnBox");
        AutomationProperties.SetHelpText(groupColumnBox, UiText.Get("Subtotal_AtEachChangeInHelpText"));

        var functionBox = new ComboBox
        {
            ItemsSource = functions,
            SelectedItem = (initialPlan is null
                ? functions.FirstOrDefault(function =>
                    string.Equals(function.FunctionText, SubtotalDialogPlanner.DefaultFunctionText, StringComparison.Ordinal))
                : SubtotalDialogPlanner.FindFunctionChoice(initialPlan.FunctionNumber, plannerText))
                ?? functions[0],
            HorizontalAlignment = AvaloniaHorizontalAlignment.Stretch,
        };
        ApplySubtotalComboBoxChrome(functionBox);
        AutomationProperties.SetName(functionBox, StripDisplayMnemonic(UiText.Get("Subtotal_UseFunctionAutomationName")));
        AutomationProperties.SetAutomationId(functionBox, "SubtotalFunctionBox");
        AutomationProperties.SetHelpText(functionBox, UiText.Get("Subtotal_UseFunctionHelpText"));

        var selectedOffsets = initialSubtotalColumnOffsets.ToHashSet();
        var columnsList = new ListBox
        {
            ItemsSource = columns,
            Height = 98,
            MinHeight = 98,
            MaxHeight = 98,
            Padding = new Thickness(0),
            BorderThickness = new Thickness(0),
        };
        columnsList.SetValue(ScrollViewer.VerticalScrollBarVisibilityProperty, ScrollBarVisibility.Hidden);
        columnsList.ItemTemplate = new FuncDataTemplate<SubtotalDialogColumnChoice>((column, _) =>
        {
            var box = new CheckBox
            {
                Content = column.Header,
                IsChecked = selectedOffsets.Contains(column.Offset),
                Margin = new Thickness(0, 0, 0, 4),
            };
            ApplySubtotalCheckBoxChrome(box);
            AutomationProperties.SetName(box, UiText.Format("Subtotal_ColumnAutomationNameFormat", column.Header));
            AutomationProperties.SetAutomationId(box, $"SubtotalColumn{column.Offset}Box");
            AutomationProperties.SetHelpText(box, UiText.Get("Subtotal_ColumnHelpText"));
            box.IsCheckedChanged += (_, _) =>
            {
                if (box.IsChecked == true)
                    selectedOffsets.Add(column.Offset);
                else
                    selectedOffsets.Remove(column.Offset);
            };
            return box;
        }, supportsRecycling: false);
        AutomationProperties.SetName(columnsList, StripDisplayMnemonic(UiText.Get("Subtotal_AddSubtotalToAutomationName")));
        AutomationProperties.SetAutomationId(columnsList, "SubtotalColumnsPanel");
        AutomationProperties.SetHelpText(columnsList, UiText.Get("Subtotal_AddSubtotalToHelpText"));

        var replaceBox = new CheckBox
        {
            Content = UiText.Get("Subtotal_ReplaceCurrentSubtotals"),
            IsChecked = initialPlan?.ReplaceCurrentSubtotals ?? true,
        };
        ApplySubtotalCheckBoxChrome(replaceBox);
        AutomationProperties.SetName(replaceBox, StripDisplayMnemonic(UiText.Get("Subtotal_ReplaceCurrentSubtotalsAutomationName")));
        AutomationProperties.SetAutomationId(replaceBox, "SubtotalReplaceCurrentBox");
        AutomationProperties.SetHelpText(replaceBox, UiText.Get("Subtotal_ReplaceCurrentSubtotalsHelpText"));

        var pageBreakBox = new CheckBox
        {
            Content = UiText.Get("Subtotal_PageBreakBetweenGroups"),
            IsChecked = initialPlan?.PageBreakBetweenGroups ?? false,
        };
        ApplySubtotalCheckBoxChrome(pageBreakBox);
        AutomationProperties.SetName(pageBreakBox, StripDisplayMnemonic(UiText.Get("Subtotal_PageBreakBetweenGroupsAutomationName")));
        AutomationProperties.SetAutomationId(pageBreakBox, "SubtotalPageBreakBox");
        AutomationProperties.SetHelpText(pageBreakBox, UiText.Get("Subtotal_PageBreakBetweenGroupsHelpText"));

        var summaryBelowBox = new CheckBox
        {
            Content = UiText.Get("Subtotal_SummaryBelowData"),
            IsChecked = summaryBelowData,
        };
        ApplySubtotalCheckBoxChrome(summaryBelowBox);
        AutomationProperties.SetName(summaryBelowBox, StripDisplayMnemonic(UiText.Get("Subtotal_SummaryBelowDataAutomationName")));
        AutomationProperties.SetAutomationId(summaryBelowBox, "SubtotalSummaryBelowBox");
        AutomationProperties.SetHelpText(summaryBelowBox, UiText.Get("Subtotal_SummaryBelowDataHelpText"));

        var errorText = new TextBlock
        {
            Foreground = Brush(143, 74, 18),
            TextWrapping = TextWrapping.Wrap,
        };
        AutomationProperties.SetName(errorText, UiText.Get("Subtotal_ValidationAutomationName"));
        AutomationProperties.SetAutomationId(errorText, "SubtotalErrorText");
        AutomationProperties.SetHelpText(errorText, UiText.Get("Subtotal_ValidationHelpText"));

        var okButton = new Button
        {
            Content = UiText.Ok,
            IsDefault = true,
            MinWidth = 76,
            Padding = new Thickness(10, 4),
        };
        AvaloniaCompactDialogChrome.ApplyButton(okButton, SubtotalDialogChromeStyle, 72, isDefault: true);
        AutomationProperties.SetName(okButton, UiText.Ok);
        AutomationProperties.SetAutomationId(okButton, "SubtotalOkButton");
        AutomationProperties.SetHelpText(okButton, UiText.Get("Subtotal_Subtotal"));

        var removeAllButton = new Button
        {
            Content = UiText.Get("Subtotal_RemoveAll"),
            MinWidth = 96,
            Padding = new Thickness(10, 4),
        };
        AvaloniaCompactDialogChrome.ApplyButton(removeAllButton, SubtotalDialogChromeStyle, 92);
        AutomationProperties.SetName(removeAllButton, UiText.Get("Subtotal_RemoveAllAutomationName"));
        AutomationProperties.SetAutomationId(removeAllButton, "SubtotalRemoveAllButton");
        AutomationProperties.SetHelpText(removeAllButton, UiText.Get("Subtotal_RemoveAllHelpText"));

        var cancelButton = new Button
        {
            Content = UiText.Cancel,
            IsCancel = true,
            MinWidth = 76,
            Padding = new Thickness(10, 4),
        };
        AvaloniaCompactDialogChrome.ApplyButton(cancelButton, SubtotalDialogChromeStyle, 72);
        AutomationProperties.SetName(cancelButton, UiText.Cancel);
        AutomationProperties.SetAutomationId(cancelButton, "SubtotalCancelButton");
        AutomationProperties.SetHelpText(cancelButton, UiText.Cancel);

        void Accept()
        {
            if (groupColumnBox.SelectedItem is not SubtotalDialogColumnChoice groupColumn ||
                functionBox.SelectedItem is not SubtotalDialogFunctionChoice functionChoice)
            {
                errorText.Text = SubtotalDialogInputParser
                    .DescribeIssue(SubtotalDialogInputParseIssue.InvalidGroupColumnOffset)
                    .Message
                    .Resolve(UiText.Get, UiText.Format);
                groupColumnBox.Focus();
                return;
            }

            if (selectedOffsets.Count == 0)
            {
                errorText.Text = SubtotalDialogInputParser
                    .DescribeIssue(SubtotalDialogInputParseIssue.InvalidSubtotalColumnOffsets)
                    .Message
                    .Resolve(UiText.Get, UiText.Format);
                columnsList.Focus();
                return;
            }

            if (!SubtotalDialogPlanner.TryCreateResult(
                    groupColumn.Offset,
                    selectedOffsets,
                    functionChoice.FunctionText,
                    replaceBox.IsChecked == true,
                    pageBreakBox.IsChecked == true,
                    summaryBelowBox.IsChecked == true,
                    out var plan,
                    out var issue))
            {
                errorText.Text = SubtotalDialogInputParser
                    .DescribeIssue(issue)
                    .Message
                    .Resolve(UiText.Get, UiText.Format);
                functionBox.Focus();
                return;
            }

            result = plan;
            dialog.Close();
        }

        okButton.Click += (_, _) => Accept();
        removeAllButton.Click += (_, _) =>
        {
            var plan = SubtotalDialogPlanner.CreateRemoveAllResult();
            result = plan;
            dialog.Close();
        };
        cancelButton.Click += (_, _) => dialog.Close();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                Accept();
                e.Handled = true;
            }
            else if (e.Key == Key.Escape)
            {
                dialog.Close();
                e.Handled = true;
            }
        };

        // WPF order: [Remove All] on the left, [OK] and [Cancel] on the right.
        var actionButtons = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Children =
            {
                okButton,
                cancelButton,
            },
        };
        var buttonRow = new Grid
        {
            Height = 22,
            Margin = new Thickness(0, 0, 0, 76),
            ColumnDefinitions = new ColumnDefinitions("Auto,*,Auto"),
            Children =
            {
                removeAllButton,
                actionButtons,
            },
        };
        Grid.SetColumn(actionButtons, 2);

        var columnsGroup = new GroupBox
        {
            Content = columnsList,
            Height = 100,
            MinHeight = 100,
            MaxHeight = 100,
            Padding = new Thickness(3, 0, 3, 0),
        };
        AvaloniaCompactDialogChrome.ApplyGroupBox(columnsGroup, SubtotalDialogChromeStyle);

        dialog.Content = new DockPanel
        {
            Margin = new Thickness(12, 12, 27, 12),
            Children =
            {
                buttonRow,
                new StackPanel
                {
                    Spacing = 0,
                    Children =
                    {
                        CreateSubtotalField(UiText.Get("Subtotal_AtEachChangeIn"), groupColumnBox),
                        CreateSubtotalField(UiText.Get("Subtotal_UseFunction"), functionBox, topMargin: 7),
                        CreateSubtotalLabel(UiText.Get("Subtotal_AddSubtotalTo"), columnsList, topMargin: 10),
                        columnsGroup,
                        replaceBox,
                        pageBreakBox,
                        summaryBelowBox,
                        errorText,
                    },
                },
            },
        };
        DockPanel.SetDock(buttonRow, Dock.Bottom);
        dialog.Opened += (_, _) =>
        {
            // ApplyWindow normalizes descendants for every dialog. Reapply this route's measured
            // metrics after that pass so Subtotal stays aligned with the WPF capture.
            ApplySubtotalComboBoxChrome(groupColumnBox);
            ApplySubtotalComboBoxChrome(functionBox);
            AvaloniaCompactDialogChrome.ApplyButton(okButton, SubtotalDialogChromeStyle, 72, isDefault: true);
            AvaloniaCompactDialogChrome.ApplyButton(removeAllButton, SubtotalDialogChromeStyle, 92);
            AvaloniaCompactDialogChrome.ApplyButton(cancelButton, SubtotalDialogChromeStyle, 72);
            groupColumnBox.Focus();
        };

        await dialog.ShowDialog(this);
        return result;
    }

    private static StackPanel CreateSubtotalField(string label, Control control, double topMargin = 0) =>
        new()
        {
            Margin = new Thickness(0, topMargin, 0, 0),
            Spacing = 2,
            Children =
            {
                CreateSubtotalLabel(label, control),
                control,
            },
        };

    private static Label CreateSubtotalLabel(string label, Control target, double topMargin = 0) =>
        new()
        {
            Content = CreateSubtotalAccessText(label),
            Target = target,
            Height = 14,
            MinHeight = 14,
            MaxHeight = 14,
            Padding = new Thickness(0),
            Margin = new Thickness(0, topMargin, 0, 0),
        };

    private static void ApplySubtotalComboBoxChrome(ComboBox comboBox)
    {
        AvaloniaCompactDialogChrome.ApplyComboBox(comboBox, SubtotalDialogChromeStyle);
    }

    private static AccessText CreateSubtotalAccessText(string label) =>
        new() { Text = label };

    private static void ApplySubtotalCheckBoxChrome(CheckBox checkBox)
    {
        StripContentMnemonic(checkBox);
        AvaloniaCompactDialogChrome.ApplyCompactCheckBox(checkBox, SubtotalDialogChromeStyle);
    }

    private async Task ShowRemoveDuplicatesDialogAsync()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var plan = await ShowRemoveDuplicatesInputDialogAsync();
        if (plan is null)
            return;

        var result = _session.ExecuteRemoveDuplicatesPlan(plan);
        if (!result.Success)
        {
            RefreshShell(_statusText.Text ?? UiText.Get("MainLoc_Ready"));
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_RemoveDuplicatesFailed"));
            return;
        }

        var status = FormatRemoveDuplicatesStatus(result);
        RefreshShell(status);
        await ShowTextDialogAsync(UiText.Get("MainWindowMessage_RemoveDuplicatesTitle"), status, 420, 220);
    }

    private async Task<RemoveDuplicatesPlan?> ShowRemoveDuplicatesInputDialogAsync(bool? forceHasHeaders = null)
    {
        RemoveDuplicatesPlan? result = null;
        var range = _session.SelectedRange;
        var hasHeaders = forceHasHeaders ?? RemoveDuplicatesPlanner.GuessHasHeaders(_session.ActiveSheet, range);
        IReadOnlyList<RemoveDuplicateColumnChoice> columns =
            RemoveDuplicatesPlanner.BuildColumnChoices(_session.ActiveSheet, range, hasHeaders);

        var dialog = new Window
        {
            Title = UiText.Get("MainWindowMessage_RemoveDuplicatesTitle"),
            Width = 360,
            Height = 360,
            MinWidth = 360,
            MinHeight = 360,
            MaxWidth = 360,
            MaxHeight = 360,
            CanResize = false,
            FontFamily = FormulaBarFontFamily,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };
        AutomationProperties.SetAutomationId(dialog, "RemoveDuplicatesCompactDialog");

        var hasHeadersBox = new CheckBox
        {
            Content = UiText.Get("RemoveDuplicates_MyDataHasHeadersAutomationName"),
            IsChecked = hasHeaders,
            Margin = new Thickness(0, 0, 0, 8),
        };
        AutomationProperties.SetName(hasHeadersBox, UiText.CreateAutomationName(UiText.Get("RemoveDuplicates_MyDataHasHeadersAutomationName")));
        AutomationProperties.SetAutomationId(hasHeadersBox, "RemoveDuplicatesHasHeadersBox");
        AutomationProperties.SetHelpText(hasHeadersBox, UiText.Get("RemoveDuplicates_MyDataHasHeadersHelpText"));
        ApplyDialogCheckBoxChrome(hasHeadersBox);

        var columnsPanel = new StackPanel
        {
            Spacing = 4,
        };
        AutomationProperties.SetName(columnsPanel, UiText.CreateAutomationName(UiText.Get("RemoveDuplicates_ColumnsAutomationName")));
        AutomationProperties.SetAutomationId(columnsPanel, "RemoveDuplicatesColumnsPanel");
        AutomationProperties.SetHelpText(columnsPanel, UiText.Get("RemoveDuplicates_ColumnsHelpText"));

        var columnBoxes = new List<CheckBox>();

        IReadOnlyList<RemoveDuplicateColumnChoice> CaptureColumns() =>
            columns.Select((column, index) =>
                column with { IsSelected = columnBoxes.ElementAtOrDefault(index)?.IsChecked == true }).ToArray();

        void RenderColumns(IReadOnlyList<RemoveDuplicateColumnChoice> nextColumns)
        {
            columns = nextColumns;
            columnBoxes.Clear();
            columnsPanel.Children.Clear();
            foreach (var column in columns)
            {
                var box = new CheckBox
                {
                    Content = column.Label,
                    IsChecked = column.IsSelected,
                    Margin = new Thickness(0, 0, 0, 4),
                };
                AutomationProperties.SetName(box, column.Label);
                AutomationProperties.SetAutomationId(box, $"RemoveDuplicatesColumn{column.Offset}Box");
                AutomationProperties.SetHelpText(box, UiText.Get("RemoveDuplicates_ColumnHelpText"));
                ApplyDialogCheckBoxChrome(box);
                box.PropertyChanged += (_, e) =>
                {
                    if (e.Property == ToggleButton.IsCheckedProperty)
                        RefreshBulkButtonState();
                };
                columnBoxes.Add(box);
                columnsPanel.Children.Add(box);
            }

            RefreshBulkButtonState();
        }

        var selectAllButton = new Button
        {
            Content = StripDisplayMnemonic(UiText.Get("RemoveDuplicates_SelectAll")),
            Width = 88,
            MinWidth = 88,
            Margin = new Thickness(0, 0, 8, 0),
        };
        AutomationProperties.SetName(selectAllButton, UiText.Get("RemoveDuplicates_SelectAllAutomationName"));
        AutomationProperties.SetAutomationId(selectAllButton, "RemoveDuplicatesSelectAllButton");
        AutomationProperties.SetHelpText(selectAllButton, UiText.Get("RemoveDuplicates_SelectAllHelpText"));
        ApplyDialogButtonChrome(selectAllButton, width: 88);

        var unselectAllButton = new Button
        {
            Content = StripDisplayMnemonic(UiText.Get("RemoveDuplicates_UnselectAll")),
            Width = 88,
            MinWidth = 88,
        };
        AutomationProperties.SetName(unselectAllButton, UiText.Get("RemoveDuplicates_UnselectAllAutomationName"));
        AutomationProperties.SetAutomationId(unselectAllButton, "RemoveDuplicatesUnselectAllButton");
        AutomationProperties.SetHelpText(unselectAllButton, UiText.Get("RemoveDuplicates_UnselectAllHelpText"));
        ApplyDialogButtonChrome(unselectAllButton, width: 88);

        var errorText = new TextBlock
        {
            Foreground = Brush(143, 74, 18),
            TextWrapping = TextWrapping.Wrap,
            IsVisible = false,
        };
        AutomationProperties.SetName(errorText, UiText.Get("RemoveDuplicates_ValidationAutomationName"));
        AutomationProperties.SetAutomationId(errorText, "RemoveDuplicatesErrorText");
        AutomationProperties.SetHelpText(errorText, UiText.Get("RemoveDuplicates_ValidationHelpText"));

        var okButton = new Button
        {
            Content = UiText.CreateAutomationName(UiText.Get("Common_Ok")),
            Width = 72,
            MinWidth = 72,
            IsDefault = true,
        };
        AutomationProperties.SetName(okButton, UiText.CreateAutomationName(UiText.Get("Common_Ok")));
        AutomationProperties.SetAutomationId(okButton, "RemoveDuplicatesOkButton");
        AutomationProperties.SetHelpText(okButton, UiText.Get("RemoveDuplicates_ApplyHelpText"));
        ApplyDialogButtonChrome(okButton, width: 72, isDefault: true);

        var cancelButton = new Button
        {
            Content = UiText.CreateAutomationName(UiText.Get("Common_Cancel")),
            Width = 72,
            MinWidth = 72,
            IsCancel = true,
        };
        AutomationProperties.SetName(cancelButton, UiText.CreateAutomationName(UiText.Get("Common_Cancel")));
        AutomationProperties.SetAutomationId(cancelButton, "RemoveDuplicatesCancelButton");
        AutomationProperties.SetHelpText(cancelButton, UiText.Get("RemoveDuplicates_CancelHelpText"));
        ApplyDialogButtonChrome(cancelButton, width: 72);

        void RefreshBulkButtonState()
        {
            var selectedCount = columnBoxes.Count(static box => box.IsChecked == true);
            selectAllButton.IsEnabled = selectedCount < columnBoxes.Count;
            unselectAllButton.IsEnabled = selectedCount > 0;
        }

        void RebuildColumnsForHeaderState()
        {
            var previous = CaptureColumns().ToDictionary(static column => column.Offset, static column => column.IsSelected);
            var rebuilt = RemoveDuplicatesPlanner
                .BuildColumnChoices(_session.ActiveSheet, range, hasHeadersBox.IsChecked == true)
                .Select(column => column with
                {
                    IsSelected = previous.TryGetValue(column.Offset, out var selected)
                        ? selected
                        : column.IsSelected,
                })
                .ToArray();
            RenderColumns(rebuilt);
        }

        void Accept()
        {
            var planResult = RemoveDuplicatesPlanner.CreatePlan(
                range,
                hasHeadersBox.IsChecked == true,
                CaptureColumns());
            if (!planResult.IsReady || planResult.Plan is null)
            {
                errorText.Text = planResult.StatusText;
                errorText.IsVisible = true;
                Control focusTarget = selectAllButton;
                foreach (var columnBox in columnBoxes)
                {
                    focusTarget = columnBox;
                    break;
                }

                focusTarget.Focus();
                return;
            }

            result = planResult.Plan;
            dialog.Close();
        }

        hasHeadersBox.PropertyChanged += (_, e) =>
        {
            if (e.Property == ToggleButton.IsCheckedProperty)
                RebuildColumnsForHeaderState();
        };
        selectAllButton.Click += (_, _) =>
        {
            errorText.Text = "";
            errorText.IsVisible = false;
            RenderColumns(RemoveDuplicatesPlanner.SelectAll(CaptureColumns()));
        };
        unselectAllButton.Click += (_, _) =>
        {
            errorText.Text = "";
            errorText.IsVisible = false;
            RenderColumns(RemoveDuplicatesPlanner.ClearAll(CaptureColumns()));
        };
        okButton.Click += (_, _) => Accept();
        cancelButton.Click += (_, _) => dialog.Close();
        RenderColumns(columns);

        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                Accept();
                e.Handled = true;
            }
            else if (e.Key == Key.Escape)
            {
                dialog.Close();
                e.Handled = true;
            }
        };

        dialog.Content = new Border
        {
            Padding = new Thickness(12),
            Child = new StackPanel
            {
                Children =
                {
                    hasHeadersBox,
                    new TextBlock
                    {
                        Text = StripDisplayMnemonic(UiText.Get("RemoveDuplicates_Columns")),
                        Margin = new Thickness(0, 0, 0, 4),
                    },
                    new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 0, 0, 8),
                        Children =
                        {
                            selectAllButton,
                            unselectAllButton,
                        },
                    },
                    new ScrollViewer
                    {
                        Height = 160,
                        VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                        Content = columnsPanel,
                    },
                    errorText,
                    new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
                        Spacing = 8,
                        Margin = new Thickness(0, 12, 0, 0),
                        Children =
                        {
                            okButton,
                            cancelButton,
                        },
                    },
                },
            },
        };
        dialog.Opened += (_, _) => hasHeadersBox.Focus();

        await dialog.ShowDialog(this);
        return result;
    }

    private static string FormatRemoveDuplicatesStatus(WorkbookRemoveDuplicatesResult result) =>
        // R92-render-localization-chrome-5-3: reuse the WPF host's own resx-backed message
        // (MainWindow.DataCommands.cs) instead of a hardcoded, English-only, naively-pluralized
        // ("row"/"rows") sentence -- the shared catalog already owns this exact status string.
        UiText.Format("MainWindowMessage_RemoveDuplicatesRemovedRows", result.RemovedRowCount);

    private async Task ShowScenarioManagerDialogAsync()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var initialPlan = ScenarioManagerPlanner.CreateDialogPlan(_session.Workbook);
        if (!initialPlan.IsReady)
        {
            ShowEditIssue(initialPlan.StatusText ?? UiText.Get("MainLoc_ScenarioManagerFailed"));
            return;
        }

        await ShowScenarioManagerCompactDialogAsync(initialPlan);
    }

