        string? CurrentScenarioName() =>
            scenarioList.SelectedItem is ScenarioManagerDialogScenarioItem item
                ? item.Choice.Name
                : selectedScenarioName;

        void RefreshSelectionDetails()
        {
            var selected = scenarioList.SelectedItem is ScenarioManagerDialogScenarioItem item
                ? item.Choice
                : null;
            selectedScenarioName = selected?.Name;
            showButton.IsEnabled = selected is not null;
            deleteButton.IsEnabled = selected is not null;
            editButton.IsEnabled = selected is not null;
            AvaloniaCompactDialogChrome.ApplyButton(showButton, dialogChrome, ScenarioManagerDialogLayout.ActionButtonWidth, isDefault: selected is not null);

            var selectedDialogItem = selected is null
                ? null
                : ScenarioManagerDialogPlanner.BuildItems(_session.Workbook)
                    .FirstOrDefault(item => string.Equals(item.Name, selected.Name, StringComparison.OrdinalIgnoreCase));
            var fields = ScenarioManagerDialogPlanner.ProjectSelectionFields(
                selectedDialogItem,
                nameBox.Text ?? "",
                ScenarioManagerPlanner.GetDefaultScenarioName(plan.Scenarios.Select(scenario => scenario.Name)));
            if (fields is not null)
            {
                nameBox.Text = fields.ScenarioName;
                changingCellsBox.Text = fields.ChangingCellsText;
                resultCellsBox.Text = fields.ResultCellsText;
                commentBox.Text = fields.CommentText;
                preventChangesBox.IsChecked = fields.Locked;
                hideBox.IsChecked = fields.Hidden;
            }
        }

        void RefreshDialogPlan(string? preferredScenarioName = null)
        {
            plan = ScenarioManagerPlanner.CreateDialogPlan(_session.Workbook, preferredScenarioName ?? selectedScenarioName);
            var items = plan.Scenarios
                .Select(choice => new ScenarioManagerDialogScenarioItem(choice))
                .ToArray();
            scenarioList.ItemsSource = items;
            ScenarioManagerDialogScenarioItem? selectedItem = null;
            foreach (var item in items)
            {
                if (item.Choice.IsSelected)
                {
                    selectedItem = item;
                    break;
                }
            }

            scenarioList.SelectedItem = selectedItem;
            changingCellsBox.Text = FormatRangeReference(_session.SelectedRange);
            summaryButton.IsEnabled = items.Length > 0;
            RefreshSelectionDetails();
        }

        SheetId? ResolveScenarioManagerSheetIdByName(string sheetName) =>
            _session.Workbook.Sheets.FirstOrDefault(
                sheet => string.Equals(sheet.Name, sheetName, StringComparison.OrdinalIgnoreCase))?.Id;

        Control ValidationTarget(ScenarioManagerDialogValidationField field) =>
            field switch
            {
                ScenarioManagerDialogValidationField.ScenarioName => nameBox,
                ScenarioManagerDialogValidationField.ChangingCells => changingCellsBox,
                ScenarioManagerDialogValidationField.ResultCells => resultCellsBox,
                _ => nameBox,
            };

        bool ValidateScenarioManagerFields(ScenarioManagerAction action)
        {
            var failure = ScenarioManagerDialogPlanner.ValidateAcceptRequest(
                action,
                nameBox.Text,
                changingCellsBox.Text,
                resultCellsBox.Text,
                _session.ActiveSheet.Id,
                ResolveScenarioManagerSheetIdByName);
            if (failure is null)
                return true;

            var presentation = ScenarioManagerDialogPlanner.DescribeValidationFailure(failure);
            var message = presentation.Message.Resolve(UiText.Get, UiText.Format);
            errorText.Text = message;
            errorText.IsVisible = true;
            ShowEditIssue(message);
            var target = ValidationTarget(presentation.FocusTarget);
            target.Focus();
            if (target is TextBox textBox)
                textBox.SelectAll();
            return false;
        }

        bool TryReadScenarioManagerRanges(
            string? text,
            out IReadOnlyList<GridRange> ranges)
        {
            if (string.IsNullOrWhiteSpace(text))
            {
                ranges = [_session.SelectedRange];
                return true;
            }

            return WorkbookRangeTextCodec.TryParseMany(
                _session.ActiveSheet.Id,
                text,
                ResolveScenarioManagerSheetIdByName,
                out ranges);
        }

        void ReportScenarioManagerFailure(WorkbookCellEditResult result)
        {
        var message = result.ErrorMessage ?? UiText.Get("MainLoc_ScenarioManagerFailed");
            errorText.Text = message;
            errorText.IsVisible = true;
            ShowEditIssue(message);
        }

        bool ApplyScenarioManagerResult(WorkbookCellEditResult result, string status)
        {
            if (!result.Success)
            {
                ReportScenarioManagerFailure(result);
                return false;
            }

            errorText.Text = "";
            errorText.IsVisible = false;
            RefreshShell(status);
            return true;
        }

        void SaveCurrentValues(ScenarioManagerAction action)
        {
            if (!ValidateScenarioManagerFields(action))
                return;

            if (!TryReadScenarioManagerRanges(changingCellsBox.Text, out var ranges))
            {
                var message = ScenarioManagerDialogPlanner
                    .DescribeValidationError(ScenarioManagerDialogValidationError.EnterValidChangingCellsReference)!
                    .Resolve(UiText.Get, UiText.Format);
                errorText.Text = message;
                errorText.IsVisible = true;
                ShowEditIssue(message);
                changingCellsBox.Focus();
                changingCellsBox.SelectAll();
                return;
            }

            var changingCells = CaptureScenarioManagerChangingCells(ranges);
            var selectedDialogItem = ScenarioManagerDialogPlanner.BuildItems(_session.Workbook)
                .FirstOrDefault(item => string.Equals(
                    item.Name,
                    CurrentScenarioName(),
                    StringComparison.OrdinalIgnoreCase));
            var accepted = ScenarioManagerDialogPlanner.ProjectAcceptResult(
                action,
                selectedDialogItem,
                nameBox.Text ?? "",
                changingCellsBox.Text ?? "",
                resultCellsBox.Text ?? "",
                commentBox.Text ?? "",
                preventChangesBox.IsChecked == true,
                hideBox.IsChecked == true);
            var acceptedName = accepted.NewScenarioName.Trim();
            var request = new ScenarioManagerSaveRequest(
                acceptedName,
                changingCells,
                ReplaceScenarioName: accepted.Action == ScenarioManagerAction.Edit
                    ? accepted.SelectedScenarioName
                    : null,
                Comment: accepted.CommentText,
                Hidden: accepted.Hidden,
                Locked: accepted.Locked);
            var savePlan = ScenarioManagerPlanner.CreateSavePlan(_session.Workbook, request);
            var result = _session.ExecuteScenarioManagerSavePlan(savePlan, request);
            if (!ApplyScenarioManagerResult(
                    result,
                    UiText.Format("MainLoc_SavedX", acceptedName)))
            {
                var target = action == ScenarioManagerAction.Edit
                    ? nameBox
                    : changingCellsBox;
                target.Focus();
                target.SelectAll();
                return;
            }

            RefreshDialogPlan(acceptedName);
            nameBox.Text = ScenarioManagerPlanner.GetDefaultScenarioName(plan.Scenarios.Select(scenario => scenario.Name));
            commentBox.Text = "";
        }

        void ShowSelectedScenario()
        {
            var scenarioName = CurrentScenarioName();
            var showPlan = ScenarioManagerPlanner.CreateShowPlan(_session.Workbook, scenarioName);
            var result = _session.ExecuteScenarioManagerShowPlan(showPlan);
            if (!ApplyScenarioManagerResult(
                    result,
                    UiText.Format(
                        "MainLoc_ActionRangeStatusFormat",
                        UiText.Get("ScenarioManager_Show"),
                        showPlan.SelectedScenario?.Name ?? scenarioName)))
                return;

            RefreshDialogPlan(showPlan.SelectedScenario?.Name ?? scenarioName);
        }

        void DeleteSelectedScenario()
        {
            var scenarioName = CurrentScenarioName();
            var deletePlan = ScenarioManagerPlanner.CreateDeletePlan(_session.Workbook, scenarioName);
            var deletedName = deletePlan.SelectedScenario?.Name
                ?? scenarioName
                ?? UiText.Get("ScenarioManager_ScenarioFallbackName");
            var result = _session.ExecuteScenarioManagerDeletePlan(deletePlan);
            if (!ApplyScenarioManagerResult(
                    result,
                    UiText.Format("ScenarioManager_DeletedStatusFormat", deletedName)))
                return;

            RefreshDialogPlan();
            nameBox.Text = ScenarioManagerPlanner.GetDefaultScenarioName(plan.Scenarios.Select(scenario => scenario.Name));
        }

        void CreateSummaryReport()
        {
            if (!ValidateScenarioManagerFields(ScenarioManagerAction.Report))
                return;

            IReadOnlyList<CellAddress> resultCells = [];
            if (!string.IsNullOrWhiteSpace(resultCellsBox.Text))
            {
                if (!WorkbookRangeTextCodec.TryParseMany(
                        _session.ActiveSheet.Id,
                        resultCellsBox.Text,
                        ResolveScenarioManagerSheetIdByName,
                        out var resultRanges))
                {
                    var message = UiText.Get("ScenarioManager_EnterValidResultCellsReference");
                    errorText.Text = message;
                    errorText.IsVisible = true;
                    ShowEditIssue(message);
                    resultCellsBox.Focus();
                    resultCellsBox.SelectAll();
                    return;
                }

                resultCells = resultRanges.SelectMany(range => range.AllCells()).Distinct().ToArray();
            }

            var summaryPlan = ScenarioManagerPlanner.CreateSummaryReportPlan(_session.Workbook, resultCells);
            var result = _session.ExecuteScenarioManagerSummaryReportPlan(summaryPlan);
            if (!ApplyScenarioManagerResult(
                    result,
                    UiText.Format(
                        "MainLoc_ActionRangeStatusFormat",
                        UiText.Get("ScenarioManager_Summary"),
                        FormatCountLabel(
                            summaryPlan.Scenarios.Count,
                            "ScenarioManager_ScenarioSingular",
                            "ScenarioManager_ScenarioPlural"))))
                return;

            RefreshDialogPlan(selectedScenarioName);
        }

        scenarioList.SelectionChanged += (_, _) => RefreshSelectionDetails();
        saveButton.Click += (_, _) => SaveCurrentValues(ScenarioManagerAction.Add);
        editButton.Click += (_, _) => SaveCurrentValues(ScenarioManagerAction.Edit);
        showButton.Click += (_, _) => ShowSelectedScenario();
        deleteButton.Click += (_, _) => DeleteSelectedScenario();
        summaryButton.Click += (_, _) => CreateSummaryReport();
        closeButton.Click += (_, _) => dialog.Close();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Escape)
            {
                e.Handled = true;
                dialog.Close();
            }
        };

        var closeButtonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Margin = new Thickness(0, ScenarioManagerDialogLayout.CloseRowTopMargin, 0, 0),
            Children =
            {
                closeButton,
            },
        };

        var actionColumn = new StackPanel
        {
            Spacing = 6,
            VerticalAlignment = AvaloniaVerticalAlignment.Top,
            Margin = new Thickness(10, 20, 0, 0),
            Children =
            {
                saveButton,
                editButton,
                deleteButton,
                showButton,
                summaryButton,
            },
        };

        var scenariosHeader = new TextBlock
        {
            Text = StripDisplayMnemonic(UiText.Get("ScenarioManager_Scenarios")),
            Margin = new Thickness(0, 0, 0, ScenarioManagerDialogLayout.ScenarioListHeaderBottomMargin),
        };

        var fields = new AvaloniaGrid
        {
            RowDefinitions = new RowDefinitions("Auto,Auto,Auto,Auto,Auto,Auto"),
            ColumnDefinitions = new ColumnDefinitions($"{ScenarioManagerDialogLayout.FieldLabelColumnWidth},*"),
        };

        AddScenarioManagerField(fields, 0, StripDisplayMnemonic(UiText.Get("ScenarioManager_ScenarioName")), nameBox);
        AddScenarioManagerField(fields, 1, StripDisplayMnemonic(UiText.Get("ScenarioManager_ChangingCells")), changingCellsBox);
        AddScenarioManagerField(fields, 2, StripDisplayMnemonic(UiText.Get("ScenarioManager_ResultCells")), resultCellsBox);
        AddScenarioManagerField(fields, 3, StripDisplayMnemonic(UiText.Get("ScenarioManager_Comment")), commentBox);
        AddScenarioManagerCheckBox(fields, 4, preventChangesBox);
        AddScenarioManagerCheckBox(fields, 5, hideBox);

        var addEditGroup = new GroupBox
        {
            Header = StripDisplayMnemonic(UiText.Get("ScenarioManager_AddEditScenario")),
            Margin = new Thickness(0, ScenarioManagerDialogLayout.GroupTopMargin, 0, 0),
            Padding = new Thickness(8),
            Content = fields,
        };
        AvaloniaCompactDialogChrome.ApplyGroupBox(addEditGroup, dialogChrome);

        var body = new AvaloniaGrid
        {
            ColumnDefinitions = new ColumnDefinitions("*,Auto"),
        };
        var left = new StackPanel
        {
            Children = { scenariosHeader, scenarioList, addEditGroup },
        };
        body.Children.Add(left);
        body.Children.Add(actionColumn);
        AvaloniaGrid.SetColumn(actionColumn, 1);

        RefreshDialogPlan(selectedScenarioName);
        if (plan.SelectedScenario is null)
            nameBox.Text = ScenarioManagerPlanner.GetDefaultScenarioName(plan.Scenarios.Select(scenario => scenario.Name));
        dialog.Content = new AvaloniaGrid
        {
            Margin = new Thickness(12),
            RowDefinitions = new RowDefinitions("*,Auto,Auto"),
            Children = { body, errorText, closeButtonRow },
        };
        AvaloniaGrid.SetRow(body, 0);
        AvaloniaGrid.SetRow(errorText, 1);
        AvaloniaGrid.SetRow(closeButtonRow, 2);
        dialog.Opened += (_, _) =>
        {
            if (plan.Scenarios.Count > 0)
                scenarioList.Focus();
            else
                nameBox.Focus();
        };

        await dialog.ShowDialog(this);
    }

    private IReadOnlyList<ScenarioCellValue> CaptureScenarioManagerChangingCells(
        IReadOnlyList<GridRange> ranges)
    {
        var values = new List<ScenarioCellValue>();
        var seen = new HashSet<CellAddress>();
        foreach (var range in ranges)
        {
            var sheet = _session.Workbook.GetSheet(range.Start.Sheet);
            if (sheet is null)
                continue;

            foreach (var address in range.AllCells())
            {
                if (seen.Add(address))
                    values.Add(new ScenarioCellValue(address, sheet.GetValue(address)));
            }
        }

        return values;
    }

    private static string FormatScenarioManagerSelectionSummary(GridRange range) =>
        UiText.Format(
            "MainLoc_SelectedX",
            FormatRangeReference(range));

    private static string FormatScenarioManagerScenarioDetails(ScenarioManagerScenarioChoice? choice)
    {
        if (choice is null)
            return UiText.Get("ScenarioManager_NoScenarioSelected");

        var comment = string.IsNullOrWhiteSpace(choice.Comment)
            ? UiText.Get("ScenarioManager_NoComment")
            : choice.Comment.Trim();
        var flags = new List<string>();
        if (choice.Hidden)
            flags.Add(UiText.Get("ScenarioManager_HiddenState"));
        if (choice.Locked)
            flags.Add(UiText.Get("ScenarioManager_LockedState"));

        var flagText = flags.Count == 0
            ? UiText.Get("ScenarioManager_VisibleEditableState")
            : UiText.Format("ScenarioManager_FlagListFormat", string.Join(UiText.Get("ManageConditionalFormats_ListSeparator"), flags));
        return string.Join(
            Environment.NewLine,
            UiText.Format(
                "MainLoc_ActionRangeStatusFormat",
                choice.Name,
                FormatCountLabel(
                    choice.ChangingCellCount,
                    "ScenarioManager_ChangingCellSingular",
                    "ScenarioManager_ChangingCellPlural")),
            comment,
            flagText);
    }

    private static string FormatCountLabel(long count, string singularKey, string pluralKey) =>
        UiText.Get(count == 1 ? singularKey : pluralKey);

