    private void UndoLastEdit()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        ApplyEditHistoryResult(_session.UndoLastEdit(), "Undid last edit");
    }

    private void RedoLastEdit()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        ApplyEditHistoryResult(_session.RedoLastEdit(), "Redid last edit");
    }

    private void ApplyEditHistoryResult(WorkbookCellEditResult result, string successStatus)
    {
        if (!result.Success)
        {
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_EditHistoryUnavailable"));
            return;
        }

        // R127C-avalonia-clipboard-marquee-undo-redo-1: WorkbookSession.UndoLastEdit/RedoLastEdit
        // already retire the SESSION-level pending Copy/Cut on success (CancelPendingCutAfterMutatingEdit,
        // unconditional since R127-services-clipboard-formats-copy-cancel-1 -- covers a plain Copy too,
        // not only a Cut), but this shell's own marching-ants overlay (_clipboardMarqueeRange in
        // MainWindow.cs) is separate UI-only state that RefreshShell does not touch. Clear it here so
        // a still-shown marquee doesn't misleadingly suggest a later Paste would still honor a
        // snapshot Undo/Redo just invalidated -- matching the WPF host's ExecuteUndo/ExecuteRedo, which
        // call ClearClipboardMarqueeAfterStructuralEdit whenever the command outcome is not a no-op
        // (and this method is only reached via a Success result, so every call here is a real change).
        SetClipboardMarquee(null, isCut: false);

        RefreshShell(successStatus);

        // Undo/Redo can return the workbook to its last-saved state (WorkbookSession clears
        // IsDirty via its own save-point tracking). When that happens, any autosave snapshot
        // written while the workbook was dirty is now stale — delete it so a later crash does not
        // offer already-undone content as a false "recover unsaved changes?" prompt, mirroring the
        // WPF host's ExecuteUndo/ExecuteRedo (NotifyAutosaveSaved after TryMarkCleanIfAtSavePoint).
        if (!_session.IsDirty)
            _autosaveCoordinator?.NotifyAutosaveSaved();
    }

    private async Task CutSelectedRangeToClipboardAsync()
    {
        if (_isOpening || _isSaving)
            return;

        // Keep object Cut separate from the cell clipboard. The source is removed only by the
        // shared move command after Paste has validated and added the destination object.
        _drawingObjectClipboard.Clear();

        if (await TryCopySelectedDrawingObjectAsync(isCut: true))
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var rangeReference = FormatRangeReference(_session.SelectedRange);
        var cutResult = _session.TryCutSelectedRangeText();
        if (!cutResult.Success || cutResult.Text is not { } cutText)
        {
            ShowEditIssue(cutResult.ErrorMessage ?? UiText.Get("MainLoc_CutFailed"));
            return;
        }

        // R148-clipboard-cut-format-parity: match CopySelectedRangeToClipboardAsync and the WPF
        // host's shared ExecuteCopy(isCut) path -- Cut must place the same HTML/CSV/picture
        // flavors on the OS clipboard as Copy, not flattened plain text only. TryCutSelectedRangeText
        // already rejects multi-range selections outright (unlike Copy's fallback), so reaching here
        // guarantees a single range and cutResult.Viewport is populated exactly like copyResult's.
        var clipboardContent = BuildClipboardTextAndHtmlContent(
            cutText,
            cutResult.Viewport ?? _session.Viewport,
            _session.ActiveSheet,
            _session.SelectedRange,
            _session.Workbook.Theme);

        var picturePlan = ClipboardRangePicturePlanner.TryBuild(ClipboardSerializer.Deserialize(cutText));
        clipboardContent = clipboardContent with
        {
            Image = SkiaClipboardRangePictureRenderer.TryRender(picturePlan),
        };

        var write = await _platformClipboard.WriteAsync(
            WorkbookClipboardSession.AttachMarker(clipboardContent, cutResult.ClipboardMarker));
        if (write.Status == PlatformClipboardWriteStatus.Unavailable)
        {
            ShowEditIssue(UiText.Get("Clipboard_UnavailableOnPlatform"));
            return;
        }
        if (!write.IsSuccess)
            throw new InvalidOperationException(write.ErrorMessage);
        SetClipboardMarquee(_session.SelectedRange, isCut: true);
        RefreshShell(UiText.Format("MainLoc_CutX", rangeReference));
    }

    private async Task CopySelectedRangeToClipboardAsync()
    {
        if (_isOpening || _isSaving)
            return;

        _drawingObjectClipboard.Clear();
        if (await TryCopySelectedDrawingObjectAsync())
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var rangeReference = FormatRangeReference(_session.SelectedRange);
        var copyResult = _session.TryCopySelectedRangeText();
        if (!copyResult.Success || copyResult.Text is not { } copiedText)
        {
            ShowEditIssue(copyResult.ErrorMessage ?? UiText.Get("MainLoc_CopyFailed"));
            return;
        }

        // Place plain text AND an HTML table fragment on the OS clipboard together, matching real
        // Excel and the WPF host's M7 CF_HTML export: destinations that understand HTML (LibreOffice
        // Writer/Calc, browsers, Word/Outlook) pick up bold/fill/merges/number-format display styling
        // instead of only flattened TSV text. Only single-range selections build the HTML fragment
        // (mirroring TryCopySelectedRangeText's own single-range Viewport/SelectedRange usage) —
        // multi-area selections keep the existing plain-text-only behavior.
        PlatformClipboardContent clipboardContent;
        if (_session.SelectedRanges.Count > 1)
        {
            clipboardContent = new PlatformClipboardContent(Text: copiedText);
        }
        else
        {
            // R14-clipboard-formats-deep-1: _session.Viewport only materializes the on-screen scroll
            // position and truncates any part of the selection scrolled out of view. Prefer the
            // full-range viewport TryCopySelectedRangeText() built for the same range (falling back to
            // the on-screen one only if a result somehow carries none) so the CF_HTML fragment always
            // reflects the complete selection, matching the plain-text payload it is paired with.
            clipboardContent = BuildClipboardTextAndHtmlContent(
                copiedText,
                copyResult.Viewport ?? _session.Viewport,
                _session.ActiveSheet,
                _session.SelectedRange,
                _session.Workbook.Theme);
        }

        // Match WPF and Excel's normal range-copy contract: image-only destinations must receive
        // a picture flavor alongside Text/HTML/CSV. Shared Presentation owns the bounded grid plan;
        // this shell only realizes it through Skia and attaches the encoded PNG.
        var picturePlan = ClipboardRangePicturePlanner.TryBuild(ClipboardSerializer.Deserialize(copiedText));
        clipboardContent = clipboardContent with
        {
            Image = SkiaClipboardRangePictureRenderer.TryRender(picturePlan),
        };

        clipboardContent = WorkbookClipboardSession.AttachMarker(
            clipboardContent,
            copyResult.ClipboardMarker);
        var write = await _platformClipboard.WriteAsync(clipboardContent);
        if (write.Status == PlatformClipboardWriteStatus.Unavailable)
        {
            ShowEditIssue(UiText.Get("Clipboard_UnavailableOnPlatform"));
            return;
        }
        if (!write.IsSuccess)
            throw new InvalidOperationException(write.ErrorMessage);

        SetClipboardMarquee(_session.SelectedRange, isCut: false);
        RefreshShell(UiText.Format("MainLoc_CopiedX", rangeReference));
    }

    /// <summary>
    /// R132-clipboard-cut-move-os-invalidation: mirrors the WPF host's
    /// MainWindow.ClipboardCommands.InvalidateOsClipboardAfterCutMove -- once a Cut+Paste MOVE has
    /// completed (<see cref="WorkbookCellEditResult.ClipboardCutMoveCompleted"/>), the real OS
    /// clipboard must be invalidated too. Without this, it still holds the payload
    /// CutSelectedRangeToClipboardAsync placed there for the original Ctrl+X, so a later Ctrl+V --
    /// finding the workbook clipboard session already empty -- falls through to the external-clipboard
    /// path and re-pastes the already-moved content a second time. Best-effort: a transiently
    /// unavailable clipboard just leaves the stale cut payload in place, matching how every other
    /// clipboard call in this shell already treats OS-clipboard access as fallible.
    /// </summary>
    private async Task InvalidateOsClipboardAfterCutMoveAsync()
    {
        _ = await _platformClipboard.ClearAsync();
    }

    /// <summary>
    /// R75-render-selection-marquee-4-2: sets (or clears, with a null <paramref name="range"/>) the
    /// Copy/Cut marching-ants marquee state rendered by <see cref="AddClipboardMarqueeOverlayToGrid"/>.
    /// Centralized so every set/clear call site (Copy, Cut, every Paste* method, Escape, and
    /// committing an ordinary cell edit) goes through one place, matching how the WPF host's
    /// SheetGrid.ClipboardRange/ClipboardIsCut dependency properties are the single source of truth
    /// there.
    /// </summary>
    private void SetClipboardMarquee(GridRange? range, bool isCut)
    {
        _clipboardMarqueeRange = range;
        _clipboardMarqueeIsCut = isCut;
    }

    private void SelectCurrentRegionOrAll()
    {
        if (_isOpening || _isSaving)
            return;

