        var rangeReference = FormatRangeReference(_session.SelectedRange);
        var result = _session.SetSelectedRangeHorizontalAlignment(alignment);
        if (!result.Success)
        {
            RefreshShell(_statusText.Text ?? UiText.Get("MainLoc_Ready"));
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_AlignmentFailed"));
            return;
        }

        RefreshShell(WorksheetCommandPresentationCatalog.FormatHorizontalAlignmentStatus(rangeReference, alignment));
    }

    private void ApplySelectedRangeVerticalAlignment(CellVAlign alignment)
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var rangeReference = FormatRangeReference(_session.SelectedRange);
        var result = _session.SetSelectedRangeVerticalAlignment(alignment);
        if (!result.Success)
        {
            RefreshShell(_statusText.Text ?? UiText.Get("MainLoc_Ready"));
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_VerticalAlignmentFailed"));
            return;
        }

        RefreshShell(WorksheetCommandPresentationCatalog.FormatVerticalAlignmentStatus(rangeReference, alignment));
    }

    private void MainWindow_DragOver(object? sender, DragEventArgs e)
    {
        // R153-shared-drag-drop-F1: DragOver fires continuously while an OS drag merely hovers
        // over the window, before any drop occurs -- it must only preview whether the hovered
        // file would be openable. It must NEVER force-commit or force-cancel an in-progress
        // formula-bar edit as a side effect of the pointer passing over the window (unlike an
        // actual Drop, which legitimately must finish the pending edit before opening). See
        // TryPreviewDroppedWorkbookPath.
        e.DragEffects = TryPreviewDroppedWorkbookPath(e)
            ? DragDropEffects.Copy
            : DragDropEffects.None;
        e.Handled = true;
    }

    private bool TryPreviewDroppedWorkbookPath(DragEventArgs e)
    {
        if (_isOpening || _isSaving)
            return false;

        var files = e.DataTransfer.TryGetFiles();
        return files is not null && TryResolveOpenableLocalWorkbookPath(files, out _, out _, out _);
    }

    private async void MainWindow_Drop(object? sender, DragEventArgs e)
    {
        e.Handled = true;
        if (!TrySelectDroppedWorkbookPath(e, out var path, out var storageItem, out var message))
        {
            ShowOpenIssue(message);
            return;
        }

        // async void: CreateIdentityAsync (and any failure outside OpenWorkbookPathAsync's filtered
        // catch) would otherwise escape to the dispatcher and crash the app.
        try
        {
            e.DragEffects = DragDropEffects.Copy;
            var fileAccessIdentity = await _workbookFileAccessService.CreateIdentityAsync(path!, storageItem);
            await OpenWorkbookPathAsync(path!, fileAccessIdentity);
        }
        catch (Exception ex)
        {
            ShowOpenIssue(UiText.Format("File_OpenFailedFormat", ex.Message));
        }
    }

    public async Task OpenActivatedFilesAsync(IReadOnlyList<IStorageItem> files)
    {
        if (!TrySelectOpenableLocalWorkbookPath(files, out var path, out var storageItem, out var message))
        {
            ShowOpenIssue(message);
            return;
        }

        var fileAccessIdentity = await _workbookFileAccessService.CreateIdentityAsync(path!, storageItem);
        await OpenWorkbookPathAsync(path!, fileAccessIdentity);
    }

    internal Task OpenStartupFileAsync(string path) => OpenWorkbookPathAsync(path);

    internal void ReportStartupFileNotFound(string path) =>
        ShowOpenIssue(UiText.Format("Startup_FileArgumentNotFoundMessage", path));

    partial void ObserveOptionalBoldCommand(bool before, bool after);

    partial void ObserveOptionalItalicCommand(bool before, bool after);

    partial void ObserveOptionalUnderlineCommand(bool before, bool after);

    partial void ObserveOptionalSelectAllCommand(bool before, bool after);

    private bool HasSheetTabButton(Func<Button, bool> predicate) =>
        _sheetTabsHost.Content is StackPanel panel &&
        panel.Children
            .OfType<Button>()
            .Any(predicate);

    private bool HasSheetTabContextMenuItem(string expectedHeader) =>
        _sheetTabsHost.Content is StackPanel panel &&
        panel.Children
            .OfType<Button>()
            .Any(button =>
                button.ContextMenu?.ItemsSource is IEnumerable<Control> items &&
                items
                    .OfType<MenuItem>()
                    .Any(item => string.Equals(item.Header?.ToString(), expectedHeader, StringComparison.Ordinal)));

    private bool HasSheetTabContextSubmenuItem(string parentHeader, string expectedHeader) =>
        _sheetTabsHost.Content is StackPanel panel &&
        panel.Children
            .OfType<Button>()
            .Any(button =>
                button.ContextMenu?.ItemsSource is IEnumerable<Control> items &&
                items
                    .OfType<MenuItem>()
                    .Where(item => string.Equals(item.Header?.ToString(), parentHeader, StringComparison.Ordinal))
                    .Any(item =>
                        item.ItemsSource is IEnumerable<MenuItem> submenuItems &&
                        submenuItems.Any(submenuItem => string.Equals(submenuItem.Header?.ToString(), expectedHeader, StringComparison.Ordinal))));

    private void RefreshNativeOpenRecentMenu(bool isIdle)
    {
        _openRecentMenuItem.Menu = CreateNativeOpenRecentMenu(isIdle);
    }

    private NativeMenu CreateNativeOpenRecentMenu(bool isIdle)
    {
        var menu = new NativeMenu();
        // R152-shared-recent-files-F1: route through the cache (not a raw File.Exists) so an
        // unreachable UNC/network entry never blocks the UI thread for the SMB/TCP connect timeout
        // (commonly 20+ seconds) -- this rebuild runs synchronously after every File>Open and every
        // Save/Save-As (WorkbookFileWorkflow's recentFilesChanged callback), matching the Home pane's
        // BuildLiveBackstageHomePane, which already routes through this same cache.
        var plan = OpenRecentWorkbookMenuPlanner.Create(
            _recentFiles.Snapshot(),
            _recentFilePathExistenceCache.Exists,
            path => _fileWorkflow.TryResolveOpenTarget(path, out var target, out _) ? target!.Path : null);
        if (plan.ItemCount == 0)
        {
            menu.Items.Add(new NativeMenuItem
            {
                Header = UiText.Get("Backstage_Home_NoRecentWorkbooks"),
                IsEnabled = false,
            });
            return menu;
        }

        foreach (var entry in plan.Items)
        {
            var path = entry.Path;
            var fileAccessIdentity = entry.FileAccessIdentity;
            var item = new NativeMenuItem
            {
                Header = entry.Header,
                IsEnabled = isIdle,
            };
            item.Click += async (_, _) => await OpenRecentWorkbookAsync(path, fileAccessIdentity);
            menu.Items.Add(item);
        }

        return menu;
    }

    private async Task OpenRecentWorkbookAsync(
        string path,
        WorkbookFileAccessIdentity? fileAccessIdentity = null)
    {
        if (!_fileWorkflow.TryResolveOpenTarget(path, fileAccessIdentity, out var target, out _) ||
            target is null)
        {
            _recentFiles.Remove(path);
            RefreshNativeOpenRecentMenu(!_isOpening && !_isSaving);
            ShowOpenIssue(WorkbookFileWorkflowMessages.RecentWorkbookMissing(path));
            return;
        }

        using var fileAccess = await _workbookFileAccessService.BeginAccessAsync(
            StorageProvider,
            target.FileAccessIdentity);
        if (!File.Exists(target.Path))
        {
            _recentFiles.Remove(path);
            RefreshNativeOpenRecentMenu(!_isOpening && !_isSaving);
            ShowOpenIssue(WorkbookFileWorkflowMessages.RecentWorkbookMissing(path));
            return;
        }

        await OpenWorkbookPathAsync(target.Path, target.FileAccessIdentity);
    }

    private void RecordStartupRecentWorkbook(StartupWorkbookLoadResult source)
    {
        if (!source.IsFallback && !string.IsNullOrWhiteSpace(source.SourcePath))
            RecordRecentWorkbook(source.SourcePath, source.SourceFileAccessIdentity);
    }

    private void RecordRecentWorkbook(string path, WorkbookFileAccessIdentity? fileAccessIdentity = null)
    {
        if (!_fileWorkflow.TryResolveOpenTarget(path, out var target, out _) ||
            target is null ||
            !File.Exists(target.Path))
            return;

        _fileWorkflow.RegisterRecentFile(new RecentFileRegistrationRequest(
            target.Path,
            FileAccessIdentity: fileAccessIdentity ?? target.FileAccessIdentity));
    }

    private static bool HasOnlyCommandModifier(KeyModifiers modifiers)
    {
        const KeyModifiers commandModifiers = KeyModifiers.Control | KeyModifiers.Meta;
        return (modifiers & commandModifiers) != 0 &&
            (modifiers & ~commandModifiers) == 0;
    }

    private static bool HasCommandAndShiftModifiers(KeyModifiers modifiers)
    {
        const KeyModifiers commandModifiers = KeyModifiers.Control | KeyModifiers.Meta;
        return modifiers.HasFlag(KeyModifiers.Shift) &&
            (modifiers & commandModifiers) != 0 &&
            (modifiers & ~(commandModifiers | KeyModifiers.Shift)) == 0;
    }

    private static bool IsShellFocusCycleKey(KeyEventArgs args) =>
        args.Key == Key.F6 &&
        (args.KeyModifiers == KeyModifiers.None || args.KeyModifiers == KeyModifiers.Shift);

    private static bool HasOnlyControlModifier(KeyModifiers modifiers) =>
        modifiers == KeyModifiers.Control;

    private static bool IsAutoSumShortcut(KeyEventArgs args) =>
        args.Key == Key.OemPlus && args.KeyModifiers == KeyModifiers.Alt;

    private static bool IsSelectVisibleCellsOnlyShortcut(KeyEventArgs args) =>
        args.Key == Key.Oem1 && args.KeyModifiers == KeyModifiers.Alt;

    private static bool IsOpenActiveDropdownShortcut(KeyEventArgs args) =>
        args.Key == Key.Down && args.KeyModifiers == KeyModifiers.Alt;

    private static bool TryGetWorkbookShortcutRoute(
        Key key,
        KeyModifiers modifiers,
        out WorkbookShortcutRoute route)
    {
        route = default;
        return TryGetWorkbookShortcutKey(key, out var shortcutKey) &&
            TryGetWorkbookShortcutRoute(shortcutKey, ToWorkbookShortcutModifiers(modifiers), out route);
    }

    private static bool TryGetWorkbookShortcutRoute(
        WorkbookShortcutKey key,
        WorkbookShortcutModifiers modifiers,
        out WorkbookShortcutRoute route) =>
        WorkbookKeyboardShortcutCatalog.TryGetWindowsRoute(key, modifiers, out route) ||
        WorkbookKeyboardShortcutCatalog.TryGetNativeMenuRoute(key, modifiers, out route);

    private static bool TryGetWorkbookShortcutKey(Key key, out WorkbookShortcutKey shortcutKey) =>
        WorkbookKeyboardShortcutCatalog.TryParseKeyName(key.ToString(), out shortcutKey);

    private static WorkbookShortcutModifiers ToWorkbookShortcutModifiers(KeyModifiers modifiers)
    {
        var result = WorkbookShortcutModifiers.None;
        if (modifiers.HasFlag(KeyModifiers.Control))
            result |= WorkbookShortcutModifiers.Control;
        if (modifiers.HasFlag(KeyModifiers.Meta))
            result |= WorkbookShortcutModifiers.Meta;
        if (modifiers.HasFlag(KeyModifiers.Alt))
            result |= WorkbookShortcutModifiers.Alt;
        if (modifiers.HasFlag(KeyModifiers.Shift))
            result |= WorkbookShortcutModifiers.Shift;
        return result;
    }

    /// <summary>
    /// The worksheet-cell context-menu shortcut (Menu key / Shift+F10) — the same key combo used for
    /// the sheet-tab context menu (<see cref="IsSheetTabContextMenuKey"/>), Excel's universal
    /// "open the context menu for whatever's focused" gesture applied to the active grid cell/range.
    /// </summary>
    private static bool IsWorksheetContextMenuKey(KeyEventArgs args) =>
        args.Key == Key.Apps ||
        args.Key == Key.F10 && args.KeyModifiers == KeyModifiers.Shift;

    /// <summary>
    /// True for Ctrl/Cmd(+Shift)+Arrow, Ctrl/Cmd+Home, and Ctrl/Cmd(+Shift)+End - the Excel
    /// used-range navigation/extend shortcuts that must still reach <see cref="NavigateActiveCell"/>
    /// even though the command modifier is held (mirrors the WPF host's
    /// <see cref="ExcelWorksheetNavigationPlanner.ShouldHandleWorksheetNavigationKey"/> gate).
    /// </summary>
    private static bool IsWorksheetNavigationKeyWithCommandModifier(KeyEventArgs args)
    {
        if (args.Key is not (Key.Up or Key.Down or Key.Left or Key.Right or Key.Home or Key.End))
            return false;

        const KeyModifiers commandModifiers = KeyModifiers.Control | KeyModifiers.Meta;
        return (args.KeyModifiers & commandModifiers) != 0 &&
            (args.KeyModifiers & ~(commandModifiers | KeyModifiers.Shift)) == 0;
    }

    // Routed through RunGuarded: this is an `async void` handler, so an exception escaping it kills
    // the process — and it sits behind EVERY keystroke, fanning out to save/close/print-preview/
    // paste-special/help-link/go-to/hyperlink paths. A single throwing shortcut (a browser launch
    // that fails, a malformed hyperlink, a paste edge case) would take the app down mid-edit.
    private void MainWindow_KeyDown(object? sender, KeyEventArgs e) =>
        RunGuarded(() => MainWindow_KeyDownAsync(e));

    private async Task MainWindow_KeyDownAsync(KeyEventArgs e)
    {
        if (e.Key is Key.CapsLock or Key.NumLock)
        {
            UpdateKeyLockToggleState(e.Key);
            RefreshKeyLockIndicators();
        }

        if (e.KeyModifiers == KeyModifiers.None &&
            !ShouldHandleEscapeLocallyBeforeFormulaPointMode(e.Key) &&
            TryRouteFormulaPointModeKey(e.Key))
        {
            e.Handled = true;
            return;
        }

        if (TryHandleWorkbookWindowSwitchShortcut(e))
            return;

        if (TryHandleRibbonKeyTipInput(e))
            return;

        if (TryHandleRibbonKeyTips(e))
            return;

        if (_backstageOverlay.IsVisible && e.Key == Key.Escape)
        {
            HideBackstageOverlay();
            e.Handled = true;
            return;
        }

        if (TryHandleSlicerTimelinePaneKey(e))
            return;

        if (IsShellFocusCycleKey(e))
        {
            e.Handled = true;
            CycleShellFocus(reverse: e.KeyModifiers == KeyModifiers.Shift);
            return;
        }

        if (IsOpenActiveDropdownShortcut(e))
        {
            if (!_formulaBox.IsFocused)
            {
                e.Handled = OpenActiveDropdown();
            }

            return;
        }

        if (IsWorksheetContextMenuKey(e) && !IsTextEditingEventSource(e))
        {
            // Menu key / Shift+F10 over the worksheet grid: open the same cell context menu the
            // pointer-driven right-click path opens (OpenWorksheetCellContextMenu), anchored on the
            // active cell's Border so it appears where the user is actually looking — mirrors WPF's
            // KeyboardCommandShortcut.OpenContextMenu -> OpenKeyboardContextMenu.
            var anchor = (Control?)_activeCellBorder ?? _sheetGridHost;
            OpenWorksheetCellContextMenu(anchor);
            e.Handled = true;
            return;
        }

        if (await TryHandleApplicationOrLocalShortcutAsync(e))
            return;

        if (e.Key == Key.Enter &&
            HasHyperlinkActivationModifier(e.KeyModifiers) &&
            !e.KeyModifiers.HasFlag(KeyModifiers.Shift) &&
            !e.KeyModifiers.HasFlag(KeyModifiers.Alt) &&
            !_formulaBox.IsFocused &&
            !IsTextEditingEventSource(e))
        {
            e.Handled = true;
            await OpenSelectedHyperlinkAsync();
            return;
        }

        if (IsAutoSumShortcut(e))
        {
            e.Handled = true;
            InsertAutoSumFormula("SUM");
            return;
        }

        if (IsSelectVisibleCellsOnlyShortcut(e))
        {
            e.Handled = true;
            SelectGoToSpecial(GoToSpecialKind.VisibleCellsOnly);
            return;
        }

        if (TryHandleRowColumnVisibilityShortcut(e))
            return;

        if (e.Key == Key.F4 && e.KeyModifiers == KeyModifiers.None &&
            !_formulaBox.IsFocused && !IsTextEditingEventSource(e))
        {
            e.Handled = true;
            ExecuteRepeatLastAction();
            return;
        }

        if (e.Key == Key.F9 && !_formulaBox.IsFocused && !IsTextEditingEventSource(e))
        {
            if (e.KeyModifiers == KeyModifiers.None)
            {
                e.Handled = true;
                CalculateNow();
                return;
            }

            if (e.KeyModifiers == KeyModifiers.Shift)
            {
                e.Handled = true;
                CalculateActiveSheet();
                return;
            }

            if (e.KeyModifiers == (KeyModifiers.Control | KeyModifiers.Alt))
            {
                e.Handled = true;
                CalculateNow();
                return;
            }
        }

        if (e.Key == Key.Space && !_formulaBox.IsFocused && !IsTextEditingEventSource(e))
        {
            if (e.KeyModifiers == (KeyModifiers.Control | KeyModifiers.Shift))
            {
                e.Handled = true;
                SelectAllCells();
                return;
            }

            if (e.KeyModifiers == KeyModifiers.Control)
            {
                e.Handled = true;
                SelectWholeColumnsFromSelection();
                return;
            }

            if (e.KeyModifiers == KeyModifiers.Shift)
            {
                e.Handled = true;
                SelectWholeRowsFromSelection();
                return;
            }
        }

        if ((!e.KeyModifiers.HasFlag(KeyModifiers.Control) &&
                !e.KeyModifiers.HasFlag(KeyModifiers.Meta)) ||
            IsWorksheetNavigationKeyWithCommandModifier(e))
        {
            if (e.Key == Key.F5)
            {
                e.Handled = true;
                await ShowGoToDialogAsync();
                return;
            }

            if (_formulaBox.IsFocused)
                return;

            if (IsTextEditingEventSource(e))
                return;

            if (e.Key == Key.F11 && e.KeyModifiers == KeyModifiers.Shift)
            {
                e.Handled = true;
                AddNewSheet();
                return;
            }

            if (e.Key == Key.F3 && e.KeyModifiers == KeyModifiers.Shift)
            {
                e.Handled = true;
                InsertFunction();
                return;
            }

            if (e.Key == Key.F1)
            {
                e.Handled = true;
                await OpenExternalHelpLinkAsync(AppHelpInfo.HelpUrl, UiText.Get("MainWindow_Content_HelpOnline"));
                return;
            }

            if (e.Key == Key.Delete)
            {
                if (IsTextEditingEventSource(e))
                    return;

                e.Handled = true;
                // R121-model-drawing-delete-1: Delete on a currently-selected picture/text box/shape/
                // chart removes the OBJECT (matching Excel), not the contents of whatever cell range
                // happens to be selected underneath it.
                if (TryDeleteSelectedDrawingObject())
                    return;

                ClearSelectedRangeContents();
                return;
            }

            if (e.Key == Key.Escape && _session.IsFormatPainterActive)
            {
                e.Handled = true;
                CancelFormatPainter();
                return;
            }

            if (e.Key == Key.Escape && IsBorderDrawModeActive)
            {
                e.Handled = true;
                CancelBorderDrawMode();
                return;
            }

            // R75-render-selection-marquee-4-2: Escape cancels an active Copy/Cut marching-ants
            // marquee, mirroring the WPF host's ClearClipboardVisualState call on Escape
            // (MainWindow.Editing.cs).
            if (e.Key == Key.Escape &&
                (_clipboardMarqueeRange is not null || _drawingObjectClipboard.HasContent))
            {
                e.Handled = true;
                SetClipboardMarquee(null, isCut: false);
                _drawingObjectClipboard.Clear();
                RefreshShell(UiText.Get("MainLoc_Ready"));
                return;
            }

            // R129-model-drawing-escape-1: Escape with a genuinely selected picture/shape/text
            // box/chart deselects the object first, matching Excel and the WPF host's
            // MainWindow.Selection.cs fix -- previously nothing on this shell's keyboard path ever
            // cleared _selectedDrawingObjectKind/-Id on Escape, so the object stayed visibly
            // selected (handles still drawn) after pressing it.
            if (e.Key == Key.Escape && HasSelectedDrawingObject())
            {
                e.Handled = true;
                ClearSelectedDrawingObject();
                RefreshShell(UiText.Get("MainLoc_Ready"));
                return;
            }

            // R129-model-drawing-nudge-1: with a picture/shape/text box/chart genuinely selected,
            // Excel routes plain and Ctrl+ arrow keys to nudging the object instead of moving the
            // cell cursor underneath it. Shift/Alt + arrow combos fall through unchanged; the
            // shared planner owns that modifier/selection enablement policy for both renderers.
            if (TryPlanSelectedDrawingObjectNudge(e.Key, e.KeyModifiers, out var nudgePlan))
            {
                e.Handled = true;
                ExecuteSelectedDrawingObjectNudge(nudgePlan);
                return;
            }

            NavigateActiveCell(e);
            return;
        }

        if (_formulaBox.IsFocused &&
            e.Key is Key.Z or Key.Y or Key.X or Key.C or Key.V or Key.A or Key.B or Key.D or Key.E or Key.I or Key.R or Key.U or Key.D4 or Key.NumPad4 or Key.D5 or Key.NumPad5)
        {
            return;
        }

        if (e.Key == Key.G && e.KeyModifiers == KeyModifiers.Meta)
        {
            e.Handled = true;
            FindNext();
        }
        else if (e.Key == Key.K && HasOnlyControlModifier(e.KeyModifiers))
        {
            e.Handled = true;
            await ShowInsertHyperlinkDialogAsync();
        }
        else if (e.Key == Key.V && HasCommandAndShiftModifiers(e.KeyModifiers))
        {
            // Ctrl+Shift+V ("Paste Values") — Excel/WPF paste the literal computed value only, with
            // no formula and no source formatting. Must be checked before the bare Key.V fallback
            // below, which performs a full (formula + formatting) paste.
            e.Handled = true;
            await PasteSpecialClipboardTextAsync(PasteCellsMode.Values, default, "Values");
        }
        else if (e.Key == Key.A && HasOnlyCommandModifier(e.KeyModifiers))
        {
            e.Handled = true;
            var before = _session.SelectedRange;
            SelectCurrentRegionOrAll();
            ObserveOptionalSelectAllCommand(
                before == _session.SelectedRange,
                after: true);
        }
        else if (e.Key == Key.S && e.KeyModifiers.HasFlag(KeyModifiers.Shift))
        {
            e.Handled = true;
            await SaveWorkbookAsAsync();
        }
        else if (e.Key == Key.W && HasOnlyCommandModifier(e.KeyModifiers))
        {
            e.Handled = true;
            await CloseWorkbookAsync();
        }
        else if (e.Key == Key.P && HasCommandAndShiftModifiers(e.KeyModifiers))
        {
            e.Handled = true;
            await ShowPrintPreviewDialogAsync();
        }
        else if (e.Key == Key.O && HasCommandAndShiftModifiers(e.KeyModifiers))
        {
            // Ctrl+Shift+O ("Select Cells with Comments") — must be checked before the bare Key.O
            // fallback below, which opens the file-Open dialog.
            e.Handled = true;
            SelectGoToSpecial(GoToSpecialKind.Comments);
        }
        else if (await TryHandleWorkbookShortcutRouteAsync(e))
        {
        }
    }

    private async Task<bool> TryHandleWorkbookShortcutRouteAsync(KeyEventArgs e)
    {
        var effectiveKey = GetEffectiveWorkbookShortcutKey(e);
        if (effectiveKey != e.Key)
        {
            var normalizedArgs = new KeyEventArgs
            {
                Key = effectiveKey,
                PhysicalKey = e.PhysicalKey,
                KeyModifiers = e.KeyModifiers,
            };
            var handled = await TryHandleWorkbookShortcutRouteAsync(normalizedArgs);
            e.Handled = normalizedArgs.Handled;
            return handled;
        }

        if (!TryGetWorkbookShortcutRoute(e.Key, e.KeyModifiers, out var route))
            return false;

        if (!WorkbookApplicationCommandRouter.TryRouteShortcut(route, out var applicationRoute))
            return false;

        var execution = await WorkbookApplicationCommands.TryExecuteAsync(
            applicationRoute,
            nativeSource: e.Source,
            nativeEventArgs: e);
        if (!execution.IsBound)
            return false;

        e.Handled = execution.Handled;
        return true;
    }

    private bool IsTextEditingEventSource(KeyEventArgs args) =>
        _formulaBox.IsFocused ||
        _inlineCellEditor?.IsFocused == true ||
        _textBoxInlineEditor?.IsFocused == true ||
        args.Source is TextBox ||
        args.Source is TextPresenter;

    private bool OpenActiveDataValidationDropdown()
    {
        if (_isOpening || _isSaving)
            return true;

        if (!TryCommitPendingFormulaEdit())
            return true;

        RefreshShell(UiText.Get("MainLoc_Ready"));
        if (_activeDataValidationDropdown is null)
            return false;

        _activeDataValidationDropdown.Focus();
        _activeDataValidationDropdown.IsDropDownOpen = true;
        return true;
    }

    private bool OpenActiveDropdown() =>
        OpenActiveNameBoxDropdown() ||
        OpenActiveDataValidationDropdown() ||
        OpenActiveAutoFilterDropdown() ||
        OpenTextEntryPickListDropdown();

    private bool OpenActiveNameBoxDropdown()
    {
        if (!_cellAddressText.IsFocused)
            return false;

        ShowCellAddressAutocompletePopup();
        return true;
    }

    private bool OpenTextEntryPickListDropdown()
    {
        var items = DataValidationDropdownPlanner.GetTextEntryPickListItems(
            _session.ActiveSheet,
            _session.ActiveCell);
        if (items.Count == 0 ||
            _cellAffordanceOverlay is not { } overlay ||
            !TryGetDisplayedCellBounds(
                _session.Viewport,
                _session.ActiveCell,
                _session.IsShowingHeadings,
                GetActiveZoomFactor(),
                out var left,
                out var top,
                out var width,
                out var height))
        {
            return false;
        }

        var btnWidth = Math.Max(
            DataValidationDropdownPlanner.MinimumWidth,
            DataValidationAffordancePlanner.ArrowButtonWidth * GetActiveZoomFactor());
        var btnHeight = Math.Max(DataValidationDropdownPlanner.MinimumHeight, height);
        var plan = new DataValidationDropdownPlan(
            items,
            SelectedItem: null,
            new DataValidationDropdownBounds(left + width - btnWidth, top, btnWidth, btnHeight));
        var dropdown = CreateDataValidationDropdown(plan, btnWidth, btnHeight);
        Canvas.SetLeft(dropdown, plan.Bounds.Left);
        Canvas.SetTop(dropdown, plan.Bounds.Top);
        overlay.Children.Add(dropdown);
        _activeDataValidationDropdown = dropdown;
        dropdown.Focus();
        dropdown.IsDropDownOpen = true;
        return true;
    }

    private void DataValidationDropdown_SelectionChanged(object? sender, SelectionChangedEventArgs e)
    {
        if (sender is not ComboBox { SelectedItem: string selected })
            return;

        CommitDataValidationDropdownSelection(selected);
    }

    private void CommitDataValidationDropdownSelection(string selected)
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        var address = _session.ActiveCell;
        _session.BeginFormulaEdit(address);
        var result = _session.CommitCellText(selected, UseR1C1ReferenceStyle);
        if (!result.Success)
        {
            _session.CancelFormulaEdit();
            _formulaBoxEditOriginalText = null;
            ShowEditIssue(result.ErrorMessage ?? UiText.Get("MainLoc_DataValidationDropdownFailed"));
            return;
        }

        RefreshShell(UiText.Format(
            "MainLoc_ActionRangeStatusFormat",
            selected,
            FormatCellReference(address)));
    }

    private void CycleShellFocus(bool reverse)
    {
        ShellFocusCyclePlanner.TryFocusNextAvailable(
            GetCurrentShellFocusTarget(),
            reverse,
            IsShellFocusTargetAvailable,
            FocusShellRegion);
    }

    private bool IsShellFocusTargetAvailable(ShellFocusTarget target) =>
        target != ShellFocusTarget.TaskPane ||
        _pivotFieldPaneHost.IsVisible ||
        _slicerTimelinePaneHost.IsVisible;

    private ShellFocusTarget GetCurrentShellFocusTarget()
    {
        if (_formulaBox.IsFocused)
            return ShellFocusTarget.FormulaBar;

        if (IsAnySheetTabFocused())
            return ShellFocusTarget.SheetTabs;

        if (_zoomText.IsFocused)
            return ShellFocusTarget.StatusBar;

        if (IsPivotFieldPaneFocused())
            return ShellFocusTarget.TaskPane;

        if (IsSlicerTimelinePaneFocused())
            return ShellFocusTarget.TaskPane;

        if (IsAnyToolbarControlFocused())
            return ShellFocusTarget.Ribbon;

        return ShellFocusTarget.Worksheet;
    }

    private bool FocusShellRegion(ShellFocusTarget target) =>
        target switch
        {
            ShellFocusTarget.Ribbon => FocusFirstEnabledToolbarControl(),
            ShellFocusTarget.FormulaBar => FocusControl(_formulaBox),
            ShellFocusTarget.SheetTabs => FocusActiveSheetTab(),
            ShellFocusTarget.TaskPane => FocusVisibleTaskPane(),
            ShellFocusTarget.StatusBar => FocusControl(_zoomText),
            _ => FocusActiveCellOrGridHost()
        };

    /// <summary>
    /// Targets real keyboard focus at the active cell's own Border (see
    /// <see cref="MoveFocusToActiveCellBorder"/>'s doc comment for why that matters to a screen
    /// reader) rather than the static "Worksheet"-named <see cref="_sheetGridHost"/>, for every
    /// <see cref="FocusShellRegion"/> caller that means "put focus back on the worksheet" after a
    /// selection-changing action -- e.g. Name Box (Go To) navigation and committing/cancelling an
    /// inline cell edit. RefreshShell always runs before these callers reach this point, so
    /// <see cref="_activeCellBorder"/> already reflects the new active cell by the time this runs.
    /// Falls back to <see cref="_sheetGridHost"/> when no active cell Border exists yet (e.g. before
    /// the first grid build) so this can never regress to focusing nothing at all.
    /// </summary>
    private bool FocusActiveCellOrGridHost() =>
        (_activeCellBorder is { } activeCellBorder && FocusControl(activeCellBorder)) ||
        FocusControl(_sheetGridHost);

    private bool FocusVisibleTaskPane() =>
        (_pivotFieldPaneSearchBox is { } searchBox && FocusControl(searchBox)) ||
        FocusControl(_pivotFieldPaneHost) ||
        FocusSlicerTimelinePane();

    private bool IsPivotFieldPaneFocused() =>
        _pivotFieldPaneHost.IsFocused ||
        _pivotFieldPaneSearchBox?.IsFocused == true ||
        _pivotDropZones.Any(zone => zone.Bucket.IsFocused);

    private bool FocusFirstEnabledToolbarControl()
    {
        foreach (var control in GetToolbarFocusTargets())
        {
            if (FocusControl(control))
                return true;
        }

        return false;
    }

    private IReadOnlyList<Control> GetToolbarFocusTargets() =>
    [
        _openButton,
        _saveButton,
        _saveAsButton,
        _undoButton,
        _redoButton,
        _cutButton,
        _copyButton,
        _pasteButton,
        _pasteSpecialButton,
        _formatPainterButton,
        _autoSumButton,
        _fillCellsButton,
        _clearButton,
        _boldButton,
        _italicButton,
        _underlineButton,
        _doubleUnderlineButton,
        _strikethroughButton,
        _increaseFontSizeButton,
        _decreaseFontSizeButton,
        _fillColorButton,
        _fontColorButton,
        _bordersButton,
        _cellStylesButton,
        _orientationButton,
        _currencyFormatButton,
        _percentFormatButton,
        _commaStyleButton,
        _increaseDecimalButton,
        _decreaseDecimalButton,
        _alignTopButton,
        _alignMiddleButton,
        _alignBottomButton,
        _wrapTextButton,
        _mergeAndCenterButton,
        _decreaseIndentButton,
        _increaseIndentButton,
        _alignLeftButton,
        _alignCenterButton,
        _alignRightButton
    ];

    private bool IsAnyToolbarControlFocused() =>
        GetToolbarFocusTargets().Any(control => control.IsFocused);

    private bool IsAnySheetTabFocused() =>
        _sheetTabsHost.Content is StackPanel panel &&
        panel.Children.OfType<Button>().Any(button => button.IsFocused);

    private static bool FocusControl(Control control)
    {
        if (!control.Focusable ||
            !control.IsEnabled ||
            !control.IsVisible)
        {
            return false;
        }

        control.Focus();
        return control.IsFocused;
    }

    private async void MainWindow_Closing(object? sender, WindowClosingEventArgs e)
    {
        if (_allowCloseWithoutDirtyPrompt)
            return;

        if (_isOpening || _isSaving)
        {
            e.Cancel = true;
            ShowOpenIssue(UiText.Get("File_FinishOperationBeforeClosing"));
            return;
        }

        if (!TryCommitPendingFormulaEdit())
        {
            e.Cancel = true;
            return;
        }

        // A sibling "New Window" view keeps the document (and its dirty state) alive, so closing
        // this view must not prompt to save -- only the document's last view prompts (Excel
        // parity, mirrors the WPF host's DocumentSharedWithOtherWindows() guard in its own
        // MainWindow_Closing).
        if (!_session.IsDirty || WindowRegistry.HasOtherWindowForDocument(this))
            return;

        e.Cancel = true;
        if (_isDirtyCloseDialogOpen)
            return;

        // async void: the close stays cancelled above, so a thrown dialog leaves the window open
        // rather than escaping to the dispatcher and crashing the app mid-close.
        try
        {
            if (await ConfirmBeforeDestructiveWorkbookActionAsync(
                    UiText.Get("DirtyWorkbook_CloseFreeXTitle"),
                    UiText.Get("DirtyWorkbook_DiscardAndClose")))
            {
                _allowCloseWithoutDirtyPrompt = true;
                Close();
            }
        }
        catch (Exception ex)
        {
            ShowOpenIssue(UiText.Format("File_CloseFailedFormat", ex.Message));
        }
    }

    private async Task TryQuitApplicationAsync()
    {
        if (_isOpening || _isSaving)
        {
            ShowOpenIssue(UiText.Get("File_FinishOperationBeforeQuitting"));
            return;
        }

        if (!TryCommitPendingFormulaEdit())
            return;

        if (!await ConfirmBeforeDestructiveWorkbookActionAsync(
                UiText.Get("DirtyWorkbook_QuitFreeXTitle"),
                UiText.Get("DirtyWorkbook_DiscardAndQuit")))
            return;

        // The confirmation above answers for the shared document, not just this window: a
        // "New Window" sibling views the SAME WorkbookSession document state (CreateSiblingView),
        // so on Discard the document stays dirty (only Save clears it) and _allowCloseWithoutDirtyPrompt
        // is otherwise a per-window flag. Without propagating it here, desktop.TryShutdown's cascade
        // reaches each sibling's own MainWindow_Closing, which re-checks the still-dirty shared session
        // and -- once this window has already unregistered -- finds itself the "last" window for the
        // document and prompts a SECOND time for the identical file. If the user cancels that redundant
        // prompt, shutdown aborts with this window already gone: a half-quit split of one document
        // across an open and a closed window. Marking every sibling here keeps the single confirmation
        // authoritative for the whole document and matches the WPF host, which has no separate quit
        // gate at all -- it relies solely on the per-window Closing handler's own
        // DocumentSharedWithOtherWindows() check (see MainWindow.WorkbookLifecycle.cs), so it never
        // duplicates a prompt in the first place.
        foreach (var sibling in WindowRegistry.Windows)
        {
            if (sibling.DocumentId == DocumentId)
                sibling._allowCloseWithoutDirtyPrompt = true;
        }

        if (Application.Current?.ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop)
        {
            desktop.TryShutdown(0);
            return;
        }

        Close();
    }

    private void NavigateActiveCell(KeyEventArgs e)
    {
        if (e.Key == Key.F2)
        {
            e.Handled = true;

            // R129-model-drawing-f2-1: F2 must no-op, not open the underlying active cell for edit,
            // while a picture/shape/text box/chart is genuinely selected -- same family as the
            // Escape/Fill/Backspace/Delete guards (see HasSelectedDrawingObject).
            if (HasSelectedDrawingObject())
                return;

            var address = _session.ActiveCell;
            var editText = FormatEditText(_session.ActiveSheet.GetCell(address), address);
            BeginInlineCellEdit(address, editText, editText.Length);
            return;
        }

        var navigationKey = ToWorksheetNavigationKey(e.Key);
        var navigationModifiers = ToWorksheetNavigationModifiers(e.KeyModifiers);

        // Plain End (no modifiers) toggles Excel's sticky "End Mode" instead of moving the
        // active cell; the next arrow key then jumps to the data boundary in that direction
        // (mirrors the WPF host's MainWindow.Selection.cs / ExcelWorksheetNavigationPlanner).
        if (ExcelWorksheetNavigationPlanner.TryToggleEndMode(navigationKey, navigationModifiers, _endMode, out var nextEndMode))
        {
            _endMode = nextEndMode;
            e.Handled = true;
            RefreshShell(UiText.Get("MainLoc_Ready"));
            return;
        }

        if (!ExcelWorksheetNavigationPlanner.ShouldHandleWorksheetNavigationKey(navigationKey, navigationKey, navigationModifiers, _endMode))
            return;

        var pageRows = Math.Max(1, WorkbookViewportScrollPlanner.CountVisibleScrollableRows(
            _session.Viewport, _session.ActiveSheet) - 1);
        var pageCols = Math.Max(1, WorkbookViewportScrollPlanner.CountVisibleScrollableColumns(
            _session.Viewport, _session.ActiveSheet) - 1);
        var extendSelection = e.KeyModifiers.HasFlag(KeyModifiers.Shift);
        var moveOnly = navigationKey is ExcelWorksheetNavigationKey.Enter or ExcelWorksheetNavigationKey.Tab;
        var useDataBoundary = ExcelWorksheetNavigationPlanner.ShouldUseDataBoundary(navigationKey, navigationModifiers, _endMode);
        var ctrlHeld = e.KeyModifiers.HasFlag(KeyModifiers.Control) || e.KeyModifiers.HasFlag(KeyModifiers.Meta);
        var sheet = _session.Workbook.GetSheet(_session.ActiveSheet.Id);
        var current = extendSelection && !moveOnly && _selectionExtensionCursor is { } cursor
            ? cursor
            : _session.ActiveCell;

        if (_endMode)
            _endMode = false;

        // Presentation owns traversal order, multi-area wrapping, and merged-cell eligibility.
        // Avalonia retains native key conversion and applies only the returned active-cell target.
        var cyclePlan = moveOnly
            ? GridSelectionNavigationPlanner.PlanCycle(
                sheet,
                _session.SelectedRange,
                _session.SelectedRanges,
                current,
                navigationKey == ExcelWorksheetNavigationKey.Tab
                    ? GridSelectionCycleKey.Tab
                    : GridSelectionCycleKey.Enter,
                forward: !extendSelection)
            : null;
        if (cyclePlan is { } cycle)
        {
            _session.MoveActiveCellWithinSelection(cycle.Target);
            ClearSelectedDrawingObject();
            e.Handled = true;
            RefreshShell(UiText.Get("MainLoc_Ready"));
            return;
        }

        // Alt+PageUp/Alt+PageDown resolve to a horizontal screen-page move (Excel/WPF parity)
        // before falling back to the vertical PageUp/PageDown handling below.
        CellAddress? target = ExcelWorksheetNavigationPlanner.GetHorizontalPageTarget(
            navigationKey,
            navigationKey,
            navigationModifiers,
            current,
            pageCols);

        target ??= navigationKey switch
        {
            ExcelWorksheetNavigationKey.Up => useDataBoundary
                ? ExcelWorksheetNavigationPlanner.FindVerticalDataBoundary(sheet, current, -1)
                : OffsetAddress(current, -1, 0),
            ExcelWorksheetNavigationKey.Down => useDataBoundary
                ? ExcelWorksheetNavigationPlanner.FindVerticalDataBoundary(sheet, current, +1)
                : OffsetAddress(current, 1, 0),
            ExcelWorksheetNavigationKey.Left => useDataBoundary
                ? ExcelWorksheetNavigationPlanner.FindHorizontalDataBoundary(sheet, current, -1)
                : OffsetAddress(current, 0, -1),
            ExcelWorksheetNavigationKey.Right => useDataBoundary
                ? ExcelWorksheetNavigationPlanner.FindHorizontalDataBoundary(sheet, current, +1)
                : OffsetAddress(current, 0, 1),
            ExcelWorksheetNavigationKey.PageUp => OffsetAddress(current, -pageRows, 0),
            ExcelWorksheetNavigationKey.PageDown => OffsetAddress(current, pageRows, 0),
            ExcelWorksheetNavigationKey.Home => new CellAddress(
                _session.ActiveSheet.Id,
                ctrlHeld ? 1u : current.Row,
                1u),
            // ShouldHandleWorksheetNavigationKey only lets End through when Ctrl is held (plain End
            // is consumed by TryToggleEndMode above), so this always resolves via GetCtrlEndCell.
            ExcelWorksheetNavigationKey.End => ExcelWorksheetNavigationPlanner.GetCtrlEndCell(sheet, _session.ActiveSheet.Id),
            ExcelWorksheetNavigationKey.Enter => extendSelection
                ? OffsetAddress(current, -1, 0)
                : OffsetAddress(current, 1, 0),
            ExcelWorksheetNavigationKey.Tab => extendSelection
                ? OffsetAddress(current, 0, -1)
                : OffsetAddress(current, 0, 1),
            _ => null
        };

        if (target is not { } resolvedTarget)
            return;

        var navigationTarget = moveOnly
            ? ExcelWorksheetNavigationPlanner.AdjustTargetPastMerge(sheet, current, resolvedTarget)
            : resolvedTarget;

        // Arrow/Tab/Enter navigation on a protected sheet must SKIP a locked cell it would
        // otherwise land the active cell on (when "Select locked cells" is unchecked), stepping
        // further in the same direction of travel until a selectable cell is found -- matching
        // Excel -- rather than moving onto it (R75-services-protection-security-4-1). Only
        // applies when this navigation will actually MOVE the active cell (not extend a range).
        bool willMoveActiveCell = !(extendSelection && !moveOnly);
        if (willMoveActiveCell &&
            sheet is { IsProtected: true })
        {
            var adjustedTarget = ExcelWorksheetNavigationPlanner.ResolveProtectedSheetTarget(
                _session.Workbook,
                sheet,
                navigationTarget,
                navigationKey,
                extendSelection);
            if (adjustedTarget is null)
            {
                // No selectable cell exists further in this direction (e.g. every remaining cell
                // to the edge is locked) -- Excel simply doesn't move; consume the key anyway.
                e.Handled = true;
                return;
            }

            navigationTarget = adjustedTarget.Value;
        }

        MoveOrExtendActiveCellTo(navigationTarget, extendSelection && !moveOnly);
        ClearSelectedDrawingObject();
        e.Handled = true;
        RefreshShell(UiText.Get("MainLoc_Ready"));
    }

    private CellAddress OffsetAddress(CellAddress current, int rowDelta, int colDelta) =>
        new(
            _session.ActiveSheet.Id,
            OffsetCellIndex(current.Row, rowDelta, CellAddress.MaxRow),
            OffsetCellIndex(current.Col, colDelta, CellAddress.MaxCol));

    private static ExcelWorksheetNavigationKey ToWorksheetNavigationKey(Key key) =>
        key switch
        {
            Key.Up => ExcelWorksheetNavigationKey.Up,
            Key.Down => ExcelWorksheetNavigationKey.Down,
            Key.Left => ExcelWorksheetNavigationKey.Left,
            Key.Right => ExcelWorksheetNavigationKey.Right,
            Key.Home => ExcelWorksheetNavigationKey.Home,
            Key.End => ExcelWorksheetNavigationKey.End,
            Key.PageUp => ExcelWorksheetNavigationKey.PageUp,
            Key.PageDown => ExcelWorksheetNavigationKey.PageDown,
            Key.Enter => ExcelWorksheetNavigationKey.Enter,
            Key.Tab => ExcelWorksheetNavigationKey.Tab,
            _ => ExcelWorksheetNavigationKey.Other
        };

    private static ExcelWorksheetNavigationModifiers ToWorksheetNavigationModifiers(KeyModifiers modifiers)
    {
        var result = ExcelWorksheetNavigationModifiers.None;
        if (modifiers.HasFlag(KeyModifiers.Shift))
            result |= ExcelWorksheetNavigationModifiers.Shift;
        if (modifiers.HasFlag(KeyModifiers.Control) || modifiers.HasFlag(KeyModifiers.Meta))
            result |= ExcelWorksheetNavigationModifiers.Control;
        if (modifiers.HasFlag(KeyModifiers.Alt))
            result |= ExcelWorksheetNavigationModifiers.Alt;
        return result;
    }

    /// <summary>
    /// Moves the active cell to <paramref name="target"/> (or extends the current selection to
    /// it). When not extending, snaps to the full merged region if <paramref name="target"/> lands
    /// on a non-anchor merge member - mirroring the WPF host's <c>SetActiveCell</c>, which selects
    /// the whole merged rectangle rather than a single cell inside it.
    /// </summary>
    private void MoveOrExtendActiveCellTo(CellAddress target, bool extendSelection)
    {
        if (!extendSelection)
        {
            ClearSelectionExtensionState();
            var sheet = _session.ActiveSheet;
            if (sheet.MergedRegions.Count > 0 && sheet.GetMergeRegion(target) is { } merge)
            {
                _session.SelectRange(merge);
                return;
            }

            _session.SelectCell(target);
            return;
        }

        var anchor = _selectionExtensionAnchor ?? _session.ActiveCell;
        _selectionExtensionAnchor = anchor;
        _selectionExtensionCursor = target;
        // Extend toward `target` while keeping the active cell pinned to the extension anchor, so an
        // upward/leftward Shift+Arrow run doesn't relocate the active cell to the range's top-left.
        _session.SelectAnchoredRange(anchor, target);
    }

    private static uint OffsetCellIndex(uint current, int delta, uint max) =>
        (uint)Math.Clamp((long)current + delta, 1, max);

    private void MainWindow_TextInput(object? sender, TextInputEventArgs e)
    {
        if (e.Source is TextBox or TextPresenter ||
            string.IsNullOrEmpty(e.Text))
            return;

        // X11 can source the first post-F2 TextInput from the worksheet while Avalonia is handing
        // focus to the attached editor. The packet can arrive after the editor claims focus, so
        // ownership is determined by the event source rather than the current focus state. Text
        // sourced by the TextBox itself is already handled by its local boundary above.
        if (_inlineCellEditAddress is not null && _inlineCellEditor is { } inlineEditor)
        {
            if (TryApplyInlineCellTextInput(inlineEditor, e.Text))
            {
                inlineEditor.Focus();
                e.Handled = true;
                return;
            }

            return;
        }

        if (_formulaBox.IsFocused)
            return;

        foreach (var character in e.Text)
        {
            if (char.IsControl(character))
                return;
        }

        BeginFormulaEdit(_session.ActiveCell, e.Text);
        e.Handled = true;
    }

    private void SheetScrollViewer_PointerWheelChanged(object? sender, PointerWheelEventArgs e)
    {
        if (_formulaBox.IsFocused)
            return;

        CloseAutoFilterFlyout();

        var vertical = WorkbookViewportScrollPlanner.NormalizePointerWheelNotches(e.Delta.Y);
        var horizontal = WorkbookViewportScrollPlanner.NormalizePointerWheelNotches(e.Delta.X);

        if (e.KeyModifiers.HasFlag(KeyModifiers.Control))
        {
            // Ctrl+Scroll = zoom (mirrors the WPF host's SheetGrid_MouseWheel).
            var wheelScroll = Math.Abs(horizontal) > Math.Abs(vertical) ? horizontal : vertical;
            if (wheelScroll != 0)
                ApplyZoomPercent(_session.ZoomPercent + wheelScroll * StatusBarZoomSliderPlanner.ZoomStepPercent, "Zoom failed.");

            e.Handled = true;
            return;
        }

        var rowDelta = 0;
        var colDelta = 0;
        if (e.KeyModifiers.HasFlag(KeyModifiers.Shift) ||
            Math.Abs(horizontal) > Math.Abs(vertical))
        {
            var scroll = Math.Abs(horizontal) > 0 ? horizontal : vertical;
            colDelta = -scroll;
        }
        else if (Math.Abs(vertical) > 0)
        {
            rowDelta = -vertical;
        }

        if (rowDelta == 0 && colDelta == 0)
            return;

        var visibleSpan = colDelta != 0
            ? _horizontalWorksheetScrollBar.ViewportSize
            : _verticalWorksheetScrollBar.ViewportSize;
        var step = WorkbookViewportScrollPlanner.NormalizeWheelScrollStep(
            GetSystemWheelScrollLines(),
            visibleSpan);
        SplitPanePointerWheelTarget? splitTarget = null;
        if (TryGetSplitPanePointerLayout(out var splitLayout))
        {
            var position = e.GetPosition(_sheetGridHost);
            splitTarget = SplitPanePointerPlanner.ResolveWheelTarget(
                splitLayout.Viewport,
                new GridPoint(position.X, position.Y),
                splitLayout.Width,
                splitLayout.Height,
                splitLayout.RowHeaderWidth,
                splitLayout.ColumnHeaderHeight,
                colDelta != 0,
                splitLayout.MetricScale);
        }

        if (splitTarget is { } target && !CanScrollSplitPane(target.Region, target.Horizontal))
        {
            e.Handled = true;
            return;
        }

        // Split-pane scrollbar chrome is only a second visual for the shared main scrollbar. WPF
        // deliberately removed independent TopRight/BottomLeft offsets (r56), so every permitted
        // split-pane wheel route must use the same PanViewport delta as BottomRight.
        var routesToSharedScrollbar = splitTarget is null ||
            splitTarget is { Region: SplitPanePointerRegion.BottomRight } ||
            splitTarget is { Region: SplitPanePointerRegion.TopRight, Horizontal: true } ||
            splitTarget is { Region: SplitPanePointerRegion.BottomLeft, Horizontal: false };
        var changed = routesToSharedScrollbar
            ? _session.PanViewport(rowDelta * step, colDelta * step)
            : false;

        if (changed)
        {
            RefreshShellForViewportPan("Ready");
            BroadcastScrollOffsetToSideBySidePartner();
        }

        e.Handled = true;
    }

    private static int GetSystemWheelScrollLines()
    {
        if (!OperatingSystem.IsWindows())
            return WorkbookViewportScrollPlanner.DefaultWheelScrollLinesPerNotch;

        try
        {
            return NativeMethods.SystemParametersInfo(NativeMethods.SPI_GETWHEELSCROLLLINES, 0, out var value, 0)
                ? unchecked((int)value)
                : WorkbookViewportScrollPlanner.DefaultWheelScrollLinesPerNotch;
        }
        catch
        {
            // Mirrors the WPF host's try/catch fallback: never let a wheel-scroll-lines lookup
            // failure break the wheel handler itself.
            return WorkbookViewportScrollPlanner.DefaultWheelScrollLinesPerNotch;
        }
    }

    private static class NativeMethods
    {
        public const uint SPI_GETWHEELSCROLLLINES = 0x0068;

        [System.Runtime.InteropServices.DllImport("user32.dll", SetLastError = true)]
        public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, out uint pvParam, uint fWinIni);
    }

    private void SheetScrollViewer_SizeChanged(object? sender, SizeChangedEventArgs e)
    {
        if (!TryGetSheetViewportSize(out var viewportHeight, out var viewportWidth))
            return;

        if (_session.UpdateViewportSize(viewportHeight, viewportWidth))
            RefreshShell(string.IsNullOrWhiteSpace(_statusText.Text) ? UiText.Get("MainLoc_Ready") : _statusText.Text);
    }

    private void WorksheetScrollBar_ValueChanged(object? sender, RangeBaseValueChangedEventArgs e)
    {
        if (_isUpdatingWorksheetScrollBars)
            return;

        CloseAutoFilterFlyout();

        var (topRow, leftCol) = WorkbookViewportScrollPlanner.CalculateViewportOrigin(
            _session.ActiveSheet,
            _verticalWorksheetScrollBar.Value,
            _horizontalWorksheetScrollBar.Value);
        if (_session.SetViewportOrigin(topRow, leftCol))
        {
            RefreshShellForViewportPan("Ready");
            BroadcastScrollOffsetToSideBySidePartner();
        }
    }

    private async Task OpenWorkbookAsync()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        // Claim the busy flag SYNCHRONOUSLY here, before the very first await, rather than deep
        // inside OpenWorkbookFromTargetAsync (mirroring the WPF host's _isOpeningFile set-before-
        // await). Otherwise a second Open request (a drop, OS file-activation, or another click)
        // arriving while the confirm dialog / file picker below are still pending sees _isOpening
        // still false and silently races this one instead of being rejected
        // (R68-async-ordering-race-sweep-3).
        _isOpening = true;
        UpdateSaveButton();
        try
        {
            if (!await ConfirmBeforeDestructiveWorkbookActionAsync(
                    UiText.Get("DirtyWorkbook_OpenWorkbookTitle"),
                    UiText.Get("DirtyWorkbook_DiscardAndOpen")))
                return;

            var openPlan = WorkbookFileCommandPlanner.PlanOpenPicker(StorageProvider.CanOpen, _fileWorkflow.OpenFormats);
            if (!openPlan.CanShowPicker)
            {
                ShowOpenIssue(openPlan.Message);
                return;
            }

            var pickedStorageFile = await AvaloniaFilePickerService.PickSingleOpenFileWithLocalPathAsync(
                StorageProvider,
                AvaloniaFilePickerOpenRequest.FromDescriptors("Open Workbook", openPlan.FileTypes));

            if (pickedStorageFile is null)
                return;

            using (pickedStorageFile)
            {
                var path = pickedStorageFile.LocalPath;
                if (string.IsNullOrWhiteSpace(path))
                {
            ShowOpenIssue(UiText.Get("File_OpenRequiresLocalPath"));
                    return;
                }

                var fileAccessIdentity = await _workbookFileAccessService.CreateIdentityAsync(
                    path,
                    pickedStorageFile.StorageFile);
                // Call the guard-free core directly: this method already owns the busy flag for
                // the whole operation, so routing through the guarded OpenWorkbookPathAsync wrapper
                // would see _isOpening already true and bail out on its own request.
                await OpenWorkbookPathCoreAsync(path, fileAccessIdentity, confirmDirtyWorkbook: false);
            }
        }
        finally
        {
            _isOpening = false;
            UpdateSaveButton();
        }
    }

    private async Task OpenWorkbookPathAsync(
        string path,
        WorkbookFileAccessIdentity? fileAccessIdentity = null,
        bool confirmDirtyWorkbook = true)
    {
        if (_isOpening || _isSaving)
            return;

        // Same set-before-await fix as OpenWorkbookAsync above: this is itself a top-level entry
        // point (drop / OS file-activation / recent-file open all call this directly), so it must
        // claim the busy flag itself before its own confirm-dialog await, not rely on
        // OpenWorkbookFromTargetAsync claiming it later (R68-async-ordering-race-sweep-3).
        _isOpening = true;
        UpdateSaveButton();
        try
        {
            await OpenWorkbookPathCoreAsync(path, fileAccessIdentity, confirmDirtyWorkbook);
        }
        finally
        {
            _isOpening = false;
            UpdateSaveButton();
        }
    }

    private async Task OpenWorkbookPathCoreAsync(
        string path,
        WorkbookFileAccessIdentity? fileAccessIdentity,
        bool confirmDirtyWorkbook)
    {
        if (!TryCommitPendingFormulaEdit())
            return;

        if (confirmDirtyWorkbook &&
            !await ConfirmBeforeDestructiveWorkbookActionAsync(
                UiText.Get("DirtyWorkbook_OpenWorkbookTitle"),
                UiText.Get("DirtyWorkbook_DiscardAndOpen")))
            return;

        if (!_fileWorkflow.TryResolveOpenTarget(path, fileAccessIdentity, out var target, out var message))
        {
            ShowOpenIssue(message);
            return;
        }

        await OpenWorkbookFromTargetAsync(target!);
    }

    private bool TrySelectDroppedWorkbookPath(DragEventArgs e, out string? path, out string message) =>
        TrySelectDroppedWorkbookPath(e, out path, out _, out message);

    private bool TrySelectDroppedWorkbookPath(
        DragEventArgs e,
        out string? path,
        out IStorageItem? storageItem,
        out string message)
    {
        var files = e.DataTransfer.TryGetFiles();
        if (files is null)
        {
            path = null;
            storageItem = null;
            message = "Drop a supported local workbook file.";
            return false;
        }

        return TrySelectOpenableLocalWorkbookPath(files, out path, out storageItem, out message);
    }

    private bool TrySelectOpenableLocalWorkbookPath(IEnumerable<IStorageItem> files, out string? path, out string message) =>
        TrySelectOpenableLocalWorkbookPath(files, out path, out _, out message);

    private bool TrySelectOpenableLocalWorkbookPath(
        IEnumerable<IStorageItem> files,
        out string? path,
        out IStorageItem? storageItem,
        out string message)
    {
        path = null;
        storageItem = null;
        if (_isOpening || _isSaving)
        {
            message = "Open is busy.";
            return false;
        }

        if (!TryCommitPendingFormulaEdit())
        {
            message = "Finish the current cell edit before opening another workbook.";
            return false;
        }

        return TryResolveOpenableLocalWorkbookPath(files, out path, out storageItem, out message);
    }

    // Shared by TrySelectOpenableLocalWorkbookPath (a real Open/Drop, which first commits any
    // pending formula edit above) and TryPreviewDroppedWorkbookPath (the DragOver preview, which
    // must NOT touch formula-edit state -- see R153-shared-drag-drop-F1). This half only resolves
    // file-openability; it has no side effects on session/editor state.
    private bool TryResolveOpenableLocalWorkbookPath(
        IEnumerable<IStorageItem> files,
        out string? path,
        out IStorageItem? storageItem,
        out string message)
    {
        var candidates = files
            .Select(file => new
            {
                StorageItem = file,
                LocalPath = file.TryGetLocalPath()
            })
            .ToList();
        var plan = WorkbookOpenIngressPlanner.SelectOpenableExistingLocalFile(
            candidates.Select(candidate => candidate.LocalPath),
            candidatePath =>
                _fileWorkflow.TryResolveOpenTarget(candidatePath, out var target, out var unsupportedMessage)
                    ? WorkbookOpenIngressResolution.Resolved(target!.Path)
                    : WorkbookOpenIngressResolution.Failed(unsupportedMessage));
        if (!plan.Success)
        {
            path = null;
            storageItem = null;
            message = plan.Message;
            return false;
        }

        path = plan.Path;
        storageItem = candidates[plan.CandidateIndex].StorageItem;
        message = "";
        return true;
    }

    private async Task OpenWorkbookFromTargetAsync(WorkbookOpenTarget target)
    {
        // _isOpening is already claimed by the entry point that reached here (OpenWorkbookAsync /
        // OpenWorkbookPathAsync), set synchronously before their first await -- this method no
        // longer owns the flag itself (R68-async-ordering-race-sweep-3).
        //
        // R119-avalonia-file-op-cancel: this is the single choke point every open path funnels
        // through (File > Open, drag-drop, MRU clicks, startup args), so wiring the cancellable
        // token here -- rather than at each caller -- reaches all of them at once, mirroring the
        // WPF host's OpenFileAsync shared cancellation-session lease.
        var operationCancellation = _fileOperationCancellationSession.Begin();
        UpdateSaveButton();
        try
        {
            _statusText.Text = WorkbookProgressTextFormatter
                .FormatOpen("preparing", TimeSpan.Zero, percent: null, UiText.Get)
                .Detail;
            _statusText.Foreground = Brush(67, 113, 83);
            ApplyFileOperationProgress(null);
            var progress = new Progress<WorkbookOpenProgressUpdate>(
                update =>
                {
                    _statusText.Text = WorkbookProgressTextFormatter.FormatOpen(update, UiText.Get).Detail;
                    _statusText.Foreground = Brush(67, 113, 83);
                    ApplyFileOperationProgress(update.Percent);
                });

            var workflowResult = await _fileWorkflow.OpenAsync(new WorkbookOpenWorkflowRequest(
                target,
                ApplyOpenedWorkbookAsync,
                // R154-shared-templates-F2: no CompletionDisplayName override here, matching the
                // WPF host's identical Open call (MainWindow.Backstage.cs) -- leave it to the
                // shared planner's own default (WorkbookOpenResult.DisplayName =
                // Path.GetFileNameWithoutExtension(path), see WorkbookOpenService.cs). A normal
                // open still shows its extension because WorkbookSession.DisplayName falls back
                // to Path.GetFileName(CurrentFilePath) once a real backing file is set; only a
                // template open (CurrentFilePath forced null) falls back to this completion name,
                // and Excel never shows a real file extension on an unsaved, template-derived
                // document. Passing the extension-including file name here (as before) leaked the
                // template's own extension into that fallback, showing e.g. "Invoice.xltx" for a
                // brand-new, nowhere-saved workbook.
                Progress: progress,
                PrepareAsync: async (openTarget, _) => new WorkbookFileWorkflowPreparation(
                    await _workbookFileAccessService.BeginAccessAsync(
                        StorageProvider,
                        openTarget.FileAccessIdentity)),
                CancellationToken: operationCancellation.Token));
            if (!workflowResult.Succeeded)
            {
                ShowOpenIssue(workflowResult.Message);
                return;
            }

            return;

            Task ApplyOpenedWorkbookAsync(
                WorkbookOpenWorkflowContext context,
                CancellationToken cancellationToken)
            {
            var result = context.Result;
            cancellationToken.ThrowIfCancellationRequested();
            var (viewportHeight, viewportWidth) = GetCurrentSheetViewportSize();
            ReplaceSession(_sessionFactory.CreateOpened(
                target,
                result,
                viewportHeight,
                viewportWidth,
                includeObjects: true,
                completionPlan: context.CompletionPlan));
            RefreshViewportSizeForZoom();
            // Capture the write-time snapshot this workbook was opened from so a later Save to the
            // SAME path can detect a concurrent second writer (see _currentFileSourceLastWriteTimeUtc)
            // -- mirrors the WPF host's equivalent capture in MainWindow.Backstage.cs
            // (R116-avalonia-external-modification-detection). ReplaceSession above already reset
            // this to null; only a successful open of a real file (SourceLastWriteTimeUtc non-null)
            // re-arms the check. Deliberately placed AFTER the ReplaceSession/RefreshViewportSizeForZoom/
            // RecordRecentWorkbook trio, which AvaloniaShellSourceTests pins as one contiguous block:
            // nothing in that trio touches this field, so the capture is equivalent here and the
            // existing open-sequence contract stays intact rather than being loosened to fit.
            _currentFileSourceLastWriteTimeUtc = result.SourceLastWriteTimeUtc;
            ClearSelectedDrawingObject();
            RefreshShell(_session.StartupStatus);
            _session.DataValidationPromptResolver = ResolveDataValidationPrompt;
            _session.SortAdjacentDataPromptResolver = ResolveSortAdjacentDataPrompt;
            // A workbook saved with "Read-Only Recommended" or a write-reservation password used
            // to open fully editable on this shell with no prompt at all until this fix
            // (R75-services-protection-security-4-2); mirrors the WPF host's
            // ApplyWorkbookReadOnlyOpenPolicy (MainWindow.Backstage.cs), called at the same
            // point in the open sequence, right after the session/shell refresh.
            ApplyWorkbookReadOnlyOpenPolicy(_session.Workbook, target.Path);
            return Task.CompletedTask;
            }
        }
        catch (OperationCanceledException) when (operationCancellation.Token.IsCancellationRequested)
        {
            // The user clicked the status-bar Cancel button (R119-avalonia-file-op-cancel): the
            // session was never replaced (ReplaceSession only runs after LoadAsync/the
            // ThrowIfCancellationRequested above both return normally), so there is nothing to roll
            // back -- just report the abort, matching the WPF host's equivalent catch.
                ShowOpenIssue(UiText.Get("File_OpenCanceledMessage"));
        }
        catch (Exception ex)
        {
            // Broad catch (matching the WPF host's equivalent open path in
            // MainWindow.Backstage.cs) rather than an allow-list of exception types: adapter
            // failures at open time are not limited to IOException/InvalidDataException/etc -- a
            // password-protected .xlsx throws WorkbookPasswordProtectedException (a plain
            // Exception subtype, not any of those), and a misnamed/mismatched file can throw other
            // adapter-specific exceptions (e.g. XmlException). Any of those escaping this method
            // propagates out of an `async void` event handler (OpenButton_Click / the Open Recent
            // menu item's click handler), which is fatal and crashes the whole app instead of
            // showing "Open failed: ..." (R86-services-file-format-detect-5-1).
            ShowOpenIssue(UiText.Format("File_OpenFailedFormat", ex.Message));
        }
        finally
        {
            // R119-avalonia-file-op-cancel: release the token so a later operation gets its own
            // fresh source and the Cancel button hides again via the caller's own UpdateSaveButton
            // (OpenWorkbookAsync/OpenWorkbookPathAsync already call it in their own finally after
            // clearing _isOpening).
            operationCancellation.Dispose();
        }
    }

    /// <summary>
    /// Loads a crash-recovery snapshot (a <c>NativeJsonAdapter</c>-serialized <c>.fxl</c> sidecar
    /// written by <see cref="AvaloniaAutosaveCoordinator"/>) directly into this window's session,
    /// associates it with <paramref name="originalFilePath"/> so Save goes back to the right
    /// place, and marks the shell refreshed — mirroring the WPF host's
    /// <c>OpenRecoverySnapshotAsync</c> + <c>SetCurrentFilePathForRecovery</c> combination. Unlike
    /// a normal open, the snapshot path itself is never recorded in the recent-files list (it is a
    /// temporary file under the app-data recovery folder, not a document the user opened).
    /// </summary>
    internal Task<bool> LoadRecoverySnapshotAsync(string snapshotPath, string? originalFilePath)
    {
        try
        {
            var source = RecoverySnapshotLoader.Load(snapshotPath, originalFilePath);

            var (viewportHeight, viewportWidth) = GetCurrentSheetViewportSize();
            ReplaceSession(_sessionFactory.Create(source, viewportHeight, viewportWidth, includeObjects: true));
            _session.DataValidationPromptResolver = ResolveDataValidationPrompt;
            _session.SortAdjacentDataPromptResolver = ResolveSortAdjacentDataPrompt;
            // Mark the recovered session dirty so the user sees the modified indicator and is
            // prompted to save rather than risk silently losing the recovered data — mirrors the
            // WPF host's MarkWorkbookDirtyForRecovery call after a successful recovery load.
            _session.MarkDirtyForRecovery();
            RefreshViewportSizeForZoom();
            ClearSelectedDrawingObject();
            RefreshShell(_session.StartupStatus);
            return Task.FromResult(true);
        }
        catch (Exception)
        {
            // Best-effort recovery: a corrupt/partially-written snapshot (e.g. the process was
            // killed mid-write) must never crash startup — just report "nothing to recover".
            return Task.FromResult(false);
        }
    }

    private async Task<bool> SaveCurrentWorkbookAsync()
    {
        if (_isSaving)
            return false;

        if (!TryCommitPendingFormulaEdit())
            return false;

        return await _fileWorkflow.SaveResolvedAsync(
            isDirty: _session.IsDirty,
            currentFilePath: _session.CurrentFilePath,
            resolveCurrentTarget: ResolveExistingSaveTarget,
            saveTargetAsync: target => SaveWorkbookToTargetAsync(target),
            saveAsAsync: SaveWorkbookAsAsync);
    }

    /// <summary>
    /// The existing-path save target, or <c>null</c> if there is none usable OR this session was
    /// marked read-only by <see cref="ApplyWorkbookReadOnlyOpenPolicy"/> -- withholding the
    /// target here falls <see cref="SaveCurrentWorkbookAsync"/> through to the Save-As dialog instead
    /// of silently overwriting the original file (R83-services-doc-recovery-props-5-1, mirrors the
    /// WPF host's <c>MainWindow.WorkbookLifecycle.ResolveExistingSaveTarget</c>).
    /// </summary>
    private FileSaveTarget? ResolveExistingSaveTarget() =>
        _workbookReadOnlySession.ResolveExistingSaveTarget(
            () => _fileWorkflow.ResolveExistingSaveTarget(_session.CurrentFilePath));

    private async Task ShareWorkbookAsync()
    {
        if (_isOpening || _isSaving)
            return;

        if (!TryCommitPendingFormulaEdit())
            return;

        await ExecuteWorkbookShareActionPlanAsync(CreateWorkbookShareActionPlan());
    }

    private DocumentShareActionPlan CreateWorkbookShareActionPlan() =>
        DocumentShareActionPlanner.CreatePlan(
            _session.CurrentFilePath,
            CreateWorkbookShareActionSurface(),
            File.Exists);

    private DocumentShareActionSurface CreateWorkbookShareActionSurface()
    {
        var capability = _workbookShareSheetService.Capability;
        return new(
            capability.ShareSheetLabel,
            CanShowShareSheet: capability.CanShowShareSheet,
            CanOpenContainingFolder: TopLevel.GetTopLevel(this)?.Launcher is not null,
            OpenContainingFolderLabel: GetWorkbookShareOpenContainingFolderLabel());
    }

    private static string GetWorkbookShareOpenContainingFolderLabel() =>
        OperatingSystem.IsMacOS()
            ? "Reveal in Finder"
            : "Open Containing Folder";

    private static string FormatWorkbookShareStatus(DocumentShareActionPlan plan) =>
        DocumentShareActionPlanner.FormatStatus(plan, DocumentShareActionTextSpec.WorkbookEnglish);

    private async Task ExecuteWorkbookShareActionPlanAsync(DocumentShareActionPlan plan)
    {
        switch (plan.Kind)
        {
            case DocumentShareActionPlanKind.SaveAsBeforeShare:
                ShowShareStatus(FormatWorkbookShareStatus(plan), isWarning: true);
                if (!await SaveWorkbookAsAsync())
                    return;
                var nextPlan = CreateWorkbookShareActionPlan();
                if (nextPlan.Kind == DocumentShareActionPlanKind.SaveAsBeforeShare)
                {
                    ShowShareStatus(FormatWorkbookShareStatus(nextPlan), isWarning: true);
                    return;
                }

                await ExecuteWorkbookShareActionPlanAsync(nextPlan);
                break;

            case DocumentShareActionPlanKind.OpenContainingFolder:
                if (!await TrySaveDirtyWorkbookForShareAsync())
                    return;

                var refreshedPlan = CreateWorkbookShareActionPlan();
                if (refreshedPlan.Kind != DocumentShareActionPlanKind.OpenContainingFolder)
                {
                    await ExecuteWorkbookShareActionPlanAsync(refreshedPlan);
                    return;
                }

                await OpenWorkbookContainingFolderAsync(refreshedPlan);
                break;

            case DocumentShareActionPlanKind.ShareSheet:
                await ShowWorkbookShareSheetAsync(plan);
                break;

            case DocumentShareActionPlanKind.Deferred:
            default:
                ShowShareStatus(FormatWorkbookShareStatus(plan), isWarning: true);
                break;
        }
    }

    private async Task<bool> TrySaveDirtyWorkbookForShareAsync()
    {
        if (!_session.IsDirty)
            return true;

        return await SaveCurrentWorkbookAsync() && !_session.IsDirty;
    }

    private async Task ShowWorkbookShareSheetAsync(DocumentShareActionPlan plan)
    {
        if (!await TrySaveDirtyWorkbookForShareAsync())
            return;

        var refreshedPlan = CreateWorkbookShareActionPlan();
        if (refreshedPlan.Kind != DocumentShareActionPlanKind.ShareSheet)
        {
            await ExecuteWorkbookShareActionPlanAsync(refreshedPlan);
            return;
        }

        var filePath = refreshedPlan.Path;
        if (string.IsNullOrWhiteSpace(filePath) || !File.Exists(filePath))
        {
            await ExecuteWorkbookShareActionPlanAsync(CreateWorkbookShareActionPlan());
            return;
        }

        ShowShareStatus(FormatWorkbookShareStatus(refreshedPlan), isWarning: false);
        try
        {
            var result = await _workbookShareSheetService.ShowShareSheetAsync(this, filePath);
            if (result.WasShown)
            {
                ShowShareStatus(
                    $"{refreshedPlan.EffectiveSurface.ShareSheetLabel} opened for {Path.GetFileName(filePath)}.",
                    isWarning: false);
                return;
            }

            if (!string.IsNullOrWhiteSpace(result.Message))
                ShowShareStatus(result.Message, isWarning: true);

            await FallbackToOpenContainingFolderAfterShareSheetFailureAsync(refreshedPlan);
        }
        catch (Exception ex)
        {
            ShowShareStatus($"{refreshedPlan.EffectiveSurface.ShareSheetLabel} could not open: {ex.Message}", isWarning: true);
            await FallbackToOpenContainingFolderAfterShareSheetFailureAsync(refreshedPlan);
        }
    }

    private async Task FallbackToOpenContainingFolderAfterShareSheetFailureAsync(DocumentShareActionPlan shareSheetPlan)
    {
        var fallbackSurface = CreateWorkbookShareActionSurface() with { CanShowShareSheet = false };
        var fallbackPlan = DocumentShareActionPlanner.CreatePlan(shareSheetPlan.Path, fallbackSurface, File.Exists);
        if (fallbackPlan.Kind == DocumentShareActionPlanKind.OpenContainingFolder)
        {
            await OpenWorkbookContainingFolderAsync(fallbackPlan);
            return;
        }

        ShowShareStatus(FormatWorkbookShareStatus(fallbackPlan), isWarning: true);
    }

    private async Task OpenWorkbookContainingFolderAsync(DocumentShareActionPlan plan)
    {
        if (string.IsNullOrWhiteSpace(plan.Path))
        {
            var unavailablePlan = plan with
            {
                Kind = DocumentShareActionPlanKind.Deferred,
                UnavailableReason = DocumentShareActionUnavailableReason.ContainingFolderUnavailable,
            };
            ShowShareStatus(FormatWorkbookShareStatus(unavailablePlan), isWarning: true);
            return;
        }

        var launcher = TopLevel.GetTopLevel(this)?.Launcher;
        ShowShareStatus(FormatWorkbookShareStatus(plan), isWarning: true);
        var result = await DesktopPathLauncher.RevealFileAsync(
            plan.Path,
            launcher is null
                ? null
                : target => launcher.LaunchDirectoryInfoAsync(new DirectoryInfo(target.LaunchPath)));

        if (result.Outcome == DesktopPathLaunchOutcome.Missing)
        {
            var unavailablePlan = new DocumentShareActionPlan(
                DocumentShareActionPlanKind.Deferred,
                plan.Path,
                UnavailableReason: DocumentShareActionUnavailableReason.ContainingFolderUnavailable,
                Surface: plan.EffectiveSurface);
            ShowShareStatus(FormatWorkbookShareStatus(unavailablePlan), isWarning: true);
            return;
        }

        if (result.Outcome == DesktopPathLaunchOutcome.LauncherUnavailable)
        {
            ShowShareStatus(FormatWorkbookShareStatus(CreateWorkbookShareActionPlan()), isWarning: true);
            return;
        }

        if (result.Outcome != DesktopPathLaunchOutcome.Launched)
        {
            var detail = result.Error is null
                ? $" for {plan.Path}."
                : $": {result.Error.Message}";
            ShowShareStatus($"{plan.EffectiveSurface.OpenContainingFolderLabel} could not open{detail}", isWarning: true);
            return;
        }

        var workbookName = string.IsNullOrWhiteSpace(plan.Path)
            ? "the saved workbook"
            : Path.GetFileName(plan.Path);
        ShowShareStatus($"{plan.EffectiveSurface.OpenContainingFolderLabel} opened for {workbookName}.", isWarning: false);
    }

    private async Task<bool> SaveWorkbookAsAsync()
    {
        if (!TryBeginFileOperation())
            return false;

        try
        {
            if (!TryCommitPendingFormulaEdit())
                return false;

            Func<WorkbookSaveAsCommandPickerPlan, Task<WorkbookSaveAsPickerSelection?>>? pickerOverride = null;
            ResolveWorkbookSaveAsPicker(ref pickerOverride);
            var canShowPicker = ResolveWorkbookSaveAsPickerAvailability(
                StorageProvider.CanSave,
                pickerOverride is not null);
            var savePlan = WorkbookFileCommandPlanner.PlanSaveAsPicker(
                canShowPicker,
                _fileWorkflow.SaveFormats,
                _session.Workbook.Name,
                _session.DisplayName,
                NativeWorkbookExtension);
            if (!savePlan.CanShowPicker)
            {
                ShowSaveIssue(savePlan.Message);
                return false;
            }

            WorkbookSaveAsPickerSelection? pickedStorageFile;
            if (pickerOverride is not null)
            {
                pickedStorageFile = await pickerOverride(savePlan);
            }
            else
            {
                var pickedFile = await AvaloniaFilePickerService.PickSaveFileWithLocalPathAsync(
                    StorageProvider,
                    AvaloniaFilePickerSaveRequest.FromSavePlan(
                        "Save Workbook",
                        savePlan.Picker,
                        showOverwritePrompt: true,
                        suggestFirstFileType: true));
                pickedStorageFile = pickedFile is null
                    ? null
                    : WorkbookSaveAsPickerSelection.FromPickedStorageFile(pickedFile);
            }

            if (pickedStorageFile is null)
                return false;

            using (pickedStorageFile)
            {
                var path = pickedStorageFile.LocalPath;
                if (string.IsNullOrWhiteSpace(path))
                {
            ShowSaveIssue(UiText.Get("File_SaveAsRequiresLocalPath"));
                    return false;
                }

                var pathPlan = _fileWorkflow.PlanSavePathNormalization(
                    path,
                    NativeWorkbookExtension,
                    File.Exists);
                if (pathPlan.ShouldConfirmOverwrite &&
                    !await ConfirmNormalizedOverwriteAsync(
                        pathPlan.Path,
                        NormalizedOverwriteTargetKind.Workbook))
                {
                ShowSaveIssue(UiText.Get("File_SaveCanceledMessage"));
                    return false;
                }

                path = pathPlan.Path;
                if (!_fileWorkflow.TryResolveSaveTarget(path, out var target, out var message))
                {
                    ShowSaveIssue(message);
                    return false;
                }

                var fileAccessIdentity = await _workbookFileAccessService.CreateIdentityAsync(
                    path,
                    pickedStorageFile.StorageFile);
                return await SaveWorkbookToTargetAsync(target!, fileAccessIdentity);
            }
        }
        finally
        {
            EndFileOperation();
        }
    }

    private Task ExportActiveSheetPdfAsync() =>
        ExportWorkbookPdfAsync(
            WorkbookExportPrintScope.ActiveSheet,
            WorkbookExportPrintOutputKind.Pdf);

    private bool TryBeginFileOperation()
    {
        if (_isOpening || _isSaving)
            return false;

        _isSaving = true;
        UpdateSaveButton();
        return true;
    }

    private void EndFileOperation()
    {
        _isSaving = false;
        UpdateSaveButton();
    }

    private async Task<bool> ConfirmNormalizedOverwriteAsync(
        string normalizedPath,
        NormalizedOverwriteTargetKind targetKind)
    {
        var prompt = NormalizedOverwritePromptPlanner.Build(targetKind, normalizedPath);

        var dialog = new Window
        {
            Title = UiText.Get(prompt.WindowTitleResourceKey),
            Width = 460,
            Height = 210,
            MinWidth = 420,
            MinHeight = 200,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };

        var titleText = new TextBlock
        {
            Text = UiText.Format(prompt.FileExistsFormatResourceKey, prompt.FileName),
            FontSize = 16,
            FontWeight = FontWeight.SemiBold,
            TextWrapping = TextWrapping.Wrap,
        };
        var detailText = new TextBlock
        {
            Text = UiText.Get(prompt.DetailResourceKey),
            Foreground = HeaderForeground,
            TextWrapping = TextWrapping.Wrap,
        };

        var replaceButton = new Button
        {
            Content = UiText.Get(prompt.ReplaceButtonResourceKey),
            MinWidth = 92,
            Padding = new Thickness(10, 4),
        };
        AutomationProperties.SetAutomationId(replaceButton, prompt.ReplaceButtonAutomationId);
        AutomationProperties.SetName(
            replaceButton,
            UiText.CreateAutomationName(UiText.Get(prompt.ReplaceButtonResourceKey)));
        AutomationProperties.SetHelpText(replaceButton, UiText.Get(prompt.ReplaceHelpTextResourceKey));

        var cancelButton = new Button
        {
            Content = UiText.CreateAutomationName(UiText.Get(prompt.CancelButtonResourceKey)),
            MinWidth = 92,
            Padding = new Thickness(10, 4),
            IsCancel = true,
        };
        AutomationProperties.SetAutomationId(cancelButton, prompt.CancelButtonAutomationId);
        AutomationProperties.SetName(
            cancelButton,
            UiText.CreateAutomationName(UiText.Get(prompt.CancelButtonResourceKey)));
        AutomationProperties.SetHelpText(cancelButton, UiText.Get(prompt.CancelHelpTextResourceKey));

        var shouldReplace = false;
        void Finish(bool value)
        {
            shouldReplace = value;
            dialog.Close();
        }

        replaceButton.Click += (_, _) => Finish(true);
        cancelButton.Click += (_, _) => Finish(false);
        dialog.Opened += (_, _) => cancelButton.Focus();
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Escape)
            {
                Finish(false);
                e.Handled = true;
            }
        };

        dialog.Content = new StackPanel
        {
            Margin = new Thickness(18),
            Spacing = 12,
            Children =
            {
                titleText,
                detailText,
                new Border { Height = 10 },
                new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Spacing = 8,
                    HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
                    Children =
                    {
                        cancelButton,
                        replaceButton,
                    },
                },
            },
        };

        await dialog.ShowDialog(this);
        return shouldReplace;
    }

    private WorkbookExportPrintPlan CreateActiveSheetPortablePdfPrintPlan() =>
        WorkbookExportPrintPlanner.CreatePlanFromPageSetup(
            _session.Workbook,
            new WorkbookExportPrintIntent(
                WorkbookExportPrintScope.ActiveSheet,
                WorkbookExportPrintOutputKind.Pdf,
                ActiveSheetIndex: ResolveActiveSheetIndex()),
            WorkbookExportPrintSurface.MacOs);

    /// <summary>
    /// Scoped variant of <see cref="ExportActiveSheetPdfAsync"/> used by the backstage Export pane. Reuses
    /// the same picker → <see cref="WorkbookExportPrintPlanner"/> → <see cref="PortablePdfExportPlanner"/>
    /// → <see cref="Pdf.AvaloniaPdfDocumentExporter"/> path; the only addition is honoring the user's chosen
    /// scope (selection / active sheet / whole visible workbook). Output kind is currently PDF on this
    /// surface (XPS is offered only where the surface advertises it, which macOS does not).
    /// </summary>
    private async Task ExportWorkbookPdfAsync(
        WorkbookExportPrintScope scope,
        WorkbookExportPrintOutputKind outputKind)
    {
        if (!TryBeginFileOperation())
            return;

        try
        {
            if (!TryCommitPendingFormulaEdit())
                return;

            if (!StorageProvider.CanSave)
            {
                ShowExportIssue(UiText.Get("MainLoc_PdfExportUnavailable"));
                return;
            }

            var format = ExportFormatCatalog.Get(outputKind);
            if (!format.IsPortable)
            {
                ShowExportIssue("Portable export supports PDF only; XPS remains Windows-only.");
                return;
            }

            var selectionPlan = WorkbookExportInteractionPlanner.CreateSelectionPlan(
                scope,
                _session.SelectedRange);
            if (!selectionPlan.IsValid)
            {
                ShowExportIssue(UiText.Get(selectionPlan.ErrorStatusKey!));
                return;
            }

            var exportOptions = await ShowExportOptionsDialogAsync(selectionPlan.ContentScope, format.Format);
            if (exportOptions is null)
                return;

            var storageFile = await ShowPortablePdfSavePickerAsync("Export to PDF");

            if (storageFile is null)
                return;

            using (storageFile)
            {
                var path = storageFile.LocalPath;
                if (string.IsNullOrWhiteSpace(path))
                {
                    ShowExportIssue(UiText.Get("MainLoc_PdfExportRequiresLocalPath"));
                    return;
                }

                var requestPlan = WorkbookExportInteractionPlanner.CreateRequestPlan(
                    path,
                    outputKind,
                    exportOptions,
                    File.Exists);
                if (requestPlan.ShouldConfirmNormalizedOverwrite &&
                    !await ConfirmNormalizedOverwriteAsync(
                        requestPlan.Request.Path,
                        NormalizedOverwriteTargetKind.Pdf))
                {
                    ShowExportIssue(UiText.Get("MainLoc_PdfExportCanceled"));
                    return;
                }

                try
                {
                    string? adapterFailureMessage = null;
                    var workflowResult = await WorkbookExportWorkflow.ExecuteBooleanAsync(
                        requestPlan.Request,
                        async (effectiveRequest, cancellationToken) =>
                        {
                            _statusText.Text = UiText.Get("Progress_ExportingPdf");
                            _statusText.Foreground = Brush(67, 113, 83);

                            var exportPrintPlan = CreatePortablePdfPrintPlan(effectiveRequest.Options, outputKind);
                            var exportPlan = PortablePdfExportPlanner.CreatePlan(exportPrintPlan);
                            if (!exportPlan.IsReady)
                            {
                                adapterFailureMessage = exportPlan.StatusText;
                                return false;
                            }

                            if (!PortablePdfExportPlanner.TryApplyOptions(
                                    exportPlan,
                                    effectiveRequest.Options,
                                    out var effectiveExportPlan,
                                    out var optionsError,
                                    AvaloniaExportPlannerTextResolver))
                            {
                                adapterFailureMessage = optionsError ?? UiText.Get("MainWindowMessage_ExportUnsupportedOptions");
                                return false;
                            }

                            var exportExecution = await new AtomicExportExecutor()
                                .ExecuteAsync<Pdf.AvaloniaPdfDocumentExportOutcome>(
                                effectiveRequest.Path,
                                (output, token) =>
                                {
                                    token.ThrowIfCancellationRequested();
                                    return ValueTask.FromResult(Pdf.AvaloniaPdfDocumentExporter.Save(
                                        _session.Workbook,
                                        effectiveExportPlan,
                                        output,
                                        options: null,
                                        workbookDirectory: ResolveWorkbookDirectoryForHeaderFooter()));
                                },
                                cancellationToken);
                            if (!exportExecution.Succeeded)
                            {
                                cancellationToken.ThrowIfCancellationRequested();
                                throw exportExecution.Exception ?? new IOException(
                                    exportExecution.Error?.Detail.Message ??
                                    exportExecution.Validation?.Detail.ToString() ??
                                    "PDF export did not complete.");
                            }

                            RefreshShell(UiText.Format(
                                "MainLoc_StatusFileName",
                                exportExecution.Value!.Result.StatusText,
                                Path.GetFileName(effectiveRequest.Path)));
                            return true;
                        });
                    var resultPlan = WorkbookExportInteractionPlanner.CreateResultPlan(
                        workflowResult,
                        isBackstageVisible: false,
                        adapterFailureMessage: adapterFailureMessage);
                    if (resultPlan.ShouldPresentIssue)
                    {
                        var message = resultPlan.IssueKind switch
                        {
                            WorkbookExportResultIssueKind.Failure when adapterFailureMessage is null => UiText.Format(
                                "MainLoc_PdfExportFailed",
                                workflowResult.Exception?.Message ?? resultPlan.Message),
                            WorkbookExportResultIssueKind.Canceled => UiText.Get("MainLoc_PdfExportCanceled"),
                            _ => resultPlan.Message
                        };
                        ShowExportIssue(message);
                    }

                    if (resultPlan.ShouldOpenDestination)
                        await TryOpenExportedPdfAsync(resultPlan.DestinationPath);
                }
                catch (Exception ex)
                {
                    ShowExportIssue(UiText.Format("MainLoc_PdfExportFailed", ex.Message));
                }
            }
        }
        finally
        {
            EndFileOperation();
        }
    }

    private WorkbookExportPrintPlan CreatePortablePdfPrintPlan(
        ExportOptions options,
        WorkbookExportPrintOutputKind outputKind)
    {
        var scope = ExportFormatCatalog.ToPrintScope(options.Scope);
        var selectedRange = scope == WorkbookExportPrintScope.SelectedRange
            ? _session.SelectedRange
            : (GridRange?)null;

        return WorkbookExportPrintPlanner.CreatePlanFromPageSetup(
            _session.Workbook,
            new WorkbookExportPrintIntent(
                scope,
                outputKind,
                ActiveSheetIndex: ResolveActiveSheetIndex(),
                SelectedRange: selectedRange,
                IgnorePrintAreas: options.IgnorePrintAreas),
            WorkbookExportPrintSurface.MacOs);
    }

    private int ResolveActiveSheetIndex()
    {
        var index = _session.Workbook.IndexOfSheet(_session.ActiveSheet.Id);
        return index >= 0 ? index : _session.Workbook.ActiveSheetIndex ?? 0;
    }

    private Task<AvaloniaPickedStorageFile?> ShowPortablePdfSavePickerAsync(string title)
    {
        var pickerPlan = ExportFilePickerPlanner.BuildPortablePdfPickerPlan(_session.DisplayName, ApplicationTitle);
        return AvaloniaFilePickerService.PickSaveFileWithLocalPathAsync(
            StorageProvider,
            AvaloniaFilePickerSaveRequest.FromDescriptors(
                title,
                pickerPlan.FileTypes,
                pickerPlan.SuggestedFileName,
                pickerPlan.DefaultExtensionWithoutDot,
                showOverwritePrompt: true,
                suggestFirstFileType: true));
    }

    private async Task<bool> SaveWorkbookToTargetAsync(
        FileSaveTarget target,
        WorkbookFileAccessIdentity? fileAccessIdentity = null)
    {
        if (_fileWorkflow.ShouldSkipSaveTargetWrite(_session.IsDirty, _session.CurrentFilePath, target))
        {
            return true;
        }

        var targetPath = target.Path;
        var sessionAtSaveStart = _session;
        // R119-avalonia-file-op-cancel: this is the single choke point every save path funnels
        // through (Save, Save As, autosave-triggered saves), so wiring the cancellable token here
        // reaches all of them at once, mirroring the WPF host's SaveWorkbookToTargetAsync in
        // MainWindow.Backstage.cs.
        var operationCancellation = _fileOperationCancellationSession.Begin();
        try
        {
            var progress = new Progress<WorkbookSaveProgressUpdate>(
                update =>
                {
                    _statusText.Text = WorkbookProgressTextFormatter.FormatSave(update, UiText.Get).Detail;
                    _statusText.Foreground = Brush(67, 113, 83);
                    ApplyFileOperationProgress(update.Percent);
                });

            // R120-corewriter-persist-saving-window-view-1: reconcile THIS view's own per-window
            // view state (zoom/view-mode/gridlines/headings/show-formulas/freeze/split) onto the
            // shared Sheet fields before the writer reads them, so a save from THIS view persists
            // what THIS view is displaying rather than whichever sibling view last touched those
            // shared fields. Must run synchronously, before the workbook is handed off below.
            var workflowResult = await _fileWorkflow.SaveTargetAsync(new WorkbookSaveWorkflowRequest(
                sessionAtSaveStart.IsDirty,
                sessionAtSaveStart.CurrentFilePath,
                target,
                _currentFileSourceLastWriteTimeUtc,
                GetCurrentWorkbook: () => _session.Workbook,
                GetDirtyGeneration: () => _session.DirtyGeneration,
                ConfirmExternallyModifiedOverwrite: path =>
                    ResolveExternallyModifiedFileOverwriteConfirm(path) == UserMessageResult.Yes,
                ProjectViewStateForSave: sessionAtSaveStart.ReconcileViewStateForSave,
                SaveAsync: invocation => _saveService.SaveAsync(
                    invocation.Target.Path,
                    invocation.Target.Adapter,
                    invocation.Workbook,
                    progress,
                    invocation.CancellationToken,
                    invocation.ExpectedLastWriteTimeUtc),
                PrepareAsync: async _ =>
                {
                    fileAccessIdentity ??= await _workbookFileAccessService.CreateIdentityAsync(
                        targetPath,
                        existingIdentity: sessionAtSaveStart.CurrentFileAccessIdentity);
                    var fileAccess = await _workbookFileAccessService.BeginAccessAsync(
                        StorageProvider,
                        fileAccessIdentity);
                    return new WorkbookSaveExecutionPreparation(fileAccessIdentity, fileAccess);
                },
                ApplyCompletion: plan => _session.ApplySaveCompletion(plan),
                CancellationToken: operationCancellation.Token,
                CompletionDisplayName: Path.GetFileName(targetPath),
                ConfirmTargetAsync: (saveTarget, _) =>
                {
                    var extension = Path.GetExtension(saveTarget.Path);
                    var confirmed =
                        !LossyFormatFeatureLossPlanner.RequiresFeatureLossConfirmation(
                            sessionAtSaveStart.Workbook,
                            extension) ||
                        ResolveLossyFormatFeatureLossConfirm(extension) == UserMessageResult.Yes;
                    return Task.FromResult(confirmed);
                },
                ExecutionStarting: () =>
                {
                    _isSaving = true;
                    _statusText.Text = WorkbookProgressTextFormatter
                        .FormatSave("preparing", TimeSpan.Zero, percent: null, UiText.Get)
                        .Detail;
                    _statusText.Foreground = Brush(67, 113, 83);
                    ApplyFileOperationProgress(null);
                    UpdateSaveButton();
                },
                ExecutionCompleted: () =>
                {
                    _isSaving = false;
                    UpdateSaveButton();
                }));

            if (workflowResult.Outcome == WorkbookFileOperationOutcome.ExternalWriteConflict)
            {
                ShowSaveIssue(UiText.Format(
                    "MainWindowMessage_ExternallyModifiedFileBody",
                    Path.GetFileName(targetPath)));
                return false;
            }

            if (workflowResult.Outcome == WorkbookFileOperationOutcome.Rejected)
            {
                if (!string.Equals(
                        workflowResult.Message,
                        WorkbookFileWorkflowMessages.SaveCanceled,
                        StringComparison.Ordinal))
                {
                    ShowSaveIssue(workflowResult.Message);
                }
                return false;
            }

            if (workflowResult.Outcome == WorkbookFileOperationOutcome.Canceled)
            {
                ShowSaveIssue(UiText.Get("File_SaveCanceledMessage"));
                return false;
            }

            if (workflowResult.Outcome == WorkbookFileOperationOutcome.Failed)
            {
                ShowSaveIssue(UiText.Format(
                    "File_SaveFailedFormat",
                    workflowResult.Exception?.Message ?? UiText.Get("Common_UnknownError")));
                return false;
            }

            var executionResult = workflowResult.RequireExecutionResult();
            var completionPlan = workflowResult.RequireCompletionPlan();
            // The save just wrote targetPath -- refresh the "known good" write-time snapshot to the
            // file's new on-disk timestamp so the very next save doesn't mistake THIS save's own
            // write for an external modification (mirrors the WPF host's equivalent refresh).
            if (completionPlan.ApplyFileContext)
            {
                _currentFileSourceLastWriteTimeUtc = executionResult.SavedLastWriteTimeUtc;
            }
            // A clean save means there is nothing left to recover from — delete the crash-recovery
            // snapshot immediately rather than waiting for window close (mirrors WPF's
            // NotifyAutosaveSaved, called from the same save-completion point).
            if (completionPlan.MarkSaved)
                _autosaveCoordinator?.NotifyAutosaveSaved();
            RefreshShell(FormatSaveCompletionStatus(targetPath, executionResult.Warnings));
            return true;
        }
        catch (Exception ex)
        {
            ShowSaveIssue(UiText.Format("File_SaveFailedFormat", ex.Message));
            return false;
        }
        finally
        {
            operationCancellation.Dispose();
            UpdateSaveButton();
        }
    }

    private UserMessageResult ResolveExternallyModifiedFileOverwriteConfirm(string path)
    {
        Func<string, UserMessageResult>? handler = null;
        ResolveExternallyModifiedFileOverwriteConfirmHandler(ref handler);
        return handler?.Invoke(path)
            ?? ShowSynchronousPrompt(FreeXSynchronousPromptCatalog.ForExternallyModifiedFile(path));
    }

    partial void ResolveExternallyModifiedFileOverwriteConfirmHandler(
        ref Func<string, UserMessageResult>? handler);

    private UserMessageResult ResolveLossyFormatFeatureLossConfirm(string extension)
    {
        Func<string, UserMessageResult>? handler = null;
        ResolveLossyFormatFeatureLossConfirmHandler(ref handler);
        return handler?.Invoke(extension)
            ?? ShowSynchronousPrompt(FreeXSynchronousPromptCatalog.ForLossyFormatFeatureLoss(extension));
    }

    partial void ResolveLossyFormatFeatureLossConfirmHandler(
        ref Func<string, UserMessageResult>? handler);

    private void ShowSaveIssue(string message)
    {
        // Same accessibility rationale as ShowEditIssue: this is the only signal a failed/blocked
        // save-adjacent action produced, so it must be an announced live region.
        EnsureStatusTextLiveRegion();
        _statusText.Text = message;
        _statusText.Foreground = Brush(143, 74, 18);
    }

    private static string FormatSaveCompletionStatus(string path, IReadOnlyList<string> warnings) =>
        warnings.Count == 0
            ? $"Saved {Path.GetFileName(path)}"
            : $"Saved {Path.GetFileName(path)} with {warnings.Count} warning(s)";

    private void ShowExportIssue(string message)
    {
        // Same accessibility rationale as ShowEditIssue: no owned modal dialog reports export
        // failures, so _statusText's live region is the only accessible signal.
        EnsureStatusTextLiveRegion();
        _statusText.Text = message;
        _statusText.Foreground = Brush(143, 74, 18);
        UpdateSaveButton();
    }

    private void ShowShareStatus(string message, bool isWarning)
    {
        if (isWarning)
            EnsureStatusTextLiveRegion();

        _statusText.Text = message;
        _statusText.Foreground = isWarning
            ? Brush(143, 74, 18)
            : Brush(67, 113, 83);
        UpdateSaveButton();
    }

    private void ShowOpenIssue(string message)
    {
        // Same accessibility rationale as ShowEditIssue: no owned modal dialog reports open
        // failures, so _statusText's live region is the only accessible signal.
        EnsureStatusTextLiveRegion();
        _statusText.Text = message;
        _statusText.Foreground = Brush(143, 74, 18);
    }

    private void ShowEditIssue(string message)
    {
        // Announce the failure to screen readers: the Avalonia shell has no owned modal message box
        // for validation/commit failures (unlike WPF's ShowOwnedMessage), so _statusText's live
        // region is the only accessible signal that the edit did NOT succeed.
        EnsureStatusTextLiveRegion();
        _statusText.Text = message;
        _statusText.Foreground = Brush(143, 74, 18);
        UpdateSaveButton();
    }

    private void ShowHelpIssue(string message)
    {
        // Same accessibility rationale as ShowEditIssue: no owned modal dialog reports Help failures,
        // so _statusText's live region is the only accessible signal.
        EnsureStatusTextLiveRegion();
        _statusText.Text = message;
        _statusText.Foreground = Brush(143, 74, 18);
    }

    private async Task<bool> ConfirmBeforeDestructiveWorkbookActionAsync(string title, string discardButtonText)
    {
        if (!_session.IsDirty)
            return true;

        var gateCompletion = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
        _pendingDirtyWorkbookGate = gateCompletion.Task;
        try
        {
            return await _fileWorkflow.CanProceedAfterDirtyGateWithCleanSaveAsync(
                isDirty: true,
                async () => ToSaveChangesPrompt(await ShowDirtyWorkbookCloseDialogAsync(title, discardButtonText)),
                SaveCurrentWorkbookAsync,
                () => _session.IsDirty);
        }
        finally
        {
            if (ReferenceEquals(_pendingDirtyWorkbookGate, gateCompletion.Task))
                _pendingDirtyWorkbookGate = null;
            gateCompletion.TrySetResult(true);
        }
    }

    private Task WaitForPendingDirtyWorkbookGateAsync() => _pendingDirtyWorkbookGate ?? Task.CompletedTask;

    private static SaveChangesPrompt ToSaveChangesPrompt(DirtyWorkbookCloseChoice choice) => choice switch
    {
        DirtyWorkbookCloseChoice.Save => SaveChangesPrompt.Save,
        DirtyWorkbookCloseChoice.Discard => SaveChangesPrompt.DontSave,
        _ => SaveChangesPrompt.Cancel,
    };

    private async Task<DirtyWorkbookCloseChoice> ShowDirtyWorkbookCloseDialogAsync(
        string title,
        string discardButtonText)
    {
        if (_isDirtyCloseDialogOpen)
            return DirtyWorkbookCloseChoice.Cancel;

        _isDirtyCloseDialogOpen = true;
        var choice = DirtyWorkbookCloseChoice.Cancel;
        try
        {
            var dialog = new Window
            {
                Title = title,
                Width = 440,
                Height = 210,
                MinWidth = 400,
                MinHeight = 200,
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ShowInTaskbar = false,
            };

            var titleText = new TextBlock
            {
                Text = UiText.Format("DirtyWorkbook_SaveChangesToFormat", _session.DisplayName),
                FontSize = 16,
                FontWeight = FontWeight.SemiBold,
                TextWrapping = TextWrapping.Wrap,
            };
            var detailText = new TextBlock
            {
                Text = UiText.Get("DirtyWorkbook_UnsavedChangesWillBeLost"),
                Foreground = HeaderForeground,
                TextWrapping = TextWrapping.Wrap,
            };

            var saveButton = new Button
            {
                Content = UiText.Get("MainWindow_AutomationName_Save"),
                MinWidth = 92,
                Padding = new Thickness(10, 4),
            };
            AutomationProperties.SetAutomationId(saveButton, "DirtyWorkbookSaveButton");
            AutomationProperties.SetName(saveButton, UiText.CreateAutomationName(UiText.Get("MainWindow_AutomationName_Save")));
            AutomationProperties.SetHelpText(saveButton, UiText.Get("DirtyWorkbook_SaveHelpText"));

            var discardButton = new Button
            {
                Content = discardButtonText,
                MinWidth = 132,
                Padding = new Thickness(10, 4),
            };
            AutomationProperties.SetAutomationId(discardButton, "DirtyWorkbookDiscardButton");
            AutomationProperties.SetName(discardButton, discardButtonText);
            AutomationProperties.SetHelpText(discardButton, UiText.Get("DirtyWorkbook_DiscardHelpText"));

            var cancelButton = new Button
            {
                Content = UiText.CreateAutomationName(UiText.Get("Common_Cancel")),
                MinWidth = 92,
                Padding = new Thickness(10, 4),
            };
            AutomationProperties.SetAutomationId(cancelButton, "DirtyWorkbookCancelButton");
            AutomationProperties.SetName(cancelButton, UiText.CreateAutomationName(UiText.Get("Common_Cancel")));
            AutomationProperties.SetHelpText(cancelButton, UiText.Get("DirtyWorkbook_CancelHelpText"));

            void Finish(DirtyWorkbookCloseChoice selectedChoice)
            {
                choice = selectedChoice;
                dialog.Close();
            }

            saveButton.Click += (_, _) => Finish(DirtyWorkbookCloseChoice.Save);
            discardButton.Click += (_, _) => Finish(DirtyWorkbookCloseChoice.Discard);
            cancelButton.Click += (_, _) => Finish(DirtyWorkbookCloseChoice.Cancel);
            dialog.KeyDown += (_, e) =>
            {
                if (e.Key == Key.Enter)
                {
                    Finish(DirtyWorkbookCloseChoice.Save);
                    e.Handled = true;
                }
                else if (e.Key == Key.Escape)
                {
                    Finish(DirtyWorkbookCloseChoice.Cancel);
                    e.Handled = true;
                }
            };

            var buttonRow = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 8,
                HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
                Children =
                {
                    cancelButton,
                    discardButton,
                    saveButton,
                },
            };

            dialog.Content = new StackPanel
            {
                Margin = new Thickness(18),
                Spacing = 12,
                Children =
                {
                    titleText,
                    detailText,
                    new Border { Height = 10 },
                    buttonRow,
                },
            };

            await dialog.ShowDialog(this);
            return choice;
        }
        finally
        {
            _isDirtyCloseDialogOpen = false;
        }
    }

    /// <summary>
    /// Minimal Yes/No confirmation dialog for the startup crash-recovery prompt (see
    /// <c>App.OfferStartupRecoveryAsync</c>). Mirrors the plain <c>Window</c>-based dialog pattern
    /// already used by <see cref="ShowDirtyWorkbookCloseDialogAsync"/> rather than introducing a
    /// new shared message-service dependency for this single call site.
    /// </summary>
    internal async Task<bool> ShowRecoveryPromptAsync(string message, string title)
    {
        var accepted = false;
        var dialog = new Window
        {
            Title = title,
            Width = 440,
            Height = 190,
            MinWidth = 400,
            MinHeight = 180,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
            CanResize = false,
        };

        var messageText = new TextBlock
        {
            Text = message,
            FontSize = 14,
            TextWrapping = TextWrapping.Wrap,
        };

        var yesButton = new Button
        {
            Content = UiText.Get("Startup_RecoverButton"),
            MinWidth = 92,
            Padding = new Thickness(10, 4),
            IsDefault = true,
        };
        AutomationProperties.SetAutomationId(yesButton, "RecoverySnapshotYesButton");
        AutomationProperties.SetName(yesButton, UiText.Get("Startup_RecoverButton"));

        var noButton = new Button
        {
            Content = UiText.Get("Startup_DiscardButton"),
            MinWidth = 92,
            Padding = new Thickness(10, 4),
            IsCancel = true,
        };
        AutomationProperties.SetAutomationId(noButton, "RecoverySnapshotNoButton");
        AutomationProperties.SetName(noButton, UiText.Get("Startup_DiscardButton"));

        void Finish(bool selected)
        {
            accepted = selected;
            dialog.Close();
        }

        yesButton.Click += (_, _) => Finish(true);
        noButton.Click += (_, _) => Finish(false);
        dialog.KeyDown += (_, e) =>
        {
            if (e.Key == Key.Enter)
            {
                Finish(true);
                e.Handled = true;
            }
            else if (e.Key == Key.Escape)
            {
                Finish(false);
                e.Handled = true;
            }
        };

        var buttonRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 8,
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
            Children = { noButton, yesButton },
        };

        dialog.Content = new StackPanel
        {
            Margin = new Thickness(18),
            Spacing = 12,
            Children = { messageText, new Border { Height = 10 }, buttonRow },
        };

        await dialog.ShowDialog(this);
        return accepted;
    }

    private async Task OpenExternalHelpLinkAsync(string url, string title)
    {
        if (!IsHttpOrHttpsHelpUrl(url))
        {
            ShowHelpIssue($"{title} link is blocked.");
            return;
        }

        var result = await OpenExternalUriAsync(url);
        switch (result)
        {
            case ExternalUriLaunchResult.Launched:
                return;
            case ExternalUriLaunchResult.BlockedScheme:
                ShowHelpIssue($"{title} link is blocked.");
                return;
            case ExternalUriLaunchResult.LauncherUnavailable:
                ShowHelpIssue($"{title} link cannot be opened on this platform.");
                return;
            case ExternalUriLaunchResult.LaunchFailed:
            default:
                ShowHelpIssue($"{title} link could not be opened.");
                return;
        }
    }

    private static bool IsHttpOrHttpsHelpUrl(string url)
    {
        if (string.IsNullOrWhiteSpace(url) ||
            !Uri.TryCreate(url.Trim(), UriKind.Absolute, out var uri))
        {
            return false;
        }

        return string.Equals(uri.Scheme, Uri.UriSchemeHttp, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(uri.Scheme, Uri.UriSchemeHttps, StringComparison.OrdinalIgnoreCase);
    }

    private async Task<ExternalUriLaunchResult> OpenExternalUriAsync(string target)
    {
        return await AvaloniaExternalUriLauncher.OpenAsync(this, target);
    }

