    private async Task ShowTextDialogAsync(string title, string text, double width, double height)
    {
        var dialog = new Window
        {
            Title = title,
            Width = width,
            Height = height,
            MinWidth = Math.Min(width, 420),
            MinHeight = Math.Min(height, 320),
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            ShowInTaskbar = false,
        };

        var closeButton = new Button
        {
            Content = UiText.CreateAutomationName(UiText.Get("Common_Close")),
            Width = 92,
            Padding = new Thickness(10, 4),
            HorizontalAlignment = AvaloniaHorizontalAlignment.Right,
        };
        AutomationProperties.SetName(closeButton, UiText.CreateAutomationName(UiText.Get("Common_Close")));
        AutomationProperties.SetHelpText(closeButton, UiText.Format("Common_CloseNamedHelpText", title));
        closeButton.Click += (_, _) => dialog.Close();

        var textBox = new TextBox
        {
            Text = text,
            IsReadOnly = true,
            AcceptsReturn = true,
            TextWrapping = TextWrapping.Wrap,
            FontSize = 13,
            Padding = new Thickness(8),
            MinHeight = 240,
        };
        AutomationProperties.SetName(textBox, title);
        AutomationProperties.SetHelpText(textBox, UiText.Format("Common_ReadOnlyNamedTextHelpText", title));

        var root = new DockPanel
        {
            Margin = new Thickness(16),
        };
        DockPanel.SetDock(closeButton, Dock.Bottom);
        root.Children.Add(closeButton);
        root.Children.Add(new ScrollViewer
        {
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            Content = textBox,
        });

        dialog.Content = root;
        await dialog.ShowDialog(this);
    }

    private (double Height, double Width) GetCurrentSheetViewportSize()
    {
        return TryGetSheetViewportSize(out var viewportHeight, out var viewportWidth)
            ? (viewportHeight, viewportWidth)
            : (_session.ViewportHeight, _session.ViewportWidth);
    }

    private bool TryGetSheetViewportSize(out double viewportHeight, out double viewportWidth)
    {
        if (!TryGetSheetViewportDisplaySize(out var displayHeight, out var displayWidth))
        {
            viewportHeight = 0;
            viewportWidth = 0;
            return false;
        }

        var zoomFactor = GetActiveZoomFactor();
        viewportHeight = displayHeight / zoomFactor;
        viewportWidth = displayWidth / zoomFactor;
        return true;
    }

    private bool TryGetSheetViewportDisplaySize(out double viewportHeight, out double viewportWidth)
    {
        var bounds = _sheetScrollViewer.Bounds;
        var zoomFactor = GetActiveZoomFactor();
        var showHeadings = _session.IsShowingHeadings;
        var headerHeight = showHeadings ? GetColumnHeaderHeight(_session.Viewport, zoomFactor) : 0;
        var headerWidth = showHeadings ? GetRowHeaderWidth(_session.Viewport, zoomFactor) : 0;
        if (bounds.Height <= headerHeight || bounds.Width <= headerWidth)
        {
            viewportHeight = 0;
            viewportWidth = 0;
            return false;
        }

        viewportHeight = bounds.Height - headerHeight;
        viewportWidth = bounds.Width - headerWidth;
        return true;
    }

    private void RefreshViewportSizeForZoom()
    {
        if (TryGetSheetViewportSize(out var viewportHeight, out var viewportWidth))
            _session.UpdateViewportSize(viewportHeight, viewportWidth);
    }

    private double GetActiveZoomFactor() =>
        StatusBarZoomSliderPlanner.ClampZoomPercent(_session.ZoomPercent) / 100d;

    private bool ShouldUseWarningStatusColor(string status) =>
        _session.IsFallback ||
        status.Contains("Unsupported XLSX", StringComparison.Ordinal) ||
        status.Contains("load warning", StringComparison.OrdinalIgnoreCase);

    private static string FormatCellReference(CellAddress address) =>
        SpreadsheetDisplayFormatter.FormatCellReference(address, useR1C1ReferenceStyle: false);

    private static string FormatRangeReference(GridRange range) =>
        SpreadsheetDisplayFormatter.FormatRangeReference(
            range.Start,
            range.End,
            useR1C1ReferenceStyle: false);

    private string FormatEditText(Cell? cell, CellAddress address) =>
        SpreadsheetDisplayFormatter.FormatFormulaBarText(
            cell,
            address,
            useR1C1ReferenceStyle: UseR1C1ReferenceStyle,
            _session.Workbook.GetSheet(address.Sheet),
            _session.Workbook);

    // Application options are loaded and adopted by the renderer-neutral runtime session. Hot edit
    // paths read its in-memory snapshot directly, so the Avalonia renderer needs no file-time cache.
    private bool UseR1C1ReferenceStyle =>
        _optionsRuntimeSession.LiveOptions.UseR1C1ReferenceStyle;

    private bool GenerateGetPivotData =>
        _optionsRuntimeSession.LiveOptions.GenerateGetPivotData;

    private bool EnableFillHandleAndCellDragAndDrop =>
        _optionsRuntimeSession.LiveOptions.EnableFillHandleAndCellDragAndDrop;

    private bool EnableAutoCompleteForCellValues =>
        _optionsRuntimeSession.LiveOptions.EnableAutoCompleteForCellValues;

    private bool MoveSelectionAfterEnter =>
        _optionsRuntimeSession.LiveOptions.MoveSelectionAfterEnter;

    private FormulaEditorEnterDirection AfterEnterDirection =>
        AppOptionsEnterDirectionMapper.ToFormulaEditor(_optionsRuntimeSession.LiveOptions.AfterEnterDirection);

    private static void AddGridChild(AvaloniaGrid grid, Control control, int row, int column)
    {
        AvaloniaGrid.SetRow(control, row);
        AvaloniaGrid.SetColumn(control, column);
        grid.Children.Add(control);
    }

    // ImmutableSolidColorBrush has no AvaloniaObject dispatcher affinity, so it is safe to store
    // in static readonly fields that outlive a single HeadlessUnitTestSession dispatch cycle.
    private static IBrush Brush(byte red, byte green, byte blue) =>
        new ImmutableSolidColorBrush(Color.FromRgb(red, green, blue));

    private static IBrush Brush(byte alpha, byte red, byte green, byte blue) =>
        new ImmutableSolidColorBrush(Color.FromArgb(alpha, red, green, blue));

    private static IBrush Brush(CellColor color) =>
        Brush(color.R, color.G, color.B);
}
